def _log_admin_action(admin_id, class_code, action, details=""):
    """Журналируем ДЕЙСТВИЕ АДМИНИСТРАТОРА КЛАССА.

    Зачем (просьба разработчика): если админ класса рассылает запрещённый
    контент, разработчик может ДОКАЗАТЬ, что рассылал не он — в журнале
    стоит id админа, время, класс и суть действия. Журнал пишется только
    на изменяющие действия админов класса (не на действия разработчика
    и не на действия обычных пользователей). Хвост журнала обрезается
    до 500 записей, чтобы файл не рос бесконечно."""
    try:
        entries = load_admin_log()
        if not isinstance(entries, list):
            entries = []
        admin = get_user(str(admin_id))
        _who = ""
        if admin is not None:
            _who = (admin.first_name or "")
            if getattr(admin, 'username', None):
                _who += f" (@{admin.username})"
        entries.append({
            'ts': datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
            'admin_id': str(admin_id),
            'admin_name': _who,
            'class_code': str(class_code or ""),
            'action': str(action),
            'details': str(details)[:300],
        })
        if len(entries) > 500:
            entries = entries[-500:]
        save_admin_log(entries)
    except Exception as e:
        # Журнал не должен ронять само действие админа.
        logger.error(f"_log_admin_action: {e}")

def load_stars_stats():
    """Агрегированная статистика Stars БЕЗ подробной истории переводов.

    По требованию пользователя подробная история переводов полностью удалена:
    при первом же чтении старое поле 'transactions' стирается из файла и
    больше нигде не создаётся. Хранятся только АГРЕГАТЫ:
      — total_stars_spent: суммарно потрачено Stars;
      — spenders: карта {user_id: total_spent} по ВСЕМ тратившим (без капы);
      — top_donors: топ-10 по тратам (производная от spenders);
      — spenders_count: сколько пользователей вообще что-то тратили.
    """
    stats = load_data(STARS_STATS_FILE, {})
    if not stats:
        stats = {
            'total_stars_spent': 0,
            'top_donors': [],
            'spenders': {},
            'spenders_count': 0,
        }
    changed = False
    # ПОЛНАЯ ОЧИСТКА подробной истории переводов (однократная миграция).
    if 'transactions' in stats:
        stats.pop('transactions', None)
        changed = True
    if 'total_stars_spent' not in stats:
        stats['total_stars_spent'] = 0
        changed = True
    if 'spenders' not in stats or not isinstance(stats.get('spenders'), dict):
        # Реконструкция карты тративших из старого топа (лучшее возможное
        # после удаления истории — точность дальше поддерживается инкрементально).
        stats['spenders'] = {
            str(d.get('user_id')): int(d.get('total_spent', 0))
            for d in stats.get('top_donors', []) if isinstance(d, dict)
        }
        changed = True
    if 'top_donors' not in stats:
        stats['top_donors'] = []
        changed = True
    if 'spenders_count' not in stats:
        stats['spenders_count'] = len(stats.get('spenders', {}))
        changed = True
    if changed:
        save_stars_stats(stats)
    return stats


def register_stars_spending(user_id, user_name, amount):
    """Регистрирует потраченные Stars в агрегированной статистике.

    НЕ пишет никаких записей-переводов: только инкремент общей суммы,
    обновление карты тративших (spenders) и производного топ-10.
    """
    try:
        amount = int(amount)
    except (TypeError, ValueError):
        return False
    if amount <= 0:
        return False
    stats = load_stars_stats()
    stats['total_stars_spent'] = int(stats.get('total_stars_spent', 0)) + amount

    spenders = stats.get('spenders') or {}
    if not isinstance(spenders, dict):
        spenders = {}
    key = str(user_id)
    spenders[key] = int(spenders.get(key, 0)) + amount
    stats['spenders'] = spenders

    # Топ-10 — производная от полной карты тративших.
    users = load_users()
    def _name_for(uid):
        u = users.get(str(uid))
        return (u.first_name if u and getattr(u, 'first_name', None) else None)
    stats['top_donors'] = [
        {'user_id': uid, 'user_name': _name_for(uid) or 'Пользователь', 'total_spent': total}
        for uid, total in sorted(spenders.items(), key=lambda kv: kv[1], reverse=True)[:10]
    ]
    stats['spenders_count'] = len(spenders)
    save_stars_stats(stats)
    return True


def reset_stars_stats():
    """Полный сброс статистики Stars (только для разработчика)."""
    return save_stars_stats({
        'total_stars_spent': 0,
        'top_donors': [],
        'spenders': {},
        'spenders_count': 0,
    })

def save_stars_stats(stats):
    return save_data(STARS_STATS_FILE, stats)


# ==================================
# === АНТИСПАМ (rate-limit) ===
# ==================================
# Простой in-memory rate-limit, не зависящий от перезапуска: хранит для каждого
# user_id → ключа действия время последнего вызова и количество вызовов.
# Для долгоживущих ограничений (пишет «жалуется» в саппорт каждые 5 секунд) —
# имеется fallback на user.last_action_ts (сериализуется в users.json).
_RATE_LIMIT_BUCKETS = {}


def is_user_spamming(user_id, key="default", min_interval=0.7, burst=4, burst_window=5.0):
    """Возвращает True, если пользователь user_id «спамит» действием key.

    Параметры:
      min_interval — минимальная пауза между двумя событиями (сек).
      burst — сколько событий разрешено в окне burst_window (защита от
              многократного быстрого тапа).
      burst_window — окно, в котором считаем burst (сек).

    Использование:
      if is_user_spamming(user_id, "menu"):
          await reply("⏳ Слишком быстро. Подождите немного."); return
    Хелпер не блокирует пользователя в БД — это лишь мягкое замедление.
    """
    import time as _time
    now = _time.monotonic()
    bucket = _RATE_LIMIT_BUCKETS.setdefault(str(user_id), {})
    info = bucket.setdefault(key, {"last": 0.0, "events": []})
    last = info["last"]
    events = info["events"]
    # Чистим устаревшие события из окна.
    cutoff = now - burst_window
    info["events"] = [t for t in events if t >= cutoff]
    events = info["events"]
    if (now - last) < min_interval:
        return True
    if len(events) >= burst:
        return True
    info["last"] = now
    events.append(now)
    return False


def get_user_rate_limit_message():
    """Дружелюбное сообщение о превышении лимита частоты действий."""
    return (
        "⏳ Слишком много действий подряд. "
        "Подождите 1–2 секунды и повторите попытку."
    )


# === ВОЛНА 22.13: РАСШИРЕННАЯ СТАТИСТИКА ===
# 1) ACTIVITY_FILE — кто и когда последний раз пользовался ботом (день).
#    Пишем ТОЛЬКО когда день сменился — не чаще 1 записи на юзера в сутки,
#    чтобы не грузить БД. Отсюда считаются DAU/WAU/MAU и прирост.
# 2) FEATURE_STATS_FILE — счётчики функций: {key: {"total": N, "by_day": {...}}}.
_ACTIVITY_CACHE = None
_FSTATS_CACHE = None
_FSTATS_KEYS = (
    "vault_upload", "vault_get", "poll_sent", "sol_published",
    "share_created", "share_redeemed", "ai_msg", "timer_set",
)


def _activity_all():
    global _ACTIVITY_CACHE
    if _ACTIVITY_CACHE is None:
        data = load_data(ACTIVITY_FILE, {})
        _ACTIVITY_CACHE = data if isinstance(data, dict) else {}
    return _ACTIVITY_CACHE


def _touch_activity(user_id):
    """Отметить день активности пользователя. Запись на диск — только если
    день изменился (дёшево). Любой сбой молча игнорируется — статистика
    не должна ломать основной поток."""
    try:
        today = datetime.now().strftime("%Y-%m-%d")
        data = _activity_all()
        rec = data.get(str(user_id))
        if isinstance(rec, dict) and rec.get("last") == today:
            return
        data[str(user_id)] = {"last": today}
        save_data(ACTIVITY_FILE, data)
    except Exception:
        pass


def _activity_counts():
    """(dau, wau, mau) — сколько уникальных юзеров были активны
    в последние 1 / 7 / 30 дней."""
    import time as _t
    now = _t.time()
    data = _activity_all()
    dau = wau = mau = 0
    for rec in data.values():
        if not isinstance(rec, dict):
            continue
        try:
            ts = datetime.strptime(str(rec.get("last")), "%Y-%m-%d").timestamp()
        except (TypeError, ValueError):
            continue
        age = now - ts
        if age <= 86400:
            dau += 1
        if age <= 7 * 86400:
            wau += 1
        if age <= 30 * 86400:
            mau += 1
    return dau, wau, mau


def _feature_stats_all():
    global _FSTATS_CACHE
    if _FSTATS_CACHE is None:
        data = load_data(FEATURE_STATS_FILE, {})
        _FSTATS_CACHE = data if isinstance(data, dict) else {}
    return _FSTATS_CACHE


_FSTATS_FLUSH_TS = {"t": 0.0}


def _stat_flush(force=False):
    """Слить счётчики функций на диск/в БД (троттлинг 60 сек — счётчики
    обновляются часто, а писать на каждый инкремент нельзя). ВОЛНА 22.14:
    вызывается и из единого тикера (раз в минуту), и из _post_shutdown
    (force=True) — счётчики «сколько пользовались» больше не теряются.
    Кэш None (счётчиков ещё не было) — писать нечего, честно выходим."""
    import time as _t
    now = _t.monotonic()
    if not force and (now - _FSTATS_FLUSH_TS["t"]) < 60.0:
        return
    if _FSTATS_CACHE is None:
        return
    _FSTATS_FLUSH_TS["t"] = now
    try:
        save_data(FEATURE_STATS_FILE, _FSTATS_CACHE)
    except Exception:
        pass


def _stat_bump(key, n=1):
    """+1 к счётчику функции (см. _FSTATS_KEYS). Хранит сумму и разбивку
    по дням (дни старше 60 дней выкидываем, чтобы файл не рос). Пишет на
    диск не чаще раза в минуту — в памяти всегда актуально."""
    try:
        data = _feature_stats_all()
        rec = data.setdefault(str(key), {"total": 0, "by_day": {}})
        if not isinstance(rec, dict):
            rec = data[str(key)] = {"total": 0, "by_day": {}}
        rec["total"] = int(rec.get("total", 0) or 0) + int(n)
        today = datetime.now().strftime("%Y-%m-%d")
        by_day = rec.setdefault("by_day", {})
        by_day[today] = int(by_day.get(today, 0) or 0) + int(n)
        cutoff = (datetime.now() - timedelta(days=60)).strftime("%Y-%m-%d")
        for d in [d for d in by_day if str(d) < cutoff]:
            by_day.pop(d, None)
        _stat_flush()
    except Exception:
        pass  # статистика не должна ронять фичи


def _stat_days_sum(key, days):
    """Сколько раз функцию key вызывали за последние `days` дней."""
    data = _feature_stats_all().get(str(key)) or {}
    by_day = data.get("by_day") or {}
    total = 0
    for i in range(max(0, int(days))):
        d = (datetime.now() - timedelta(days=i)).strftime("%Y-%m-%d")
        total += int(by_day.get(d, 0) or 0)
    return total


# === ВОЛНА 22.13: УВЕДОМЛЕНИЯ РАЗРАБОТЧИКУ О СБОЯХ ===
# «Если что-то сломалось — разработчику должно прийти уведомление».
# Троттлинг: одинаковые ошибки не чаще раза в 90 секунд, максимум 15
# уведомлений в сутки — чтобы не устроить самому себе спам-апокалипсис
# и не попасть под флуд-лимиты Telegram.
_DEV_ERR_STATE = {"sent": {}, "day": "", "count": 0}
_DEV_ERR_THROTTLE_S = 90.0
_DEV_ERR_MAX_PER_DAY = 15


def _dev_err_key(title, err):
    return f"{title}:{type(err).__name__ if err is not None else '—'}"


def _dev_err_allowed(key):
    """Проверка троттлинга (вызывать ТОЛЬКО при уже пойманном сбое)."""
    import time as _t
    now = _t.monotonic()
    today = datetime.now().strftime("%Y-%m-%d")
    if _DEV_ERR_STATE["day"] != today:
        _DEV_ERR_STATE["day"] = today
        _DEV_ERR_STATE["count"] = 0
        _DEV_ERR_STATE["sent"] = {}
    if _DEV_ERR_STATE["count"] >= _DEV_ERR_MAX_PER_DAY:
        return False
    last = _DEV_ERR_STATE["sent"].get(key)
    if last is not None and (now - last) < _DEV_ERR_THROTTLE_S:
        return False
    _DEV_ERR_STATE["sent"][key] = now
    _DEV_ERR_STATE["count"] += 1
    return True


async def _notify_dev_error(bot, title, err=None, detail="", user_id=""):
    """Отправить разработчику уведомление о сбое (с троттлингом).
    Никогда не бросает исключений и не мешает основному потоку."""
    try:
        if not DEVELOPER_ID or str(DEVELOPER_ID) in ("0", "", "None"):
            return
        key = _dev_err_key(title, err)
        if not _dev_err_allowed(key):
            return
        lines = [f"🛠 СБОЙ: {title}"]
        if err is not None:
            lines.append(f"❗ {type(err).__name__}: {err}")
        if detail:
            lines.append(f"📄 {str(detail)[:400]}")
        if user_id:
            lines.append(f"👤 пользователь: {user_id}")
        lines.append(f"🕐 {datetime.now().strftime('%d.%m %H:%M:%S')}")
        await bot.send_message(
            chat_id=int(DEVELOPER_ID), text="\n".join(lines)[:3500])
    except Exception as e:
        logger.warning(f"notify_dev_error: не доставлено: {e}")


