def get_days_until_birthday(birthday_str):
    if not birthday_str:
        return None

    try:
        today = datetime.now().date()
        birthday = datetime.strptime(birthday_str, "%Y-%m-%d").date()

        next_birthday = birthday.replace(year=today.year)
        if next_birthday < today:
            next_birthday = next_birthday.replace(year=today.year + 1)

        return (next_birthday - today).days
    except Exception:
        return None

def calculate_timezone(user_time_str):
    try:
        utc_now = _utcnow()
        user_time = datetime.strptime(user_time_str, "%H:%M").time()
        user_datetime = datetime.combine(utc_now.date(), user_time)
        time_diff = user_datetime - utc_now
        total_seconds = time_diff.total_seconds()
        hours_diff = total_seconds / 3600
        return int(round(hours_diff))
    except Exception as e:
        logger.error(f"Ошибка вычисления часового пояса: {e}")
        return 3

def get_local_time(user):
    utc_time = _utcnow()
    return utc_time + timedelta(hours=user.timezone)

def get_bells_info(class_obj, user=None):
    if not class_obj or not class_obj.bells:
        return "🔔 Расписание звонков не установлено"

    # ИСПРАВЛЕНО: считаем «сейчас» по локальному времени пользователя, а
    # не по времени сервера, иначе после полуночи показывается «вчера».
    now = get_local_time(user) if user is not None else _utcnow() + timedelta(hours=3)
    current_time = now.time()

    sorted_bells = sorted(class_obj.bells.items(), key=lambda x: datetime.strptime(x[1]['start'], "%H:%M").time())

    for lesson, times in sorted_bells:
        start_time = datetime.strptime(times['start'], "%H:%M").time()
        end_time = datetime.strptime(times['end'], "%H:%M").time()

        if start_time <= current_time <= end_time:
            time_left = datetime.combine(now.date(), end_time) - datetime.combine(now.date(), current_time)
            minutes, seconds = divmod(time_left.total_seconds(), 60)
            return f"🔔 Сейчас идёт {lesson} урок\n⏰ До конца: {int(minutes)} мин {int(seconds)} сек"

        if current_time < start_time:
            time_until = datetime.combine(now.date(), start_time) - datetime.combine(now.date(), current_time)
            minutes, seconds = divmod(time_until.total_seconds(), 60)
            return f"🔔 Следующий урок ({lesson}) через {int(minutes)} мин {int(seconds)} сек"

    return "🔔 Уроки на сегодня закончились"

def get_holidays_count(class_obj, user=None):
    if not class_obj or not class_obj.holidays:
        return "📅 Даты каникулы не установлены"

    try:
        holiday_date = datetime.strptime(class_obj.holidays, "%Y-%m-%d").date()
        # ИСПРАВЛЕНО: «сегодня» — по локальному времени пользователя, чтобы
        # около полуночи и в часовых поясах !=UTC день не сдвигался.
        if user is not None:
            today = get_local_time(user).date()
        else:
            today = (_utcnow() + timedelta(hours=3)).date()
        days_left = (holiday_date - today).days

        if days_left > 0:
            return f"🎉 До каникул осталось {days_left} дней!"
        elif days_left == 0:
            return "🎉 Каникулы начинаются сегодня!"
        else:
            return "🎉 Каникулы уже начались!"
    except Exception:
        return "Неверный формат даты каникул"

def get_day_name(day_index):
    days_ru = ["Понедельник", "Вторник", "Среда", "Четверг", "Пятница", "Суббота", "Воскресенье"]
    return days_ru[day_index]

def _schedule_day_view(class_obj, day_name):
    """ВОЛНА 22.4: возвращает представление расписания на день.

    Расписание дня хранится в class_obj.schedule[day_name] и теперь бывает
    двух видов (обратно совместимо):
      • строка — обычный текст («1. Математика\n2. Русский…»);
      • dict {"image": <file_id>, "caption": <текст или ''>} — КАРТИНКА
        расписания, которую админ прислал при редактировании дня.

    Возвращает кортеж:
      ("text",  "<текст>")            — обычный день;
      ("image", {"image": fid, "caption": str}) — день-картинка;
      ("empty", "<пояснение>")        — расписание не установлено.
    """
    if not class_obj or not isinstance(getattr(class_obj, 'schedule', None), dict):
        return ("empty", "Расписание не установлено")
    raw = class_obj.schedule.get(day_name)
    if not raw:
        return ("empty", f"На {day_name} расписание не установлено")
    if isinstance(raw, dict) and raw.get("image"):
        return ("image", raw)
    if isinstance(raw, dict):
        # Мусорная структура без image — честно ведём себя как с пустым днём.
        return ("empty", f"На {day_name} расписание не установлено")
    return ("text", str(raw))


def get_day_schedule(class_obj, day_name):
    """Текстовое представление расписания дня.

    ВОЛНА 22.4: если день хранится КАРТИНКОЙ — возвращаем подпись (если
    админ её оставил) либо честную пометку «присылается картинкой». Места,
    которые умеют отправлять сами файлы, используют _schedule_day_view()
    и показывают настоящее изображение."""
    kind, payload = _schedule_day_view(class_obj, day_name)
    if kind == "image":
        cap = (payload.get("caption") or "").strip()
        return cap or "🖼 Расписание этого дня присылается картинкой — «📅 Расписание»."
    if kind == "empty":
        return payload
    return payload

def get_homework_for_date(class_obj, date_str):
    if not class_obj or not class_obj.homework:
        return None

    homework_for_date = {}
    for subject, assignments in class_obj.homework.items():
        filtered = [a for a in assignments if a.get('date') == date_str]
        if filtered:
            homework_for_date[subject] = filtered

    return homework_for_date if homework_for_date else None

def format_homework(homework_dict, date_str=None):
    """Форматирует домашние задания.

    Если ``date_str`` задан (например, "сегодня" / "завтра" / "2025-09-10") —
    выводится один блок с этой датой в шапке (используется в кнопках
    «📅 Сегодня» / «📅 Завтра», когда ДЗ заранее отфильтровано
    `get_homework_for_date`).

    Если ``date_str`` НЕ задан — в кнопке «📝 Домашнее задание» показываются
    ВСЕ задания, СГРУППИРОВАННЫЕ ПО ДАТЕ. По требованию пользователя:
    дата стоит «сверху» на каждый день, и в каждом блоке мы показываем
    ТОЛЬКО дату (без поля «Добавлено»), а под ней — список заданий по
    предметам. Дни отсортированы хронологически; задания без даты
    выводятся в самом конце под заголовком «Без даты».

    ВОЛНА 22.4: у пунктов с вложениями (фото/файлы/видео — ключ 'media')
    после текста печатается маркер «📎 вложения: …». Сами файлы
    досылаются следом в кнопках-просмотрах (см. _send_homework_media).
    """
    if not homework_dict:
        return "📝 Домашнее задание не задано."

    def _fmt_assignment(assignment):
        # Один пункт: текст (может быть пустым, если ДЗ — только файлы)
        # + маркер вложений.
        t = (assignment.get('text') or '').strip()
        media_line = _media_summary_line(assignment.get('media'))
        if not t:
            t = media_line or "(без текста)"
        elif media_line:
            t += f"\n  ↳ {media_line}"
        return t

    # Режим «отфильтровано извне» — стандартный вывод одной шапки.
    if date_str:
        text = f"📝 **Домашнее задание на {date_str}:**\n\n"
        for subject, assignments in homework_dict.items():
            text += f"**{subject}:**\n"
            for assignment in assignments:
                text += f"• {_fmt_assignment(assignment)}\n"
            text += "\n"
        return text

    # Режим «все ДЗ» — группируем по дате (только дата сверху каждого блока).
    grouped = {}
    for subject, assignments in homework_dict.items():
        for assignment in assignments:
            due = (assignment.get('date') or '').strip()
            grouped.setdefault(due or '', {}).setdefault(subject, []).append(
                assignment
            )

    if not grouped:
        return "📝 Домашнее задание не задано."

    def _sort_key(d):
        # Пустая дата — в самом конце; всё остальное — по возрастанию даты.
        if not d:
            return (1, "9999-12-31")
        try:
            datetime.strptime(d, "%Y-%m-%d")
            return (0, d)
        except Exception:
            return (0, d)

    text = "📝 **Домашнее задание:**\n\n"
    for due in sorted(grouped.keys(), key=_sort_key):
        # Дата сверху, без всяких «На дату:»/«Добавлено:».
        text += f"📅 **{due if due else 'Без даты'}**\n"
        for subject, items in grouped[due].items():
            text += f"**{subject}:**\n"
            for item in items:
                text += f"• {_fmt_assignment(item)}\n"
        text += "\n"

    return text


def _iter_assignment_media(homework_dict):
    """ВОЛНА 22.4: собирает непустые списки 'media' из пунктов ДЗ —
    чтобы кнопки-просмотры («📝 Домашнее задание», «📅 Сегодня»,
    «📅 Завтра») дослали файлы текстом списка. Пункты без вложений
    молча пропускаются; мусорные записи не роняют вывод."""
    for subject, assignments in (homework_dict or {}).items():
        for a in (assignments or []):
            if not isinstance(a, dict):
                continue
            m = a.get('media')
            if isinstance(m, list) and m:
                yield m


async def _send_day_schedule_screen(update, context, class_obj, day_name,
                                    when_word, when_str, homework):
    """ВОЛНА 22.4: единый экран «Расписание на сегодня/завтра» + ДЗ.

    Поддерживает дни-КАРТИНКИ (schedule[day] = {"image": file_id, …}): фото
    отправляется с шапкой, ДЗ и вложения идут следом отдельными сообщениями.
    Текстовые дни работают ровно как раньше."""
    kind, payload = _schedule_day_view(class_obj, day_name)
    header = f"📅 Расписание на {when_word} ({day_name}, {when_str})"
    hw_text = format_homework(homework, when_word).replace("**", "") if homework else ""

    if kind == "image":
        cap = header + " 🖼"
        if payload.get("caption"):
            cap += f"\n{payload['caption']}"
        try:
            # Лимит подписи Telegram — 1024 символа.
            await update.message.reply_photo(payload["image"], caption=cap[:1024])
        except Exception as e:
            logger.warning(f"schedule image send не прошёл ({day_name}): {e}")
            await update.message.reply_text(
                header + ":\n\n🖼 Картинка расписания не открылась — админ может "
                         "перезалить её через «📅 Редактировать расписание».")
        if hw_text:
            await update.message.reply_text(hw_text)
        else:
            await update.message.reply_text(
                f"📝 Домашнее задание на {when_word} не задано.")
    else:
        message = f"{header}:\n\n{payload}"
        message += f"\n\n{hw_text}" if homework else (
            f"\n\n📝 Домашнее задание на {when_word} не задано.")
        await update.message.reply_text(message)

    # Вложения ДЗ — в обоих вариантах.
    for _m_list in _iter_assignment_media(homework):
        await _send_homework_media(context, update.effective_chat.id, _m_list)


def check_class_limit(class_code):
    class_obj = get_class_by_code(class_code)
    if class_obj:
        return len(class_obj.students) < 40
    return False

