def _fmt_bytes(n):
    """Человекочитаемый размер: 1234567 -> 1.2 МБ."""
    try:
        n = float(n or 0)
    except (TypeError, ValueError):
        n = 0.0
    for unit in ("Б", "КБ", "МБ", "ГБ"):
        if n < 1024 or unit == "ГБ":
            if unit == "Б":
                return f"{int(n)} {unit}"
            return f"{n:.1f} {unit}"
        n /= 1024.0
    return f"{n:.1f} ГБ"


def _cloud_gen_file_id(user):
    files = getattr(user, "cloud_files", []) or []
    while True:
        fid = ''.join(random.choices(string.ascii_lowercase + string.digits, k=10))
        if all(f.get("id") != fid for f in files if isinstance(f, dict)):
            return fid


def _cloud_find_record(user, fid):
    for f in (getattr(user, "cloud_files", []) or []):
        if isinstance(f, dict) and f.get("id") == fid:
            return f
    return None


def _storage_channel_or_none(context=None):
    """ID канала-хранилища (конфиг или env). None — хранилище не настроено."""
    return get_storage_channel_id()


async def _storage_check_channel(context, channel_id):
    """Честная проверка доступа к каналу: бот должен быть админом.

    Возвращает (ok, описание_ошибки_or_None, title)."""
    try:
        chat = await context.bot.get_chat(channel_id)
    except Exception as e:
        return False, f"бот не видит канал ({e})", ""
    try:
        member = await context.bot.get_chat_member(channel_id, context.bot.id)
        status = str(getattr(member, "status", "") or "")
        if status not in ("administrator", "creator"):
            return (False, "бот есть в канале, но НЕ администратор — "
                           "загрузка файлов будет запрещена Telegram",
                    chat.title or "")
    except Exception as e:
        return False, f"не удалось проверить права бота ({e})", chat.title or ""
    return True, None, chat.title or ""


# --- ВОЛНА 22.35: «ШЛАГБАУМ» ПУБЛИКАЦИЙ В КАНАЛ (защита от блокировки) ---
# Telegram ограничивает частые посты в один канал (~20/мин, дальше RetryAfter,
# при систематическом шторме — блокировка канала). Мини-апп позволяет грузить
# много файлов сразу, поэтому ЛЮБАЯ публикация в канал-хранилище идёт через
# очередь: не чаще _PUB_MIN_GAP между постами, не больше _PUB_WINDOW_MAX в
# скользящем окне, RetryAfter — честная пауза всего канала + один повтор.
_PUB_GATES = {}          # channel_id -> {"lock", "wins", "pause_until", "waiters"}
_PUB_MIN_GAP = 2.6       # минимальная пауза между постами в ОДИН канал, сек
_PUB_WINDOW = 62.0       # скользящее окно, сек
_PUB_WINDOW_MAX = 20     # максимум постов в окно (с запасом ниже лимита ТГ)


def _pub_gate_state(channel_id):
    st = _PUB_GATES.get(int(channel_id))
    if st is None:
        st = {"lock": asyncio.Lock(), "wins": collections.deque(),
              "pause_until": 0.0, "waiters": 0}
        _PUB_GATES[int(channel_id)] = st
    return st


async def _pub_send(channel_id, coro_factory):
    """Публикует сообщение в канал через очередь (см. блок выше).
    coro_factory — функция без аргументов, создающая coroutine отправки
    (вызывается заново на каждый попытки, чтобы не переиспользовать корутину).
    Возвращает результат отправки; поле _queue_pos вНаружу отдаёт отдельным
    возвратом через атрибут результата — проще: возвращаем (result, queue_pos)."""
    st = _pub_gate_state(channel_id)
    st["waiters"] += 1
    queue_pos = st["waiters"]
    try:
        await st["lock"].acquire()
        try:
            last_err = None
            for attempt in (1, 2):
                # 1) пауза канала после RetryAfter
                while True:
                    now = time.time()
                    if now >= st["pause_until"]:
                        break
                    await asyncio.sleep(min(5.0, st["pause_until"] - now) + 0.05)
                # 2) скользящее окно + минимальный зазор
                while True:
                    now = time.time()
                    while st["wins"] and now - st["wins"][0] > _PUB_WINDOW:
                        st["wins"].popleft()
                    if len(st["wins"]) >= _PUB_WINDOW_MAX:
                        await asyncio.sleep(max(0.2, st["wins"][0] + _PUB_WINDOW - now))
                        continue
                    if st["wins"] and now - st["wins"][-1] < _PUB_MIN_GAP:
                        await asyncio.sleep(_PUB_MIN_GAP - (now - st["wins"][-1]))
                        continue
                    break
                # 3) сама отправка
                try:
                    result = await coro_factory()
                    st["wins"].append(time.time())
                    return result, queue_pos
                except TGRetryAfter as e:
                    ra = float(getattr(e, "retry_after", 5) or 5)
                    st["pause_until"] = time.time() + ra + 1.5
                    last_err = e
                    logger.warning(
                        f"pub-gate: канал {channel_id} попросил паузу {ra} с")
                    if attempt == 2:
                        raise
                    await asyncio.sleep(ra + 1.5)
                except TGBadRequest as e:
                    # ВОЛНА 22.36: медленный режим канала (CHAT_SLOWMODE_DELAY)
                    # приходит как BadRequest, а НЕ как RetryAfter — раньше он
                    # ронял публикацию навсегда, и пользователь видел «бот не
                    # админ канала» при пакетной загрузке. Теперь честная пауза
                    # и повтор; остальные BadRequest — наружу сразу.
                    _msg = str(getattr(e, "message", "") or "")
                    _slow = "slow mode" in _msg.lower() or "slowmode" in _msg.lower() \
                        or "too many requests" in _msg.lower()
                    if not _slow or attempt == 2:
                        raise
                    st["pause_until"] = time.time() + 12.0
                    last_err = e
                    logger.warning(
                        f"pub-gate: канал {channel_id} в slow mode — пауза 12 с")
                    await asyncio.sleep(12.0)
            raise last_err or RuntimeError("pub-gate: исчерпаны попытки")
        finally:
            st["lock"].release()
    finally:
        st["waiters"] = max(0, st["waiters"] - 1)


async def _storage_upload_document(context, data: bytes, filename: str, caption: str = "",
                                   channel_id=None, user=None, data_path=None):
    """Загружает документ в канал-хранилище.

    НОВОЕ (волна 7): если channel_id не задан явно — грузим по КРУГУ во все
    cloud-каналы (указатель cloud_rr в конфиге), при ошибке пробуем следующий.
    ВОЛНА 22.20: если у user подключён ЛИЧНЫЙ канал («🔗 Моё облако») и
    channel_id не задан явно — шифр уходит ТОЛЬКО в него, минуя общие каналы.
    ВОЛНА 22.35: каждая публикация идёт через «шлагбаум» _pub_send — не чаще
    пары сообщений в минуту НА КАНАЛ и с честной паузой по RetryAfter, иначе
    при массовых загрузках Telegram ограничивает/блокирует канал.
    ВОЛНА 22.36: data_path — читать файл с диска В МОМЕНТ публикации (под
    шлагбаумом): раньше каждый complete читал свой файл в ОЗУ ДО очереди,
    и пачка больших файлов съедала гигабайты ОЗУ сразу (до OOM на Render),
    из-за чего пакетная загрузка падала, а по одной — работала.
    Возвращает ({"message_id", "file_id", "size", "channel_id", "queue_pos"}) или None."""

    def _payload_bytes():
        if data_path:
            with open(data_path, "rb") as _fh:
                return _fh.read()
        return data

    if channel_id:
        targets = [int(channel_id)]
    else:
        _uch = _user_vault_channel(user)
        if _uch:
            targets = [_uch[0]]
        else:
            cloud_ids = get_cloud_channel_ids()
            if not cloud_ids:
                return None
            cfg = load_storage_config()
            try:
                rr = int(cfg.get("cloud_rr", 0) or 0)
            except (TypeError, ValueError):
                rr = 0
            # Круговая очередь: начинаем с указателя, дальше по порядку.
            targets = cloud_ids[rr % len(cloud_ids):] + cloud_ids[:rr % len(cloud_ids)]
    for idx, ch in enumerate(targets):
        try:
            # ВОЛНА 22.35: публикация через «шлагбаум» — очередь на канал;
            # ВОЛНА 22.36: чтение данных происходит ВНУТРИ гейта (по очереди)
            sent, queue_pos = await _pub_send(
                ch,
                lambda ch=ch: context.bot.send_document(
                    chat_id=ch,
                    document=InputFile(_payload_bytes(), filename=filename or "file.bin"),
                    caption=(caption or "")[:1024] or None,
                ),
            )
            doc = getattr(sent, "document", None)
            # Продвигаем указатель круговой загрузки (только общий путь).
            # Считаем от позиции канала в ИСХОДНОМ списке, а не в повёрнутом.
            # ВОЛНА 22.20: у пользователя свой канал — круг не трогаем.
            if not channel_id and not _user_vault_channel(user):
                cloud_now = get_cloud_channel_ids()
                if len(cloud_now) > 1 and ch in cloud_now:
                    try:
                        cfg_rr = load_storage_config()
                        cfg_rr["cloud_rr"] = (cloud_now.index(ch) + 1) % len(cloud_now)
                        save_storage_config(cfg_rr)
                    except Exception:
                        pass
            _size_out = int(getattr(doc, "file_size", 0) or 0)
            if not _size_out:
                # ВОЛНА 22.36: в режиме data_path данные читаются под гейтом —
                # размер берём с диска (len(data) на None падал раньше)
                try:
                    _size_out = (os.path.getsize(data_path) if data_path
                                 else len(data or b""))
                except Exception:
                    _size_out = 0
            return {
                "message_id": sent.message_id,
                "file_id": getattr(doc, "file_id", None),
                "size": _size_out,
                "channel_id": ch,
                "queue_pos": queue_pos,
            }
        except Exception as e:
            logger.error(f"storage: загрузка документа в канал {ch} не удалась: {e}")
            if idx + 1 < len(targets):
                continue
    return None


# Максимальный размер ОДНОЙ части при разбиении больших бэкапов
# (лимиты Telegram: отправка ≤50 МБ, скачивание ботом ≤20 МБ).
STORAGE_PART_BYTES = 19 * 1024 * 1024


async def _storage_upload_big(context, data: bytes, base_filename: str, caption: str = "",
                              channel_id=None):
    """Загрузка данных любого размера: до 19 МБ — одним документом, больше —
    ЧАСТЯМИ по 19 МБ (Telegram не даёт ботам отправлять файлы >50 МБ, а
    скачивать >20 МБ; поэтому честный путь — части).

    channel_id=None → круговая загрузка по cloud-каналам; явный channel_id
    (используется бэкапом для зеркалирования в КАЖДЫЙ db-канал) грузит строго
    в него.

    Возвращает (ок: bool, сообщение_об_ошибке_or_None,
                список_частей: [{"message_id", "file_id", "size", "channel_id"}])."""
    if len(data) <= STORAGE_PART_BYTES:
        res = await _storage_upload_document(context, data, base_filename, caption,
                                             channel_id=channel_id)
        if res is None:
            return False, "Telegram отклонил загрузку документа в канал.", []
        return True, None, [res]
    parts = []
    total = len(data)
    n_parts = (total + STORAGE_PART_BYTES - 1) // STORAGE_PART_BYTES
    for i in range(n_parts):
        chunk = data[i * STORAGE_PART_BYTES:(i + 1) * STORAGE_PART_BYTES]
        name = f"{base_filename}.part{i + 1:02d}of{n_parts:02d}"
        res = await _storage_upload_document(
            context, chunk, name,
            caption=f"📦 Часть {i + 1}/{n_parts} • {caption}"[:1024],
            channel_id=channel_id,
        )
        if res is None:
            return (False,
                    f"Часть {i + 1}/{n_parts} не загрузилась — бэкап не записан, "
                    "попробуйте ещё раз.", parts)
        parts.append(res)
    return True, None, parts


async def _storage_download_big(context, entry) -> bytes:
    """Скачивает бэкап из канала: один документ или все части подряд.

    entry — запись реестра бэкапов (file_id / parts). Бросает исключение при
    неудаче; возвращает собранные байты."""
    parts = entry.get("parts") if isinstance(entry, dict) else None
    if parts:
        chunks = []
        for p in parts:
            if not isinstance(p, dict) or not p.get("file_id"):
                raise RuntimeError("в реестре есть часть без file_id")
            tg_file = await context.bot.get_file(p["file_id"])
            buf = io.BytesIO()
            await asyncio.wait_for(tg_file.download_to_memory(out=buf), timeout=120)
            chunks.append(buf.getvalue())
        return b"".join(chunks)
    file_id = (entry or {}).get("file_id")
    if not file_id:
        raise RuntimeError("у записи нет file_id")
    tg_file = await context.bot.get_file(file_id)
    buf = io.BytesIO()
    await asyncio.wait_for(tg_file.download_to_memory(out=buf), timeout=120)
    return buf.getvalue()


def _storage_pack_payload():
    """ВОЛНА 8 (общий упаковщик для бэкапа и снапшота канал-БД).

    Собирает ВСЕ файлы данных (STORAGE_BACKUP_FILES) в ОДИН zip + _meta.json.
    Возвращает (payload: bytes, meta: dict, files_count: int) либо (None, _, 0),
    если данных нет совсем."""
    files = {}
    for const in dict.fromkeys(STORAGE_BACKUP_FILES):
        base = os.path.basename(str(const))
        try:
            data = load_data(const, None)
        except Exception:
            data = None
        if data is None and not os.path.exists(str(const)):
            continue
        try:
            files[base] = json.dumps(data if data is not None else {}, ensure_ascii=False, indent=2).encode("utf-8")
        except Exception as e:
            logger.error(f"storage pack: {base} не сериализуется: {e}")
            continue
    # ВОЛНА 10: конфиг хранилища (СПИСОК КАНАЛОВ!) едет ВНУТРИ снапшота —
    # это бутстрап-указатель. На новом сервере пользователь подключает ЛЮБОЙ
    # один db-канал, бот достаёт снапшот и вспоминает ВСЕ остальные каналы,
    # их режимы и включённость режима «База в канале». Волатильные ключи
    # (локальные реестры бэкапов/сливов) внутрь не кладём — они свои у
    # каждого сервера, а их перезапись могла бы погасить локальную историю.
    try:
        _cfg_snap = load_storage_config()
        _cfg_snap = {
            k: v for k, v in _cfg_snap.items()
            if k not in ("backups", "cdb_registry", "cdb_last_flush",
                         "cdb_sent", "last_backup_date")
        }
        files["storage_config.json"] = json.dumps(
            _cfg_snap, ensure_ascii=False, indent=2,
        ).encode("utf-8")
    except Exception as e:
        logger.error(f"storage pack: конфиг хранилища не сериализуется: {e}")
    if not files:
        return None, {}, 0
    users_n = classes_n = 0
    try:
        users_n = len(load_data(USERS_FILE, {}) or {})
    except Exception:
        pass
    try:
        classes_n = len(load_data(CLASSES_FILE, {}) or {})
    except Exception:
        pass
    now = _utcnow()
    meta = {
        "created_utc": now.strftime("%Y-%m-%d %H:%M:%S"),
        "users": users_n,
        "classes": classes_n,
        "bot": "DEVORKS+",
    }
    buf = io.BytesIO()
    # ВОЛНА 9: LZMA (алгоритм 7-Zip) — снапшот базы в канале занимает заметно
    # меньше; чтение zipfile прозрачно поддерживает LZMA (совместимо со старыми
    # бэкапами DEFLATE, там метод stored у каждого члена архива свой).
    with zipfile.ZipFile(buf, "w", zipfile.ZIP_LZMA) as zf:
        for name, content in sorted(files.items()):
            zf.writestr(name, content)
        zf.writestr("_meta.json", json.dumps(meta, ensure_ascii=False))
    return buf.getvalue(), meta, len(files)


async def _storage_do_backup(context):
    """Собирает ВСЕ файлы данных в zip и зеркалит во ВСЕ db-каналы.

    НОВОЕ (волна 7): бэкапы больше 19 МБ автоматически режутся на части
    (file_id каждой части — в реестре). Возвращает (ok, человекочитаемый
    отчёт). Реестр бэкапов хранится в storage_config.json (Bot API не умеет
    читать историю канала, поэтому указатели — message_id/file_id —
    сохраняем сами).
    ВОЛНА 8: сборка архива вынесена в общий _storage_pack_payload()."""
    db_ids = get_db_channel_ids()
    if not db_ids:
        return False, ("❌ Хранилище не настроено. Подключите приватный канал: "
                       "🛠️ Панель разработчика → ☁️ Хранилище → 🔗 Каналы.")
    payload, meta, files_n = _storage_pack_payload()
    if not payload:
        return False, "❌ Нет данных для бэкапа."
    users_n = meta.get("users", 0)
    classes_n = meta.get("classes", 0)
    now = _utcnow()
    today = now.strftime("%Y-%m-%d")
    caption = (
        f"📦 DEVORKS+ бэкап {today} • юзеров {users_n}, классов {classes_n}, "
        f"файлов {files_n} • {_fmt_bytes(len(payload))}"
    )
    # Зеркалим во ВСЕ db-каналы; у каждого канала — свой набор частей.
    per_channel_parts = {}
    ok_channels, fail_channels = [], []
    for ch in db_ids:
        ok_up, err_up, parts = await _storage_upload_big(
            context, payload, f"devorks_backup_{today}.zip", caption[:800],
            channel_id=ch,
        )
        if ok_up:
            per_channel_parts[ch] = parts
            ok_channels.append(ch)
        else:
            fail_channels.append(f"{ch}: {err_up}")
    if not ok_channels:
        return False, "❌ Бэкап не загрузился ни в один канал: " + "; ".join(fail_channels[:3])
    first = per_channel_parts[ok_channels[0]]
    entry = {
        "date": today,
        "ts": now.strftime("%Y-%m-%d %H:%M:%S"),
        "message_id": first[0]["message_id"],
        "file_id": first[0]["file_id"],
        "size": len(payload),
        "users": users_n,
        "classes": classes_n,
        "files": files_n,
        "channel_id": ok_channels[0],
        # Части появляются только если бэкап больше 19 МБ.
        "parts": (first if len(first) > 1 else None),
        "mirrored": ok_channels,
    }
    cfg = load_storage_config()
    backups = [b for b in (cfg.get("backups") or []) if isinstance(b, dict)]
    try:
        max_rec = max(1, int(cfg.get("max_backup_records", 60) or 60))
    except (TypeError, ValueError):
        max_rec = 60
    cfg["backups"] = ([entry] + backups)[:max_rec]
    cfg["last_backup_date"] = today
    save_storage_config(cfg)
    report = f"✅ {caption}"
    if len(ok_channels) > 1:
        report += f" • зеркал в {len(ok_channels)} каналах"
    if fail_channels:
        report += f"\n⚠️ Не удалось в: {'; '.join(fail_channels[:3])}"
    if entry["parts"]:
        report += f" • разобран на {len(first)} частей (>19 МБ)"
    return True, report


async def _storage_auto_backup_tick(context):
    """Ежедневный авто-бэкап базы в канал. Вызывается единым тикером.

    Стратегия: как только наступил (или прошёл) backup_hour_utc И сегодня ещё
    не бэкапились — делаем. Так бэкап случится даже если хост спал в точный час."""
    cfg = load_storage_config()
    if not cfg.get("auto_backup", True):
        return
    if not get_db_channel_ids():
        return
    now = _utcnow()
    today = now.strftime("%Y-%m-%d")
    if cfg.get("last_backup_date") == today:
        return
    try:
        hour = int(cfg.get("backup_hour_utc", 4) or 4)
    except (TypeError, ValueError):
        hour = 4
    if now.hour < hour:
        return
    ok, report = await _storage_do_backup(context)
    logger.info(f"storage auto-backup: ok={ok}; {report}")


def _storage_restore_apply(payload: bytes, fallback_name: str = ""):
    """Восстанавливает данные из zip-бэкапа (или одиночного JSON).

    Перезаписывает ВСЕ известные файлы данных, найденные в архиве.
    ВОЛНА 17: связка ключей Сейфа (vault_auth — пароль+вопросы) НЕ откатывается
    снапшотом: если в восстановленном users.json её нет или она СТАРЕЕ (ts),
    остаётся более свежая связка из текущей базы. Легаси-связки (вопросы
    открытым текстом) здесь же дошифровываются.
    Возвращает (список восстановленных, список проблем)."""
    restored, problems = [], []
    known = {os.path.basename(str(p)): p for p in set(STORAGE_BACKUP_FILES)}
    # ВОЛНА 17: снимок ДО восстановления — источник свежей связки ключей.
    try:
        _old_users = dict(load_data(USERS_FILE, {}) or {})
    except Exception:
        _old_users = {}
    zf = None
    try:
        zf = zipfile.ZipFile(io.BytesIO(payload))
        names = zf.namelist()
    except Exception:
        zf = None
    if zf is not None:
        # ВОЛНА 10: конфиг хранилища из снапшота НЕ перезаписывает локальный
        # (это не файл данных, а «бутстрап-указатель»), а ДОПОЛНЯЕТ его —
        # бот вспоминает каналы, но осознанные локальные изменения не теряет.
        _snap_names = {os.path.basename(n): n for n in names}
        if "storage_config.json" in _snap_names:
            try:
                snap_cfg = json.loads(
                    zf.read(_snap_names["storage_config.json"]).decode("utf-8")
                )
                if _storage_config_merge_from_snapshot(snap_cfg):
                    restored.append("storage_config.json (каналы вспомнены)")
            except Exception as e:
                problems.append(f"storage_config.json: не слился ({e})")
        for name in names:
            base = os.path.basename(name)
            if name.endswith("/") or base not in known:
                continue
            try:
                parsed = json.loads(zf.read(name).decode("utf-8"))
            except Exception as e:
                problems.append(f"{base}: не JSON ({e})")
                continue
            try:
                save_data(known[base], parsed)
                restored.append(base)
            except Exception as e:
                problems.append(f"{base}: не сохранён ({e})")
        try:
            zf.close()
        except Exception:
            pass
    else:
        # Одиночный JSON-файл (например, users.json, присланный вручную).
        base = os.path.basename(fallback_name or "data.json")
        if base not in known:
            return [], [f"файл «{base}» не похож на zip-бэкап и не совпадает ни с одним файлом данных"]
        try:
            parsed = json.loads(payload.decode("utf-8"))
            save_data(known[base], parsed)
            restored.append(base)
        except Exception as e:
            problems.append(f"{base}: не удалось восстановить ({e})")
    # ВОЛНА 17: перенос/защита связки ключей Сейфа (до сброса кэшей).
    _ukey = os.path.basename(str(USERS_FILE))
    if _ukey in known:
        try:
            _new_users = load_data(known[_ukey], {}) or {}
            if isinstance(_new_users, dict):
                _merged_n = _sealed_n = 0
                for _uid, _nu in _new_users.items():
                    if not isinstance(_nu, dict):
                        continue
                    _ou = _old_users.get(_uid)
                    _oa = _ou.get("vault_auth") if isinstance(_ou, dict) else None
                    _na = _nu.get("vault_auth")
                    _keep = _vault_auth_pick(_oa, _na)
                    if _keep is not None and _keep is not _na:
                        _nu["vault_auth"] = _keep
                        _merged_n += 1
                    else:
                        _keep = _na if _keep is None else _keep
                    # Легаси-связка (вопросы открытым текстом) → шифруем.
                    if isinstance(_keep, dict) and "questions" in _keep:
                        _sealed = _vault_auth_seal(_keep)
                        if _sealed is not _keep:
                            _nu["vault_auth"] = _sealed
                            _sealed_n += 1
                if _merged_n or _sealed_n:
                    save_data(known[_ukey], _new_users)
                    if _merged_n:
                        restored.append(
                            f"users.json (связка ключей Сейфа сохранена у {_merged_n})")
        except Exception as e:
            problems.append(f"users.json: связка ключей Сейфа не перенесена ({e})")
    # Сбрасываем кэши, чтобы бот сразу увидел восстановленные данные.
    try:
        _users_cache.clear()
        _classes_cache.clear()
        _personal_buttons_cache.clear()
        _global_buttons_cache.clear()
        _cache_last_update.clear()
    except Exception:
        pass
    return restored, problems


# ==================================
# === КАНАЛ-БД: ДВИЖОК СНАПШОТОВ (волна 8) ===
# ==================================
# Канал становится ПЕРВИЧНОЙ базой данных: каждое изменение данных сольётся
# в закреплённый zip-снапшот, а на старте бот восстановит данные ИЗ канала.
# Сервер — одноразовый кэш; унёсся/стерся — база живёт в канале.

async def _cdb_flush(context, force: bool = False, reason: str = ""):
    """Сливает текущую базу zip-снапшотом во ВСЕ db-каналы и ЗАКРЕПЛЯЕТ его.

    Закреплённое сообщение — указатель «последний снапшот» для восстановления
    на старте (Bot API историю читать не умеет, но пин через getChat видит).
    Предыдущие снапшоты в канале НЕ удаляем — это бесплатная история версий.

    force=True — слить немедленно, игнорируя CDB_MIN_FLUSH_INTERVAL (кнопка
    «💾 Слить сейчас», включение режима, остановка бота).

    Возвращает (ok: bool, отчёт: str)."""
    global _CDB_LAST_FLUSH_MONO
    cfg = load_storage_config()
    if not cfg.get("channel_db_enabled"):
        return False, "Режим «База в канале» выключен."
    db_ids = get_db_channel_ids()
    if not db_ids:
        return False, "Нет каналов в режиме 🗄️ База данных (или 🔀 Оба)."
    if not _CDB_DIRTY and not force:
        return True, "Изменений нет — сливать нечего."
    if not force:
        import time as _time
        if _time.monotonic() - _CDB_LAST_FLUSH_MONO < CDB_MIN_FLUSH_INTERVAL:
            return True, "Слишком рано для следующего слива (анти-шторм)."
    async with _get_cdb_flush_lock():
        # Повторная проверка после ожидания лока: другой тик уже слил.
        if not _CDB_DIRTY and not force:
            return True, "Изменений нет — сливать нечего (после лока)."
        payload, meta, files_n = _storage_pack_payload()
        if not payload:
            return False, "Нет данных для снапшота."
        now = _utcnow()
        stamp = now.strftime("%Y-%m-%d_%H-%M-%S")
        fname = f"{CDB_SNAPSHOT_PREFIX}_{stamp}.zip"
        caption = (
            f"🗄️ DEVORKS+ снапшот базы {stamp} • юзеров {meta.get('users', 0)}, "
            f"классов {meta.get('classes', 0)}, файлов {files_n} • "
            f"{_fmt_bytes(len(payload))}\n(закреплено — бот восстановит отсюда)"
        )
        registry = dict(cfg.get("cdb_registry") or {})
        # ВОЛНА 12: перечень «какие снапшоты мы уже залили в каждый канал» —
        # чтобы после успешного пина СТЕРЕТЬ старые (пользователь жаловался:
        # «там просто несколько — новые, старые — и он зачем-то ещё новые
        # создает»: канал зарастал снапшотами, и было непонятно, какой
        # актуальный; при неудачном пине бот читал СТАРЫЙ закреп).
        cdb_sent = {}
        _raw_sent = cfg.get("cdb_sent")
        if isinstance(_raw_sent, dict):
            for _k, _v in _raw_sent.items():
                if isinstance(_v, list):
                    cdb_sent[str(_k)] = [int(m) for m in _v if str(m).strip().lstrip("-").isdigit()][:50]
        ok_ch, fail_ch, pin_warn, pruned_n = [], [], [], 0
        for ch in db_ids:
            try:
                res = await _storage_upload_document(
                    context, payload, fname, caption[:1024], channel_id=ch,
                )
                if not res:
                    fail_ch.append(f"{ch}: загрузка не удалась")
                    continue
                msg_id = res["message_id"]
                # Закрепляем новый снапшот (пин заменяет предыдущий закреп).
                pin_ok = True
                try:
                    await context.bot.unpin_all_chat_messages(chat_id=ch)
                except Exception as e:
                    logger.warning(f"cdb: unpin_all в {ch}: {e}")
                try:
                    await context.bot.pin_chat_message(
                        chat_id=ch, message_id=msg_id, disable_notification=True,
                    )
                except Exception as e:
                    logger.error(f"cdb: pin в {ch} НЕ УДАЛСЯ: {e}")
                    pin_ok = False
                    pin_warn.append(
                        f"{ch}: не удалось ЗАКРЕПИТЬ снапшот — при старте бот "
                        "прочитает СТАРЫЙ закреп. Проверьте права бота на "
                        "закрепление сообщений в канале.")
                if not pin_ok:
                    fail_ch.append(f"{ch}: пин не удался (файл в канале, но указатель не обновлён)")
                    continue
                # ВОЛНА 12: свежий снапшот закреплён → старые СТИРАЕМ
                # (best-effort), чтобы в канале остался ОДИН актуальный.
                # Источники старых id: cdb_sent (наш список) + предыдущая
                # запись реестра (msg_id прошлого снапшота — работает и для
                # ПЕРВОГО слива после обновления, когда cdb_sent ещё пуст).
                _old_ids = list(cdb_sent.get(str(ch), []))
                _prev_reg = (registry.get(str(ch)) or {}).get("msg_id")
                if _prev_reg:
                    try:
                        _old_ids.append(int(_prev_reg))
                    except (TypeError, ValueError):
                        pass
                for _old in _old_ids:
                    if int(_old) == int(msg_id):
                        continue
                    try:
                        await context.bot.delete_message(chat_id=ch, message_id=int(_old))
                        pruned_n += 1
                    except Exception:
                        pass
                cdb_sent[str(ch)] = [int(msg_id)]
                registry[str(ch)] = {
                    "msg_id": msg_id,
                    "file_id": res.get("file_id"),
                    "ts": now.strftime("%Y-%m-%d %H:%M:%S"),
                    "size": len(payload),
                    "users": meta.get("users", 0),
                }
                ok_ch.append(ch)
            except Exception as e:
                fail_ch.append(f"{ch}: {e}")
        if ok_ch:
            _CDB_DIRTY.clear()
            cfg["cdb_registry"] = registry
            cfg["cdb_sent"] = cdb_sent
            cfg["cdb_last_flush"] = now.strftime("%Y-%m-%d %H:%M:%S")
            save_storage_config(cfg)
            import time as _time
            _CDB_LAST_FLUSH_MONO = _time.monotonic()
            report = (f"✅ Снапшот базы слит в канал(ы): {', '.join(map(str, ok_ch))} "
                      f"({len(payload)} байт, файлов данных {files_n}, {stamp})")
            if pruned_n:
                report += f" • 🧹 старых снапшотов стёрто: {pruned_n} (остался один актуальный)"
            if reason:
                report += f" • причина: {reason}"
            if fail_ch:
                report += f"\n⚠️ Не удалось: {'; '.join(fail_ch[:3])}"
            if pin_warn:
                report += "\n⚠️ " + ";\n⚠️ ".join(pin_warn[:2])
            logger.info(f"cdb flush: {report}")
            return True, report
        return False, "❌ Снапшот не загрузился ни в один канал: " + "; ".join(fail_ch[:3])


async def _cdb_flush_tick(context):
    """Тикер канал-БД: раз в 30 сек проверяет «грязь» и сливает не чаще
    CDB_MIN_FLUSH_INTERVAL. Любая ошибка гасится — тикер не должен падать."""
    try:
        if not _CDB_DIRTY:
            return
        ok, report = await _cdb_flush(context, force=False, reason="авто")
        if not ok:
            logger.warning(f"cdb tick: {report}")
    except Exception as e:
        logger.error(f"cdb tick crashed: {e}")


def _vault_flush_soon(context, reason="сейф"):
    """ВОЛНА 17: НЕМЕДЛЕННЫЙ слив базы в канал фоном после ключевых событий
    Сейфа (настройка пароля+вопросов, смена, восстановление доступа, шифрование
    пачки). Просьба пользователя: «бот должен запоминать пароль от сейфа и
    три секретных вопроса» — раньше связка ключей могла не доехать до канала,
    если бот перезапустился в первые 30 секунд после настройки. Фоновая задача
    tracked в bot_data._bg_tasks, ошибки гасятся."""
    try:
        task = asyncio.create_task(
            _cdb_flush(context, force=True, reason=reason))
        _bd = getattr(getattr(context, "application", None), "bot_data", None)
        if isinstance(_bd, dict):
            _bd.setdefault("_bg_tasks", []).append(task)
        return task
    except Exception as e:
        logger.warning(f"vault flush soon: {e}")
        return None


async def _cdb_recall(context, suppress_dirty: bool = True):
    """ВОЛНА 10: «ВСПОМНИТЬ ВСЁ» — вытянуть базу ИЗ КАНАЛА по требованию.

    Отличия от восстановления на старте (волна 8):
    • проверяются ВСЕ db-каналы и берётся САМЫЙ СВЕЖИЙ закреплённый снапшот
      (сравнение по штампу _meta.json created_utc), а не первый попавшийся;
    • снапшот везёт в себе конфиг каналов — после слияния бот вспоминает
      ВСЕ каналы, а не только тот, откуда читал;
    • подробный человекочитаемый отчёт: сколько юзеров/классов/файлов
      Сейфов вернулось из канала.

    suppress_dirty=True гасит «грязь» после применения (данные только что
    пришли из канала — заливать их обратно немедленно незачем).

    Возвращает (ok: bool, отчёт: str)."""
    # ВОЛНА 13: снапшот мог быть ВСТАВЛЕН пользователем и закреплён в любом
    # канале-хранилище («я буду вставлять файлы из канала последние») —
    # сканируем db-каналы ПЕРВЫМИ, затем cloud-only; побеждает самый свежий.
    db_ids = get_db_channel_ids()
    _seen_ids = set(db_ids)
    for _c in get_cloud_channel_ids():
        if _c not in _seen_ids:
            _seen_ids.add(_c)
            db_ids.append(_c)
    if not db_ids:
        return False, ("Нет каналов-хранилищ (🗄️ База данных / ☁️ Облако / "
                       "🔀 Оба) — вспоминать нечего.")
    bot = context.bot
    best = None  # (created_utc, payload, fname, ch, pinned_msg_id, doc_file_id)
    for ch in db_ids:
        try:
            chat = await bot.get_chat(ch)
        except Exception as e:
            logger.warning(f"cdb recall: get_chat({ch}) не удался: {e}")
            continue
        pinned = getattr(chat, "pinned_message", None)
        doc = getattr(pinned, "document", None) if pinned is not None else None
        fname = str(getattr(doc, "file_name", "") or "")
        if doc is None or not fname.startswith(CDB_SNAPSHOT_PREFIX):
            logger.info(f"cdb recall: в канале {ch} нет закреплённого снапшота.")
            continue
        try:
            tg_file = await bot.get_file(doc.file_id)
            buf = io.BytesIO()
            await asyncio.wait_for(
                tg_file.download_to_memory(out=buf), timeout=300,
            )
            payload = buf.getvalue()
        except Exception as e:
            logger.error(f"cdb recall: не удалось скачать снапшот из {ch}: {e}")
            continue
        # Верификация: НАШ zip с _meta.json + штамп времени для выбора свежего.
        stamp = ""
        try:
            zf = zipfile.ZipFile(io.BytesIO(payload))
            if "_meta.json" not in zf.namelist():
                raise ValueError("нет _meta.json")
            try:
                stamp = str(json.loads(
                    zf.read("_meta.json").decode("utf-8")
                ).get("created_utc") or "")
            except Exception:
                stamp = ""
            zf.close()
        except Exception as e:
            logger.error(f"cdb recall: снапшот в {ch} битый ({e}) — скип.")
            continue
        if best is None or stamp > best[0]:
            best = (stamp, payload, fname, ch,
                    getattr(pinned, "message_id", None), doc.file_id)
    if not best:
        return False, ("В db-каналах нет закреплённого снапшота DEVORKS+ "
                       "(имя файла начинается с «" + CDB_SNAPSHOT_PREFIX + "»).")
    stamp, payload, fname, ch, msg_id, file_id = best
    # Сериализация со сливом: пока применяем снапшот, тикер не должен
    # параллельно заливать в канал «полустарую» базу.
    async with _get_cdb_flush_lock():
        restored, problems = _storage_restore_apply(payload)
        if not restored:
            if problems:
                return False, ("Из снапшота ничего не восстановлено: "
                               + "; ".join(problems[:3]))
            return False, "Из снапшота ничего не восстановлено."
        if suppress_dirty:
            _CDB_DIRTY.clear()
        # Запоминаем указатель на восстановленный снапшот в локальном
        # реестре (для статуса панели).
        try:
            cfg = load_storage_config()
            reg = dict(cfg.get("cdb_registry") or {})
            reg[str(ch)] = {
                "msg_id": msg_id,
                "file_id": file_id,
                "ts": stamp,
                "size": len(payload),
            }
            cfg["cdb_registry"] = reg
            if stamp:
                cfg["cdb_last_flush"] = stamp
            save_storage_config(cfg)
        except Exception as e:
            logger.warning(f"cdb recall: реестр не обновлён: {e}")
    report = _cdb_recall_report(restored, problems, fname, ch, len(payload))
    logger.info(f"cdb recall: {report}")
    return True, report


def _cdb_recall_report(restored, problems, fname, ch, size):
    """ВОЛНА 10: человекочитаемый отчёт «что вспомнили из канала»."""
    lines = [
        f"📦 База вспомнена из канала {ch}",
        f"• Снапшот: {fname} ({_fmt_bytes(size)})",
    ]
    try:
        users = load_users()
        users_n = len(users)
        vault_n = 0
        legacy_n = 0
        bd_n = 0
        for u in users.values():
            vault_n += len([f for f in (getattr(u, 'vault_files', []) or [])
                            if isinstance(f, dict)])
            legacy_n += len([f for f in (getattr(u, 'cloud_files', []) or [])
                             if isinstance(f, dict)])
            if getattr(u, 'birthday', None):
                bd_n += 1
        lines.append(f"• Пользователей: {users_n} • дней рождения: {bd_n}")
        lines.append(f"• Файлов в Сейфах: {vault_n} (шифры целы — нужен пароль)")
        if legacy_n:
            lines.append(f"• Старых файлов без шифра: {legacy_n}")
    except Exception:
        pass
    try:
        lines.append(f"• Классов: {len(load_classes())}")
    except Exception:
        pass
    try:
        timers = load_data(TIMERS_FILE, []) or []
        lines.append(f"• Таймеров: {len(timers) if isinstance(timers, list) else '?'}")
    except Exception:
        pass
    data_files = [r for r in restored if not str(r).startswith("storage_config.json")]
    cfg_rows = [r for r in restored if str(r).startswith("storage_config.json")]
    lines.append(f"• Файлов данных восстановлено: {len(data_files)}")
    if cfg_rows:
        lines.append(f"• {cfg_rows[0]}")
    if problems:
        lines.append(f"⚠️ Проблемы: {'; '.join(problems[:3])}")
    return "\n".join(lines)


async def _boot_dev_restore_hint(application, ok: bool, report: str = ""):
    """ВОЛНА 11: при старте на ПУСТОЙ базе шлём разработчику сообщение с
    кнопками быстрого восстановления («дать каналы» / «вспомнить всё»)."""
    if not DEVELOPER_ID:
        return
    try:
        dev_chat = int(str(DEVELOPER_ID).strip())
    except (TypeError, ValueError):
        return
    try:
        if ok:
            text = ("✅ Бот запустился на ПУСТОЙ базе и ВСПОМНИЛ ВСЁ ИЗ КАНАЛА.\n\n"
                    + str(report or "")[:2500]
                    + "\n\nПроверьте данные: 🔐 Сейф, классы, ДЗ. Если что-то не так — "
                      "🛠️ Панель разработчика → ☁️ Хранилище.")
            kb = None
        else:
            text = (
                "♻️ ВНИМАНИЕ: бот запущен с ПУСТОЙ базой — он сейчас ничего не помнит.\n\n"
                f"{str(report or '')[:800]}\n\n"
                "Быстрое восстановление в два нажатия:\n"
                "1) «🔗 Дать каналы» → «➕ Подключить новый канал» → перешлите сообщение "
                "из вашего канала-хранилища (или отправьте -100…id / @username) и "
                "выберите режим 🗄️/☁️/🔀.\n"
                "2) «📦 Вспомнить всё из канала» — бот возьмёт самый свежий закреплённый "
                "снапшот и вернёт ВСЁ: пользователей, классы, ДЗ, файлы Сейфов "
                "(пароль тот же), таймеры, настройки.\n\n"
                "Совет: задайте env STORAGE_CHANNELS=\"-100…,-100…\" — тогда после "
                "деплоя каналы подключатся сами и бот вспомнит всё без кнопок.")
            kb = InlineKeyboardMarkup([
                [InlineKeyboardButton("📦 Вспомнить всё из канала", callback_data="dev_cdb_recall")],
                [InlineKeyboardButton("🔗 Дать каналы", callback_data="dev_recall_quick")],
            ])
        await application.bot.send_message(chat_id=dev_chat, text=text, reply_markup=kb)
    except Exception as e:
        logger.info(f"boot hint: сообщение разработчику не отправлено: {e}")


async def _cdb_restore_on_boot(application):
    """ВОЛНА 8/10: восстановление базы ИЗ КАНАЛА при старте.

    ВОЛНА 10 — два честных триггера:
    1. Режим «База в канале» включён → канал первичен, снапшот перезаписывает
       локальный кэш (как и раньше).
    2. Режим ВЫКЛЮЧЕН, но локальная база ПУСТА (юзеров нет — свежий сервер
       после обновления/переезда) → всё равно вспоминаем из канала. Это тот
       самый случай «обновил бота — а он всё забыл»: больше так не будет.

    Если каналов нет или в них нет закреплённого снапшота — работаем на
    локальном кэше, как раньше; при первом же изменении база уйдёт в канал.

    Вызывается из _post_init в фоне, чтобы не мешать старту."""
    try:
        cfg = load_storage_config()
        enabled = bool(cfg.get("channel_db_enabled"))
        # Пустая база = файла пользователей нет вовсе (свежий сервер/диск).
        empty_base = not os.path.exists(str(USERS_FILE))
        if not enabled and not empty_base:
            logger.info("cdb boot: режим выключен, локальная база на месте — скип.")
            return
        db_ids = get_db_channel_ids()
        if not db_ids:
            logger.info("cdb boot: db-каналов нет — скип.")
            if empty_base:
                # ВОЛНА 11: свежий сервер без каналов — разработчику кнопки
                # быстрого восстановления («дать каналы»). Раньше он узнавал
                # о потере памяти только сам, наткнувшись на пустой Сейф.
                await _boot_dev_restore_hint(
                    application, ok=False,
                    report="Каналы-хранилища не заданы — вспомнить не из чего.")
            return
        class _CtxStub:
            bot = application.bot
        ok, report = await _cdb_recall(_CtxStub(), suppress_dirty=True)
        if ok:
            logger.info(f"cdb boot: ВСПОМНИЛИ ВСЁ ИЗ КАНАЛА:\n{report}")
            if empty_base:
                await _boot_dev_restore_hint(application, ok=True, report=report)
        else:
            logger.info(f"cdb boot: восстановление не состоялось: {report}")
            if empty_base:
                await _boot_dev_restore_hint(application, ok=False, report=report)
    except Exception as e:
        logger.error(f"cdb boot crashed: {e}")


async def _post_shutdown(application):
    """Финальный слив базы в канал при остановке бота (best-effort).

    Render/хостинг может убить процесс жёстко — тогда спасёт тикер (30 сек).
    Но штатный рестарт получит свежий снапшот именно здесь."""
    try:
        # ВОЛНА 22.14: сперва принудительно сливаем счётчики функций
        # (троттлинг 60 с мог «подержать» последние инкременты в памяти),
        # чтобы финальный снапшот канала содержал самые свежие цифры.
        _stat_flush(force=True)
    except Exception as e:
        logger.error(f"post_shutdown: stat flush не удался: {e}")
    try:
        class _CtxStub:
            bot = application.bot
        ok, report = await _cdb_flush(_CtxStub(), force=True, reason="остановка бота")
        logger.info(f"post_shutdown: {report}")
    except Exception as e:
        logger.error(f"post_shutdown: финальный слив не удался: {e}")


# ==================================
# === ЛИЧНОЕ ОБЛАКО («☁️ Облако») ===
# ==================================

CLOUD_BUTTON = "☁️ Облако"

# Расширения и mime-типы, которые ZIP сжимает сильно (текст/данные).
# Фото, видео и аудио уже сжаты форматами — честно не обещаем экономии.
_COMPRESSIBLE_EXTS = (
    ".txt", ".md", ".csv", ".tsv", ".log", ".json", ".xml", ".yaml", ".yml",
    ".py", ".js", ".html", ".htm", ".css", ".sql", ".ini", ".cfg", ".bat",
    ".docx", ".xlsx", ".pptx", ".svg", ".rtf", ".epub", ".fb2",
)

def _is_compressible_name(name: str, mime: str = "") -> bool:
    """True для текстовых/документных файлов — ZIP сожмёт их в разы."""
    n = (name or "").lower()
    if any(n.endswith(ext) for ext in _COMPRESSIBLE_EXTS):
        return True
    m = (mime or "").lower()
    return m.startswith("text/") or m in (
        "application/json", "application/xml", "application/javascript",
        "application/rtf", "application/sql",
    )


def _zip_bytes_for(name: str, data: bytes) -> bytes:
    """ВОЛНА 8/9: бот САМ заворачивает файл в ZIP (по кнопке пользователя).

    Архивация всегда БЕЗ потерь (это важно: пользователь просил «без потери
    качества»). ВОЛНА 22.36: метод сжатия DEFLATED вместо ZIP_LZMA — LZMA
    внутри ZIP НЕ понимают Windows Explorer и большинство мобильных
    архиваторов, они честно рапортуют «архив/контейнер повреждён», хотя
    архив цел. DEFLATE открывается ВЕЗДЕ и так же восстанавливает файл
    байт-в-байт; для уже сжатых форматов (фото/видео/музыка) разница в
    размере минимальна."""
    buf = io.BytesIO()
    with zipfile.ZipFile(buf, "w", compression=zipfile.ZIP_DEFLATED) as zf:
        zf.writestr(name or "file.bin", data)
    return buf.getvalue()


def _cloud_display_name(msg, att, kind: str, ts_fn: str = ""):
    """ВОЛНА 8: имя файла облака с учётом ПОДПИСИ (caption).

    Пользователь просил «подписывать можно было»: если к файлу есть подпись —
    она становится именем файла в облаке (расширение из оригинала сохраняем,
    если подпись его не содержит). Без подписи — прежнее поведение."""
    ts_fn = ts_fn or datetime.now().strftime("%Y-%m-%d_%H-%M")
    caption = str(getattr(msg, "caption", "") or "").strip()
    orig_name = str(getattr(att, "file_name", "") or "")
    ext = ""
    if orig_name and "." in orig_name:
        ext = orig_name[orig_name.rfind("."):].lower()[:12]
    if caption:
        name = caption[:120]
        # Если в подписи уже есть своё расширение («Отчёт.pdf») — не наращиваем
        # расширение оригинала, иначе получим «Отчёт.pdf.txt».
        has_own_ext = "." in name and (len(name) - name.rfind(".")) <= 6
        if ext and not has_own_ext and not name.lower().endswith(ext):
            name += ext
        return name
    if kind == "photo":
        return getattr(att, "file_name", None) or f"Фото_{ts_fn}.jpg"
    if kind == "document":
        return orig_name or f"Документ_{ts_fn}"
    if kind == "video":
        return orig_name or f"Видео_{ts_fn}.mp4"
    if kind == "audio":
        return orig_name or f"Аудио_{ts_fn}.mp3"
    return f"Голосовое_{ts_fn}.ogg"


def _cloud_item_from_message(msg):
    """ВОЛНА 8: извлекает медиа-элемент из сообщения (для одиночных файлов
    и для АЛЬБОМОВ/media group). Возвращает dict или None, если медиа нет:
    {kind, file_id, size, mime, name}."""
    att = None
    kind = None
    if getattr(msg, "photo", None):
        att = msg.photo[-1]
        kind = "photo"
    elif getattr(msg, "document", None):
        att = msg.document
        kind = "document"
    elif getattr(msg, "video", None):
        att = msg.video
        kind = "video"
    elif getattr(msg, "audio", None):
        att = msg.audio
        kind = "audio"
    elif getattr(msg, "voice", None):
        att = msg.voice
        kind = "voice"
    if att is None:
        return None
    return {
        "kind": kind,
        "file_id": att.file_id,
        "size": int(getattr(att, "file_size", 0) or 0),
        "mime": str(getattr(att, "mime_type", "") or ""),
        "name": _cloud_display_name(msg, att, kind),
    }


def _big_file_advice_text(fsize: int = 0) -> str:
    """Честный текст для файлов >49 МБ (лимит Telegram Bot API на отправку).

    По запросу пользователя: бот ПРЕДЛАГАЕТ завернуть файл в ZIP (без потери
    качества) или разбить на части, и объясняет, что сожмётся, а что нет.
    ВОЛНА 8: добавлен пункт 0 — загрузка БОЛЬШИХ файлов МИМО бота, прямо
    в канал (пользователь может слать в канал до 2 ГБ!). Бот не скачивает
    такой файл — только записывает его в ваш список по закреплённой подсказке."""
    size_line = f" ({_fmt_bytes(fsize)})" if fsize else ""
    return (
        f"🚫 Файл{size_line} больше 49 МБ — Telegram запрещает ботам ОТПРАВЛЯТЬ "
        "такие файлы. Но есть пути:\n\n"
        "0️⃣ 📤 ОТПРАВИТЬ В КАНАЛ НАПРЯМУЮ (лучший путь для больших файлов):\n"
        "нажмите кнопку «📤 Отправить в канал самому» ниже — я дам ссылку на "
        "хранилище и буду ждать ваш файл. В канал Telegram разрешает грузить "
        "ДО 2 ГБ одним файлом. Я не смогу скачать его обратно (лимит ботов — "
        "20 МБ на скачивание), но в ОБЛАКЕ он будет: список, подпись, выдача "
        "себе и другим через бот работают как обычно.\n\n"
        "1️⃣ 🗜 ЗАВЕРНИТЕ В ZIP — качество НЕ пострадает (архивация всегда "
        "без потерь):\n"
        "• текст, документы, таблицы (txt/docx/xlsx/csv…) сожмутся в 3–10 раз;\n"
        "• фото, видео и аудио почти НЕ сожмутся — они уже сжаты своими "
        "форматами, ZIP лишь «завернёт» их.\n\n"
        "2️⃣ ✂️ Если и в ZIP больше 49 МБ — разбейте архив на ЧАСТИ по 45 МБ "
        "(7-Zip: «Добавить к архиву» → «Разделить на томы»; ZArchiver/WinRAR "
        "умеют то же) и пришлите части подряд — я сохраню каждую. Собрать "
        "обратно просто: скачайте все части в одну папку и распакуйте первую "
        "— архиватор сам склеит.\n\n"
        "3️⃣ 🔐 В Сейф (с шифрованием паролем) кладутся файлы до 20 МБ — "
        "такой лимит у Telegram на СКАЧИВАНИЕ ботами, обойти его честно нельзя."
    )


def get_big_file_keyboard():
    """ВОЛНА 8: кнопки при отказе на файл >49 МБ (совет + прямой путь в канал)."""
    return InlineKeyboardMarkup([
        [InlineKeyboardButton("📤 Отправить в канал самому", callback_data="cloud_bigself")],
        [InlineKeyboardButton("⬅️ Назад в меню", callback_data="cloud_exit")],
    ])


def _cloud_menu_text(user):
    # ВОЛНА 9: облако = Сейф. Показываем статистику Сейфа и честно напоминаем
    # про старые незашифрованные файлы (их можно перенести в Сейф кнопкой 🔐).
    vault_files = [f for f in (getattr(user, "vault_files", []) or []) if isinstance(f, dict)]
    legacy = [f for f in (getattr(user, "cloud_files", []) or []) if isinstance(f, dict)]
    _uch = _user_vault_channel(user)
    if not get_cloud_channel_ids() and not _uch:
        return (
            "☁️ Облако (всё в Сейфе)\n\n"
            "❌ Общее хранилище пока не подключено: разработчик ещё не задал "
            "приватный канал. НО вы можете начать прямо сейчас: подключите "
            "СВОЙ канал — 🔗 Моё облако → «➕ Подключить мой канал». Как "
            "только канал будет подключен, здесь появится бесплатное "
            "хранилище: файлы шифруются вашим паролем и только потом уходят "
            "в канал."
        )
    total_enc = sum(int(f.get("size_enc", 0) or 0) for f in vault_files)
    total_legacy = sum(int(f.get("size", 0) or 0) for f in legacy)
    limit = get_price('cloud_max_files', 50)
    lines = [
        "☁️ Облако — всё в Сейфе\n\n"
        f"🔐 В Сейфе: {len(vault_files)} файл(ов) • {_fmt_bytes(total_enc)} шифра\n"
        + (f"☁️ Хранилище: ВАШ личный канал «{_uch[1]}»"
           if _uch else
           f"☁️ Каналов-хранилищ: {len(get_cloud_channel_ids())} • лимит: {limit} шт"),
    ]
    if legacy:
        lines.append(
            f"🗂 Без шифра (старых): {len(legacy)} • {_fmt_bytes(total_legacy)} — "
            "перенесите их в Сейф кнопкой 🔐 у файла"
        )
    lines.append("")
    lines.append(
        "ФАЙЛЫ ВСЕГДА ЖИВУТ В СЕЙФЕ: перед отправкой в приватный канал каждый "
        "файл шифруется вашим паролем (AES-256). В канале — только шум; открыть "
        "не сможет никто: ни разработчик, ни Telegram. Забыли пароль — вернёте "
        "доступ по своим 3 секретным вопросам."
    )
    lines.append("")
    lines.append("Выберите действие:")
    return "\n".join(lines)


def get_cloud_menu_keyboard(user=None):
    """ВОЛНА 9: файлы всегда живут в Сейфе облака.

    • «🔐 Сейф» — первый пункт (шифрованное хранилище);
    • «📤 Загрузить в Сейф» — новая загрузка идёт ТОЛЬКО через шифрование;
    • «📁 Файлы без шифра» — появляется ТОЛЬКО если есть незашифрованные файлы
      (ВОЛНА 22.33: прежнее «🗂 Старые файлы» переименовано — сюда попадают и
      загрузки из мини-аппа при выключенном шифровании, и файлы прежних
      версий; их можно выдать, за-ZIP-ить или перенести в Сейф)."""
    legacy = 0
    if user is not None:
        legacy = len([f for f in (getattr(user, "cloud_files", []) or []) if isinstance(f, dict)])
    rows = [
        [InlineKeyboardButton("🔐 Сейф (файлы под паролем)", callback_data="vault_menu")],
        [InlineKeyboardButton("📤 Загрузить в Сейф", callback_data="vault_put")],
        # ВОЛНА 22.20: своя настройка облака — личный канал пользователя.
        [InlineKeyboardButton("🔗 Моё облако", callback_data="vault_cloud")],
        # ВОЛНА 22.29: веб-пароль — вход в Веб-облако из обычного браузера
        # по Telegram ID + паролю (без Telegram/VPN).
        [InlineKeyboardButton("🔑 Веб-пароль", callback_data="web_password_menu")],
    ]
    if legacy:
        # ВОЛНА 22.33: «Старые файлы» → «Файлы без шифра». Файл, загруженный
        # в мини-аппе при выключенном шифровании, лежит ИМЕННО здесь — старое
        # название («старые») сбивало с толку: пользователь искал его в
        # «📦 Мои файлы» (Сейф) и решал, что синхронизация сломана.
        rows.append([InlineKeyboardButton(
            f"📁 Файлы без шифра ({legacy})", callback_data="cloud_files")])
    if MINIAPP_URL:
        # ВОЛНА 22.19 (C.4): веб-облако (Mini App) — открывается прямо в
        # Telegram. Кнопка появляется ТОЛЬКО если задан MINIAPP_URL (env):
        # без адреса мёртвую кнопку не показываем («галочка ровно на месте»).
        rows.append([InlineKeyboardButton(
            "🌐 Веб-облако (Mini App)", web_app=WebAppInfo(url=MINIAPP_URL))])
    rows.append([InlineKeyboardButton("❓ Как это работает", callback_data="cloud_help")])
    rows.append([InlineKeyboardButton("⬅️ Назад", callback_data="back_to_main")])
    return InlineKeyboardMarkup(rows)


def get_cloud_files_keyboard(user):
    """ВОЛНА 8/9: по файлу — ряд [📥 имя], под ним [📦 ZIP] [🔐] [✏️] [🗑].
    📦 — бот сам заворачивает файл в ZIP (LZMA, без потерь),
    🔐 — перенести файл в Сейф (зашифровать и удалить незашифрованный оригинал),
    ✏️ — переименовать (подпись можно задать и при загрузке)."""
    files = [f for f in (getattr(user, "cloud_files", []) or []) if isinstance(f, dict)]
    kb = []
    for rec in files[:15]:
        name = str(rec.get("name") or "файл")
        size = _fmt_bytes(rec.get("size", 0))
        label = f"{name[:34]} ({size})"
        kb.append([InlineKeyboardButton(f"📥 {label}", callback_data=f"cloud_get_{rec.get('id')}")])
        kb.append([
            InlineKeyboardButton("📦 ZIP", callback_data=f"cloud_zip_{rec.get('id')}"),
            InlineKeyboardButton("🔐", callback_data=f"cloud_mv_{rec.get('id')}"),
            InlineKeyboardButton("✏️", callback_data=f"cloud_ren_{rec.get('id')}"),
            InlineKeyboardButton("🗑", callback_data=f"cloud_del_{rec.get('id')}"),
        ])
    if not kb:
        kb.append([InlineKeyboardButton("📤 Загрузить в Сейф", callback_data="vault_put")])
    kb.append([InlineKeyboardButton("⬅️ Назад", callback_data="cloud_menu")])
    return InlineKeyboardMarkup(kb)


def _cloud_files_text(user):
    files = [f for f in (getattr(user, "cloud_files", []) or []) if isinstance(f, dict)]
    if not files:
        return ("📁 Незашифрованных файлов нет — всё в Сейфе 👍\n\n"
                "Новые файлы загружайте так: ☁️ Облако → 📤 Загрузить в Сейф.")
    limit = get_price('cloud_max_files', 50)
    total = sum(int(f.get("size", 0) or 0) for f in files)
    shown = files[:30]
    # ВОЛНА 22.33: заголовок без слова «СТАРЫЕ» — раздел общий и для файлов
    # прежних версий, и для загрузок из мини-аппа (режим «без шифра»).
    lines = [f"📁 ФАЙЛЫ БЕЗ ШИФРА ({len(files)}/{limit} • {_fmt_bytes(total)}):", ""]
    for rec in shown:
        # ВОЛНА 22.21: 🔒 — файл отмечен в Веб-облаке (Mini App) как Vault
        # (отдельная папка просмотра, НЕ шифрование Сейфа).
        _mv = "🔒 " if rec.get("va") else ""
        lines.append(f"• {_mv}{rec.get('name', '?')} — {_fmt_bytes(rec.get('size', 0))} ({_rec_ts_display(rec)})")
    if len(files) > len(shown):
        lines.append(f"…и ещё {len(files) - len(shown)} шт.")
    lines.append("")
    lines.append("📥 — выдать файл; 📦 — за-ZIP-ить (открывается везде, без потерь); "
                 "🔐 — перенести в Сейф (зашифрую и удалю оригинал); 🗑 — удалить.")
    if any(isinstance(f, dict) and f.get("va") for f in files):
        lines.append("🔒 — файлы, отмеченные «Vault» в 🌐 Веб-облаке (Mini App): "
                     "это их отдельная папка просмотра, шифрованием Сейфа она не является.")
    # ВОЛНА 22.33: подсказка про синхронизацию с мини-аппом (режим без шифра).
    if _user_vault_channel(user) is not None and _vault_channel_plain(user):
        lines.append("")
        lines.append("🌐 В этот список попадают и файлы, загруженные в мини-аппе "
                     "при выключенном шифровании. Включите шифрование — новые "
                     "загрузки из веба будут попадать в Сейф («📦 Мои файлы»), "
                     "как из чата.")
    return "\n".join(lines)


@timeout(CONVERSATION_TIMEOUT)
async def cloud_menu_start(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Вход в облако кнопкой главного меню «☁️ Облако»."""
    user_id = str(update.effective_user.id)
    user = get_user(user_id)
    if not user:
        await update.message.reply_text("Сначала зарегистрируйтесь — отправьте /start.")
        return MAIN_MENU
    # Выход из режима загрузки (если ранее был включён).
    context.user_data.pop('cloud_file_mode', None)
    await update.message.reply_text(_cloud_menu_text(user), reply_markup=get_cloud_menu_keyboard(user))
    return MAIN_MENU


async def cloud_menu_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await query.answer()
    user = get_user(str(query.from_user.id))
    if not user:
        await query.answer("Сначала зарегистрируйтесь — /start", show_alert=True)
        return MAIN_MENU
    context.user_data.pop('cloud_file_mode', None)
    try:
        await query.edit_message_text(_cloud_menu_text(user), reply_markup=get_cloud_menu_keyboard(user))
    except Exception:
        await query.message.reply_text(_cloud_menu_text(user), reply_markup=get_cloud_menu_keyboard(user))
    return MAIN_MENU


