async def cloud_upload_start(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """ВОЛНА 9: обычной (незашифрованной) загрузки больше НЕТ — «файлы всегда
    должны быть в сейфе облака». Перенаправляем в поток шифрования Сейфа.
    Сама функция оставлена, чтобы не сломать старые вызовы/ссылки."""
    return await vault_put_start(update, context)


@timeout(CONVERSATION_TIMEOUT)
async def cloud_upload_receive(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Принимает файл(ы) в режиме загрузки и кладёт их в приватный канал.

    ВОЛНА 8:
    • АЛЬБОМЫ (media group) и несколько файлов подряд собираются в ПАЧКУ
      (дебаунс 1.6 сек) и грузятся одним сообщением-итогом — «сгруппированно
      или сразу много файлов» по просьбе пользователя.
    • ПОДПИСЬ (caption) файла становится его именем в облаке.
    • Файл НЕ скачивается — бот пересылает его в канал по file_id
      (Telegram разрешает ботам переотправку), в БД — только указатели."""
    msg = update.message
    user_id = str(update.effective_user.id)
    user = get_user(user_id)
    if not user:
        context.user_data.pop('cloud_file_mode', None)
        await msg.reply_text("Сначала зарегистрируйтесь — отправьте /start.")
        return ConversationHandler.END
    if not get_cloud_channel_ids():
        context.user_data.pop('cloud_file_mode', None)
        await msg.reply_text(
            "❌ Хранилище отключено — файл не сохранён. Попросите разработчика "
            "настроить канал заново.",
            reply_markup=get_main_menu_keyboard(user),
        )
        return MAIN_MENU

    item = _cloud_item_from_message(msg)
    if item is None:
        await msg.reply_text(
            "☁️ Отправьте именно ФАЙЛ: документ, фото, видео или аудио. "
            "Можно сразу НЕСКОЛЬКО файлов или альбом — я соберу всё пачкой. "
            "Чтобы выйти — нажмите «⬅️ Назад в меню»."
        )
        return CLOUD_UPLOAD_WAIT
    # ВОЛНА 22.36: честная подсказка про качество (раз за разом спрашивали,
    # «почему съедается качество»): Telegram сжимает медиа ещё НА ТЕЛЕФОНЕ,
    # до бота — фотку из галереи «как фото» бот получает уже сжатой.
    if getattr(msg, "photo", None) or getattr(msg, "video", None):
        await msg.reply_text(
            "💡 Совет: Telegram сжал это медиа ещё на телефоне — бот получил "
            "уже сжатую копию и сохраняет её без дальнейших потерь. Чтобы "
            "хранить ОРИГИНАЛ без потери качества — отправляйте фото/видео "
            "как ФАЙЛ (📎 «Файл» в меню вложений) или через мини-апп.")

    # === АЛЬБОМ / ПАЧКА ===
    mgid = getattr(msg, "media_group_id", None)
    if mgid:
        batches = context.user_data.setdefault('cloud_batch', {})
        batch = batches.setdefault(str(mgid), [])
        batch.append(item)
        # Дебаунс: Telegram присылает альбом несколькими сообщениями подряд
        # (в пределах ~1 сек). Кто первый подождал 1.6 сек — тот и грузит
        # всю пачку. Остальные задачи видят, что их список «забрали», и
        # молча выходят.
        await asyncio.sleep(1.6)
        current = context.user_data.get('cloud_batch', {}).get(str(mgid))
        if current is not batch:
            return CLOUD_UPLOAD_WAIT  # нас опередили — грузит другая задача
        context.user_data.get('cloud_batch', {}).pop(str(mgid), None)
        items = list(batch)
    else:
        items = [item]

    return await _cloud_upload_items(update, context, items)


async def _cloud_upload_items(update: Update, context: ContextTypes.DEFAULT_TYPE, items):
    """ВОЛНА 8: грузит пачку элементов в cloud-каналы ПО КРУГУ и пишет один
    честный итог. Возвращает состояние для ConversationHandler."""
    msg = update.message
    user_id = str(update.effective_user.id)
    user = get_user(user_id)
    if not user:
        return ConversationHandler.END
    cloud_ids = get_cloud_channel_ids()
    if not cloud_ids:
        context.user_data.pop('cloud_file_mode', None)
        await msg.reply_text(
            "❌ Хранилище отключено. Попросите разработчика настроить канал заново.",
            reply_markup=get_main_menu_keyboard(user),
        )
        return MAIN_MENU
    try:
        _rr = int(load_storage_config().get("cloud_rr", 0) or 0)
    except Exception:
        _rr = 0

    files = [f for f in (getattr(user, 'cloud_files', []) or []) if isinstance(f, dict)]
    limit = get_price('cloud_max_files', 50)

    try:
        await context.bot.send_chat_action(chat_id=update.effective_chat.id, action="upload_document")
    except Exception:
        pass

    saved, skipped_big, failed, limit_hit = [], [], [], False
    for item in items:
        if len(files) >= limit:
            limit_hit = True
            skipped_big.append(item)
            continue
        if item["size"] > STORAGE_MAX_FILE_BYTES:
            # ВОЛНА 8: не просто отказ — кнопка «отправить в канал самому».
            skipped_big.append(item)
            continue
        channel_id = cloud_ids[_rr % len(cloud_ids)]
        kind = item["kind"]
        name = item["name"]
        try:
            if kind == "photo":
                sent = await context.bot.send_photo(chat_id=channel_id, photo=item["file_id"], caption=name[:1024])
                new_file_id = getattr(getattr(sent, "photo", [None])[-1], "file_id", None) if getattr(sent, "photo", None) else None
            elif kind == "video":
                sent = await context.bot.send_video(chat_id=channel_id, video=item["file_id"], caption=name[:1024])
                new_file_id = getattr(getattr(sent, "video", None), "file_id", None)
            elif kind == "audio":
                sent = await context.bot.send_audio(chat_id=channel_id, audio=item["file_id"], caption=name[:1024])
                new_file_id = getattr(getattr(sent, "audio", None), "file_id", None)
            elif kind == "voice":
                sent = await context.bot.send_voice(chat_id=channel_id, voice=item["file_id"], caption=name[:1024])
                new_file_id = getattr(getattr(sent, "voice", None), "file_id", None)
            else:
                sent = await context.bot.send_document(chat_id=channel_id, document=item["file_id"], caption=name[:1024])
                new_file_id = getattr(getattr(sent, "document", None), "file_id", None)
        except TGBadRequest as e:
            failed.append(f"{name[:40]}: Telegram отклонил ({e.message})")
            continue
        except Exception as e:
            logger.error(f"cloud upload: {e}")
            failed.append(f"{name[:40]}: ошибка загрузки")
            continue
        rec = {
            "id": _cloud_gen_file_id(user),
            "name": name[:120],
            "kind": kind,
            "msg_id": int(sent.message_id),
            "file_id": new_file_id,
            "size": item["size"],
            "mime": item.get("mime", ""),
            "ts": _file_ts_now(), "tss": datetime.now().strftime("%Y-%m-%d %H:%M"),
            # ВОЛНА 7: в каком именно канале лежит файл (каналов несколько).
            "channel_id": channel_id,
        }
        files.append(rec)
        saved.append(rec)
        # Продвигаем указатель круговой загрузки между cloud-каналами.
        if len(cloud_ids) > 1:
            _rr = (_rr + 1) % len(cloud_ids)
            try:
                cfg_rr = load_storage_config()
                cfg_rr["cloud_rr"] = _rr
                save_storage_config(cfg_rr)
            except Exception:
                pass

    if saved:
        user.cloud_files = files
        save_user(user)

    lines = []
    if len(saved) == 1:
        r = saved[0]
        lines.append(f"✅ Сохранено в облако: «{r['name']}» ({_fmt_bytes(r['size'])}).")
    elif saved:
        total = sum(r["size"] for r in saved)
        lines.append(f"✅ Сохранено пачкой: {len(saved)} файл(ов), {_fmt_bytes(total)}:")
        for r in saved[:10]:
            lines.append(f"  • {r['name']} ({_fmt_bytes(r['size'])})")
        if len(saved) > 10:
            lines.append(f"  …и ещё {len(saved) - 10} шт.")
    if limit_hit:
        lines.append(f"🚫 Лимит облака ({limit} файлов) достигнут — остальное не влезло. "
                     "Удалите что-нибудь в «📁 Мои файлы» (лимит меняется в панели цен).")
    if skipped_big:
        lines.append(_big_file_advice_text(skipped_big[0]["size"]))
        for item in skipped_big[1:]:
            lines.append(f"🚫 «{item['name'][:40]}» тоже больше 49 МБ.")
    if failed:
        lines.append("⚠️ Не удалось: " + "; ".join(failed[:5]))
    if saved:
        lines.append(f"Файлов в облаке: {len(files)}/{limit}.")
        # Совет ZIP: теперь и с КНОПКОЙ — бот сам завернёт (волна 8).
        big_saved = [r for r in saved if r["size"] >= 512 * 1024
                     and _is_compressible_name(r["name"], r.get("mime", ""))]
        if big_saved:
            kb = InlineKeyboardMarkup([[
                InlineKeyboardButton(f"📦 Завернуть «{big_saved[0]['name'][:24]}» в ZIP",
                                     callback_data=f"cloud_zip_{big_saved[0]['id']}"),
            ]])
            lines.append("💡 Этот файл — текстовый: в ZIP сожмётся в 3–10 раз без потерь. "
                         "Нажмите кнопку — я сделаю ZIP сам.")
            await msg.reply_text("\n".join(lines), reply_markup=kb)
            return CLOUD_UPLOAD_WAIT
    if skipped_big:
        # ВОЛНА 8: отказ с КНОПКОЙ «📤 Отправить в канал самому».
        await msg.reply_text("\n".join(lines), reply_markup=get_big_file_keyboard())
        return CLOUD_UPLOAD_WAIT
    await msg.reply_text("\n".join(lines) if lines else "Нечего сохранять.")
    return CLOUD_UPLOAD_WAIT



async def cloud_files_cb(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await query.answer()
    user = get_user(str(query.from_user.id))
    if not user:
        await query.answer("Сначала зарегистрируйтесь — /start", show_alert=True)
        return MAIN_MENU
    text = _cloud_files_text(user)
    try:
        await query.edit_message_text(text, reply_markup=get_cloud_files_keyboard(user))
    except Exception:
        await query.message.reply_text(text, reply_markup=get_cloud_files_keyboard(user))
    return MAIN_MENU


async def cloud_get_cb(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Выдаёт файл из канала: мгновенная копия сообщения (copy_message),
    при сбое — повторная отправка по сохранённому file_id."""
    query = update.callback_query
    user = get_user(str(query.from_user.id))
    if not user:
        await query.answer("Сначала зарегистрируйтесь — /start", show_alert=True)
        return MAIN_MENU
    fid = query.data.replace("cloud_get_", "", 1)
    rec = _cloud_find_record(user, fid)
    if not rec:
        await query.answer("Файл не найден в вашем облаке.", show_alert=True)
        return MAIN_MENU
    # ВОЛНА 7: файл может лежать в любом из подключённых каналов.
    channel_id = rec.get("channel_id") or get_storage_channel_id()
    if not channel_id:
        await query.answer("Хранилище отключено.", show_alert=True)
        return MAIN_MENU
    await query.answer("Отправляю файл…", show_alert=False)
    chat_id = query.message.chat_id
    try:
        await context.bot.copy_message(
            chat_id=chat_id, from_chat_id=channel_id, message_id=int(rec["msg_id"]),
        )
        return MAIN_MENU
    except Exception as e:
        logger.warning(f"cloud get: copy_message не сработал ({e}), пробую file_id")
    file_id = rec.get("file_id")
    if not file_id:
        await context.bot.send_message(
            chat_id=chat_id,
            text=f"❌ Не удалось выдать «{rec.get('name', '?')}»: файл пропал из канала "
                 "(сообщение удалено) и сохранённого file_id нет.",
        )
        return MAIN_MENU
    kind = rec.get("kind")
    try:
        if kind == "photo":
            await context.bot.send_photo(chat_id=chat_id, photo=file_id, caption=rec.get("name", ""))
        elif kind == "video":
            await context.bot.send_video(chat_id=chat_id, video=file_id, caption=rec.get("name", ""))
        elif kind == "audio":
            await context.bot.send_audio(chat_id=chat_id, audio=file_id, caption=rec.get("name", ""))
        elif kind == "voice":
            await context.bot.send_voice(chat_id=chat_id, voice=file_id, caption=rec.get("name", ""))
        else:
            await context.bot.send_document(chat_id=chat_id, document=file_id, caption=rec.get("name", ""))
    except Exception as e:
        logger.error(f"cloud get: file_id выдача не удалась: {e}")
        await context.bot.send_message(
            chat_id=chat_id,
            text=f"❌ Не удалось выдать «{rec.get('name', '?')}». Возможно, сообщение в "
                 "канале удалено вручную. Попробуйте позже.",
        )
    return MAIN_MENU


