# ==================================
# === ОБЛАКО: ZIP ПО КНОПКЕ, ПЕРЕИМЕНОВАНИЕ, БОЛЬШИЕ ФАЙЛЫ (волна 8) ===
# ==================================

# Окна ожидания «пользователь сам пришлёт большой файл прямо в канал»:
# {user_id: {"channel_id": int, "until": monotonic_сек}}.
import time as _time
_PENDING_BIG_UPLOADS = {}
BIG_UPLOAD_WINDOW_SEC = 30 * 60


def _zip_size_check(rec) -> str | None:
    """Честная проверка возможности ZIP-кнопки: бот может СКАЧАТЬ файл
    только до 20 МБ (лимит Telegram Bot API). Больше — физически нечем."""
    if int(rec.get("size", 0) or 0) > VAULT_MAX_FILE_BYTES:
        return ("🚫 Этот файл больше 20 МБ — Telegram не даёт ботам СКАЧИВАТЬ "
                "такие файлы, поэтому я не могу завершить его в ZIP сам. "
                "Пришлите его сразу в ZIP, или используйте «📤 Отправить в "
                "канал самому» для файла без архива.")
    return None


async def cloud_zip_cb(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """ВОЛНА 8: бот САМ заворачивает файл облака в ZIP (кнопка «📦 ZIP» /
    кнопка после загрузки). Скачивает в ПАМЯТЬ (файлы >20 МБ честно
    отклоняются — лимит Telegram на скачивание ботами), архивирует без
    потерь, заливает архив в ТОТ ЖЕ канал, обновляет запись и удаляет
    оригинал из канала."""
    query = update.callback_query
    user = get_user(str(query.from_user.id))
    if not user:
        await query.answer("Сначала зарегистрируйтесь — /start", show_alert=True)
        return MAIN_MENU
    fid = query.data.replace("cloud_zip_", "", 1)
    rec = _cloud_find_record(user, fid)
    if not rec:
        await query.answer("Файл не найден.", show_alert=True)
        return MAIN_MENU
    too_big = _zip_size_check(rec)
    if too_big:
        await query.answer(too_big, show_alert=True)
        return MAIN_MENU
    if str(rec.get("kind")) != "document":
        # Архивировать можно всё (фото/видео в ZIP — «завёртка» без сжатия):
        # пользователь просил кнопку для любого файла, не запрещаем.
        pass
    await query.answer("Скачиваю и заворачиваю в ZIP…", show_alert=False)
    channel_id = rec.get("channel_id") or get_storage_channel_id()
    if not channel_id:
        await query.answer("Хранилище отключено.", show_alert=True)
        return MAIN_MENU
    try:
        tg_file = await context.bot.get_file(rec.get("file_id"))
        buf = io.BytesIO()
        await asyncio.wait_for(tg_file.download_to_memory(out=buf), timeout=300)
        data = buf.getvalue()
    except Exception as e:
        logger.error(f"cloud zip: скачать файл не удалось: {e}")
        await context.bot.send_message(
            chat_id=query.message.chat_id,
            text="❌ Не смог скачать файл из канала для архивации. Возможно, "
                 "сообщение удалено. Попробуйте позже.",
        )
        return MAIN_MENU
    old_name = str(rec.get("name") or "файл")
    old_msg_id = rec.get("msg_id")  # запоминаем ДО перезаписи — удалим оригинал
    zip_name = old_name if old_name.lower().endswith(".zip") else old_name + ".zip"
    zipped = _zip_bytes_for(old_name, data)
    # Не заворачиваем, если архив вышел крупнее оригинала (уже сжатый файл).
    if len(zipped) >= len(data):
        await context.bot.send_message(
            chat_id=query.message.chat_id,
            text=f"🤷 «{old_name}» уже сжат своим форматом: ZIP ({_fmt_bytes(len(zipped))}) "
                 f"не меньше оригинала ({_fmt_bytes(len(data))}). Оставил как есть — "
                 "качество не тронуто, место зря не расходуем.",
        )
        return MAIN_MENU
    try:
        res = await _storage_upload_document(
            context, zipped, zip_name,
            caption=f"📦 ZIP (было: {old_name})",
            channel_id=int(channel_id),
        )
    except Exception as e:
        logger.error(f"cloud zip: загрузка архива не удалась: {e}")
        res = None
    if not res:
        await context.bot.send_message(
            chat_id=query.message.chat_id,
            text="❌ Не удалось загрузить архив в канал. Оригинал не тронут.",
        )
        return MAIN_MENU
    # Обновляем запись (id прежний — колбэки остаются валидными).
    rec["name"] = zip_name[:120]
    rec["kind"] = "document"
    rec["msg_id"] = res["message_id"]
    rec["file_id"] = res.get("file_id")
    rec["size"] = len(zipped)
    rec["mime"] = "application/zip"
    rec["ts"] = datetime.now().strftime("%Y-%m-%d %H:%M")
    rec["channel_id"] = res["channel_id"]
    rec["zip_of"] = old_name[:120]
    save_user(user)
    # Оригинал в канале больше не нужен — стираем (best-effort).
    if old_msg_id and int(old_msg_id) != int(res["message_id"]):
        try:
            await context.bot.delete_message(
                chat_id=int(channel_id), message_id=int(old_msg_id),
            )
        except Exception:
            pass
    saved_pct = max(0, round(100 - 100 * len(zipped) / max(1, len(data))))
    await context.bot.send_message(
        chat_id=query.message.chat_id,
        text=(f"📦 Готово: «{old_name}» → «{zip_name}»\n"
              f"{_fmt_bytes(len(data))} → {_fmt_bytes(len(zipped))} "
              f"(−{saved_pct}%{' — ' if saved_pct else ''}качество не тронуто, "
              "архивация всегда без потерь).\n"
              "Оригинал из канала удалён, в облаке теперь архив."),
        reply_markup=get_cloud_files_keyboard(user),
    )
    return MAIN_MENU


async def cloud_mv_cb(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """ВОЛНА 9: перенос старого НЕзашифрованного файла в Сейф (кнопка 🔐).

    Бот скачивает файл в ПАМЯТЬ (≤20 МБ — лимит Bot API на скачивание) и
    передаёт его в обычный поток Сейфа: пароль → шифр в канал → старая
    незашифрованная копия удаляется и из канала, и из списка «старых файлов».
    Так выполняется правило «файлы всегда должны быть в сейфе облака»."""
    query = update.callback_query
    user = get_user(str(query.from_user.id))
    if not user:
        await query.answer("Сначала зарегистрируйтесь — /start", show_alert=True)
        return MAIN_MENU
    fid = query.data.replace("cloud_mv_", "", 1)
    rec = _cloud_find_record(user, fid)
    if not rec:
        await query.answer("Файл не найден в вашем облаке.", show_alert=True)
        return MAIN_MENU
    if not get_cloud_channel_ids():
        await query.answer("Хранилище отключено.", show_alert=True)
        return MAIN_MENU
    # ВОЛНА 22.25: в режиме «БЕЗ шифрования» (свой канал) cryptography не
    # нужна — перенос работает и без неё; в обычном режиме — обязательна.
    if (not _vault_kdf_available()
            and not (_user_vault_channel(user) is not None
                     and _vault_channel_plain(user))):
        await query.answer(
            "Шифрование недоступно: на сервере нет библиотеки cryptography.",
            show_alert=True,
        )
        return MAIN_MENU
    size = int(rec.get("size", 0) or 0)
    if size > VAULT_MAX_FILE_BYTES:
        await query.answer(
            f"Файл больше {_fmt_bytes(VAULT_MAX_FILE_BYTES)} — Telegram не даёт "
            "ботам скачивать такие файлы, перенести в Сейф честно невозможно.",
            show_alert=True,
        )
        return MAIN_MENU
    file_id = rec.get("file_id")
    if not file_id:
        await query.answer(
            "У файла нет сохранённого file_id — перенести не могу.", show_alert=True)
        return MAIN_MENU
    await query.answer("Скачиваю файл в память…")
    try:
        await context.bot.send_chat_action(chat_id=query.message.chat_id, action="typing")
        tg_file = await context.bot.get_file(file_id)
        buf = io.BytesIO()
        await asyncio.wait_for(tg_file.download_to_memory(out=buf), timeout=120)
        payload = buf.getvalue()
    except Exception as e:
        logger.error(f"cloud mv: скачать файл не удалось: {e}")
        await query.message.reply_text(
            "❌ Не смог скачать файл для шифрования (возможно, сообщение удалено "
            "из канала). Перенос отменён.")
        return MAIN_MENU
    # Готовим пачку из одного файла и открываем парольный шаг Сейфа.
    context.user_data['vault_batch'] = [{
        "source": "file", "payload": payload,
        "name": str(rec.get("name") or "файл")[:120],
        "kind": rec.get("kind") or "document",
        "mime": str(rec.get("mime") or ""),
        "size": len(payload),
    }]
    context.user_data['vault_migrate_ids'] = [fid]
    context.user_data['vault_put_mode'] = True
    # ВОЛНА 22.25: режим «БЕЗ шифрования» — переносим файл в личный канал КАК ЕСТЬ.
    if _user_vault_channel(user) is not None and _vault_channel_plain(user):
        return await _vault_plain_upload(
            query.message, context, user,
            note="📤 ПЕРЕНОС: файл ляжет в ваш канал БЕЗ шифра, "
                 "старая копия будет стёрта.\n\n")
    return await _vault_prompt_password(
        query.message, user,
        note="🔐 ПЕРЕНОС В СЕЙФ: файл скачан в память (в чат не попадёт).\n\n",
        context=context,
    )


