@timeout(CONVERSATION_TIMEOUT)
async def cloud_rename_save(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """ВОЛНА 8: сохранение нового названия файла облака."""
    msg = update.message
    text = (msg.text or "").strip()
    fid = context.user_data.pop('cloud_rename_id', None)
    user = get_user(str(update.effective_user.id))
    if not user:
        return ConversationHandler.END
    if text in ("❌ Отмена", "⬅️ Назад в меню"):
        await msg.reply_text("Без изменений.", reply_markup=get_main_menu_keyboard(user))
        return MAIN_MENU
    if not fid or not text:
        await msg.reply_text("Название пустое — оставил как было.",
                             reply_markup=get_main_menu_keyboard(user))
        return MAIN_MENU
    rec = _cloud_find_record(user, str(fid))
    if not rec:
        await msg.reply_text("Файл не найден (уже удалён?).",
                             reply_markup=get_main_menu_keyboard(user))
        return MAIN_MENU
    old = rec.get("name", "?")
    rec["name"] = text[:120]
    save_user(user)
    await msg.reply_text(
        f"✏️ Готово: «{old}» → «{rec['name']}».",
        reply_markup=get_main_menu_keyboard(user),
    )
    return MAIN_MENU


async def cloud_bigself_cb(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """ВОЛНА 8: пользователь грузит БОЛЬШОЙ файл (>49 МБ, до 2 ГБ) САМ прямо
    в канал-хранилище. Бот создаёт одноразовую ссылку-приглашение и 30 минут
    ждёт пост в канале: увидев медиа, запишет его в облако этому пользователю.
    Это честный обход лимита «боты не отправляют >49 МБ»: отправляет сам
    пользователь, а боту ничего качать не нужно — только запомнить указатель."""
    query = update.callback_query
    await query.answer()
    user = get_user(str(query.from_user.id))
    if not user:
        await query.answer("Сначала зарегистрируйтесь — /start", show_alert=True)
        return MAIN_MENU
    cloud = _storage_channels_of(None, ("cloud", "both"))
    if not cloud:
        await query.answer("Хранилище не подключено.", show_alert=True)
        return MAIN_MENU
    ch = cloud[0]
    ch_id = int(ch["id"])
    link_line = ""
    try:
        invite = await context.bot.create_chat_invite_link(
            chat_id=ch_id, member_limit=1,
            name=f"big-upload {query.from_user.id}",
        )
        link_line = f"1) Вступите в канал-хранилище по одноразовой ссылке:\n{invite.invite_link}\n\n"
    except Exception as e:
        # Ссылку создать не вышло (нет права can_invite_users) — честно
        # просим разработчика добавить пользователя вручную.
        logger.warning(f"cloud bigself: invite link не создалась: {e}")
        link_line = ("1) Попросите разработчика добавить вас в канал-хранилище "
                     f"«{ch.get('title')}» (ссылку создать не удалось).\n\n")
    _PENDING_BIG_UPLOADS[str(query.from_user.id)] = {
        "channel_id": ch_id,
        "until": _time.monotonic() + BIG_UPLOAD_WINDOW_SEC,
    }
    try:
        await query.edit_message_text(
            "📤 Загрузка большого файла НАПРЯМУЮ в канал\n\n"
            f"{link_line}"
            "2) ОТПРАВЬТЕ ФАЙЛ ПРЯМО В КАНАЛ «" + str(ch.get('title')) + "» "
            "(просто как обычное сообщение).\n\n"
            "Я получу пост и сам запишу файл в ВАШЕ облако — имя возьму из "
            "подписи, если подпишете. Жду 30 минут.\n\n"
            "Честные детали: файл до 2 ГБ (лимит Telegram для обычных "
            "пользователей). Скачать его бот не сможет (лимит 20 МБ на "
            "скачивание), но он будет лежать в облаке, а вы сможете выдавать "
            "его через «📁 Мои файлы» (выдача работает без скачивания ботом).",
            reply_markup=InlineKeyboardMarkup([[
                InlineKeyboardButton("⬅️ Назад", callback_data="cloud_menu"),
            ]]),
        )
    except Exception:
        await query.message.reply_text("Режим ожидания большого файла включён: пришлите файл в канал.")
    return MAIN_MENU


async def _cdb_fetch_payload_mtproto(context, src_chat, src_msg):
    """ВОЛНА 16: скачать файл базы 20–49 МБ через MTProto (Bot API умеет
    только 20 МБ вниз, а снапшоты бывают и такими — потолок отправки
    49 МБ). Качает ПРЯМО из чата-источника (личка или канал — бот там
    участник) потоком, в ОЗУ: снапшоты ≤49 МБ, память не проблема."""
    client = await _mt_client()
    if client is None:
        raise RuntimeError("MTProto недоступен (Telethon не установлен?)")
    if int(src_chat) < 0:
        peer = await _mt_resolve_channel(client, int(src_chat))
    else:
        peer = _mt_peer_user(int(src_chat))
    _m, doc = await _mt_fetch_document_peer(client, peer, int(src_msg))
    if doc is None:
        raise RuntimeError("сообщение с файлом не найдено через MTProto")
    buf = io.BytesIO()
    await _mt_download_stream(
        client, doc, int(getattr(doc, "size", 0) or 0), buf.write, None, "")
    payload = buf.getvalue()
    if not payload:
        raise RuntimeError("скачался пустой файл")
    return payload


async def _cdb_ingest_post(context, post, doc, fname, chat_id):
    """ВОЛНА 13: пользователь САМ вставил снапшот базы в канал.

    Просьба пользователя: «бот опять ничего не помнит — лучше я буду в него
    вставлять файлы из канала, последние, но он также их должен закрепить».
    Бот видит пост с документом devorks_db_snapshot_…, скачивает его,
    проверяет _meta.json и применяет базу. ВОЛНА 16: файл в канал вставляет
    ЧЕЛОВЕК (свои собственные снапшоты бот не видит — зацикливание
    невозможно), значит ЭТОТ файл и есть актуальная база:
    • применяем базу ВСЕГДА, ЗАКРЕПЛЯЕМ пост (pin) и стираем старые
      снапшоты этого канала — при старте бот прочитает именно этот закреп;
    • если штамп старше локального cdb_last_flush — всё равно применяем
      (ручное восстановление БЕЗ отказов «не новее»), честно помечая это
      в отчёте; защита latest-wins осталась только на автоматических
      путях (старт бота, кнопка «📦 Вспомнить всё»).
    Отчёт уходит разработчику в ЛС (у channel-постов нет автора). Свои
    собственные снапшоты бот не видит: Telegram не присылает боту
    channel_post о его же сообщениях — зацикливание невозможно.

    ДОПОЛНИТЕЛЬНО (волна 13, честная доверенная цепочка): если снапшот
    отправлен в канал, КОТОРОГО НЕТ в конфиге (конфиг потерян при переезде,
    а бот всё ещё админ в канале) — бот ПОДКЛЮЧАЕТ этот канал сам (режим
    «Оба») и применяет снапшот: пользователь не должен запирать
    восстановление о потерянный конфиг. ВОЛНА 16: и в новом канале файл
    применяется ВСЕГДА — он дан человеком вручную."""
    _reports = []
    try:
        fsize = int(getattr(doc, "file_size", 0) or 0)
        if fsize > 20 * 1024 * 1024 and not _TELETHON_OK:
            _reports.append(
                f"❌ Снапшот «{fname}» ({_fmt_bytes(fsize)}) НЕ принят: Bot API "
                "не скачивает файлы больше 20 МБ, а режим MTProto (файлы до "
                "2 ГБ) на сервере ВЫКЛЮЧЕН — нужен telethon>=1.36 в "
                "requirements.txt и строка «mtproto: клиент поднялся» в логе.")
        else:
            payload = None
            try:
                tg_file = await context.bot.get_file(doc.file_id)
                buf = io.BytesIO()
                await asyncio.wait_for(tg_file.download_to_memory(out=buf), timeout=300)
                payload = buf.getvalue()
            except Exception as e:
                # ВОЛНА 16: файлы 20–49 МБ Bot API не скачает (лимит вниз —
                # 20 МБ) — качаем MTProto-потоком ПРЯМО из этого же канала.
                logger.warning(
                    f"cdb ingest: Bot API скачать «{fname}» не смог ({e}); "
                    "пробую MTProto")
                try:
                    payload = await _cdb_fetch_payload_mtproto(
                        context, int(chat_id), int(post.message_id))
                except Exception as e2:
                    logger.error(
                        f"cdb ingest: скачать «{fname}» не удалось: {e2}")
                    _reports.append(
                        f"❌ Снапшот «{fname}» ({_fmt_bytes(fsize)}) не скачался "
                        f"через MTProto: {e2}. Проверьте, что бот админ канала, "
                        "и лог старта «mtproto: клиент поднялся».")
            if payload is not None:
                verified, stamp = False, ""
                try:
                    zf = zipfile.ZipFile(io.BytesIO(payload))
                    if "_meta.json" not in zf.namelist():
                        raise ValueError("нет _meta.json")
                    try:
                        stamp = str(json.loads(
                            zf.read("_meta.json").decode("utf-8")
                        ).get("created_utc") or "")
                    except Exception:
                        stamp = ""
                    zf.close()
                    verified = True
                except Exception as e:
                    _reports.append(
                        f"❌ Файл «{fname}» — это НЕ снапшот DEVORKS+ (битый или "
                        f"чужой zip: {e}). Ничего не применял и не закреплял.")
                if verified:
                    async with _get_cdb_flush_lock():
                        cfg = load_storage_config()
                        # ВОЛНА 13: канал не настроен → подключаем САМИ (режим «Оба»):
                        # конфиг мог потеряться при переезде, а снапшот пользователь
                        # прислал явно — это и есть восстановление.
                        _adopted = False
                        try:
                            _known = {int(c.get("id")) for c in (cfg.get("channels") or [])
                                      if isinstance(c, dict)}
                        except Exception:
                            _known = set()
                        if int(chat_id) not in _known:
                            _ch_title = str(getattr(getattr(post, "chat", None),
                                                    "title", "") or "Канал-хранилище")
                            _cfg2, _added = _storage_add_channel(
                                int(chat_id), _ch_title, "both")
                            if _added:
                                _adopted = True
                                cfg = load_storage_config()
                        last = str(cfg.get("cdb_last_flush") or "")
                        # ВОЛНА 16: снапшот в канал вставляет ЧЕЛОВЕК —
                        # ручной файл и есть актуальная база: применяем
                        # ВСЕГДА и закрепляем, БЕЗ отказа «не новее»
                        # (просьба пользователя: «загрузил базу — бот
                        # говорит Готово и всё восстанавливается»). Если
                        # штамп старше текущего — честная пометка в отчёте.
                        _older = bool(stamp and last and stamp <= last)
                        if True:
                            restored, problems = _storage_restore_apply(payload)
                            if not restored:
                                _reports.append(
                                    "❌ Из снапшота «" + fname + "» ничего не "
                                    "восстановлено"
                                    + (": " + "; ".join(problems[:3]) if problems else "."))
                            else:
                                _CDB_DIRTY.clear()  # данные только что из канала
                                # ВОЛНА 17: честная пометка — файлы Сейфа без
                                # связки ключей в этом снапшоте.
                                try:
                                    _vw17 = _vault_restore_warning(
                                        load_data(USERS_FILE, {}) or {})
                                except Exception:
                                    _vw17 = ""
                                pin_notes = []
                                if _vw17:
                                    pin_notes.append(_vw17)
                                try:
                                    await context.bot.unpin_all_chat_messages(chat_id=chat_id)
                                except Exception as e:
                                    logger.warning(f"cdb ingest: unpin_all {chat_id}: {e}")
                                try:
                                    await context.bot.pin_chat_message(
                                        chat_id=chat_id,
                                        message_id=int(post.message_id),
                                        disable_notification=True,
                                    )
                                except Exception as e:
                                    logger.error(f"cdb ingest: pin в {chat_id} НЕ УДАЛСЯ: {e}")
                                    pin_notes.append(
                                        "НЕ удалось ЗАКРЕПИТЬ снапшот — при старте бот "
                                        "его не прочитает. Проверьте право бота на "
                                        "закрепление сообщений в канале.")
                                # Реестр указателей + удаление СТАРЫХ снапшотов
                                # этого канала (правило: один актуальный снапшот).
                                cfg = load_storage_config()  # ПОСЛЕ apply — конфиг мог приехать из снапшота
                                reg = dict(cfg.get("cdb_registry") or {})
                                sent = dict(cfg.get("cdb_sent") or {})
                                _old_ids = []
                                for _v in (sent.get(str(chat_id)) or []):
                                    try:
                                        _iv = int(_v)
                                    except (TypeError, ValueError):
                                        continue
                                    if _iv not in _old_ids:
                                        _old_ids.append(_iv)
                                _prev = (reg.get(str(chat_id)) or {}).get("msg_id")
                                try:
                                    _prev = int(_prev)
                                    if _prev and _prev not in _old_ids:
                                        _old_ids.append(_prev)
                                except (TypeError, ValueError):
                                    pass
                                pruned = 0
                                for _old in _old_ids:
                                    if int(_old) == int(post.message_id):
                                        continue
                                    try:
                                        await context.bot.delete_message(
                                            chat_id=chat_id, message_id=int(_old))
                                        pruned += 1
                                    except Exception:
                                        pass
                                reg[str(chat_id)] = {
                                    "msg_id": int(post.message_id),
                                    "file_id": getattr(doc, "file_id", None),
                                    "ts": stamp,
                                    "size": len(payload),
                                }
                                sent[str(chat_id)] = [int(post.message_id)]
                                cfg["cdb_registry"] = reg
                                cfg["cdb_sent"] = sent
                                if stamp:
                                    cfg["cdb_last_flush"] = stamp
                                save_storage_config(cfg)
                                _rep = (
                                    f"📥 СНАПШОТ ИЗ КАНАЛА ПРИНЯТ И ЗАКРЕПЛЁН: {fname} "
                                    f"({_fmt_bytes(len(payload))}, штамп {stamp or '?'})\n"
                                    f"• Файлов данных восстановлено: {len(restored)}")
                                if _adopted:
                                    _rep += (f"\n➕ Канал {chat_id} не был настроен — "
                                             "подключён автоматически (режим «Оба»).")
                                if _older:
                                    _rep += (f"\nℹ️ Штамп снапшота ({stamp}) НЕ новее "
                                             f"текущей базы ({last}) — применён "
                                             "ПРИНУДИТЕЛЬНО: файл дан вручную, "
                                             "он и есть актуальная база.")
                                if pruned:
                                    _rep += (f" • 🧹 старых снапшотов стёрто: {pruned} "
                                             "(остался один актуальный)")
                                if problems:
                                    _rep += f"\n⚠️ Проблемы: {'; '.join(problems[:3])}"
                                for _pn in pin_notes:
                                    _rep += f"\n⚠️ {_pn}"
                                _reports.append(_rep)
                                logger.info(
                                    f"cdb ingest: снапшот из канала {chat_id} применён "
                                    f"и закреплён: {fname} (штамп {stamp or '?'})")
    except Exception as e:
        logger.error(f"cdb ingest crashed: {e}")
        _reports.append(f"❌ Снапшот из канала не принят (внутренняя ошибка): {e}")
    for _t in _reports:
        try:
            if DEVELOPER_ID:
                await context.bot.send_message(
                    chat_id=int(str(DEVELOPER_ID).strip()), text=str(_t)[:3500])
        except Exception:
            pass


async def _storage_channel_post_handler(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """ВОЛНА 8: пост в канале-хранилище = файл от пользователя (большие файлы).

    Работает только для НАШИХ cloud-каналов и только когда кто-то недавно
    (BIG_UPLOAD_WINDOW_SEC) нажал «📤 Отправить в канал самому» — иначе пост
    игнорируется (никакой атрибуции «на глаз»: чужой пост нельзя записать
    первому встречному). Индексируем медиа любого размера: бот НЕ скачивает
    файл — сохраняет только указатель (chat/message_id, file_id, размер).

    ВОЛНА 13: документ с именем devorks_db_snapshot_… — это ВСТАВЛЕННЫЙ
    пользователем снапшот базы: принимаем (latest-wins), ЗАКРЕПЛЯЕМ и
    стираем старые снапшоты (_cdb_ingest_post) в любом канале-хранилище."""
    try:
        post = getattr(update, "channel_post", None) or getattr(update, "edited_channel_post", None)
        if post is None:
            return
        chat_id = post.chat_id
        # ВОЛНА 13: сначала проверяем, не снапшот ли это базы — принимается
        # в ЛЮБОМ канале, где бот админ (даже не настроенном: конфиг мог
        # потеряться — бот подключит канал сам, см. _cdb_ingest_post).
        _doc = getattr(post, "document", None)
        _fname = str(getattr(_doc, "file_name", "") or "")
        if _doc is not None and _fname.startswith(CDB_SNAPSHOT_PREFIX):
            await _cdb_ingest_post(context, post, _doc, _fname, chat_id)
            return
        if chat_id not in get_cloud_channel_ids():
            return
        # Кому записать? Ищем свежее окно ожидания для ЭТОГО канала.
        now_mono = _time.monotonic()
        target_uid, target_slot = None, None
        for uid, slot in list(_PENDING_BIG_UPLOADS.items()):
            if slot.get("until", 0) < now_mono:
                _PENDING_BIG_UPLOADS.pop(uid, None)
                continue
            if int(slot.get("channel_id", 0)) == int(chat_id):
                target_uid, target_slot = uid, slot
                break
        if not target_uid:
            return  # никто не ждёт файл — это обычный служебный пост
        item = _cloud_item_from_message(post)
        if item is None:
            return
        user = get_user(target_uid)
        if not user:
            return
        files = [f for f in (getattr(user, "cloud_files", []) or []) if isinstance(f, dict)]
        limit = get_price('cloud_max_files', 50)
        if len(files) >= limit:
            try:
                await context.bot.send_message(
                    chat_id=int(target_uid),
                    text=f"🚫 «{item['name']}» не записан: лимит облака ({limit}) достигнут.",
                )
            except Exception:
                pass
            return
        rec = {
            "id": _cloud_gen_file_id(user),
            "name": item["name"][:120],
            "kind": item["kind"],
            "msg_id": int(post.message_id),
            "file_id": item["file_id"],
            "size": item["size"],
            "mime": item.get("mime", ""),
            "ts": _file_ts_now(), "tss": datetime.now().strftime("%Y-%m-%d %H:%M"),
            "channel_id": int(chat_id),
            "big": True,
        }
        files.append(rec)
        user.cloud_files = files
        save_user(user)
        _PENDING_BIG_UPLOADS.pop(target_uid, None)
        try:
            await context.bot.send_message(
                chat_id=int(target_uid),
                text=(f"✅ БОЛЬШОЙ файл в облаке: «{rec['name']}» "
                      f"({_fmt_bytes(rec['size'])}). Файлов: {len(files)}/{limit}."),
            )
        except Exception:
            pass
        logger.info(f"channel_post: большой файл записан юзеру {target_uid} "
                    f"(name_len={len(rec.get('name') or '')})")
    except Exception as e:
        logger.error(f"channel_post handler crashed: {e}")


# ==================================
# === БАЗА В ЛИЧКЕ (волна 15) ===
# ==================================
# Просьба пользователя: «бот ничего не помнит — лучше я загружу в него
# файл, который он давал в прошлый раз, последний с базой данных».
# До волны 15 снапшот базы принимался только ПОСТОМ В КАНАЛ (волна 13).
# Теперь:
#   1) кнопка «💾 Снапшот базы мне в личку» (панель разработчика) отдаёт
#      пользователю САМ файл базы — его можно хранить где угодно;
#   2) этот файл можно просто ОТПРАВИТЬ БОТУ В ЛИЧКУ из любого состояния —
#      бот подтвердит, применит базу (latest-wins), скопирует файл в
#      канал-хранилище, ЗАКРЕПИТ его и сотрёт старые снапшоты — после
#      рестарта бот вспомнит всё именно из этого закрепа.
# Фильтр-перехватчик зарегистрирован ПЕРЕД ConversationHandler (группа 0):
# снапшот не попадает ни в Сейф, ни в облако, ни в старое восстановление
# панели — двойной обработки нет; кнопки подтверждения живут вне FSM и
# работают даже когда состояние разговора потеряно после рестарта.

class _CdbSnapshotDocFilter(filters.MessageFilter):
    """True только для ДОКУМЕНТА-снапшота базы (devorks_db_snapshot_…).

    На остальные документы фильтр НЕ срабатывает — они идут дальше по
    обычным маршрутам (Сейф, облако, панель). Группа чата проверяется
    отдельно в регистрационной строке (filters.ChatType.PRIVATE)."""

    def __init__(self):
        super().__init__()
        self.name = "CdbSnapshotDocFilter"

    def filter(self, message):
        doc = getattr(message, "document", None)
        if doc is None:
            return False
        fname = str(getattr(doc, "file_name", "") or "")
        return fname.startswith(CDB_SNAPSHOT_PREFIX)


_CDB_SNAPSHOT_DOC_FILTER = _CdbSnapshotDocFilter()


async def _cdb_private_doc_handler(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """ВОЛНА 15: файл базы отправлен боту В ЛИЧКУ — предложение восстановления.

    • Не разработчик → честный отказ: в снапшоте база ВСЕХ пользователей,
      восстановление по нему меняет данные каждого — это право разработчика.
    • Больше 20 МБ → честный отказ (Bot API не даёт ботам скачивать такие
      файлы; снапшоты DEVORKS+ такими не бывают — файл чужой/битый).
    • Иначе — сохраняем указатель файла в user_data и показываем кнопки
      [✅ Восстановить][❌ Отмена]. Само восстановление — по нажатию «Да»
      (_cdb_private_restore_cb): файл скачивается ТОГДА, поэтому между
      «отправил файл» и «нажал Да» может пройти сколько угодно времени."""
    msg = getattr(update, "effective_message", None)
    if msg is None:
        return
    doc = getattr(msg, "document", None)
    if doc is None:
        return
    fname = str(getattr(doc, "file_name", "") or "")
    _from = getattr(msg, "from_user", None)
    uid = str(getattr(_from, "id", "") or "")
    if uid != str(DEVELOPER_ID):
        try:
            await msg.reply_text(
                "🔒 Это системный архив базы данных DEVORKS+: внутри данные "
                "ВСЕХ пользователей. Восстановление из него доступно только "
                "разработчику бота.")
        except Exception:
            pass
        return
    fsize = int(getattr(doc, "file_size", 0) or 0)
    if fsize > 20 * 1024 * 1024:
        try:
            await msg.reply_text(
                f"❌ «{fname}» ({_fmt_bytes(fsize)}) больше 20 МБ — Telegram "
                "не даёт ботам скачивать такие файлы. Снапшоты, сделанные "
                "этим ботом, такими не бывают: проверьте, тот ли это файл.")
        except Exception:
            pass
        return
    context.user_data["cdb_rst_pending"] = {
        "file_id": str(getattr(doc, "file_id", "") or ""),
        "fname": fname,
        "size": fsize,
        "msg_id": int(getattr(msg, "message_id", 0) or 0),
        "chat_id": int(getattr(msg, "chat_id", 0) or 0),
    }
    try:
        await msg.reply_text(
            "♻️ Это ФАЙЛ БАЗЫ ДАННЫХ DEVORKS+.\n\n"
            f"«{fname}» • {_fmt_bytes(fsize)}\n\n"
            "По «✅ Восстановить» бот:\n"
            "• применит ЭТОТ файл как актуальную базу — БЕЗ отказов «не "
            "новее»: вы дали файл вручную, значит он и есть последний "
            "(ответ — «Готово!»);\n"
            "• скопирует файл в канал-хранилище, ЗАКРЕПИТ его и сотрёт "
            "старые снапшоты — после рестарта бот вспомнит всё из закрепа.\n\n"
            "Продолжить?",
            reply_markup=InlineKeyboardMarkup([[
                InlineKeyboardButton("✅ Восстановить", callback_data="cdb_rst_yes"),
                InlineKeyboardButton("❌ Отмена", callback_data="cdb_rst_no"),
            ]]))
    except Exception:
        pass


async def _cdb_private_restore_cb(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """ВОЛНА 15: «✅ Восстановить» под файлом базы, присланным в личку.

    Полностью повторяет правила волны 13 (_cdb_ingest_post), но источник —
    личный чат, а закреп делается в НАСТРОЕННЫХ db-каналах (после применения
    снапшота конфиг перечитывается: список каналов сам приезжает из файла):
      1) скачать (Bot API ≤20 МБ; больше — MTProto-поток, ВОЛНА 16) и
         проверить _meta.json → штамп created_utc;
      2) ВОЛНА 16: применяется ВСЕГДА — вы дали файл вручную и нажали
         «✅ Восстановить», значит ЭТОТ файл и есть актуальная база,
         ответ — «Готово!» (latest-wins остался только на автопутях);
      3) применить базу (_storage_restore_apply) под flush-локом;
      4) в КАЖДЫЙ db-канал: серверная копия файла (copy_message — без
         повторной загрузки), unpin_all + pin, стирание старых снапшотов;
      5) реестр cdb_registry/cdb_sent/cdb_last_flush → storage_config.json;
      6) отчёт пользователю (и разработчику, если это разные люди)."""
    query = update.callback_query
    try:
        await query.answer()
    except Exception:
        pass
    if str(query.from_user.id) != str(DEVELOPER_ID):
        try:
            await query.edit_message_text("Доступ запрещён.")
        except Exception:
            pass
        return
    pend = dict((context.user_data or {}).get("cdb_rst_pending") or {})
    if query.data == "cdb_rst_no":
        context.user_data.pop("cdb_rst_pending", None)
        try:
            await query.edit_message_text(
                "❌ Отменено: файл проигнорирован, ничего не менялось.")
        except Exception:
            pass
        return
    # === «Да» ===
    if not pend or not pend.get("file_id"):
        try:
            await query.answer(
                "Не нашёл файл в памяти (перезапуск?). Отправьте файл базы "
                "ещё раз — и нажмите «Восстановить».", show_alert=True)
        except Exception:
            pass
        return
    _src_chat = int(pend.get("chat_id") or 0) or int(query.message.chat_id)
    _src_msg = int(pend.get("msg_id") or 0)
    fname = str(pend.get("fname") or CDB_SNAPSHOT_PREFIX)
    payload = None
    try:
        tg_file = await context.bot.get_file(str(pend.get("file_id")))
        buf = io.BytesIO()
        await asyncio.wait_for(tg_file.download_to_memory(out=buf), timeout=300)
        payload = buf.getvalue()
    except Exception as e:
        # ВОЛНА 16: файлы 20–49 МБ Bot API не скачает (лимит вниз — 20 МБ),
        # а снапшоты бывают и такими. Качаем MTProto-потоком ПРЯМО из
        # этого чата (бот видит свои личные чаты и через MTProto).
        logger.warning(
            f"cdb private restore: Bot API скачать «{fname}» не смог ({e}); "
            "пробую MTProto")
        try:
            payload = await _cdb_fetch_payload_mtproto(
                context, _src_chat, _src_msg)
        except Exception as e2:
            logger.error(
                f"cdb private restore: скачать «{fname}» не удалось: {e2}")
            context.user_data.pop("cdb_rst_pending", None)
            try:
                await query.edit_message_text(
                    f"❌ Не удалось скачать файл: {e2}. Снапшоты больше 20 МБ "
                    "качаются через MTProto — проверьте строку «mtproto: "
                    "клиент поднялся» в логе старта.")
            except Exception:
                pass
            return
    # Верификация: наш zip с _meta.json + штамп времени.
    verified, stamp = False, ""
    try:
        zf = zipfile.ZipFile(io.BytesIO(payload))
        if "_meta.json" not in zf.namelist():
            raise ValueError("нет _meta.json")
        try:
            stamp = str(json.loads(
                zf.read("_meta.json").decode("utf-8")
            ).get("created_utc") or "")
        except Exception:
            stamp = ""
        zf.close()
        verified = True
    except Exception as e:
        context.user_data.pop("cdb_rst_pending", None)
        try:
            await query.edit_message_text(
                f"❌ Файл «{fname}» — это НЕ снапшот DEVORKS+ (битый или "
                f"чужой zip: {e}). Ничего не применял и не закреплял.")
        except Exception:
            pass
        return
    if not verified:
        return
    _notes = []
    try:
        async with _get_cdb_flush_lock():
            # ВОЛНА 16: ручное восстановление по файлу от разработчика —
            # БЕЗ отказа «не новее»: вы дали файл и нажали «✅ Восстановить»,
            # значит ЭТОТ файл и есть актуальная база. Отвечаем «Готово!».
            # (Просьба пользователя: «загрузил базу — бот должен сказать
            # готово и вся база должна восстановиться».) Защита latest-wins
            # осталась только на АВТОМАТИЧЕСКИХ путях (старт/кнопка),
            # чтобы свежую базу никто случайно не откатил.
            cfg = load_storage_config()
            last = str(cfg.get("cdb_last_flush") or "")
            if stamp and last and stamp <= last:
                _notes.append(
                    f"ℹ️ Штамп файла ({stamp}) НЕ новее текущей базы ({last}) — "
                    "применён ПРИНУДИТЕЛЬНО: файл дан вручную.")
            restored, problems = _storage_restore_apply(payload)
            if not restored:
                try:
                    await query.edit_message_text(
                        "❌ Из файла «" + fname + "» ничего не восстановлено"
                        + (": " + "; ".join(problems[:3]) if problems else "."))
                except Exception:
                    pass
                return
            # ВОЛНА 17: честная пометка — если у файлов Сейфа нет связки ключей.
            try:
                _vw = _vault_restore_warning(load_data(USERS_FILE, {}) or {})
                if _vw:
                    _notes.append(_vw)
            except Exception:
                pass
            _CDB_DIRTY.clear()  # данные только что из файла — заливать обратно нечего
            cfg = load_storage_config()  # ПОСЛЕ apply: каналы могли приехать из снапшота
            db_ids = get_db_channel_ids()
            pinned_ch, fail_ch, pruned_n = [], [], 0
            reg = dict(cfg.get("cdb_registry") or {})
            sent = dict(cfg.get("cdb_sent") or {})
            for ch in db_ids:
                new_msg_id = 0
                try:
                    _copy = await context.bot.copy_message(
                        chat_id=int(ch), from_chat_id=_src_chat,
                        message_id=_src_msg,
                    )
                    new_msg_id = int(getattr(_copy, "message_id", 0) or 0)
                except Exception as e:
                    logger.error(f"cdb private restore: копия в {ch} не удалась: {e}")
                    fail_ch.append(f"{ch}: копия не удалась")
                    continue
                try:
                    await context.bot.unpin_all_chat_messages(chat_id=int(ch))
                except Exception as e:
                    logger.warning(f"cdb private restore: unpin_all {ch}: {e}")
                try:
                    await context.bot.pin_chat_message(
                        chat_id=int(ch), message_id=new_msg_id,
                        disable_notification=True,
                    )
                    pinned_ch.append(int(ch))
                except Exception as e:
                    logger.error(f"cdb private restore: pin в {ch} НЕ УДАЛСЯ: {e}")
                    _notes.append(
                        f"НЕ удалось ЗАКРЕПИТЬ в канале {ch} — при старте бот "
                        "его не прочитает. Проверьте право бота на закрепление.")
                # Чистка СТАРЫХ снапшотов канала (правило: один актуальный).
                _old_ids = []
                for _v in (sent.get(str(ch)) or []):
                    try:
                        _iv = int(_v)
                    except (TypeError, ValueError):
                        continue
                    if _iv not in _old_ids:
                        _old_ids.append(_iv)
                _prev = (reg.get(str(ch)) or {}).get("msg_id")
                try:
                    _prev = int(_prev)
                    if _prev and _prev not in _old_ids:
                        _old_ids.append(_prev)
                except (TypeError, ValueError):
                    pass
                for _old in _old_ids:
                    if int(_old) == int(new_msg_id):
                        continue
                    try:
                        await context.bot.delete_message(
                            chat_id=int(ch), message_id=int(_old))
                        pruned_n += 1
                    except Exception:
                        pass
                reg[str(ch)] = {
                    "msg_id": int(new_msg_id),
                    "file_id": str(pend.get("file_id") or ""),
                    "ts": stamp,
                    "size": len(payload),
                }
                sent[str(ch)] = [int(new_msg_id)]
            if stamp:
                cfg["cdb_last_flush"] = stamp
            cfg["cdb_registry"] = reg
            cfg["cdb_sent"] = sent
            save_storage_config(cfg)
    except Exception as e:
        logger.error(f"cdb private restore crashed: {e}")
        try:
            await query.edit_message_text(
                f"❌ Восстановление не удалось (внутренняя ошибка): {e}")
        except Exception:
            pass
        return
    context.user_data.pop("cdb_rst_pending", None)
    # Отчёт пользователю (он же разработчик) — подробный и честный.
    _rep = (
        f"✅ Готово! База восстановлена из файла: {fname}\n"
        f"• штамп снапшота: {stamp or '?'}\n"
        f"• файлов данных восстановлено: {len(restored)}\n"
        f"• закреплено в каналах: {len(pinned_ch)}"
        + (f" ({', '.join(str(c) for c in pinned_ch)})" if pinned_ch else "")
        + (f"\n• 🧹 старых снапшотов стёрто: {pruned_n}" if pruned_n else "")
    )
    if problems:
        _rep += f"\n⚠️ Проблемы: {'; '.join(problems[:3])}"
    if fail_ch:
        _rep += ("\n⚠️ Не удалось скопировать файл в: " + "; ".join(fail_ch[:3])
                 + " — данные восстановлены, но в этих каналах остался старый закреп.")
    if not db_ids and not fail_ch:
        _rep += ("\nℹ️ Каналов-хранилищ нет: база восстановлена в память бота. "
                 "Подключите канал (Панель разработчика → Хранилище), чтобы "
                 "переживать рестарты, и пришлите файл базы ещё раз — "
                 "закреплю его там.")
    for _n in _notes:
        _rep += f"\n⚠️ {_n}"
    try:
        await query.edit_message_text(_rep[:3500])
    except Exception:
        pass
    try:
        if DEVELOPER_ID and str(query.from_user.id) != str(DEVELOPER_ID):
            await context.bot.send_message(
                chat_id=int(str(DEVELOPER_ID).strip()), text=_rep[:3500])
    except Exception:
        pass


async def dev_cdb_export_cb(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """ВОЛНА 15: кнопка «💾 Снапшот базы мне в личку» — файл базы ПОЛЬЗОВАТЕЛЮ.

    Тот же zip, что уходит в канал (_storage_pack_payload + _meta.json со
    штампом), но он отправляется в личный чат разработчика: сохраните файл —
    и даже если бот полностью забудет всё, вы просто отправите этот файл ему
    в чат, и всё вернётся (см. _cdb_private_doc_handler)."""
    query = update.callback_query
    try:
        await query.answer("Собираю снапшот…", show_alert=False)
    except Exception:
        pass
    if str(query.from_user.id) != str(DEVELOPER_ID):
        try:
            await query.edit_message_text("Доступ запрещён.")
        except Exception:
            pass
        return
    payload, meta, files_n = _storage_pack_payload()
    if not payload:
        try:
            await query.answer("Нет данных для снапшота.", show_alert=True)
        except Exception:
            pass
        return
    if len(payload) > STORAGE_MAX_FILE_BYTES:
        try:
            await query.answer(
                "Снапшот больше 49 МБ — Telegram не даст отправить его "
                "файлом. Берите актуальный из закрепа канала-хранилища.",
                show_alert=True)
        except Exception:
            pass
        return
    stamp = _utcnow().strftime("%Y-%m-%d_%H-%M-%S")
    fname = f"{CDB_SNAPSHOT_PREFIX}_{stamp}.zip"
    caption = (
        f"💾 DEVORKS+ база данных • штамп {stamp} • юзеров "
        f"{meta.get('users', 0)}, классов {meta.get('classes', 0)}, "
        f"файлов {files_n} • {_fmt_bytes(len(payload))}\n\n"
        "СОХРАНИ ЭТОТ ФАЙЛ (он же уходит в канал-хранилище закрепом).\n"
        "Если бот забудет всё — просто ОТПРАВЬ ЭТОТ ФАЙЛ ЕМУ В ЧАТ: бот "
        "восстановит базу, закрепит её в канале и вспомнит всё."
    )
    try:
        await context.bot.send_document(
            chat_id=int(query.from_user.id),
            document=InputFile(payload, filename=fname),
            caption=caption[:1024],
        )
    except Exception as e:
        logger.error(f"dev cdb export: не удалось отправить снапшот: {e}")
        try:
            await query.answer(f"❌ Не удалось отправить файл: {e}", show_alert=True)
        except Exception:
            pass
        return
    try:
        cfg = load_storage_config()
        await query.edit_message_text(
            "✅ Снапшот базы отправил тебе в личку (выше). Сохрани его: "
            "отправь этот файл боту в чат в любой момент — и всё "
            "восстановится.\n\n" + _storage_dev_status_text(cfg),
            reply_markup=get_storage_dev_keyboard(cfg))
    except Exception:
        pass


# ==================================
# === СЕЙФ (🔐 zero-knowledge) ===
# ==================================
# НОВОЕ (волна 7) по запросу пользователя: файлы (текст, фото, видео,
# документы) шифруются ПАРОЛЕМ самого пользователя так, что открыть их
# не сможет НИКТО — ни разработчик, ни владелец сервера, ни Telegram.
#
# Как это устроено (честно и без магии):
#   • Ключ выводится из пароля функцией PBKDF2-HMAC-SHA256 (600 000 итераций,
#     случайная соль на каждый файл). Пароль НЕ хранится нигде вообще.
#   • Содержимое шифруется AES-256-GCM (аутентичное шифрование: чужой ключ
#     и даже перестановка байт мгновенно обнаруживаются).
#   • В канале лежит ТОЛЬКО зашифрованный контейнер, в БД — указатели и
#     соль/nonce/верификатор. Имя файла ТОЖЕ зашифровано: в списке видны
#     только «Файл #N», размер и дата.
#   • Забытый пароль = файл потерян НАВСЕГДА. Это цена настоящей приватности,
#     и мы не будем притворяться, что «как-нибудь откроем».
#
# Контейнер: b"DVF1" + ver(1) + iters(4 BE) + salt(16) + nonce(12) + AESGCM(
#   key, nonce, header_json + b"\x00" + payload, aad=b"DVF1"+ver).
VAULT_BUTTON = "🔐 Сейф"
VAULT_MAGIC = b"DVF1"
VAULT_VERSION = 1
# ВОЛНА 11: минимум 7 символов — 7 симв. ≈ 11 лет перебора у супер-машины
# (см. таблицу стойкости _vault_strength_table_text, показывается пользователю).
VAULT_MIN_PASSWORD = 7
VAULT_MAX_FILE_BYTES = 20 * 1024 * 1024   # лимит Telegram на СКАЧИВАНИЕ ботами
VAULT_MAX_TEXT_CHARS = 4000               # текст тоже можно зашифровать
VAULT_ATTEMPTS_MAX = 3                    # попыток ввода пароля на файл
# ВОЛНА 9: восстановление по секретным вопросам.
VAULT_QUESTIONS_N = 3        # сколько секретных вопросов придумывает пользователь
VAULT_REC_MAX_ATTEMPTS = 3   # попыток пройти восстановление (цикл из 3 ответов = попытка)
VAULT_REC_COOLDOWN_MIN = 30  # блокировка восстановления после исчерпания попыток
# AAD для запечатанного пароля — не даёт подставить этот блоб как файловый шифр.
VAULT_REC_AAD = b"DVF1-REC"

try:  # AES-256-GCM из библиотеки cryptography (единственная зависимость).
    from cryptography.hazmat.primitives.ciphers.aead import AESGCM
except Exception:  # pragma: no cover - честная деградация без библиотеки
    AESGCM = None

# ВОЛНА 14: большие файлы (>20 МБ, до 2 ГБ) — гибрид Bot API + MTProto.
# Контейнер DVF2: чанки по 1 МБ, каждый — свой AES-256-GCM с nonce,
# выведенным из случайной 4-байтной приставки и НОМЕРА куска (AAD тоже
# привязан к номеру — переставить/выкинуть кусок нельзя). Потоковое
# шифрование/расшифровка: в ОЗУ никогда не лежит больше ~1 МБ данных.
VAULT_DVF2_MAGIC = b"DVF2"
VAULT_DVF2_VERSION = 1
VAULT_DVF2_BLOCK = 1024 * 1024            # 1 МБ открытого текста на кусок
VAULT_DVF2_TAG = 16                        # GCM-тег на кусок
# Лимит MTProto-загрузки для ботов: 2000 МиБ (4 ГБ — только Premium у людей,
# ботам Premium недоступен). Запас 4 МиБ — под накладные расходы контейнера.
VAULT_MTPROTO_MAX_BYTES = (2000 - 4) * 1024 * 1024

# Число итераций PBKDF2: чем больше — тем медленнее подбор пароля.
# 600 000 ≈ OWASP-2023; на слабом хостинге можно снизить через env.
VAULT_KDF_ITERS = max(50_000, int(_env("VAULT_KDF_ITERS", "600000") or "600000"))


def _vault_kdf_available() -> bool:
    return AESGCM is not None


def _vault_derive_key(password: str, salt: bytes, iters: int) -> bytes:
    """Ключ AES-256 из пароля: PBKDF2-HMAC-SHA256. Пароль нигде не сохраняем."""
    return hashlib.pbkdf2_hmac(
        "sha256", (password or "").encode("utf-8"), salt, int(iters), dklen=32,
    )


def _vault_verifier(key: bytes) -> bytes:
    """«Отпечаток» ключа: позволяет проверить пароль БЕЗ скачивания файла.

    Это HMAC от ключа, а не сам ключ: по нему пароль восстановить нельзя,
    но совпадающий отпечаток доказывает, что ключ именно тот."""
    return hmac.new(b"DEVORKS-VAULT-VERIFY", key, hashlib.sha256).digest()[:16]


def _vault_pack(password: str, payload: bytes, meta: dict) -> bytes:
    """Шифрует payload + метаданные паролем. Возвращает контейнер DVF1.

    meta — dict (имя файла, mime, тип, дата). Сериализуется внутрь
    контейнера и шифруется ВМЕСТЕ с файлом: без пароля не видно даже имени."""
    salt = os.urandom(16)
    nonce = os.urandom(12)
    key = _vault_derive_key(password, salt, VAULT_KDF_ITERS)
    header = json.dumps(meta, ensure_ascii=False).encode("utf-8")
    plaintext = header + b"\x00" + (payload or b"")
    ct = AESGCM(key).encrypt(nonce, plaintext, VAULT_MAGIC + bytes([VAULT_VERSION]))
    return (
        VAULT_MAGIC + bytes([VAULT_VERSION])
        + VAULT_KDF_ITERS.to_bytes(4, "big") + salt + nonce + ct
    )


def _vault_unpack(password: str, container: bytes):
    """Расшифровывает контейнер DVF1. Возвращает (meta: dict, payload: bytes).

    Бросает ValueError: неверный пароль/испорченный контейнер — различить их
    снаружи и не нужно, обе ситуации для пользователя означают «не открылось»."""
    if not isinstance(container, (bytes, bytearray)) or len(container) < 40:
        raise ValueError("контейнер повреждён")
    if bytes(container[:4]) != VAULT_MAGIC:
        raise ValueError("это не контейнер Сейфа")
    ver = container[4]
    if ver != VAULT_VERSION:
        raise ValueError(f"неизвестная версия контейнера: {ver}")
    iters = int.from_bytes(container[5:9], "big")
    salt = bytes(container[9:25])
    nonce = bytes(container[25:37])
    ct = bytes(container[37:])
    key = _vault_derive_key(password, salt, iters)
    try:
        plaintext = AESGCM(key).decrypt(nonce, ct, VAULT_MAGIC + bytes([ver]))
    except Exception:
        raise ValueError("неверный пароль")
    if b"\x00" not in plaintext:
        raise ValueError("повреждённые данные")
    header_raw, payload = plaintext.split(b"\x00", 1)
    try:
        meta = json.loads(header_raw.decode("utf-8"))
    except Exception:
        meta = {}
    if not isinstance(meta, dict):
        meta = {}
    return meta, payload


def _vault_check_password(user, rec, password: str) -> bool:
    """Быстрая проверка пароля по верификатору (файл даже не скачивается)."""
    try:
        salt = bytes.fromhex(rec.get("salt", ""))
        iters = int(rec.get("iters") or VAULT_KDF_ITERS)
        key = _vault_derive_key(password, salt, iters)
        return hmac.compare_digest(_vault_verifier(key), bytes.fromhex(rec.get("verifier", "")))
    except Exception:
        return False


# ==================================
# === ВОЛНА 22.29: ВЕБ-ПАРОЛЬ ===
# Вход в 🌐 Веб-облако по Telegram ID + паролю из ОБЫЧНОГО браузера
# (без Telegram, без telegram.org, без VPN — по просьбе пользователей
# с VPN, у которых скрипт Telegram не загружается и initData не доходит).
# Пароль нигде не хранится: PBKDF2-HMAC-SHA256 (200 000 итераций) → ключ
# → HMAC-верификатор «DEVORKS-WEB-VERIFY». Проверка — сравнение верификаторов.
# ==================================

WEB_PW_KDF_ITERS = 200000


def _web_hash_password(password: str, salt: bytes, iters: int = WEB_PW_KDF_ITERS) -> bytes:
    """Ключ из веб-пароля: PBKDF2-HMAC-SHA256, 32 байта."""
    return hashlib.pbkdf2_hmac(
        "sha256", (password or "").encode("utf-8"), salt, int(iters), dklen=32,
    )


def _web_make_verifier(key: bytes) -> bytes:
    """«Отпечаток» ключа веб-пароля: HMAC-SHA256(b"DEVORKS-WEB-VERIFY", key),
    первые 16 байт. По верификатору пароль восстановить нельзя."""
    return hmac.new(b"DEVORKS-WEB-VERIFY", key, hashlib.sha256).digest()[:16]


def _web_set_password(user, password: str) -> None:
    """Задаёт/меняет веб-пароль пользователя: свежая соль os.urandom(16),
    ключ → верификатор → user.web_password_hash; сохраняет юзера."""
    salt = os.urandom(16)
    key = _web_hash_password(password, salt, WEB_PW_KDF_ITERS)
    verifier = _web_make_verifier(key)
    user.web_password_hash = {
        "salt": salt.hex(),
        "iters": int(WEB_PW_KDF_ITERS),
        "verifier": verifier.hex(),
    }
    user.web_password_set_at = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    # Новый пароль — старые блокировки и счётчики попыток не имеют смысла.
    user.web_login_attempts = 0
    user.web_login_locked_until = None
    save_user(user)


def _web_check_password(user, password: str) -> bool:
    """Проверяет веб-пароль по верификатору (hmac.compare_digest)."""
    rec = getattr(user, "web_password_hash", None)
    if not isinstance(rec, dict):
        return False
    try:
        salt = bytes.fromhex(str(rec.get("salt", "")))
        iters = int(rec.get("iters") or WEB_PW_KDF_ITERS)
        key = _web_hash_password(password, salt, iters)
        return hmac.compare_digest(
            _web_make_verifier(key), bytes.fromhex(str(rec.get("verifier", ""))))
    except Exception:
        return False


# === ВОЛНА 22.29: ВЕБ-СЕССИИ (Bearer-токены для /api/*) ===
# Живут В ПАМЯТИ процесса: рестарт сервера сбрасывает сессии — пользователю
# нужно просто войти заново (пароль остаётся). TTL — 30 дней.
_WEB_SESSIONS = {}
WEB_SESSION_TTL = 30 * 24 * 3600   # 30 дней, сек
WEB_SESSIONS_MAX = 10000           # капа словаря (при превышении чистим просрочку)


def _web_create_session(user_id) -> str:
    """Создаёт веб-сессию: secrets.token_urlsafe(32) → {user_id, expires, created}."""
    # Капа: если записей стало слишком много — сначала чистим просроченные.
    if len(_WEB_SESSIONS) >= WEB_SESSIONS_MAX:
        _now = time.time()
        for _k in [k for k, v in _WEB_SESSIONS.items() if v.get("expires", 0) <= _now]:
            _WEB_SESSIONS.pop(_k, None)
        # Всё ещё тесно — срезаем самые старые.
        if len(_WEB_SESSIONS) >= WEB_SESSIONS_MAX:
            _oldest = sorted(_WEB_SESSIONS, key=lambda k: _WEB_SESSIONS[k].get("created", 0))
            for _k in _oldest[: len(_WEB_SESSIONS) - WEB_SESSIONS_MAX + 1]:
                _WEB_SESSIONS.pop(_k, None)
    token = secrets.token_urlsafe(32)
    _now = time.time()
    _WEB_SESSIONS[token] = {
        "user_id": str(user_id),
        "expires": _now + WEB_SESSION_TTL,
        "created": _now,
    }
    return token


def _web_check_session(token) -> "str | None":
    """Возвращает user_id живой сессии; просроченную удаляет; None — нет/битая."""
    if not token:
        return None
    rec = _WEB_SESSIONS.get(token)
    if not rec:
        return None
    if float(rec.get("expires", 0)) <= time.time():
        _WEB_SESSIONS.pop(token, None)
        return None
    uid = str(rec.get("user_id") or "")
    return uid or None


# ВОЛНА 17: ТЕКСТЫ секретных вопросов шифруются в файле базы ключом бота
# (AES-256-GCM). Просьба пользователя: «если они будут в файле с данными —
# пусть тоже шифруются». Пароль Сейфа и так запечатан ответами (rec), а
# тексты вопросов раньше лежали в users.json ОТКРЫТО — теперь тоже шифр.
# Ключ выводится из BOT_TOKEN (PBKDF2-HMAC-SHA256, фикс. 120 000 раундов):
# менять число раундов нельзя — ключ изменится и старые вопросы не прочтутся.
_VAULT_KB_SALT = b"DEVORKS+vault-auth-seal-v17"
_VAULT_KB_AAD = b"devorks-vault-auth-q"
_VAULT_KB_ITERS = 120000
_VAULT_KB_KEY_CACHE = None


def _vault_kb_key():
    """ВОЛНА 17: ключ бота для шифрования текстов вопросов в файле базы.
    Смена BOT_TOKEN делает старые зашифрованные вопросы нечитаемыми —
    тогда бот честно предложит задать вопросы заново (зная пароль)."""
    global _VAULT_KB_KEY_CACHE
    if _VAULT_KB_KEY_CACHE is not None:
        return _VAULT_KB_KEY_CACHE
    secret = (os.environ.get("BOT_TOKEN") or "DEVORKS+").encode("utf-8")
    _VAULT_KB_KEY_CACHE = hashlib.pbkdf2_hmac(
        "sha256", secret, _VAULT_KB_SALT, _VAULT_KB_ITERS, dklen=32)
    return _VAULT_KB_KEY_CACHE


def _vault_kb_seal(obj) -> dict:
    """ВОЛНА 17: шифрует JSON-объект ключом бота → {"n", "d"} (hex) или {}."""
    if AESGCM is None:
        return {}
    try:
        nonce = os.urandom(12)
        ct = AESGCM(_vault_kb_key()).encrypt(
            nonce, json.dumps(obj, ensure_ascii=False).encode("utf-8"),
            _VAULT_KB_AAD)
        return {"n": nonce.hex(), "d": ct.hex()}
    except Exception as e:
        logger.warning(f"vault kb seal: {e}")
        return {}


def _vault_kb_open(enc):
    """ВОЛНА 17: расшифровывает {"n","d"} обратно в объект (или бросает)."""
    nonce = bytes.fromhex(str((enc or {}).get("n", "")))
    data = bytes.fromhex(str((enc or {}).get("d", "")))
    return json.loads(AESGCM(_vault_kb_key()).decrypt(
        nonce, data, _VAULT_KB_AAD).decode("utf-8"))


# === ВОЛНА 22.13: СЕКРЕТ ХРАНИЛИЩА (bot-side seal) ===
# Требование пользователя: «файл из ссылки обмена тоже должен шифроваться в
# канале, чтобы никто не мог посмотреть», и «в канале, где облако, всё должны
# шифроваться — разработчик не может ничего посмотреть». Файлы Сейфа шифруются
# ПАРОЛЕМ владельца (zero-knowledge), но копии для share-ссылок и решения в
# базе класса пароля владельца не имеют к моменту выдачи. Поэтому бот шифрует
# ИХ собственным ключом: DVF1-контейнер с паролем = PBKDF2(BOT_TOKEN, фикс.
# соль). В канале-хранилище НИКОГДА не появляется открытого содержимого —
# только шифр. Ключ живёт только в памяти процесса и выводится из BOT_TOKEN.
_STORAGE_SEAL_SALT = b"DEVORKS+storage-seal-v13"
_STORAGE_SEAL_PW_CACHE = None


def _storage_seal_pw():
    """Пароль-ключ бота для шифрования служебных копий файлов в канале.
    Детерминирован от BOT_TOKEN: переживает рестарт бота."""
    global _STORAGE_SEAL_PW_CACHE
    if _STORAGE_SEAL_PW_CACHE is None:
        secret = (os.environ.get("BOT_TOKEN") or "DEVORKS+").encode("utf-8")
        _STORAGE_SEAL_PW_CACHE = hashlib.pbkdf2_hmac(
            "sha256", secret, _STORAGE_SEAL_SALT, 60000, dklen=32).hex()
    return _STORAGE_SEAL_PW_CACHE


def _seal_pack(payload: bytes, name: str, mime: str = "", kind: str = "doc") -> bytes:
    """Шифрует байты ключом бота (DVF1). Возвращает контейнер."""
    return _vault_pack(_storage_seal_pw(), payload or b"", {
        "n": str(name or "file.bin")[:200],
        "m": str(mime or "")[:100],
        "k": str(kind or "doc")[:10],
        "t": datetime.now().strftime("%Y-%m-%d %H:%M"),
    })


def _seal_unpack(container: bytes):
    """Расшифровывает DVF1-контейнер ключом бота → (meta, payload)."""
    return _vault_unpack(_storage_seal_pw(), container)


def _vault_auth_open(auth) -> dict:
    """ВОЛНА 17: вид vault_auth с ОТКРЫТЫМ списком вопросов.
    enc-форма (вопросы зашифрованы) расшифровывается ключом бота;
    легаси-форма (вопросы в открытом виде, до волны 17) — как есть.
    При сбое расшифровки (например, сменился BOT_TOKEN) questions=None."""
    if not isinstance(auth, dict):
        return {}
    if "questions" in auth:
        return auth
    enc = auth.get("enc")
    out = dict(auth)
    if isinstance(enc, dict) and enc.get("n") and enc.get("d"):
        try:
            blob = _vault_kb_open(enc)
            out["questions"] = list(blob.get("q") or [])
        except Exception as e:
            logger.warning(f"vault auth: вопросы не расшифрованы ({e})")
            out["questions"] = None
    else:
        out["questions"] = None
    return out


def _vault_auth_seal(auth) -> dict:
    """ВОЛНА 17: убирает ОТКРЫТЫЕ тексты вопросов из vault_auth, шифруя их
    ключом бота (поле "enc"). rec (запечатанный пароль) уже шифр — не трогаем.
    Если cryptography недоступна — честно оставляем как было (легаси-форма).
    Возвращает НОВЫЙ словарь; вход не меняет."""
    if not isinstance(auth, dict):
        return auth
    q = auth.get("questions")
    if not (isinstance(q, list) and q):
        return auth
    enc = _vault_kb_seal({"q": q})
    if not enc:
        return auth
    out = dict(auth)
    out["enc"] = enc
    out.pop("questions", None)
    return out


def _vault_auth_pick(old_auth, new_auth):
    """ВОЛНА 17: какую связку ключей Сейфа оставить после восстановления —
    САМУЮ СВЕЖУЮ по метке времени "ts" (ISO-строка, лексикографика = хронология).
    old есть, new нет → old; new есть, old нет → new; обе → по ts (нет ts —
    считается самой старой); ts равны → new. Пароль Сейфа больше НЕ ОТКАТЫВАЕТСЯ
    восстановлением старого снапшота — просьба пользователя «бот должен
    запоминать пароль и вопросы»."""
    old_ok = isinstance(old_auth, dict) and old_auth.get("salt")
    new_ok = isinstance(new_auth, dict) and new_auth.get("salt")
    if old_ok and not new_ok:
        return old_auth
    if not old_ok and new_ok:
        return new_auth
    if not old_ok and not new_ok:
        return None
    to = str(old_auth.get("ts") or "")
    tn = str(new_auth.get("ts") or "")
    if to and not tn:
        return old_auth
    return new_auth if tn >= to else old_auth


def _vault_auth_valid(user) -> bool:
    """ВОЛНА 9/17: настроен ли ЕДИНЫЙ пароль Сейфа с 3 секретными вопросами.
    Принимает ОБЕ формы вопросов: легаси (открытый список) и enc (зашифрованные
    ключом бота — волна 17)."""
    auth = getattr(user, "vault_auth", None)
    if not (
        isinstance(auth, dict)
        and auth.get("salt") and auth.get("verifier")
        and isinstance(auth.get("rec"), dict)
    ):
        return False
    q = auth.get("questions")
    if isinstance(q, list) and len(q) >= VAULT_QUESTIONS_N:
        return True
    enc = auth.get("enc")
    return isinstance(enc, dict) and bool(enc.get("n")) and bool(enc.get("d"))


def _vault_restore_warning(users: dict) -> str:
    """ВОЛНА 17: честная пометка в отчёт восстановления: у пользователя есть
    зашифрованные файлы Сейфа, но связка ключей (пароль+вопросы) в базе
    отсутствует — файлы откроет только пароль, действовавший НА МОМЕНТ снапшота
    (если и он утерян — шифры не откроются уже никогда, это физика AES)."""
    try:
        n = 0
        for u in (users or {}).values():
            if not isinstance(u, dict):
                continue
            if (isinstance(u.get("vault_files"), list) and u["vault_files"]
                    and not isinstance(u.get("vault_auth"), dict)):
                n += 1
        if not n:
            return ""
        return ("🔐 В снапшоте нет пароля Сейфа для файлов " + str(n) + " польз. — "
                "открыть их сможет только пароль, действовавший НА МОМЕНТ этого "
                "снапшота (новый пароль их не откроет).")
    except Exception:
        return ""


def _vault_check_safe_password(user, password: str) -> bool:
    """Проверка ЕДИНОГО пароля Сейфа по верификатору (без скачивания файлов)."""
    auth = getattr(user, "vault_auth", None) or {}
    try:
        salt = bytes.fromhex(auth.get("salt", ""))
        iters = int(auth.get("iters") or VAULT_KDF_ITERS)
        key = _vault_derive_key(password, salt, iters)
        return hmac.compare_digest(_vault_verifier(key), bytes.fromhex(auth.get("verifier", "")))
    except Exception:
        return False


# ВОЛНА 11: таблица стойкости — за сколько пароль ПЕРЕБРАЛА БЫ супер-сильная
# машина (миллиарды попыток в секунду). Значения показываются пользователю
# ДОСЛОВНО при постановке пароля. В реальности никто перебирать не станет —
# файлы открывает только тот, кто знает пароль.
_VAULT_CRACK_TABLE = {
    7: "11 лет",
    8: "691 год",
    9: "42 800 лет",
    10: "2,6 миллиона лет",
    11: "165 миллионов лет",
    12: "10 миллиардов лет",
    13: "634 миллиарда лет",
}


def _vault_crack_time_for_len(n: int) -> str:
    """Человекочитаемая оценка времени перебора пароля длины n."""
    try:
        n = int(n)
    except (TypeError, ValueError):
        n = 0
    if n < VAULT_MIN_PASSWORD:
        return "меньше 11 лет — слишком коротко"
    if n in _VAULT_CRACK_TABLE:
        return _VAULT_CRACK_TABLE[n]
    return "более 634 миллиардов лет"


def _vault_strength_note(password: str) -> str:
    """Одна строка «стойкость вашего пароля» — показывается после принятия."""
    n = len(password or "")
    return (f"🔒 Стойкость вашего пароля: {n} симв. — "
            f"{_vault_crack_time_for_len(n)} на разгадку даже у супер-сильной машины.")


def _vault_strength_table_text() -> str:
    """Таблица стойкости при ПОСТАНОВКЕ пароля (значения дословно от разработчика)."""
    lines = [
        "📏 За сколько СУПЕР-СИЛЬНАЯ машина (миллиарды попыток в секунду) "
        "разгадала бы пароль в зависимости от длины:",
    ]
    for _n in sorted(_VAULT_CRACK_TABLE):
        lines.append(f"• {_n} символов — {_VAULT_CRACK_TABLE[_n]}.")
    lines.append("• 14 и больше — дольше, чем сотни раз существует Вселенная.")
    lines.append("")
    lines.append(
        "Спокойно: НИКТО этими переборами заниматься не станет — данные "
        "показали бы только в фантастическом сценарии, где пароль разгадывает "
        "супер-сильная машина. Реально файлы открывает лишь тот, кто знает пароль.")
    return "\n".join(lines)


def _vault_norm_answer(text: str) -> str:
    """Нормализация ответа: регистр и лишние пробелы не должны мешать."""
    return " ".join(str(text or "").lower().split())


def _vault_rec_key(answers, salt: bytes, iters: int) -> bytes:
    """Ключ запечатывания из ОТВЕТОВ на 3 вопроса (тот же PBKDF2, что и для
    пароля: 600 000 раундов — перебор ответов так же дорог, как пароля)."""
    joined = "\x1f".join(_vault_norm_answer(a) for a in answers)
    return _vault_derive_key(joined, salt, int(iters))


def _vault_seal_password(password: str, answers) -> dict:
    """ВОЛНА 9: запечатывает пароль Сейфа ключом из ответов на вопросы.

    Это честно делает восстановление РАБОТАЮЩИМ: бот НЕ хранит пароль,
    но хранит пароль, ЗАШИФРОВАННЫЙ ответами (AES-256-GCM). Без верных
    ответов блоб — случайный шум; с верными — распечатывается. AAD
    привязывает блоб к назначению (нельзя подставить его как файловый шифр)."""
    if AESGCM is None:
        raise RuntimeError("cryptography недоступна")
    salt = os.urandom(16)
    nonce = os.urandom(12)
    iters = VAULT_KDF_ITERS
    key = _vault_rec_key(answers, salt, iters)
    ct = AESGCM(key).encrypt(nonce, (password or "").encode("utf-8"), VAULT_REC_AAD)
    return {"salt": salt.hex(), "iters": iters, "nonce": nonce.hex(), "data": ct.hex()}


def _vault_unseal_password(rec, answers):
    """ВОЛНА 9: распечатывает запечатанный пароль по ответам.

    Возвращает пароль (str) или None — если неверно ХОТЬ ОДИН ответ
    (GCM-тег не сойдётся) либо блоб повреждён."""
    if not isinstance(rec, dict) or AESGCM is None:
        return None
    try:
        salt = bytes.fromhex(rec.get("salt", ""))
        iters = int(rec.get("iters") or VAULT_KDF_ITERS)
        nonce = bytes.fromhex(rec.get("nonce", ""))
        ct = bytes.fromhex(rec.get("data", ""))
        key = _vault_rec_key(answers, salt, iters)
        pw = AESGCM(key).decrypt(nonce, ct, VAULT_REC_AAD)
        return pw.decode("utf-8")
    except Exception:
        return None


def _vault_gen_id(user) -> str:
    files = getattr(user, "vault_files", []) or []
    while True:
        vid = ''.join(random.choices(string.ascii_lowercase + string.digits, k=8))
        if all(f.get("id") != vid for f in files if isinstance(f, dict)):
            return vid


def _vault_find_record(user, vid):
    for f in (getattr(user, "vault_files", []) or []):
        if isinstance(f, dict) and f.get("id") == vid:
            return f
    return None


def _vault_menu_text(user):
    files = [f for f in (getattr(user, "vault_files", []) or []) if isinstance(f, dict)]
    total_enc = sum(int(f.get("size_enc", 0) or 0) for f in files)
    _uch = _user_vault_channel(user)
    channels_n = len(get_cloud_channel_ids())
    if not channels_n and not _uch:
        return (
            "🔐 Сейф\n\n"
            "❌ Хранилище пока не подключено. Общее подключает разработчик, "
            "НО вы можете начать прямо сейчас: подключите СВОЙ приватный "
            "канал — 🔗 Моё облако → «➕ Подключить мой канал». Сейф хранит "
            "зашифрованные файлы в приватном канале — пока канала нет, "
            "шифровать некуда."
        )
    if not _vault_kdf_available():
        return (
            "🔐 Сейф временно недоступен: на сервере нет библиотеки "
            "шифрования. Разработчику нужно выполнить:\n"
            "pip install cryptography"
        )
    if _uch:
        storage_line = f"☁️ Хранилище: ВАШ личный канал «{_uch[1]}»"
    else:
        storage_line = f"☁️ Каналов-хранилищ: {channels_n}"
    return (
        "🔐 Сейф — шифрованное хранилище\n\n"
        f"🔒 Файлов: {len(files)} • зашифровано {_fmt_bytes(total_enc)}\n"
        f"{storage_line}\n\n"
        "ОДИН ПАРОЛЬ открывает весь Сейф. Файлы шифруются им (AES-256, ключ "
        "выводится 600 000 раундами) и уходят в канал только шифром — открыть "
        "не сможет никто: ни разработчик, ни владелец сервера, ни Telegram.\n\n"
        "🔑 Забыли пароль? Восстановление по ВАШИМ 3 секретным вопросам: "
        "ответите верно — зададите новый пароль и вернёте данные. "
        "Попыток: 3, после — пауза 30 минут. Сами ответы нигде не хранятся — "
        "только пароль, запечатанный ими: без верных ответов он не читается.\n\n"
        "❌ После распаковки файл исчезает из чата кнопкой «Отменить» "
        "В КЛАВИАТУРЕ снизу (отключить — в ⚙️ Настройках).\n\n"
        "⚖️ Сейф и Облако вы используете на свой риск: даже при сбоях бота "
        "разработчик не отвечает за ваши данные. Полные условия — «⚖️ "
        "Правовая информация» в ⚙️ Настройках.\n\n"
        "Выберите действие:"
    )


# ============================================================
# === ВОЛНА 14: ДО 2 ГБ — гибрид Bot API + MTProto (Telethon) ===
# ============================================================
# Bot API жёстко ограничен: скачивание ботом ≤20 МБ, отправка ≤50 МБ.
# MTProto под тем же бот-токеном (клиент Telethon) поднимает ОБЕ стороны
# до 2 ГБ — это потолок Telegram для ботов (4 ГБ — только Premium у людей,
# ботам Premium недоступен). Цепочка для большого файла:
#   приём: ВОЛНА 17 — НЕ копируем никуда: источник — сообщение пользователя
#   в личном чате (сырых файлов в каналах больше нет — по требованию);
#   «✅ Готово»: Telethon качает сообщение ПОТОКОМ → шифр DVF2 (куски 1 МБ,
#   AES-256-GCM) пишется во временный файл → контейнер в cloud-канал
#   (≤49 МБ — Bot API, больше — MTProto) → при успехе оригинал из чата стёрт;
#   выдача: Telethon качает шифр потоком → расшифровка на лету (в ОЗУ только
#   куски) → временный файл → отправка пользователю (до 2 ГБ) → стёрт.
# Файлы ≤20 МБ работают как раньше (DVF1 целиком в памяти) — ноль регрессий.

try:
    import shutil as _shutil
    import tempfile as _tempfile
except Exception:  # pragma: no cover
    _shutil = None
    _tempfile = None

_TELETHON_OK = False
try:
    from telethon import TelegramClient as _TGClient
    from telethon.sessions import StringSession as _StringSession
    from telethon.tl.types import (
        InputPeerUser as _InputPeerUser,
        InputPeerChannel as _InputPeerChannel,
    )
    from telethon.errors import FloodWaitError as _FloodWaitError
    try:  # ВОЛНА 21: перебор api_id-пар требует ловить ApiIdInvalid
        from telethon.errors import (
            ApiIdInvalidError as _ApiIdInvalidError,
            ApiIdPublishedFloodError as _ApiIdPubFloodError,
        )
    except Exception:
        _ApiIdInvalidError = None
        _ApiIdPubFloodError = None
    _TELETHON_OK = True
except Exception as _telethon_import_err:  # честная деградация без Telethon
    _TGClient = None
    _StringSession = None
    _InputPeerUser = None
    _InputPeerChannel = None
    _FloodWaitError = None
    _ApiIdInvalidError = None
    _ApiIdPubFloodError = None
    # ВОЛНА 19: молчаливый импорт маскировал причину — на Render было видно
    # только «MTProto недоступен», а ПОЧЕМУ — только в логах сборки.
    try:
        logging.getLogger(__name__).error(
            "telethon: библиотека не импортировалась — файлы >20 МБ "
            f"недоступны. Причина: {_telethon_import_err!r}")
    except Exception:
        pass

# api_id/api_hash: строго БЕЗ личных ключей пользователя (он их не даёт —
# и не нужно). Официальные клиенты Telegram открыты в исходниках и ходят
# в API со СВОИМИ публичными парами — используем их. ВОЛНА 21: пара
# 2048/b18441… отвергнута Telegram (ApiIdInvalidError, подтверждено в
# проде), поэтому вместо одной константы — СПИСОК публичных пар с
# автоворотом: если Telegram отклонил пару, клиент молча пробует
# следующую, а рабочая пара запоминается до рестарта. Свою пару можно
# задать в env (TELEGRAM_API_ID + TELEGRAM_API_HASH) — она получит
# наивысший приоритет.
_MT_API_PAIRS = []
_e_api_id = (_env("TELEGRAM_API_ID", "") or "").strip()
_e_api_hash = (_env("TELEGRAM_API_HASH", "") or "").strip()
if _e_api_id.isdigit() and int(_e_api_id) > 0 and _e_api_hash:
    _MT_API_PAIRS.append((int(_e_api_id), _e_api_hash, "env"))
# Публичная пара Telegram Android из официального репозитория
# (BuildVars.java) — ПЕРВАЯ: проверено вживую (2026-09, реальный замер
# с фейковым токеном) — Telegram ПРИНИМАЕТ её для ботов
# (AccessTokenInvalidError на фейковый токен, НЕ ApiIdInvalidError).
_MT_API_PAIRS.append((6, "eb06d4abfb49dc3eeb1aeb98ae0f581e",
                      "Telegram Android"))
# Публичная пара Telegram Desktop из официального репозитория tdesktop
# (config.h) — запасная: тот же замер показал, что с 2026-09 Telegram
# отвергает её для ImportBotAuthorizationRequest — ротация пропустит
# её мгновенно, если Android-пара когда-нибудь перестанет работать.
_MT_API_PAIRS.append((611835, "d524b414d21f4d37f08684c1df41ac9c",
                      "Telegram Desktop"))
_MT_PAIR_IDX = 0  # индекс пары, которая последней сработала


def _is_api_id_error(e: Exception) -> bool:
    """ВОЛНА 21: это ошибка «пара api_id/api_hash отклонена Telegram»?
    Ловим и по классу, и по тексту (на случай старой версии Telethon,
    где класс импортируется иначе)."""
    try:
        if _ApiIdInvalidError is not None and isinstance(e, _ApiIdInvalidError):
            return True
        if _ApiIdPubFloodError is not None and isinstance(e, _ApiIdPubFloodError):
            return True
    except Exception:
        pass
    _s = repr(e)
    return ("ApiIdInvalidError" in _s
            or "api_id/api_hash combination" in _s)

_MT_CLIENT = None
_MT_LOCK = None
# ВОЛНА 19: ПОСЛЕДНЯЯ причина, почему MTProto-клиент недоступен. Раньше
# пользователь видел безликое «MTProto недоступен (нет Telethon/BOT_TOKEN)»
# даже когда Telethon установлен, а падало именно ПОДКЛЮЧЕНИЕ (сеть/сессия) —
# из-за этого причина сбоя выглядела неправдоподобно и путала.
_MT_LAST_ERR = ""
_MT_SESSION_FILE = None  # лениво через _data_file()


def _mt_session_path() -> str:
    """ВОЛНА 20: путь к файлу сохранённой MTProto-сессии бота. Живёт в
    каталоге данных: сессия переживает рестарт Render, и бот перестаёт
    создавать НОВУЮ авторизацию при каждом старте/попытке — именно частые
    новые авторизации Telegram ограничивает FLOOD_WAIT'ом, что и роняло
    большие файлы с «не поднялся MTProto-клиент»."""
    global _MT_SESSION_FILE
    if _MT_SESSION_FILE is None:
        _MT_SESSION_FILE = _data_file("mt_session.txt")
    return _MT_SESSION_FILE


def _mt_load_saved_session() -> str:
    try:
        with open(_mt_session_path(), "r", encoding="utf-8") as fh:
            return (fh.read() or "").strip()
    except Exception:
        return ""


def _mt_save_session(sess_str: str) -> None:
    try:
        if not sess_str:
            return
        tmp = _mt_session_path() + ".tmp"
        with open(tmp, "w", encoding="utf-8") as fh:
            fh.write(sess_str)
        os.replace(tmp, _mt_session_path())
    except Exception as e:
        logger.warning(f"mtproto: сессия не сохранена ({e})")


def _mt_unavailable_reason() -> str:
    """ВОЛНА 19: честная причина недоступности MTProto — для сообщений
    пользователю и для логов. Вызывать, когда _mt_client() вернул None."""
    global _MT_LAST_ERR
    if not _TELETHON_OK:
        return ("библиотека Telethon не установлена — пересоберите деплой "
                "из нового zip (requirements.txt: telethon>=1.36)")
    if not BOT_TOKEN:
        return "нет токена бота (BOT_TOKEN)"
    return _MT_LAST_ERR or ("клиент MTProto не смог подключиться к Telegram "
                            "(сеть/сессия) — повторите через минуту")


async def _mt_client():
    """Единственный MTProto-клиент бота (Telethon) — поднимается ЛЕНИВО при
    первой операции с файлами >20 МБ и живёт до конца процесса. Сессия бота
    создаётся по токену (без телефона, без api_id от пользователя — берётся
    публичный id Telegram Desktop). Возвращает клиент или None.
    ВОЛНА 19: самовосстановление — битая env-сессия не ломает MTProto.
    ВОЛНА 20: ПОЛНАЯ ЛЕСТНИЦА СЕССИЙ [сохранённая на диске → чистая →
    чистая], таймауты 45/60 с на каждый сетевой шаг, особая обработка
    FloodWaitError (ждём ровно столько, сколько велел Telegram), проверка
    get_me() после входа и СОХРАНЕНИЕ рабочей сессии на диск — чтобы бот
    перестал создавать новую авторизацию на каждую попытку и не загонял
    себя в FLOOD_WAIT.
    ВОЛНА 21: АВТОВОРОТ публичных api_id-пар (env → Telegram Desktop →
    Telegram Android): отклонённая пара (ApiIdInvalidError) больше НЕ
    ломает подключение и НЕ съедает попытку сессии — клиент молча пробует
    следующую пару, а сработавшая запоминается до рестарта."""
    global _MT_CLIENT, _MT_LOCK, _MT_LAST_ERR, _MT_PAIR_IDX
    if not _TELETHON_OK:
        _MT_LAST_ERR = ("библиотека Telethon не установлена — пересоберите "
                        "деплой из нового zip (requirements.txt: telethon>=1.36)")
        return None
    if not BOT_TOKEN:
        _MT_LAST_ERR = "нет токена бота (BOT_TOKEN)"
        return None
    if _MT_LOCK is None:
        _MT_LOCK = asyncio.Lock()
    async with _MT_LOCK:
        if _MT_CLIENT is not None:
            try:
                if _MT_CLIENT.is_connected():
                    return _MT_CLIENT
            except Exception:
                pass
        env_session = (_env("TELETHON_SESSION", "") or "").strip()
        saved_session = _mt_load_saved_session()
        if env_session:
            ladder = [env_session, saved_session or "", ""]
        elif saved_session:
            ladder = [saved_session, ""]
        else:
            ladder = ["", ""]
        client = None
        last_exc = None
        for _try, _sess_val in enumerate(ladder, 1):
            if _sess_val and _sess_val == env_session:
                _tag = "env"
            elif _sess_val:
                _tag = "сохранённая"
            else:
                _tag = "чистая"
            # ВОЛНА 21: перебор публичных api_id-пар. Отклонённая пара
            # (ApiIdInvalidError) НЕ съедает попытку сессии — внутри одной
            # ступени лестницы молча пробуем следующую пару. Порядок:
            # сначала та, что последней сработала, затем остальные.
            _pair_order = ([_MT_PAIR_IDX]
                           + [i for i in range(len(_MT_API_PAIRS))
                              if i != _MT_PAIR_IDX])
            _pair_rejects = 0
            _pair_last_rej = None
            for _pi in _pair_order:
                _pid, _phash, _plabel = _MT_API_PAIRS[_pi]
                try:
                    client = _TGClient(
                        _StringSession(_sess_val), _pid, _phash,
                        device_model="DEVORKS+ Bot", system_version="Linux",
                        app_version="14.0", flood_sleep_threshold=120,
                    )
                    try:
                        await asyncio.wait_for(client.connect(), timeout=45)
                    except asyncio.TimeoutError:
                        raise RuntimeError(
                            "подключение к Telegram не за 45 с (сеть сервера?)")
                    if not await client.is_user_authorized():
                        try:
                            await asyncio.wait_for(
                                client.sign_in(bot_token=BOT_TOKEN), timeout=60)
                        except asyncio.TimeoutError:
                            raise RuntimeError(
                                "авторизация бота не прошла за 60 с")
                    try:
                        _me = await asyncio.wait_for(client.get_me(), timeout=30)
                        logger.info("mtproto: бот авторизован как "
                                    f"@{getattr(_me, 'username', '?')}")
                    except Exception as _me_err:
                        logger.warning(f"mtproto: get_me не ответила ({_me_err}) "
                                       "— не критично")
                    _MT_CLIENT = client
                    _MT_PAIR_IDX = _pi
                    try:
                        _mt_save_session(str(client.session.save() or ""))
                    except Exception as _se:
                        logger.warning(f"mtproto: сессию не запомнил ({_se})")
                    _dvf2_tmp_sweep()
                    _MT_LAST_ERR = ""
                    logger.info(f"mtproto: клиент поднялся (попытка {_try}, "
                                f"сессия {_tag}, пара {_plabel}) — файлы до "
                                "2 ГБ доступны")
                    return _MT_CLIENT
                except _FloodWaitError as fw:
                    _fw_s = int(getattr(fw, "seconds", 0) or 0)
                    _wait_s = min(max(_fw_s, 10), 120)
                    logger.error(f"mtproto: FLOOD_WAIT {_fw_s}с при поднятии "
                                 f"клиента (попытка {_try}/{len(ladder)}, "
                                 f"пара {_plabel}) — жду {_wait_s}с")
                    _MT_LAST_ERR = (f"Telegram просит паузу {_fw_s}с на "
                                    "авторизацию MTProto (слишком много новых "
                                    "сессий подряд) — повторите через пару минут")
                    if client is not None:
                        try:
                            await client.disconnect()
                        except Exception:
                            pass
                        client = None
                    await asyncio.sleep(_wait_s + 2)
                    break  # FloodWait сменой пары не лечится — следующая ступень
                except Exception as e:
                    if _is_api_id_error(e):
                        _pair_rejects += 1
                        _pair_last_rej = e
                        logger.warning(f"mtproto: пара api_id отклонена "
                                       f"({_plabel}): {e!r} — молча пробую "
                                       "следующую пару")
                        if client is not None:
                            try:
                                await client.disconnect()
                            except Exception:
                                pass
                            client = None
                        continue
                    last_exc = e
                    logger.error(f"mtproto: клиент не поднялся "
                                 f"(попытка {_try}/{len(ladder)}, сессия "
                                 f"{_tag}, пара {_plabel}): {e!r}")
                    _MT_LAST_ERR = (f"клиент MTProto не смог подключиться к "
                                    f"Telegram ({e!r})")
                    if client is not None:
                        try:
                            await client.disconnect()
                        except Exception:
                            pass
                        client = None
                    if _try < len(ladder):
                        await asyncio.sleep(2)  # сразу рвать связь не стоит
                    break  # серьёзная ошибка сменой пары не лечится
            if _pair_rejects >= len(_pair_order):
                # ВОЛНА 21: все пары в этой ступени отклонены — честная
                # причина вместо безликого «не поднялся».
                _MT_LAST_ERR = ("Telegram отклонил все публичные пары "
                                f"api_id ({_pair_rejects} шт., последняя: "
                                f"{_pair_last_rej!r})")
        if not _MT_LAST_ERR:
            _MT_LAST_ERR = (f"клиент MTProto не смог подключиться "
                            f"({last_exc!r})")
        return None


_MT_KEEPALIVE_TASK = None


def _mt_keepalive_kick():
    """ВОЛНА 20: фоновый догрев MTProto из единого тикера (каждые 30 с).
    Если клиент ещё не поднят — запускает поднятие В ФОНЕ (не блокируя
    тикер: FloodWait-паузы внутри фоновой задачи, а не в тике). Благодаря
    сохранённой на диске сессии догрев почти всегда мгновенный и без новых
    авторизаций; когда клиент уже поднят — функция ничего не делает."""
    global _MT_KEEPALIVE_TASK
    if not _TELETHON_OK or not BOT_TOKEN:
        return
    if _MT_CLIENT is not None:
        return
    _t = _MT_KEEPALIVE_TASK
    if _t is not None and not _t.done():
        return  # предыдущий догрев ещё работает — не плодим задачи
    _MT_KEEPALIVE_TASK = asyncio.ensure_future(_mt_keepalive_bg())


async def _mt_keepalive_bg():
    try:
        await _mt_client()
    except Exception as e:
        logger.warning(f"mtproto: фоновый догрев не удался ({e})")


async def _mt_warmup():
    """ВОЛНА 16: прогрев MTProto при старте — клиент поднимается ЗАРАНЕЕ
    (а не при первом файле >20 МБ) и строит кэш сущностей. После рестарта
    Render большие файлы (до 2 ГБ) работают сразу. Любая ошибка — не
    критична: режим остаётся ленивым и повторит попытку при операции.
    ВОЛНА 18: get_dialogs ботам Telegram НЕ разрешает (user-only API) —
    это было пустышкой; вместо неё честно прогреваем кэш КАНАЛОВ-хранилищ
    (get_messages с hash=0 ботам разрешён и кэширует access_hash)."""
    try:
        client = await _mt_client()
        if client is None:
            logger.info(f"mtproto: прогрев пропущен ({_mt_unavailable_reason()})")
            return
        _dlg_ok = True
        try:
            await client.get_dialogs(limit=100)
        except Exception:
            _dlg_ok = False  # для бота это норма, а не сбой
        _ok_ch = _all_ch = 0
        _cl = list(get_cloud_channel_ids() or [])
        for _c in (get_db_channel_ids() or []):
            if _c not in _cl:
                _cl.append(_c)
        for ch in _cl:
            _all_ch += 1
            try:
                await client.get_messages(_mt_peer_channel(ch), limit=1)
                _ok_ch += 1
            except Exception:
                pass
        if _dlg_ok:
            logger.info("mtproto: прогрев готов — большие файлы до 2 ГБ доступны")
        elif _all_ch:
            logger.info(f"mtproto: прогрев готов (каналы {_ok_ch}/{_all_ch}) — "
                        "большие файлы до 2 ГБ доступны")
        else:
            logger.info("mtproto: клиент поднят — большие файлы до 2 ГБ доступны")
    except Exception as e:
        logger.warning(f"mtproto: прогрев не удался (не критично): {e}")


def _mt_peer_channel(ch_id):
    """Bot API id канала (-100…) → InputPeerChannel. Ботам Telegram разрешает
    access_hash=0 для каналов, где бот администратор — это наш случай."""
    cid = int(ch_id)
    raw = -cid - 1000000000000 if cid <= -1000000000000 else cid
    return _InputPeerChannel(raw, 0)


def _mt_peer_user(user_id, access_hash=0):
    """InputPeerUser для личного чата. Для ботов Telegram принимает
    access_hash=0 от пользователей, которые писали боту; ВОЛНА 18 — можно
    передать и НАСТОЯЩИЙ access_hash (запомненный при приёме файла)."""
    return _InputPeerUser(int(user_id), int(access_hash or 0))


def _dvf2_tmp_dir():
    """Каталог временных файлов перекачки (системный tmp)."""
    try:
        return _tempfile.gettempdir()
    except Exception:
        return "/tmp"


def _dvf2_tmp_sweep():
    """Уборка после сбоев: временные файлы/каталоги dvf2_*, старше 24 ч,
    стираются (если процесс умер посреди перекачки, файл не лежит вечно)."""
    try:
        now = time.time()
        d = _dvf2_tmp_dir()
        for fn in os.listdir(d):
            if not fn.startswith("dvf2_"):
                continue
            p = os.path.join(d, fn)
            try:
                if now - os.path.getmtime(p) > 86400:
                    if os.path.isdir(p):
                        _shutil.rmtree(p, ignore_errors=True)
                    else:
                        os.unlink(p)
            except Exception:
                pass
    except Exception as e:
        logger.warning(f"dvf2: уборка tmp не удалась: {e}")


def _dvf2_disk_ok(need_bytes):
    """Хватит ли на диске места под временный файл (с запасом 64 МБ).
    Если проверить не удалось — не блокируем: ошибку поймает запись."""
    try:
        free = _shutil.disk_usage(_dvf2_tmp_dir()).free
    except Exception:
        return True
    try:
        return free > int(need_bytes or 0) + 64 * 1024 * 1024
    except Exception:
        return True


def _dvf2_make_job_dir():
    """Отдельный каталог на время перекачки одного файла — чтобы имя файла
    для Telegram можно было задать переименованием, а уборка была одной
    командой (rmtree)."""
    return _tempfile.mkdtemp(prefix="dvf2_job_")


def _dvf2_safe_name(name):
    """Имя файла без разделителей пути и управляющих символов."""
    name = str(name or "").replace("/", "_").replace("\\", "_")
    name = "".join(ch for ch in name if ord(ch) >= 32)
    name = name.strip().lstrip(".") or "file.bin"
    return name[:120]


class _ProgressEdit:
    """Редкие правки сообщения-прогресса (не чаще раза в 3.5 с — лимиты
    editMessageText), чтобы потоковые операции 2 ГБ не упирались во флуд.
    ВОЛНА 22.5: если у сообщения-прогресса есть inline-клавиатура — она
    СОХРАНЯЕТСЯ при каждой правке (22.8: кнопок на прогрессе больше нет,
    reply_markup остаётся None).
    ВОЛНА 22.12: при передаче done/total рисует ПОЛОСУ ПРОГРЕССА в стиле
    [▓▓▓░░░░░░░] с размерами, скоростью и остатком времени."""

    def __init__(self, context, progress_msg, title="", reply_markup=None):
        self.context = context
        self.msg = progress_msg
        self.title = title or ""
        self.reply_markup = reply_markup
        self._last = 0.0
        self._sp_t = None      # время прошлого замера скорости
        self._sp_done = 0      # байты на прошлом замере
        self._sp_ema = 0.0     # сглаженная скорость (байт/с)

    def _bar_line(self, text, done, total):
        """Формирует строку с полосой, скоростью и ETA (22.12)."""
        now = time.monotonic()
        try:
            done = max(0, int(done or 0))
            total = max(0, int(total or 0))
        except (TypeError, ValueError):
            return text or self.title
        if total > 0 and done >= 0:
            if self._sp_t is not None and now > self._sp_t:
                inst = (done - self._sp_done) / (now - self._sp_t)
                self._sp_ema = (0.65 * self._sp_ema + 0.35 * inst
                                if self._sp_ema else inst)
            self._sp_t, self._sp_done = now, done
            line = (f"[{_vault_bar(done, total)}] {_fmt_bytes(done)} / "
                    f"{_fmt_bytes(total)} ({done * 100 // total}%)")
            if self._sp_ema > 1:
                line += f"\n⚡ {_fmt_bytes(int(self._sp_ema))}/с"
                _eta = (total - done) / self._sp_ema
                if 0 <= _eta < 86400 * 7:
                    line += f" | ⏱ осталось {_fmt_eta(int(_eta))}"
            return (text + "\n" + line) if text else line
        return text or self.title

    async def edit(self, text=None, force=False, done=None, total=None):
        if self.msg is None:
            return None
        now = time.monotonic()
        if not force and (now - self._last) < 3.5:
            return None
        self._last = now
        if done is not None or total is not None:
            text = self._bar_line(text, done, total)
        try:
            return await self.context.bot.edit_message_text(
                text or self.title,
                chat_id=self.msg.chat_id, message_id=self.msg.message_id,
                reply_markup=self.reply_markup,
            )
        except Exception:
            return None


class _Dvf2Encryptor:
    """Потоковое шифрование DVF2 в файл: push() скармливает куски открытого
    текста, finish() дописывает хвост и закрывает файл. В ОЗУ — не больше
    одного куска (1 МБ) независимо от размера исходного файла.
    Формат: DVF2|ver|iters(4)|salt(16)|np(4)|hdr_len(4)|hdr_ct|блоки…
    hdr_ct = AESGCM(key, np+0xff*8, json{имя,тип,mime,дата,sz,bs});
    блок i: nonce = np + i (8 байт BE), ct = AESGCM(key, nonce, кусок,
    aad=b"DVF2-B"+i) — переставить/выбросить кусок нельзя."""

    def __init__(self, password, meta, out_path):
        self.salt = os.urandom(16)
        self.np = os.urandom(4)
        self.iters = VAULT_KDF_ITERS
        self.key = _vault_derive_key(password, self.salt, self.iters)
        m = dict(meta or {})
        m["bs"] = VAULT_DVF2_BLOCK
        self.meta = m
        hdr = json.dumps(m, ensure_ascii=False).encode("utf-8")
        nonce_hdr = self.np + b"\xff" * 8
        ct = AESGCM(self.key).encrypt(
            nonce_hdr, hdr, VAULT_DVF2_MAGIC + bytes([VAULT_DVF2_VERSION]))
        header = (VAULT_DVF2_MAGIC + bytes([VAULT_DVF2_VERSION])
                  + int(self.iters).to_bytes(4, "big") + self.salt + self.np
                  + len(ct).to_bytes(4, "big") + ct)
        self._hdr_len = len(header)
        self._fh = open(out_path, "wb")
        self._fh.write(header)
        self._buf = bytearray()
        self._idx = 0
        self._total = 0
        self._closed = False

    def push(self, chunk):
        self._buf.extend(chunk)
        while len(self._buf) >= VAULT_DVF2_BLOCK:
            self._push_block(bytes(self._buf[:VAULT_DVF2_BLOCK]))
            del self._buf[:VAULT_DVF2_BLOCK]

    def _push_block(self, block):
        nonce = self.np + self._idx.to_bytes(8, "big")
        ct = AESGCM(self.key).encrypt(
            nonce, block, b"DVF2-B" + self._idx.to_bytes(8, "big"))
        self._fh.write(ct)
        self._total += len(ct)
        self._idx += 1

    def finish(self):
        """Дописывает хвост (<1 МБ), закрывает файл. Возвращает полный
        размер контейнера (заголовок + шифр)."""
        if not self._closed:
            if self._buf:
                self._push_block(bytes(self._buf))
                self._buf = bytearray()
            self._fh.flush()
            os.fsync(self._fh)
            self._fh.close()
            self._closed = True
        return self._hdr_len + self._total

    def abort(self):
        """Аварийное закрытие (при сбое перекачки)."""
        self._closed = True
        try:
            self._fh.close()
        except Exception:
            pass

    def salt_hex(self):
        return self.salt.hex()

    def np_hex(self):
        return self.np.hex()

    def verifier_hex(self):
        return _vault_verifier(self.key).hex()


class _Dvf2Decryptor:
    """Потоковая расшифровка DVF2: push() принимает куски шифра (какими их
    отдаёт сеть), сам накапливает и разбирает заголовок, отдаёт открытый
    текст куска́ми ≤1 МБ. finish() допечатывает хвост и проверяет размер.
    Неверный пароль → ValueError уже на заголовке (контент не качается зря)."""

    def __init__(self, password):
        self._password = password
        self._hdr = bytearray()
        self.key = None
        self.np = None
        self.meta = None
        self.bs = VAULT_DVF2_BLOCK
        self._sz = 0
        self._idx = 0
        self._buf = bytearray()
        self._out_total = 0

    def push(self, chunk):
        if self.meta is None:
            self._hdr.extend(chunk)
            return self._try_parse_header()
        return self._push_ct(chunk)

    def _try_parse_header(self):
        if len(self._hdr) < 33:
            return b""
        if bytes(self._hdr[:4]) != VAULT_DVF2_MAGIC:
            raise ValueError("это не контейнер Сейфа")
        if self._hdr[4] != VAULT_DVF2_VERSION:
            raise ValueError(f"неизвестная версия контейнера: {self._hdr[4]}")
        iters = int.from_bytes(bytes(self._hdr[5:9]), "big")
        salt = bytes(self._hdr[9:25])
        np_ = bytes(self._hdr[25:29])
        hdr_len = int.from_bytes(bytes(self._hdr[29:33]), "big")
        if hdr_len <= 0 or hdr_len > 1024 * 1024:
            raise ValueError("повреждённый контейнер")
        if len(self._hdr) < 33 + hdr_len:
            return b""
        hdr_ct = bytes(self._hdr[33:33 + hdr_len])
        rest = bytes(self._hdr[33 + hdr_len:])
        self.key = _vault_derive_key(self._password, salt, iters)
        self.np = np_
        try:
            plain = AESGCM(self.key).decrypt(
                np_ + b"\xff" * 8, hdr_ct,
                VAULT_DVF2_MAGIC + bytes([VAULT_DVF2_VERSION]))
        except Exception:
            raise ValueError("неверный пароль")
        try:
            meta = json.loads(plain.decode("utf-8"))
        except Exception:
            meta = {}
        if not isinstance(meta, dict):
            meta = {}
        self.meta = meta
        self.bs = int(meta.get("bs") or VAULT_DVF2_BLOCK)
        self._sz = int(meta.get("sz") or 0)
        if rest:
            return self._push_ct(rest)
        return b""

    def _push_ct(self, chunk):
        self._buf.extend(chunk)
        out = bytearray()
        while len(self._buf) >= self.bs + VAULT_DVF2_TAG:
            out.extend(self._decrypt_block(bytes(self._buf[:self.bs + VAULT_DVF2_TAG])))
            del self._buf[:self.bs + VAULT_DVF2_TAG]
        return bytes(out)

    def _decrypt_block(self, ct):
        nonce = self.np + self._idx.to_bytes(8, "big")
        try:
            pt = AESGCM(self.key).decrypt(
                nonce, ct, b"DVF2-B" + self._idx.to_bytes(8, "big"))
        except Exception:
            raise ValueError("неверный пароль")
        self._idx += 1
        self._out_total += len(pt)
        return pt

    def finish(self):
        if self.meta is None:
            raise ValueError("контейнер повреждён (нет заголовка)")
        tail = bytearray()
        if self._buf:
            tail.extend(self._decrypt_block(bytes(self._buf)))
            self._buf = bytearray()
        if self._sz and self._out_total != self._sz:
            raise ValueError(
                f"контейнер неполный: ожидалось {self._sz} байт, "
                f"получено {self._out_total}")
        return bytes(tail)


async def _mt_run_with_flood(coro_factory, tries=4):
    """Запускает корутину, пережидая FloodWait (до tries раз)."""
    last_err = None
    for _ in range(max(1, tries)):
        try:
            return await coro_factory()
        except _FloodWaitError as e:
            wait = min(int(getattr(e, "seconds", 30) or 30) + 1, 900)
            logger.warning(f"mtproto: FloodWait {wait} с")
            last_err = e
            await asyncio.sleep(wait)
    raise RuntimeError(f"Telegram просит паузу {getattr(last_err, 'seconds', '?')} с")


async def _mt_resolve_channel(client, ch_id):
    """ВОЛНА 16: надёжный InputPeer канала для бота. Порядок попыток:
    1) кэш Telethon (правильный access_hash — Telethon сидит под ТЕМ же
       токеном и получает те же апдейты, что и Bot API, поэтому помнит
       сущности всех чатов бота);
    2) прогрев кэша через get_dialogs (бот видит чаты, где он участник)
       и повторная попытка;
    3) классический приём ботов — InputPeerChannel(id, 0): Telegram
       разрешает access_hash=0 ботам-участникам канала.
    После рестарта Render кэш пуст — раньше это могло дать CHANNEL_INVALID
    на первом же большом файле; теперь лечится автоматически."""
    try:
        return await client.get_input_entity(int(ch_id))
    except Exception:
        pass
    try:
        await client.get_dialogs(limit=100)
    except Exception:
        pass
    try:
        return await client.get_input_entity(int(ch_id))
    except Exception:
        return _mt_peer_channel(ch_id)


async def _mt_fetch_document_peer(client, peer, msg_id):
    """Достаёт сообщение по ГОТОВОМУ peer'у и его документ (MTProto).
    Возвращает (message, document) или (message_or_None, None)."""
    m = await _mt_run_with_flood(
        lambda: client.get_messages(peer, ids=int(msg_id)))
    if m is None:
        return None, None
    doc = getattr(m, "document", None) or getattr(m, "photo", None)
    return m, doc


async def _mt_resolve_peer(client, peer_id):
    """ВОЛНА 17: надёжный InputPeer для КАНАЛА (id < 0) И ЛИЧНОГО чата
    (id > 0 — обычный пользователь). Личный чат нужен для больших файлов
    Сейфа: источник — сообщение пользователя в личке (сырых копий в каналах
    больше нет). У юзера access_hash обязателен: берём из кэша сессии
    (юзер только что писал боту — апдейты того же токена уже прогрели кэш),
    иначе догреваем через get_dialogs и пробуем снова."""
    pid = int(peer_id)
    if pid < 0:
        return await _mt_resolve_channel(client, pid)
    try:
        return await client.get_input_entity(pid)
    except Exception:
        pass
    try:
        await client.get_dialogs(limit=200)
    except Exception:
        pass
    try:
        return await client.get_input_entity(pid)
    except Exception:
        raise RuntimeError(
            "личный чат не найден в кэше Telethon — попробуйте ещё раз "
            "через минуту (кэш прогреется сам)")


async def _mt_resolve_peer_ah(client, peer_id):
    """ВОЛНА 18: (peer, access_hash) для ЛИЧНОГО чата — не бросает.
    peer=None, если сущность не найдена; access_hash=0, если неизвестен.
    Нужен прогреву при приёме большого файла: access_hash запоминается в
    элементе пачки и используется при шифровании, даже если кэш сессии
    к тому моменту потеряется."""
    pid = int(peer_id)
    for _attempt in (0, 1):
        try:
            peer = await client.get_input_entity(pid)
            return peer, int(getattr(peer, "access_hash", 0) or 0)
        except Exception:
            pass
        if _attempt == 0:
            try:
                await client.get_dialogs(limit=200)
            except Exception:
                pass
    return None, 0


async def _mt_fetch_document(client, peer_id, msg_id, ah=0):
    """Достаёт сообщение (канал ИЛИ личный чат — волна 17) и его документ
    (MTProto). Возвращает (message, document) или (message_or_None, None).
    ВОЛНА 18: для ЛИЧНОГО чата цепочка peer'ов — кэш Telethon →
    сохранённый access_hash (запомнен прогревом при приёме файла) → hash=0:
    раньше холодный кэш после рестарта Render ронял загрузку Сейфа целиком
    (get_dialogs ботам Telegram не разрешает, догреть кэш было нечем).
    Исключение бросаем, только если упали ВСЕ попытки (сеть/права)."""
    pid, mid = int(peer_id), int(msg_id)
    if pid < 0:
        peer = await _mt_resolve_channel(client, pid)
        return await _mt_fetch_document_peer(client, peer, mid)
    attempts, seen = [], set()
    try:
        peer = await client.get_input_entity(pid)
        seen.add((pid, int(getattr(peer, "access_hash", 0) or 0)))
        attempts.append(peer)
    except Exception:
        pass
    if int(ah or 0) and (pid, int(ah)) not in seen:
        seen.add((pid, int(ah)))
        attempts.append(_mt_peer_user(pid, int(ah)))
    if (pid, 0) not in seen:
        attempts.append(_mt_peer_user(pid, 0))
    if not attempts:
        attempts.append(_mt_peer_user(pid, 0))
    last_err, last_res = None, None
    for peer in attempts:
        try:
            res = await _mt_fetch_document_peer(client, peer, mid)
        except Exception as e:
            last_err = e
            continue
        last_res = res
        if res[1] is not None:
            return res
    if last_res is not None:
        return last_res
    raise RuntimeError(f"источник недоступен для MTProto ({last_err})")


async def _mt_download_stream(client, doc, doc_size, sink, progress=None, title="",
                              cancel_check=None):
    """Качает документ ПОТОКОМ и скармливает sink() (шифратору или
    расшифровщику). Обрывы и FloodWait — продолжаем с выровненного
    смещения, ничего не теряя и не дублируя. Возвращает байт скачано.
    ВОЛНА 22.5: cancel_check (callable) — кооперативная отмена: если он
    вернул True, бросаем _VaultCancelled (проверка на каждом куске)."""
    got = 0
    attempts = 0
    while True:
        resume_off = got - (got % 4096)
        skip = got - resume_off
        try:
            async for chunk in client.iter_download(
                doc, offset=resume_off, request_size=524288,
                file_size=int(doc_size or 0),
            ):
                # ВОЛНА 22.5: точка отмены на каждом куске.
                if cancel_check is not None and cancel_check():
                    raise _VaultCancelled()
                if skip:
                    if len(chunk) <= skip:
                        skip -= len(chunk)
                        continue
                    chunk = chunk[skip:]
                    skip = 0
                sink(chunk)
                got += len(chunk)
                if progress is not None and doc_size:
                    pct = min(99, got * 100 // int(doc_size))
                    # ВОЛНА 22.12: полоса прогресса [▓▓▓░░] + скорость + ETA.
                    await progress.edit(
                        f"{title}… {pct}%",
                        done=got, total=int(doc_size))
            break
        except _FloodWaitError as e:
            attempts += 1
            wait = min(int(getattr(e, "seconds", 30) or 30) + 1, 900)
            logger.warning(f"mtproto: FloodWait {wait} с при скачивании "
                           f"(попытка {attempts})")
            if attempts > 10:
                raise RuntimeError("Telegram просит слишком долгую паузу")
            await asyncio.sleep(wait)
        except (ConnectionError, asyncio.TimeoutError, TimeoutError) as e:
            attempts += 1
            logger.warning(f"mtproto: обрыв скачивания ({e}), попытка {attempts}")
            if attempts > 8:
                raise RuntimeError("не удалось докачать файл (сеть)")
            await asyncio.sleep(min(3 * attempts, 20))
    return got


async def _mt_upload_container(client, path, size, caption, filename=None,
                               progress_cb=None, user=None):
    """Заливает ГОТОВЫЙ шифр-контейнер в cloud-канал через MTProto
    (Bot API не умеет больше 50 МБ). Каналы пробует по порядку.
    ВОЛНА 22.20: если у user подключён ЛИЧНЫЙ канал («🔗 Моё облако») —
    контейнер уходит ТОЛЬКО в него, минуя общие каналы.
    ВОЛНА 22.12: progress_cb(current, total) — живая полоса прогресса.
    Возвращает {"message_id", "file_id", "size", "channel_id"} или None."""
    # ВОЛНА 16: каналы «только для базы» тоже годятся для шифров Сейфа —
    # раньше при пустом cloud-списке заливка отказывала, хотя канал был.
    _uch = _user_vault_channel(user)
    if _uch:
        targets = [_uch[0]]
    else:
        targets = get_cloud_channel_ids() or get_db_channel_ids()
    if not targets:
        return None
    upload_path = path
    if filename:
        try:
            fixed = os.path.join(os.path.dirname(path), filename)
            if fixed != path and os.path.exists(path):
                os.replace(path, fixed)
                upload_path = fixed
        except Exception:
            upload_path = path
    for ch in targets:
        try:
            peer = await _mt_resolve_channel(client, ch)

            async def _send_file(peer=peer, upload_path=upload_path):
                return await _mt_run_with_flood(lambda: client.send_file(
                    peer, upload_path, force_document=True,
                    caption=(caption or "")[:1024] or None,
                    file_size=int(size or 0) or None,
                    progress_callback=progress_cb,
                ))

            # ВОЛНА 22.35: публикация через «шлагбаум» — очередь на канал,
            # чтобы массовые загрузки из веба не упёрлись в лимиты Telegram.
            sent, queue_pos = await _pub_send(ch, _send_file)
            doc = getattr(sent, "document", None)
            # ВОЛНА 22.36: сохраняем расположение документа (id/access_hash/
            # file_reference) — скачивание работает МИМО сообщения, даже если
            # пользователь скрыл его из канала кнопкой «Скрыть».
            _mt_doc = None
            try:
                if doc is not None and int(getattr(doc, "id", 0) or 0):
                    import base64 as _b64
                    _mt_doc = {
                        "id": int(doc.id),
                        "ah": int(getattr(doc, "access_hash", 0) or 0),
                        "ref": _b64.b64encode(bytes(getattr(doc, "file_reference", b"") or b"")).decode("ascii"),
                    }
            except Exception:
                _mt_doc = None
            return {
                "message_id": int(getattr(sent, "id", 0) or 0),
                "file_id": None,
                "size": int(getattr(doc, "size", 0) or size or 0),
                "channel_id": ch,
                "queue_pos": queue_pos,
                "mt_doc": _mt_doc,
            }
        except Exception as e:
            logger.error(f"mtproto: заливка контейнера в канал {ch} не удалась: {e}")
            continue
    return None


async def _mt_send_file_to_user(client, chat_id, path, size, caption,
                                context, progress_msg, cancel_check=None,
                                progress_markup=None):
    """Отправляет РАСШИФРОВАННЫЙ файл пользователю через MTProto (до 2 ГБ)
    с прогрессом. Имя файла = имя временного файла (переименован заранее).
    Ботам разрешён InputPeerUser(id, 0) для тех, кто писал боту; если
    Telethon не нашёл peer в кэше — подтягиваем hash из этого же чата.
    ВОЛНА 22.5: cancel_check — отмена ЗАГРУЗКИ пользователю (бросок из
    progress_callback обрывает выгрузку — недосланное сообщение Telegram
    не создаёт); progress_markup — 22.8: НЕ используется (кнопок на
    сообщениях больше нет), параметр оставлен для совместимости."""
    state = {"cur": 0, "total": int(size or 0)}

    def _pcb(cur, total):
        # ВОЛНА 22.5: точка отмены прямо в выгрузке пользователю.
        if cancel_check is not None and cancel_check():
            raise _VaultCancelled()
        state["cur"] = int(cur or 0)
        if total:
            state["total"] = int(total)

    stop = asyncio.Event()

    async def _tick():
        last = -1
        while not stop.is_set():
            await asyncio.sleep(6)
            cur, total = state["cur"], state["total"]
            if total and cur != last:
                last = cur
                try:
                    await context.bot.edit_message_text(
                        f"📤 Отправляю файл… {min(99, cur * 100 // total)}% "
                        f"({_fmt_bytes(cur)} из {_fmt_bytes(total)})",
                        chat_id=progress_msg.chat_id,
                        message_id=progress_msg.message_id,
                        reply_markup=progress_markup,
                    )
                except Exception:
                    pass

    peer = _mt_peer_user(chat_id)
    tick_task = asyncio.create_task(_tick())
    try:
        try:
            return await _mt_run_with_flood(lambda: client.send_file(
                peer, path, force_document=True,
                caption=(caption or "")[:1024] or None,
                file_size=int(size or 0) or None,
                progress_callback=_pcb,
            ))
        except Exception as e:
            # Peer не в кэше Telethon — подтягиваем access_hash из чата
            # с пользователем (бот ВИДИТ свои сообщения там) и повторяем.
            logger.warning(f"mtproto: peer не разрешился ({e}), повторяю")
            try:
                await client.get_messages(peer, limit=1)
                ent = await client.get_input_entity(int(chat_id))
                return await _mt_run_with_flood(lambda: client.send_file(
                    ent, path, force_document=True,
                    caption=(caption or "")[:1024] or None,
                    file_size=int(size or 0) or None,
                    progress_callback=_pcb,
                ))
            except Exception as e2:
                raise RuntimeError(f"не удалось отправить файл: {e2}")
    finally:
        stop.set()
        tick_task.cancel()


def _vault_fail_reason(e):
    """ВОЛНА 18: честная ПРИЧИНА сбоя для сообщения пользователю — раньше
    он видел только «попробуйте ещё раз позже», а причина жила в логах
    Render, которые пользователь всё равно не читает."""
    try:
        s = str(e or "").strip()
    except Exception:
        s = ""
    if not s:
        s = "неизвестная ошибка"
    low = s.lower()
    if ("личный чат не найден" in low or ("peer" in low and "invalid" in low)
            or "источник недоступен" in low):
        s = ("Telegram не дал боту доступ к источнику файла — пришлите файл "
             "ещё раз (обычно помогает сразу)")
    elif "mtproto недоступен" in low:
        # ВОЛНА 20: ветка оставлена только для старых формулировок; новый
        # текст «потоковый режим… : <причина>» уже читаемый — пройдёт как есть.
        s = ("потоковый режим больших файлов сейчас недоступен на сервере — "
             "точная причина указана ботом рядом; повторите через минуту")
    elif "потоковый режим больших файлов" in low:
        # ВОЛНА 20: уже читаемый текст — НЕ маскируем, показываем как есть.
        return s[:220]
    elif "файл исчез" in low or "message_id_invalid" in low:
        s = "файл исчез из чата (сообщение удалено?) — пришлите его ещё раз"
    elif "источник файла потерян" in low:
        s = "источник файла потерян — пришлите файл ещё раз"
    elif "мало свободного места" in low:
        s = "мало свободного места на диске сервера — место освобождается после перезапуска бота"
    elif ("floodwait" in low or "паузу" in low
          or "too many requests" in low or "flood" in low):
        s = "Telegram просит паузу (слишком много запросов) — попробуйте через пару минут"
    elif ("не принят" in low or "не удалось загрузить" in low
          or "контейнер" in low or "channel" in low and "invalid" in low):
        s = ("канал-хранилище не принял шифр — проверьте, что бот "
             "администратор канала, и попробуйте ещё раз")
    return s[:220]


async def _vault_botapi_download(context, file_id):
    """ВОЛНА 18: скачивание ОРИГИНАЛА через Bot API (≤20 МБ) — запасной путь,
    когда MTProto не смог открыть источник (холодный кэш после рестарта и т.
    п.). Возвращает bytes; при сбое бросает исключение."""
    tg_file = await context.bot.get_file(file_id)
    buf = io.BytesIO()
    await asyncio.wait_for(tg_file.download_to_memory(out=buf), timeout=300)
    return buf.getvalue()


async def _vault_mt_precheck(context, item, ack_msg=None):
    """ВОЛНА 18: ранний прогрев источника БОЛЬШОГО файла — фоном, ПОКА
    пользователь называет файлы и вводит пароль. Проверяет, что MTProto уже
    видит сообщение с файлом, и запоминает access_hash в элементе пачки.
    Раньше всё это впервые происходило ПОСЛЕ «✅ Готово» — холодный кэш
    сущностей после рестарта Render ронял шифрование, и пользователь узнавал
    об этом только в конце. Если файл не виден — честно правим ack-сообщение
    с предупреждением. Ошибки не критичны: при шифровании будут повторные
    попытки и запасной путь через file_id."""
    try:
        client = await _mt_client()
        if client is None:
            # ВОЛНА 19: предупреждаем ЗАРАНЕЕ — пока пользователь вводит пароль,
            # а не только после «✅ Готово». Клиент может подняться к моменту
            # шифрования (самовосстановление с чистой сессией), поэтому это
            # именно предупреждение, а не отказ.
            if ack_msg is not None:
                _txt = str(getattr(ack_msg, "text", "") or "")
                if _txt and "Потоковый режим" not in _txt:
                    try:
                        await context.bot.edit_message_text(
                            _txt + "\n\n⚠️ Потоковый режим сейчас недоступен ("
                            f"{_mt_unavailable_reason()}). Если после "
                            "«✅ Готово» шифрование не удастся — попробуйте "
                            "ещё раз через пару минут: клиент поднимается сам.",
                            chat_id=ack_msg.chat_id,
                            message_id=ack_msg.message_id,
                            # 22.19: кнопки должны остаться ровно на месте
                            reply_markup=_vault_put_kb(),
                        )
                    except Exception:
                        pass
            return
        mt = dict(item.get("mt_raw") or {})
        pid = int(mt.get("peer_id") or mt.get("channel_id") or 0)
        mid = int(mt.get("msg_id") or 0)
        if not pid or not mid:
            return
        peer, ah = (None, 0)
        if pid > 0:
            peer, ah = await _mt_resolve_peer_ah(client, pid)
            if peer is None:
                peer = _mt_peer_user(pid)
        else:
            peer = await _mt_resolve_channel(client, pid)
        m = await _mt_run_with_flood(lambda: client.get_messages(peer, ids=mid))
        doc = None
        if m is not None:
            doc = getattr(m, "document", None) or getattr(m, "photo", None)
        if doc is not None:
            item["mt_ok"] = True
            if ah:
                mt["ah"] = int(ah)
                item["mt_raw"] = mt
        elif ack_msg is not None:
            _txt = str(getattr(ack_msg, "text", "") or "")
            if _txt:
                try:
                    await context.bot.edit_message_text(
                        _txt + "\n\n⚠️ Большой файл: источник пока не виден "
                        "режиму потока (кэш Telegram прогревается). Если после "
                        "«✅ Готово» шифрование не удастся — просто пришлите "
                        "файл ещё раз.",
                        chat_id=ack_msg.chat_id,
                        message_id=ack_msg.message_id,
                    )
                except Exception:
                    pass
    except Exception as e:
        logger.info(f"vault precheck: источник пока не прогрет ({e})")


async def _vault_seal_item_mtproto(msg, context, user, item, password,
                                   progress_msg, idx, total):
    """ВОЛНА 14/17: шифрует ОДИН большой файл. Источник — САМО сообщение
    пользователя в личном чате (волна 17: сырых копий в каналах больше нет —
    поддерживается и старый ключ channel_id для незавершённых сессий).
    Поток: MTProto качает оригинал → шифр DVF2 пишется во временный файл →
    контейнер в канал (≤49 МБ — Bot API, больше — MTProto) → при УСПЕХЕ
    оригинал стирается из личного чата и временные файлы удаляются.
    Возвращает запись user.vault_files; при сбое бросает исключение —
    оригинал остаётся в чате, чтобы пользователь его не потерял.
    ВОЛНА 18: ДВЕ попытки (сбои сети/кэша самоизлечиваются) + запасные пути:
    file_id через Bot API (≤20 МБ) и заливка шифра MTProto, если Bot API
    отказал. Причина сбоя — честная, для сообщения пользователю."""
    last_err = None
    for _attempt in (1, 2):
        try:
            return await _vault_seal_item_mtproto_once(
                msg, context, user, item, password, progress_msg, idx, total)
        except _VaultCancelled:
            raise  # ВОЛНА 22.3: отмену пользователя НЕ ретраим — это не сбой
        except Exception as e:
            last_err = e
            # ПОЛИТИКА ПДн 1.2: имя файла пользователя в лог не попадает.
            logger.error(f"vault put: попытка {_attempt}/2 не удалась, "
                         f"user_id={getattr(user, 'user_id', '?')}: {e}")
            if _attempt == 1:
                await asyncio.sleep(5)  # холодный кэш/сеть часто отходят сами
    raise last_err  # обе попытки упали — оригинал остаётся в чате


async def _vault_seal_item_mtproto_once(msg, context, user, item, password,
                                        progress_msg, idx, total):
    """ВОЛНА 18: ОДНА попытка шифрования большого файла (обёртка повторяет).
    ВОЛНА 19: Telethon обязателен ТОЛЬКО для файлов >20 МБ. Файлы ≤20 МБ
    полностью обслуживаются Bot API (скачали по file_id → шифр DVF2 → канал),
    даже если MTProto-клиент не поднялся, — раньше проверка клиента стояла
    ПЕРЕД запасным путём и роняла малые файлы с «MTProto недоступен»."""
    name = str(item.get("name") or "файл")
    kind = str(item.get("kind") or "document")
    mime = str(item.get("mime") or "")
    size = int(item.get("size", 0) or 0)
    if AESGCM is None:
        raise RuntimeError("нет библиотеки cryptography")
    mt = dict(item.get("mt_raw") or {})
    raw_ch = int(mt.get("peer_id") or mt.get("channel_id") or 0)
    raw_mid = int(mt.get("msg_id") or 0)
    if not raw_ch or not raw_mid:
        raise RuntimeError("источник файла потерян — пришлите файл ещё раз")
    small = 0 < size <= VAULT_MAX_FILE_BYTES
    client = await _mt_client()  # None — не приговор: ≤20 МБ пойдёт через Bot API
    if client is None:
        logger.warning(f"vault put: MTProto недоступен ({_mt_unavailable_reason()})"
                       + (" — файл ≤20 МБ, шифрую через Bot API" if small
                          else " — запасной Bot API-путь попробую, но файл больше 20 МБ"))
    # ВОЛНА 18/19: сначала MTProto (цепочка peer'ов: кэш → access_hash →
    # hash=0), при полном провале и размере ≤20 МБ — запасное скачивание
    # через Bot API по file_id (файл уже лежит в Telegram, Bot API умеет
    # ≤20 МБ). MTProto-шаг выполняется ТОЛЬКО если клиент есть.
    doc = None
    mt_err = None
    if client is not None:
        try:
            _m, doc = await _mt_fetch_document(
                client, raw_ch, raw_mid, int(mt.get("ah") or 0))
        except Exception as e:
            mt_err = e
            logger.warning(f"vault put: MTProto-источник не открылся ({e}); "
                           "пробую запасной путь Bot API/file_id")
    botapi_payload = None
    if doc is None:
        fid = str(item.get("file_id") or "")
        if fid and 0 < size <= VAULT_MAX_FILE_BYTES:
            try:
                botapi_payload = await _vault_botapi_download(context, fid)
            except Exception as e:
                logger.warning(f"vault put: Bot API-скачивание не удалось: {e}")
        if botapi_payload is None:
            if client is None:
                # ВОЛНА 19/20: читаемый текст с ЧЕСТНОЙ причиной — он идёт
                # пользователю как есть (без маскировки в _vault_fail_reason).
                raise RuntimeError(
                    "потоковый режим больших файлов сейчас недоступен на "
                    f"сервере: {_mt_unavailable_reason()}"
                    + ("" if small else
                       " — файл больше 20 МБ, без потока его не взять; "
                       "повторите позже или пришлите файл заново"))
            if mt_err is not None:
                raise mt_err
            raise RuntimeError(
                "файл исчез из чата (сообщение удалено?) — пришлите файл ещё раз")
    doc_size = int(getattr(doc, "size", 0) or size or 0)
    if not _dvf2_disk_ok(doc_size):
        raise RuntimeError("мало свободного места на диске сервера")
    job = _dvf2_make_job_dir()
    # ВОЛНА 22.3: регистрируем временник в операции — при отмене сотрём.
    _op_here = _VAULT_OPS.get(str(getattr(user, "user_id", "") or ""))
    if _op_here is not None:
        _op_here["temp"].append(job)
    tmp_enc = os.path.join(job, "container.bin")
    enc = _Dvf2Encryptor(password, {
        "n": name, "k": kind, "m": mime,
        "t": datetime.now().strftime("%Y-%m-%d %H:%M"),
        "sz": size or doc_size,
    }, tmp_enc)
    up = None
    enc_total = 0
    try:
        # ВОЛНА 22.3: прогресс качания/шифрования пишется в op['sub'] — его
        # показывает аниматор (никаких параллельных правок того же сообщения).
        _op_here = _VAULT_OPS.get(str(getattr(user, "user_id", "") or ""))
        prog = _VaultSubProg(_op_here, f"📦 [{idx}/{total}] «{name}»")
        if _op_here is not None:
            _op_here["phase"] = f"Файл {idx}/{total}: «{name}»"

        def _push_checked(chunk):
            # ВОЛНА 22.3: кусок-за-куском — кооперативная отмена «❌ Отмена».
            if _op_here is not None and _op_here["event"].is_set():
                raise _VaultCancelled()
            enc.push(chunk)

        try:
            if botapi_payload is not None:
                # ВОЛНА 18: оригинал уже в памяти (Bot API) — шифруем сразу.
                if _op_here is not None and _op_here["event"].is_set():
                    raise _VaultCancelled()
                enc.push(botapi_payload)
                enc_total = enc.finish()
                botapi_payload = b""
            else:
                await _mt_download_stream(
                    client, doc, doc_size, _push_checked, prog,
                    f"📦 [{idx}/{total}] «{name}»: качаю и шифрую")
                enc_total = enc.finish()
        except Exception:
            enc.abort()
            raise
        if _op_here is not None and _op_here["event"].is_set():
            raise _VaultCancelled()
        if _op_here is not None:
            _op_here["sub"] = f"📦 [{idx}/{total}] «{name}»: заливаю шифр в канал…"
        _vault_cap = "🔐 Сейф: зашифрованный файл (открыть без пароля невозможно)."
        _vault_fn = f"vault_{datetime.now().strftime('%Y%m%d_%H%M%S')}_{idx}.bin"
        # ВОЛНА 22.12: живая полоса заливки шифра (Telethon progress_callback,
        # синхронная — обновляет op['sub'], аниматор показывает её в сообщении).
        _up_prog = _VaultSubProg(_op_here, f"📦 [{idx}/{total}] «{name}»")
        _up_cb = (lambda cur, tot: _up_prog.sync_bar(cur, tot, "📤 Заливаю шифр")) \
            if _op_here is not None else None
        if enc_total <= (49 * 1024 * 1024 - 1024 * 1024):
            with open(tmp_enc, "rb") as fh:
                enc_bytes = fh.read()
            try:
                up = await _storage_upload_document(
                    context, enc_bytes, filename=_vault_fn, caption=_vault_cap,
                    user=user)
            finally:
                enc_bytes = b""
            # ВОЛНА 18: Bot API отказал — шифр ≤48 МБ можно залить и MTProto.
            if up is None and _TELETHON_OK and BOT_TOKEN:
                if _op_here is not None and _op_here["event"].is_set():
                    raise _VaultCancelled()
                up = await _mt_upload_container(
                    client, tmp_enc, enc_total,
                    caption=_vault_cap, filename=_vault_fn,
                    progress_cb=_up_cb, user=user)
        else:
            up = await _mt_upload_container(
                client, tmp_enc, enc_total,
                caption=_vault_cap, filename=_vault_fn,
                progress_cb=_up_cb, user=user)
        if up is None:
            raise RuntimeError(
                "шифр не принят каналом — проверьте, что бот администратор "
                "канала-хранилища")
        # ВОЛНА 22.3: залитый шифр ЭТОЙ пачки — в реестр отмены.
        if _op_here is not None:
            try:
                _op_here["sent"].append(
                    (int(up.get("channel_id") or get_storage_channel_id() or 0),
                     int(up.get("message_id") or 0)))
            except (TypeError, ValueError):
                pass
        rec = {
            "id": _vault_gen_id(user),
            "kind": kind, "mime": mime,
            "ts": _file_ts_now(), "tss": datetime.now().strftime("%Y-%m-%d %H:%M"),
            "size_orig": size or doc_size,
            "size_enc": int(up.get("size", 0) or enc_total),
            "salt": enc.salt_hex(),
            "verifier": enc.verifier_hex(),
            "iters": enc.iters,
            "nonce": enc.np_hex(),
            "msg_id": int(up.get("message_id", 0)),
            "file_id": up.get("file_id"),
            "channel_id": up.get("channel_id"),
            "dvf2": True,
        }
        _stat_bump("vault_upload")
        # ВОЛНА 17: источник (сообщение в личном чате) стираем ТОЛЬКО при
        # успехе — шифр уже в канале, обещание «оригинал из чата сотру»
        # выполнено. При сбое оригинал ОСТАЁТСЯ в чате (политика волны 11).
        item.pop("mt_raw", None)
        if raw_ch and raw_mid:
            try:
                await context.bot.delete_message(
                    chat_id=raw_ch, message_id=raw_mid)
            except Exception:
                pass
        return rec
    finally:
        try:
            _shutil.rmtree(job, ignore_errors=True)
        except Exception:
            pass


async def _vault_get_dvf2(msg, context, user, rec, password):
    """ВОЛНА 14: выдача БОЛЬШОГО файла Сейфа (DVF2, >20 МБ до 2 ГБ).
    Поток: MTProto качает шифр из канала → расшифровка на лету (в ОЗУ только
    куски) → временный файл → отправка пользователю с прогрессом → временный
    файл стёрт. САМ ШИФР на диск не пишется вовсе.
    ВОЛНА 22.5→22.9: во время выдачи отмены НЕТ — по прямому требованию
    пользователя («если еще загружается то загрузка должна закончиться»)
    выдача НЕ прерывается ни на какой фазе (скачивание, расшифровка,
    отправка) — она спокойно дойдёт до конца. После выдачи бот подсказывает:
    «❌ Отменить» — В КЛАВИАТУРЕ (22.8: кнопок на сообщениях больше нет) —
    файл исчезает из чата (отмена после распаковки)."""
    if AESGCM is None:
        await msg.reply_text("❌ На сервере нет библиотеки шифрования (cryptography).")
        return MAIN_MENU
    client = await _mt_client()
    if client is None:
        await msg.reply_text(
            "❌ Режим больших файлов не активен: на сервере не установлен "
            "Telethon (pip install telethon). Попросите разработчика включить.",
            reply_markup=get_main_menu_keyboard(user),
        )
        return MAIN_MENU
    channel_id = rec.get("channel_id") or get_storage_channel_id()
    mid = int(rec.get("msg_id") or 0)
    if not channel_id or not mid:
        await msg.reply_text(
            "❌ Шифр недоступен: файл лежал в канале, который больше не "
            "подключён, либо указатель потерян.",
            reply_markup=get_main_menu_keyboard(user),
        )
        return MAIN_MENU
    try:
        _m, doc = await _mt_fetch_document(client, channel_id, mid)
    except Exception as e:
        logger.error(f"vault get dvf2: не удалось открыть шифр: {e}")
        doc = None
    if doc is None:
        await msg.reply_text(
            "❌ Не смог скачать шифр из канала. Возможно, сообщение в канале "
            "удалено вручную.",
            reply_markup=get_main_menu_keyboard(user),
        )
        return MAIN_MENU
    doc_size = int(getattr(doc, "size", 0) or rec.get("size_enc", 0) or 0)
    orig_size = int(rec.get("size_orig", 0) or 0)
    if not _dvf2_disk_ok(max(orig_size, doc_size)):
        await msg.reply_text(
            f"❌ На диске сервера сейчас меньше свободного места, чем нужно "
            f"для файла ({_fmt_bytes(orig_size)}). Место освобождается после "
            "перезапуска бота — попробуйте позже.",
            reply_markup=get_main_menu_keyboard(user),
        )
        return MAIN_MENU
    # ВОЛНА 22.5/22.8/22.9: операция с родом "get" — выдача НЕ прерывается
    # (требование пользователя: «загрузка должна закончиться»). Кнопки НА
    # СООБЩЕНИИ больше нет — «❌ Отмена»/«❌ Отменить» ждут В КЛАВИАТУРЕ;
    # старые inline-кнопки (vault_getstop) работают как легаси.
    op = _vault_op_begin(getattr(user, "user_id", "") or "", 1, kind="get")
    op["phase"] = "Качаю и расшифровываю"

    def _cancelled():
        return op["event"].is_set()

    progress_msg = None
    try:
        progress_msg = await msg.reply_text(
            "🔓 Качаю шифр и расшифровываю потоком… 0%\n"
            "⏳ Не прерываю — загрузка спокойно дойдёт до конца; после выдачи "
            "«❌ Отменить» в клавиатуре сотрёт файл из чата.")
    except Exception:
        progress_msg = None
    prog = _ProgressEdit(context, progress_msg,
                         "🔓 Качаю шифр и расшифровываю потоком")
    job = _dvf2_make_job_dir()
    op["temp"].append(job)  # ВОЛНА 22.5: для отмены (страховка к finally)
    dec = None
    err_text = None
    final_path = None
    real_name = ""
    cancelled = False
    _cancel_after = False  # 22.10: «Отмена» нажали ВО ВРЕМЯ выдачи
    sent_mid = 0
    try:
        out_path = os.path.join(job, "data.bin")
        with open(out_path, "wb") as fh:
            dec = _Dvf2Decryptor(password)

            def _sink(b):
                # ВОЛНА 22.5: отмена также проверяется в расшифровщике.
                if _cancelled():
                    raise _VaultCancelled()
                out = dec.push(b)
                if out:
                    fh.write(out)

            await _mt_download_stream(
                client, doc, doc_size, _sink, prog,
                "🔓 Качаю шифр и расшифровываю потоком",
                cancel_check=_cancelled)
            if _cancelled():
                raise _VaultCancelled()
            tail = dec.finish()
            if tail:
                fh.write(tail)
        meta = dec.meta or {}
        real_name = _dvf2_safe_name(
            meta.get("n") or f"vault_{rec.get('id', 'file')}.bin")
        final_path = os.path.join(job, real_name)
        try:
            os.replace(out_path, final_path)
        except Exception:
            final_path = out_path
        real_size = int(meta.get("sz") or 0) or orig_size or os.path.getsize(final_path)
        _lbl = str(rec.get("label") or "").strip()
        cap = (f"🔓 {_lbl} — {real_name}" if _lbl
               else f"🔓 Расшифровано: {real_name}")
        if _cancelled():
            raise _VaultCancelled()
        try:
            await context.bot.send_chat_action(
                chat_id=msg.chat_id, action="upload_document")
        except Exception:
            pass
        op["phase"] = "Отправляю файл"
        await _ProgressEdit(context, progress_msg, "").edit(
            "📤 Заливаю расшифрованный файл… 0%", force=True)
        _sent = await _mt_send_file_to_user(
            client, msg.chat_id, final_path, real_size, cap,
            context, progress_msg or msg,
            cancel_check=_cancelled)
        # ВОЛНА 22.6: id выданного файла — для кнопки «❌ Отменить» (стереть из чата).
        try:
            sent_mid = int(getattr(_sent, "id", 0) or 0)
        except (TypeError, ValueError):
            sent_mid = 0
    except _VaultCancelled:
        cancelled = True
    except ValueError as e:
        err_text = str(e)
    except Exception as e:
        logger.error(f"vault get dvf2: выдача не удалась: {e}")
        err_text = "сбой при перекачке файла"
    finally:
        # ВОЛНА 22.10: читаем пометку «Отмена была во время выдачи» ДО
        # закрытия операции — после выдачи её исполним в _vault_offer_wipe.
        try:
            _cancel_after = bool(op.get("cancel_after"))
        except Exception:
            _cancel_after = False
        try:
            _shutil.rmtree(job, ignore_errors=True)
        except Exception:
            pass
        # ВОЛНА 22.5: операцию закрываем в ЛЮБОМ исходе.
        _vault_op_end(getattr(user, "user_id", "") or "")
    context.user_data.pop('vault_get_id', None)
    context.user_data.pop('vault_attempts', None)
    if cancelled:
        # ВОЛНА 22.5: честный отчёт об отмене — временные файлы уже стёрты
        # (finally выше), шифр в канале НЕ тронут, в чат ничего не попало.
        if progress_msg is not None:
            try:
                await context.bot.edit_message_text(
                    "⛔ Отменено — расшифровка остановлена, временные файлы "
                    "стёрты. Шифр в Сейфе цел: файл можно расшифровать снова.",
                    chat_id=progress_msg.chat_id,
                    message_id=progress_msg.message_id)
            except Exception:
                pass
        await msg.reply_text(
            "Отменено.", reply_markup=get_main_menu_keyboard(user))
        return MAIN_MENU
    if err_text is not None:
        await msg.reply_text(
            f"❌ Расшифровать/передать не удалось: {err_text}. Если забыли "
            "пароль — файл открыть нельзя (запасного ключа не существует).",
            reply_markup=get_main_menu_keyboard(user),
        )
        return MAIN_MENU
    if progress_msg is not None:
        try:
            await context.bot.edit_message_text(
                "✅ Файл расшифрован и отправлен ниже.",
                chat_id=progress_msg.chat_id,
                message_id=progress_msg.message_id)
        except Exception:
            pass
    # ВОЛНА 22.6→22.10: подсказка после выдачи; cancel_after=True — «Отмена»
    # нажали ещё во время загрузки: САМИ стираем файл и возвращаем меню.
    if sent_mid:
        await _vault_offer_wipe(
            context, msg.chat_id, sent_mid,
            wipe_enabled=bool(getattr(user, "vault_wipe_on_cancel", True)),
            user=user, cancel_after=_cancel_after)
    else:
        await msg.reply_text("✅ Готово. Файл расшифрован только что и только для вас.")
    return MAIN_MENU


async def _vault_reencrypt_dvf2(msg, context, user, rec, old_pw, new_pw):
    """ВОЛНА 14: перешифровка БОЛЬШОГО файла (DVF2) новым паролем потоком:
    старый шифр качается из канала и расшифровывается на лету во временный
    файл, затем шифруется новым паролем и заливается обратно. Старый шифр
    стирается ТОЛЬКО после успешной заливки нового. Возвращает True/False."""
    up = None
    enc = None
    enc_total = 0
    try:
        client = await _mt_client()
        if client is None or AESGCM is None:
            raise RuntimeError("MTProto/криптография недоступны")
        channel_id = rec.get("channel_id") or get_storage_channel_id()
        mid = int(rec.get("msg_id") or 0)
        if not channel_id or not mid:
            raise RuntimeError("указатель на шифр потерян")
        _m, doc = await _mt_fetch_document(client, channel_id, mid)
        if doc is None:
            raise RuntimeError("сообщение с шифром не найдено в канале")
        doc_size = int(getattr(doc, "size", 0) or rec.get("size_enc", 0) or 0)
        if not _dvf2_disk_ok(max(doc_size, int(rec.get("size_orig", 0) or 0))):
            raise RuntimeError("мало места на диске сервера")
        job = _dvf2_make_job_dir()
        try:
            tmp_dec = os.path.join(job, "data.bin")
            dec = _Dvf2Decryptor(old_pw)
            with open(tmp_dec, "wb") as fh:
                def _sink(b):
                    out = dec.push(b)
                    if out:
                        fh.write(out)

                await _mt_download_stream(client, doc, doc_size, _sink)
                tail = dec.finish()
                if tail:
                    fh.write(tail)
            meta = dict(dec.meta or {})
            tmp_enc = os.path.join(job, "container.bin")
            enc = _Dvf2Encryptor(new_pw, meta, tmp_enc)
            try:
                with open(tmp_dec, "rb") as fh:
                    while True:
                        chunk = fh.read(VAULT_DVF2_BLOCK)
                        if not chunk:
                            break
                        enc.push(chunk)
                enc_total = enc.finish()
            except Exception:
                enc.abort()
                raise
            if enc_total <= (49 * 1024 * 1024 - 1024 * 1024):
                with open(tmp_enc, "rb") as fh:
                    enc_bytes = fh.read()
                try:
                    up = await _storage_upload_document(
                        context, enc_bytes,
                        filename=f"vault_{datetime.now().strftime('%Y%m%d_%H%M%S')}_{rec.get('id', 'f')}.bin",
                        caption="🔐 Сейф: зашифрованный файл (открыть без пароля невозможно).",
                        user=user)
                finally:
                    enc_bytes = b""
            else:
                up = await _mt_upload_container(
                    client, tmp_enc, enc_total,
                    caption="🔐 Сейф: зашифрованный файл (открыть без пароля невозможно).",
                    filename=f"vault_{datetime.now().strftime('%Y%m%d_%H%M%S')}_{rec.get('id', 'f')}.bin",
                    user=user)
            if up is None:
                raise RuntimeError("новый шифр не удалось загрузить в канал")
        finally:
            try:
                _shutil.rmtree(job, ignore_errors=True)
            except Exception:
                pass
    except Exception as e:
        logger.error(f"vault dvf2 reencrypt ({rec.get('id')}): {e}")
        return False
    old_msg_id = int(rec.get("msg_id") or 0)
    old_channel = rec.get("channel_id") or get_storage_channel_id()
    rec.update({
        "salt": enc.salt_hex(),
        "nonce": enc.np_hex(),
        "verifier": enc.verifier_hex(),
        "iters": enc.iters,
        "msg_id": int(up.get("message_id", 0)),
        "file_id": up.get("file_id"),
        "channel_id": up.get("channel_id"),
        "size_enc": int(up.get("size", 0) or enc_total),
        "dvf2": True,
    })
    if old_msg_id:
        try:
            await context.bot.delete_message(
                chat_id=old_channel, message_id=old_msg_id)
        except Exception:
            pass
    return True


def get_vault_menu_keyboard():
    return InlineKeyboardMarkup([
        [InlineKeyboardButton("📥 Положить файл/текст", callback_data="vault_put")],
        [InlineKeyboardButton("📦 Мои файлы", callback_data="vault_files")],
        # ВОЛНА 22.20: «🔗 Моё облако» — НАСТРОЙКА САМОГО ПОЛЬЗОВАТЕЛЯ:
        # свой приватный канал как личное хранилище (без панели разработчика).
        [InlineKeyboardButton("🔗 Моё облако", callback_data="vault_cloud")],
        # ВОЛНА 22.29: веб-пароль для входа в Веб-облако без Telegram.
        [InlineKeyboardButton("🔑 Веб-пароль", callback_data="web_password_menu")],
        # ВОЛНА 9: восстановление и управление вопросами — прямо в меню Сейфа.
        [InlineKeyboardButton("🔑 Забыл пароль (восстановить)", callback_data="vault_rec")],
        [InlineKeyboardButton("❓ Сменить секретные вопросы", callback_data="vault_qs")],
        [InlineKeyboardButton("❓ Как это работает", callback_data="vault_help")],
        [InlineKeyboardButton("⬅️ Назад", callback_data="back_to_main")],
    ])


def get_vault_files_keyboard(user):
    """ВОЛНА 12: список файлов Сейфа с ПОДПИСЯМИ; ВОЛНА 13: кнопка 🔎 —
    раскрыть ПОЛНОЕ название (Telegram обрезает длинные надписи кнопок).

    Подпись («label») пользователь задаёт сам — названием загрузки при
    добавлении, reply при загрузке или ✏️ в списке: «чтобы не запутаться,
    где что». Видна открытым текстом только ВАМ в вашем чате; настоящее имя
    файла и содержимое по-прежнему зашифрованы. Без подписи — прежний вид
    «Файл #N» + размер + дата (zero-knowledge)."""
    files = [f for f in (getattr(user, "vault_files", []) or []) if isinstance(f, dict)]
    kb = []
    for idx, rec in enumerate(files[:20], start=1):
        label = str(rec.get("label") or "").strip()
        if label:
            title = f"{label[:30]} • {_fmt_bytes(rec.get('size_orig', 0))}"
        else:
            title = (f"Файл #{idx} • {_fmt_bytes(rec.get('size_orig', 0))} • "
                     f"{_rec_ts_display(rec)[:10]}")
        kb.append([
            InlineKeyboardButton(f"📥 {title}", callback_data=f"vault_get_{rec.get('id')}"),
            # ВОЛНА 13: 🔎 — карточка с ПОЛНЫМ названием (кнопка «⬅️ Свернуть»
            # возвращает к списку — можно раскрыть другой файл).
            InlineKeyboardButton("🔎", callback_data=f"vault_show_{rec.get('id')}"),
            InlineKeyboardButton("🔑", callback_data=f"vault_chp_{rec.get('id')}"),
            # Карандаш НЕ убираем (просьба пользователя): ✏️ — подписать/переименовать.
            InlineKeyboardButton("✏️", callback_data=f"vault_ren_{rec.get('id')}"),
            InlineKeyboardButton("🗑", callback_data=f"vault_del_{rec.get('id')}"),
        ])
    if not kb:
        kb.append([InlineKeyboardButton("📥 Положить файл/текст", callback_data="vault_put")])
    # ВОЛНА 22.12: поиск по названиям, тегам и категориям + share-ссылки.
    kb.append([InlineKeyboardButton("🔍 Поиск по файлам", callback_data="vault_search"),
               InlineKeyboardButton("🔗 Поделиться", callback_data="share_open")])
    kb.append([InlineKeyboardButton("⬅️ Назад", callback_data="vault_menu")])
    return InlineKeyboardMarkup(kb)


def _vault_files_text(user):
    files = [f for f in (getattr(user, "vault_files", []) or []) if isinstance(f, dict)]
    if not files:
        return ("📦 В Сейфе пока пусто. Нажмите «📥 Положить файл/текст»: "
                "пришлите документ, фото, видео, аудио — или просто текст "
                "сообщением. Бот зашифрует всё вашим паролем.")
    lines = [
        f"📦 Ваши файлы ({len(files)} шт.):",
        "",
        "🏷 Название задаётся при добавлении (шаг после «✅ Готово»), reply-сообщением "
        "при загрузке или кнопкой ✏️ здесь — чтобы не запутаться, где что. Подпись "
        "видна только вам; настоящее имя и содержимое файла зашифрованы и появятся "
        "после ввода пароля. Длинное название целиком — кнопкой 🔎 у файла.",
        "",
    ]
    for idx, rec in enumerate(files[:20], start=1):
        label = str(rec.get("label") or "").strip()
        head = f"• {label} — " if label else f"• Файл #{idx} (без подписи) — "
        _cat = _VAULT_CAT_TITLES.get(rec.get("cat") or "", "")
        _tags = " ".join("#" + str(t) for t in (rec.get("tags") or []))
        # ВОЛНА 22.25: файлы режима «без шифра» помечаем честно.
        _plain_mark = " 🔓 без шифра" if rec.get("plain") else ""
        lines.append(
            f"{head}{_fmt_bytes(rec.get('size_orig', 0))} "
            + (f", {_rec_ts_display(rec)}" if rec.get("plain") else
               f"(в шифре {_fmt_bytes(rec.get('size_enc', 0))}), {_rec_ts_display(rec)}")
            + _plain_mark
            + (f"  {_cat}" if _cat else "")
            + (f"\n   {_tags}" if _tags else "")
        )
    lines.append("")
    # ВОЛНА 22.25: честная легенда — файлы «без шифра» отдаём сразу.
    lines.append("📥 — достать (спросит пароль; файлы с пометкой «без шифра» "
                 "отдаёт сразу, без пароля) • 🔎 — полное название • "
                 "🔑 — сменить пароль • ✏️ — подписать • 🗑 — удалить. "
                 "🔍 — поиск по названиям, тегам и категориям.")
    return "\n".join(lines)


def _vault_help_text():
    return (
        "❓ Как работает Сейф\n\n"
        "1. Вы присылаете файл (документ/фото/видео/аудио, до 20 МБ) или текст "
        "— можно сразу НЕСКОЛЬКО файлов пачкой. Когда закончите — нажмите "
        "кнопку «✅ Готово» ПОД сообщением (или напишите «готово»).\n"
        "   🏷 ЗАТЕМ бот попросит НАЗВАТЬ загрузку — название будет видно в "
        "«📦 Мои файлы», чтобы не запутаться, где что (можно «⏭ Пропустить»). "
        "После этого бот попросит ПАРОЛЬ СЕЙФА.\n"
        "   ✏️ Подпись ОДНОГО файла (видна только вам в списке Сейфа): "
        "ответьте (reply) на своё сообщение с файлом коротким названием, "
        "или позже — кнопкой ✏️ у файла в списке. Длинное название целиком "
        "смотрится кнопкой 🔎 у файла (карточка открывается и закрывается).\n"
        f"2. Пароль один на весь Сейф (минимум {VAULT_MIN_PASSWORD} символов — "
        "бот показывает, за сколько его разгадала бы супер-машина). Ключ "
        "выводится из него (PBKDF2, "
        "600 000 раундов), содержимое шифруется AES-256-GCM. В Telegram-канал "
        "уходит ТОЛЬКО шифр — неразличимый от случайного шума.\n"
        "3. Чтобы достать файл, вводите пароль Сейфа: бот скачивает шифр, "
        "расшифровывает в памяти и присылает файл. На диск ничего не пишется.\n"
        "   ❌ ПОСЛЕ РАСПАКОВКИ: в КЛАВИАТУРЕ снизу появляется кнопка "
        "«❌ Отменить» — нажмите, и расшифрованная копия ИСЧЕЗНЕТ из чата "
        "(это и есть «отмена» после распаковки). Шифр в канале остаётся целым — "
        "файл можно расшифровать заново в любой момент. Нужен файл — сохраните "
        "или перешлите его ДО нажатия. Не хотите автоудаления — выключите его "
        "в ⚙️ Настройках (пункт «🧹 Оптимизация памяти»).\n\n"
        "🔑 ВОССТАНОВЛЕНИЕ (если пароль забылся):\n"
        "• при создании пароля бот просит придумать 3 секретных вопроса и "
        "ответы (вопрос — ваш, ответ знаете только вы);\n"
        "• ответы нигде не хранятся — ими ЗАПЕЧАТЫВАЕТСЯ сам пароль (AES-256): "
        "без верных ответов он не распечатывается даже разработчиком;\n"
        "• забыли пароль → «🔑 Забыл пароль» → отвечаете на 3 вопроса → "
        "задаёте НОВЫЙ пароль → бот перешифрует файлы, и данные снова можно "
        "посмотреть или забрать;\n"
        f"• попыток: {VAULT_REC_MAX_ATTEMPTS}, после — пауза {VAULT_REC_COOLDOWN_MIN} минут "
        "(чтобы никто не перебирал ответы за вас).\n\n"
        "Почему никто не откроет:\n"
        "• пароль нигде не хранится (проверка — по «отпечатку» ключа);\n"
        "• настоящее ИМЯ файла зашифровано; в списке видны только ваша подпись "
        "(если сами подписали), номер/размер/дата;\n"
        "• разработчик видит в канале лишь зашифрованный контейнер.\n\n"
        "🔓 РЕЖИМ «БЕЗ ШИФРА» (только для СВОЕГО канала, волна 22.25):\n"
        "• если хотите, шифрование можно ВЫКЛЮЧИТЬ: 🔐 Сейф → 🔗 Моё облако → "
        "«🔓 Хранить файлы БЕЗ шифра» (или в веб-облаке: ☁️ → Хранилище);\n"
        "• тогда НОВЫЕ загрузки будут ложиться в ваш личный канал КАК ЕСТЬ — "
        "с исходными именами, без пароля, и доставаться кнопкой файла сразу, "
        "без ввода пароля;\n"
        "• ЧЕСТНОЕ предупреждение: содержимое таких файлов видно всем, у кого "
        "есть доступ к каналу, а «восстановление по секретным вопросам» для "
        "них не работает;\n"
        "• уже зашифрованные файлы остаются под шифром; вернуть шифрование — "
        "та же кнопка («🔒 Включить шифрование файлов»);\n"
        "• в ОБЩЕЕ хранилище бота незашифрованные файлы не попадают никогда — "
        "режим существует только вместе с вашим личным каналом.\n\n"
        "Выйти из Сейфа можно кнопкой «❌ Отмена» в ЛЮБОЙ момент — следы "
        "загруженных файлов и недописанные вопросы/ответы стираются из чата "
        "(это работает даже после перезапуска бота).\n"
        "   ⛔ ОТМЕНА ВО ВРЕМЯ ВЫДАЧИ БОЛЬШОГО ФАЙЛА: на клавиатуре снизу "
        "жмёте «❌ Отмена»/«❌ Отменить» — остановится "
        "процесс и сотрутся все временные файлы; в чат ничего не попадёт.\n"
        "   ❌ ОТМЕНА ПОСЛЕ РАСПАКОВКИ: кнопка «❌ Отменить» в клавиатуре — "
        "расшифрованная копия исчезает из чата (настраивается "
        "в ⚙️ Настройках).\n\n"
        "Честные ограничения:\n"
        f"• файл до {_fmt_bytes(VAULT_MAX_FILE_BYTES)} — быстрый путь: "
        "качается и шифруется мгновенно;\n"
        f"• от {_fmt_bytes(VAULT_MAX_FILE_BYTES)} до 2 ГБ — режим больших "
        "файлов: бот качает и шифрует ПОТОКОМ через MTProto, это занимает "
        "несколько минут (прогресс видно в чате);\n"
        "• больше 2 ГБ не может НИ ОДИН бот в Telegram (4 ГБ — только "
        "Premium у людей, ботам он недоступен): делите файл на части;\n"
        "• вопросы — ваша страховка: КТО ЗНАЕТ ОТВЕТЫ, ТОТ ПОЛУЧИТ ДОСТУП. "
        "Придумывайте вопросы, ответ на которые знаете только вы.\n\n"
        "💡 СОВЕТ РАЗРАБОТЧИКА: если сомневаетесь в анонимности или "
        "стабильности облака бота — заведите СВОЙ приватный Telegram-канал, "
        "добавьте туда бота администратором и подключите его в 🔗 Моём "
        "облаке (кнопка в меню Сейфа и Облака): шифры ваших файлов будут "
        "лежать только в вашем личном канале: вы полностью контролируете "
        "хранилище, а бот — лишь инструмент шифрования. Панель разработчика "
        "для этого НЕ нужна — это настройка вас самого.\n"
        "   📸 КАЧЕСТВО БЕЗ ПОТЕРЬ: фото и видео присылайте «КАК ФАЙЛ» "
        "(скрепка → «Файл», или «Отправить как файл» в меню вложения) — "
        "Telegram не сожмёт их при отправке; выдача всегда документом, "
        "без пережатия. Оригиналы без сжатия принимает и 🌐 Веб-облако "
        "(Mini App)."
    )


# ============================================================
# === ВОЛНА 22.20: «🔗 Моё облако» — ЛИЧНЫЙ канал-хранилище ===
# ============================================================
# По прямому требованию пользователя: «панель разработчика только у
# разработчика», а у обычного пользователя СВОЯ настройка в его облаке.
# Пользователь подключает свой приватный канал (бот — админ с правом
# публикации), и шифры ЕГО загрузок уходят только в ЕГО канал. Это настройка
# самого пользователя в ☁️ Облако / 🔐 Сейф → «🔗 Моё облако» — доступ к
# 🛠️ Панели разработчика для неё НЕ нужен и не предполагается.


def _vault_cloud_text(user):
    """Экран «🔗 Моё облако»: статус личного канала + честные правила.
    ВОЛНА 22.25: добавлен честный блок про режим шифрования (вкл/выкл)."""
    _uch = _user_vault_channel(user)
    if _uch:
        _plain = _vault_channel_plain(user)
        _mode = (
            "🔒 ШИФРОВАНИЕ: ВКЛЮЧЕНО — в канал уходит только шифр, открыть "
            "его можно лишь вашим паролем Сейфа (даже мы/Telegram не видят "
            "содержимое). Это режим по умолчанию и рекомендация."
            if not _plain else
            "🔓 ШИФРОВАНИЕ: ВЫКЛЮЧЕНО Вами — новые файлы Сейфа ложатся в ваш "
            "канал КАК ЕСТЬ, без пароля: их видно любому, у кого есть доступ "
            "к каналу, а «восстановить по секретным вопросам» для них не "
            "работает. Уже зашифрованные файлы остаются под шифром."
        )
        return (
            "🔗 Моё облако\n\n"
            f"✅ Подключён ВАШ личный канал: «{_uch[1]}» ({_uch[0]}).\n\n"
            "Новые загрузки Сейфа уходят ТОЛЬКО в него: ни разработчик, ни "
            "Telegram не читают канал. Файлы, уже лежащие в общем хранилище, "
            "остаются там и открываются как раньше — у каждого файла свой "
            "адрес.\n\n"
            f"{_mode}\n\n"
            "❗ ВАЖНО: не удаляйте бота из вашего канала. Бот — администратор "
            "с правом публикации; без него файлы в канале станут недоступны. "
            "Если случайно удалили — верните бота в канал, и всё снова "
            "заработает.\n\n"
            "ℹ️ Хотите вернуть загрузки в общее хранилище — «🗑 Отключить "
            "мой канал» ниже (уже сохранённое никуда не денется)."
        )
    return (
        "🔗 Моё облако — ваш личный канал\n\n"
        "Сейчас шифры ваших загрузок лежат в общем хранилище бота. Если "
        "хотите ПОЛНЫЙ контроль и независимость — подключите СВОЙ приватный "
        "канал (это официальная рекомендация разработчика для всех, кому "
        "важна анонимность и стабильность хранилища).\n\n"
        "Как это работает:\n"
        "1. Создайте свой канал в Telegram (можно приватный, без ссылки).\n"
        "2. Добавьте этого бота администратором — право «Публикация "
        "сообщений» обязательно.\n"
        "3. Нажмите «➕ Подключить мой канал» и перешлите сюда ЛЮБОЕ "
        "сообщение из вашего канала (или отправьте его @username / -100…id).\n\n"
        "После проверки бот запомнит канал, и шифры ВАШИХ новых загрузок "
        "будут уходить только в него: анонимно, под вашим полным контролем "
        "— бот лишь инструмент шифрования. Общее хранилище разработчика "
        "вами больше не используется.\n\n"
        "🗑 Отключить можно в любой момент — уже сохранённые файлы останутся "
        "доступны (пока бот остаётся админом их канала)."
    )


def get_vault_cloud_keyboard(user):
    """Клавиатура «🔗 Моё облако»: зависит от того, подключён ли канал.
    ВОЛНА 22.25: кнопка-переключатель «хранить файлы БЕЗ шифрования»
    (видна только при подключённом личном канале)."""
    _uch = _user_vault_channel(user)
    rows = []
    if _uch:
        rows.append([InlineKeyboardButton("🔄 Заменить канал",
                                          callback_data="vault_cloud_add")])
        # ВОЛНА 22.25: честный переключатель. Подпись = ЧТО СДЕЛАЕТ нажатие.
        if _vault_channel_plain(user):
            rows.append([InlineKeyboardButton("🔒 Включить шифрование файлов",
                                              callback_data="vault_plain")])
        else:
            rows.append([InlineKeyboardButton("🔓 Хранить файлы БЕЗ шифра",
                                              callback_data="vault_plain")])
        rows.append([InlineKeyboardButton("🗑 Отключить мой канал",
                                          callback_data="vault_cloud_off")])
    else:
        rows.append([InlineKeyboardButton("➕ Подключить мой канал",
                                          callback_data="vault_cloud_add")])
    rows.append([InlineKeyboardButton("⬅️ Назад", callback_data="vault_menu")])
    return InlineKeyboardMarkup(rows)


async def vault_cloud_cb(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """ВОЛНА 22.20: экран «🔗 Моё облако» — настройка ЛИЧНОГО канала."""
    query = update.callback_query
    try:
        await query.answer()
    except Exception:
        pass
    user = get_user(str(query.from_user.id))
    if not user:
        try:
            await query.answer("Сначала зарегистрируйтесь — /start", show_alert=True)
        except Exception:
            pass
        return MAIN_MENU
    try:
        await query.edit_message_text(
            _vault_cloud_text(user), reply_markup=get_vault_cloud_keyboard(user))
    except Exception:
        await query.message.reply_text(
            _vault_cloud_text(user), reply_markup=get_vault_cloud_keyboard(user))
    return MAIN_MENU


