# ==================================
# === ВОЛНА 22.29: «🤒 Я БОЛЕЛ(А)» ===
# Пользователь выбирает период болезни (с … по …), бот собирает:
#   1) ВСЁ домашнее задание класса за эти даты;
#   2) ВСЕ объявления администратора класса за это время (журнал
#      class_obj.announcements — пишется при «📢 Написать классу»).
# ==================================

SICK_MAX_DAYS = 60  # честный потолок периода (защита от «с 1 года до н.э.»)


def _sick_parse_date(text: str) -> "date | None":
    """Понимает ГГГГ-ММ-ДД и ДД.ММ.ГГГГ (любой лексикон дат)."""
    t = (text or "").strip()
    for fmt in ("%Y-%m-%d", "%d.%m.%Y", "%d.%m.%y"):
        try:
            return datetime.strptime(t, fmt).date()
        except ValueError:
            continue
    return None


async def sick_from_save(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Шаг 1: дата НАЧАЛА болезни (состояние SICK_WAIT_FROM)."""
    user = get_user(str(update.effective_user.id))
    if not user:
        return MAIN_MENU
    text = (update.message.text or "").strip()
    if text.lower() in ("отмена", "cancel"):
        context.user_data.pop("sick_from", None)
        await update.message.reply_text("Выход. Выздоравливайте!")
        return await global_cancel_handler(update, context)
    d = _sick_parse_date(text)
    if d is None:
        await update.message.reply_text(
            "Не похоже на дату. Пришлите ГГГГ-ММ-ДД (например, 2026-02-10) "
            "или ДД.ММ.ГГГГ.\n\n«отмена» — выйти.")
        return SICK_WAIT_FROM
    context.user_data["sick_from"] = d.strftime("%Y-%m-%d")
    await update.message.reply_text(
        f"✅ С {d.strftime('%d.%m.%Y')}.\n\n"
        "📅 ПО КАКОЕ число вы болели? Тот же формат даты.\n\n"
        "«отмена» — выйти.")
    return SICK_WAIT_TO


async def sick_to_save(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Шаг 2: дата КОНЦА + сборка отчёта (ДЗ + объявления за период)."""
    user = get_user(str(update.effective_user.id))
    if not user:
        return MAIN_MENU
    text = (update.message.text or "").strip()
    if text.lower() in ("отмена", "cancel"):
        context.user_data.pop("sick_from", None)
        await update.message.reply_text("Выход. Выздоравливайте!")
        return await global_cancel_handler(update, context)
    d_to = _sick_parse_date(text)
    if d_to is None:
        await update.message.reply_text(
            "Не похоже на дату. Пришлите ГГГГ-ММ-ДД (например, 2026-02-14) "
            "или ДД.ММ.ГГГГ.\n\n«отмена» — выйти.")
        return SICK_WAIT_TO
    from_raw = context.user_data.pop("sick_from", None)
    if not from_raw:
        await update.message.reply_text(
            "Сначала пришлите дату НАЧАЛА болезни. Нажмите «🤒 Я болел(а)» заново.")
        return MAIN_MENU
    try:
        d_from = datetime.strptime(from_raw, "%Y-%m-%d").date()
    except Exception:
        await update.message.reply_text("Ошибка диапазона — начните заново.")
        return MAIN_MENU
    if d_to < d_from:
        await update.message.reply_text(
            "Дата конца раньше даты начала. Пришлите дату КОНЦА болезни "
            f"не раньше {d_from.strftime('%d.%m.%Y')}:\n\n«отмена» — выйти.")
        context.user_data["sick_from"] = from_raw
        return SICK_WAIT_TO
    if (d_to - d_from).days + 1 > SICK_MAX_DAYS:
        await update.message.reply_text(
            f"Период больше {SICK_MAX_DAYS} дней — слишком длинный. "
            "Разбейте его на части (например, по месяцам).")
        context.user_data["sick_from"] = from_raw
        return SICK_WAIT_TO

    class_obj = get_class_by_user(user.user_id)
    if not class_obj:
        await update.message.reply_text("Вы не состоите в классе.")
        return MAIN_MENU

    # --- 1) Домашнее задание по дням ---
    # format_homework возвращает Markdown (**жирный**) — для честного HTML
    # снимаем звёздочки и экранируем пользовательский текст.
    hw_parts = []
    cur = d_from
    hw_days = 0
    while cur <= d_to:
        ds = cur.strftime("%Y-%m-%d")
        hw = get_homework_for_date(class_obj, ds)
        if hw:
            hw_days += 1
            hw_text = format_homework(hw, ds).replace("**", "")
            hw_parts.append(f"📅 {cur.strftime('%d.%m.%Y')}:\n{escape_html(hw_text)}")
        cur += timedelta(days=1)

    # --- 2) Объявления админов за период ---
    ann_parts = []
    for rec in (getattr(class_obj, 'announcements', []) or []):
        if not isinstance(rec, dict):
            continue
        ts = str(rec.get('ts') or '')
        if not ts or not (from_raw <= ts[:10] <= d_to.strftime("%Y-%m-%d")):
            continue
        name = str(rec.get('name') or 'админ')
        body = str(rec.get('text') or '')[:1500]
        ann_parts.append(f"📢 {ts} — {escape_html(name)}:\n{escape_html(body)}")

    header = (f"🤒 <b>Ваши пропуски: {d_from.strftime('%d.%m.%Y')} — "
              f"{d_to.strftime('%d.%m.%Y')}</b> ({escape_html(class_obj.class_name)})\n"
              "Выздоравливайте! Вот что произошло за это время:")

    sections = []
    if hw_days:
        sections.append("📚 <b>ДОМАШНЕЕ ЗАДАНИЕ</b>\n\n" + "\n\n".join(hw_parts))
    else:
        sections.append("📚 <b>ДОМАШНЕЕ ЗАДАНИЕ</b>\n\nЗа эти дни ДЗ не задано "
                        "(или админ не вносил его с датами).")
    if ann_parts:
        sections.append("📢 <b>ОБЪЯВЛЕНИЯ КЛАССА</b>\n\n" + "\n\n".join(ann_parts))
    else:
        sections.append("📢 <b>ОБЪЯВЛЕНИЯ КЛАССА</b>\n\nЗа этот период "
                        "объявлений от админа не было (журнал ведётся "
                        "с волны 22.29 — раньше объявления не записывались).")

    full = header + "\n\n" + "\n\n".join(sections)
    MAX_LEN = 3800
    if len(full) <= MAX_LEN:
        await update.message.reply_text(full, parse_mode=ParseMode.HTML)
    else:
        chunk = ""
        for para in full.split("\n\n"):
            if len(chunk) + len(para) + 2 > MAX_LEN:
                if chunk:
                    await update.message.reply_text(chunk, parse_mode=ParseMode.HTML)
                chunk = para
            else:
                chunk = f"{chunk}\n\n{para}" if chunk else para
        if chunk:
            await update.message.reply_text(chunk, parse_mode=ParseMode.HTML)
    logger.info(f"sick: {user.user_id} запросил пропуски {from_raw}..{d_to} "
                f"(ДЗ-дней: {hw_days}, объявлений: {len(ann_parts)})")
    return MAIN_MENU


async def vault_cloud_receive(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """ВОЛНА 22.20: принимает ЛИЧНЫЙ канал пользователя для «🔗 Моё облако».

    Понимает: пересланное сообщение из канала/супергруппы, @username
    публичного канала, числовой -100…id. Честно проверяет, что бот —
    администратор канала с правом «Публикация сообщений», иначе отказ с
    понятной причиной. Успех → user.vault_channel (id, title, дата)."""
    msg = update.message
    user_id = str(update.effective_user.id)
    user = get_user(user_id)
    if not user:
        await msg.reply_text("Сначала зарегистрируйтесь — отправьте /start.")
        return ConversationHandler.END
    raw_text = (msg.text or "").strip()
    low = raw_text.lower()
    if (low in ("отмена", "cancel", "/cancel", "❌ отмена", "❌ отменить")
            or "отмена" in low or "cancel" in low or "назад в меню" in low):
        await msg.reply_text(
            "Отменено — настройки облака не менялись.",
            reply_markup=get_main_menu_keyboard(user))
        return MAIN_MENU

    # 1) Определяем канал: пересланное сообщение / ссылка t.me / @username / -100…id.
    # ВОЛНА 22.24 (КЛЮЧЕВОЙ ФИКС): в PTB 21.x поле forward_from_chat УДАЛЕНО
    # (Bot API 7.0 заменил его на msg.forward_origin — MessageOriginChannel).
    # Раньше ЛЮБАЯ пересылка из канала сюда не доезжала: атрибут был None, и
    # пользователь честно получал «Не похоже на канал» на настоящий канал.
    fwd_origin = getattr(msg, "forward_origin", None)
    fwd = getattr(fwd_origin, "chat", None) if fwd_origin is not None else None
    if fwd is None:  # страховка для старых версий PTB, где поле ещё живо
        fwd = getattr(msg, "forward_from_chat", None)
    target = None
    if fwd is not None:
        target = int(getattr(fwd, "id", 0) or 0)
    elif raw_text.lower().startswith(("https://t.me/", "http://t.me/", "t.me/")):
        # Честное удобство (как в мини-аппе): ссылку на канал превращаем в id.
        # «t.me/имя» или «t.me/имя/123» → @имя (публичный канал);
        # «t.me/c/2266…/12» — внутренняя ссылка ЧАСТНОГО канала → -100…id:
        # число после /c/ — это id канала без префикса -100.
        _m = re.match(r"(?i)^(?:https?://)?t\.me/c/(\d+)(?:/\d+)?/?$", raw_text)
        if _m:
            target = int("-100" + _m.group(1))
        else:
            _rest = re.sub(r"(?i)^(?:https?://)?t\.me/", "", raw_text).strip("/")
            _uname = _rest.split("/")[0] if _rest else ""
            if _uname and not _uname.startswith("+"):
                target = "@" + _uname
    elif raw_text.startswith("@") and len(raw_text) > 2 and " " not in raw_text:
        target = raw_text
    elif raw_text.startswith("-100") and raw_text[1:].isdigit():
        target = int(raw_text)
    if target is None:
        await msg.reply_text(
            "Не похоже на пересылку из канала. Перешлите ЛЮБОЕ сообщение ИЗ "
            "вашего канала или отправьте его @username / -100…id / ссылку "
            "t.me из канала (подойдёт и «Поделиться → скопировать ссылку» — "
            "я пойму и t.me/имя, и t.me/c/… частного канала).\n\n"
            "Если Telegram не даёт переслать сообщение — в канале включён "
            "«Запрет пересылки»: пришлите ссылку или id. «отмена» — выйти.",
            reply_markup=InlineKeyboardMarkup([[
                InlineKeyboardButton("⬅️ Назад", callback_data="vault_cloud")]]),
        )
        return VAULT_MYCLOUD_WAIT

    # 2) Честная проверка: бот в канале и может публиковать.
    try:
        tc = await context.bot.get_chat(target)
    except TGBadRequest as e:
        await msg.reply_text(
            "❌ Telegram не дал посмотреть канал: "
            f"{(getattr(e, 'message', None) or e)}.\n"
            "Проверьте: бот ДОБАВЛЕН в канал (администратором) и вы "
            "переслали сообщение именно из него.",
            reply_markup=InlineKeyboardMarkup([[
                InlineKeyboardButton("⬅️ Назад", callback_data="vault_cloud")]]),
        )
        return VAULT_MYCLOUD_WAIT
    except Exception as e:
        logger.warning(f"mycloud: get_chat не удался: {e}")
        await msg.reply_text(
            "❌ Не смог проверить канал (сбой сети?). Попробуйте ещё раз.",
            reply_markup=InlineKeyboardMarkup([[
                InlineKeyboardButton("⬅️ Назад", callback_data="vault_cloud")]]),
        )
        return VAULT_MYCLOUD_WAIT
    if str(getattr(tc, "type", "")) not in ("channel", "supergroup"):
        await msg.reply_text(
            "❌ Это не канал и не супергруппа. Нужен именно КАНАЛ "
            "(можно приватный).",
            reply_markup=InlineKeyboardMarkup([[
                InlineKeyboardButton("⬅️ Назад", callback_data="vault_cloud")]]),
        )
        return VAULT_MYCLOUD_WAIT
    try:
        member = await context.bot.get_chat_member(tc.id, context.bot.id)
    except Exception:
        member = None
    status = str(getattr(member, "status", "") or "")
    can_post = bool(getattr(member, "can_post_messages", False))
    if status != "administrator" or not can_post:
        await msg.reply_text(
            "❌ Бот не администратор этого канала (или без права «Публикация "
            "сообщений»).\n\nДобавьте бота админом с этим правом и пришлите "
            "сообщение из канала ещё раз — без права публикации шифрам "
            "физически некуда лечь.",
            reply_markup=InlineKeyboardMarkup([[
                InlineKeyboardButton("⬅️ Назад", callback_data="vault_cloud")]]),
        )
        return VAULT_MYCLOUD_WAIT

    # 3) Сохраняем — и честно объясняем, что теперь где лежит.
    title = str(getattr(tc, "title", "") or raw_text or tc.id)[:80]
    user.vault_channel = {
        "id": int(tc.id),
        "title": title,
        "added": datetime.now().strftime("%Y-%m-%d %H:%M"),
    }
    save_user(user)
    _q_note = (
        "\n\n📸 И СОВЕТ ПРО КАЧЕСТВО: фото/видео присылайте «КАК ФАЙЛ» "
        "(скрепка → «Файл») или грузите оригиналы через 🌐 Веб-облако — "
        "тогда в вашем канале будут лежать байты ровно с вашего устройства, "
        "без сжатия Telegram."
    )
    await msg.reply_text(
        "✅ Готово! Ваш личный канал подключён:\n"
        f"«{title}» ({tc.id})\n\n"
        "Шифры ВАШИХ новых загрузок Сейфа теперь уходят только в него — "
        "общее хранилище бота больше не используется. Файлы, уже лежащие в "
        "общем хранилище, открываются как раньше." + _q_note,
        reply_markup=get_main_menu_keyboard(user),
    )
    return MAIN_MENU


async def vault_cloud_off_cb(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """ВОЛНА 22.20: «🗑 Отключить мой канал» — новые загрузки пойдут в
    общее хранилище; уже сохранённые остаются в канале пользователя."""
    query = update.callback_query
    try:
        await query.answer()
    except Exception:
        pass
    user = get_user(str(query.from_user.id))
    if not user:
        try:
            await query.answer("Сначала зарегистрируйтесь — /start", show_alert=True)
        except Exception:
            pass
        return MAIN_MENU
    user.vault_channel = None
    save_user(user)
    text = (
        "🗑 Личный канал отключён.\n\n"
        "Новые загрузки снова пойдут в общее хранилище бота. Файлы, уже "
        "лежавшие в вашем канале, ОТКРЫВАЮТСЯ как раньше — у каждого файла "
        "свой адрес; главное — не удаляйте бота из того канала."
    )
    try:
        await query.edit_message_text(
            text, reply_markup=get_vault_cloud_keyboard(user))
    except Exception:
        await query.message.reply_text(
            text, reply_markup=get_vault_cloud_keyboard(user))
    return MAIN_MENU


async def vault_plain_toggle_cb(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """ВОЛНА 22.25: «🔓 Хранить файлы БЕЗ шифра» / «🔒 Включить шифрование» —
    переключатель режима хранения НОВЫХ загрузок Сейфа в ЛИЧНОМ канале.
    Уже сохранённые файлы не трогаем: зашифрованные остаются под шифром,
    незашифрованные — как есть. Экран честно перерисовывается с новым
    статусом. В общий хранилище бота режим не действует (там всегда шифр)."""
    query = update.callback_query
    try:
        await query.answer()
    except Exception:
        pass
    user = get_user(str(query.from_user.id))
    if not user:
        try:
            await query.answer("Сначала зарегистрируйтесь — /start", show_alert=True)
        except Exception:
            pass
        return MAIN_MENU
    _uch = _user_vault_channel(user)
    if not _uch:
        try:
            await query.answer(
                "Сначала подключите свой канал — переключатель относится "
                "только к личному каналу.", show_alert=True)
        except Exception:
            pass
        return MAIN_MENU
    vc = user.vault_channel
    vc["plain"] = not bool(vc.get("plain"))
    user.vault_channel = vc
    save_user(user)
    logger.info(f"vault plain: пользователь {getattr(user, 'user_id', '?')} "
                f"{'ВЫКЛЮЧИЛ' if vc['plain'] else 'включил'} шифрование для "
                f"канала {_uch[0]}")
    text = _vault_cloud_text(user)
    try:
        await query.edit_message_text(text, reply_markup=get_vault_cloud_keyboard(user))
    except Exception:
        await query.message.reply_text(text, reply_markup=get_vault_cloud_keyboard(user))
    return MAIN_MENU


@timeout(CONVERSATION_TIMEOUT)
async def vault_menu_start(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Вход в Сейф кнопкой главного меню «🔐 Сейф»."""
    user_id = str(update.effective_user.id)
    user = get_user(user_id)
    if not user:
        await update.message.reply_text("Сначала зарегистрируйтесь — отправьте /start.")
        return MAIN_MENU
    # ВОЛНА 11/12: если до этого была начата загрузка в Сейф — при входе в
    # меню стираем следы из чата. ВОЛНА 12: чистим ВСЕГДА (даже с пустой
    # пачкой) — персистентный след переживает рестарт и чистится здесь.
    _stale_batch = context.user_data.get('vault_batch')
    if isinstance(_stale_batch, list) and _stale_batch:
        try:
            await _vault_cleanup_chat(context, update.message.chat_id, _stale_batch, user=user)
        except Exception:
            pass
    else:
        try:
            await _vault_cleanup_chat(context, update.message.chat_id, None, user=user)
        except Exception:
            pass
    context.user_data.pop('vault_put_mode', None)
    context.user_data.pop('vault_get_id', None)
    context.user_data.pop('vault_chp_id', None)
    context.user_data.pop('vault_ren_id', None)
    context.user_data.pop('vault_attempts', None)
    for key in ('vault_batch', 'vault_migrate_ids', 'vault_setup_pw', 'vault_qs_data',
                'vault_qs_pw', 'vault_qs_stage', 'vault_rec_answers', 'vault_rec_oldpw',
                'vault_batch_label',
                'vault_ack_mid', 'vault_ack_last', 'vault_q_warned'):
        context.user_data.pop(key, None)
    await update.message.reply_text(_vault_menu_text(user), reply_markup=get_vault_menu_keyboard())
    return MAIN_MENU


async def vault_menu_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await query.answer()
    user = get_user(str(query.from_user.id))
    if not user:
        await query.answer("Сначала зарегистрируйтесь — /start", show_alert=True)
        return MAIN_MENU
    # ВОЛНА 11/12: незавершённая пачка — следы файлов из чата стираем
    # (включая персистентный след — работает и после рестарта бота).
    _stale_batch = context.user_data.get('vault_batch')
    try:
        await _vault_cleanup_chat(
            context, query.message.chat_id,
            _stale_batch if isinstance(_stale_batch, list) else None, user=user)
    except Exception:
        pass
    for key in ('vault_put_mode', 'vault_get_id', 'vault_chp_id', 'vault_attempts',
                'vault_ren_id',
                'vault_batch', 'vault_migrate_ids', 'vault_setup_pw', 'vault_qs_data',
                'vault_qs_pw', 'vault_qs_stage', 'vault_rec_answers', 'vault_rec_oldpw',
                'vault_batch_label',
                'vault_ack_mid', 'vault_ack_last', 'vault_q_warned'):
        context.user_data.pop(key, None)
    try:
        await query.edit_message_text(_vault_menu_text(user), reply_markup=get_vault_menu_keyboard())
    except Exception:
        await query.message.reply_text(_vault_menu_text(user), reply_markup=get_vault_menu_keyboard())
    return MAIN_MENU


