async def vault_put_start(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await query.answer()
    user = get_user(str(query.from_user.id))
    if not user:
        await query.answer("Сначала зарегистрируйтесь — /start", show_alert=True)
        return MAIN_MENU
    # ВОЛНА 22.20: если общего хранилища нет, но у пользователя подключён
    # СВОЙ канал — Сейф полностью работает и без разработчика.
    if not get_cloud_channel_ids() and not _user_vault_channel(user):
        try:
            await query.edit_message_text(
                "❌ Общее хранилище пока не подключено. НО вы можете начать "
                "СЕЙЧАС: подключите СВОЙ приватный канал — 🔗 Моё облако → "
                "«➕ Подключить мой канал» (свой канал + бот админом = шифры "
                "только в вашем канале, под вашим полным контролем).",
                reply_markup=get_vault_menu_keyboard(),
            )
        except Exception:
            pass
        return MAIN_MENU
    # ВОЛНА 22.25: режим «БЕЗ шифрования» — библиотека cryptography НЕ нужна.
    _plain = (_user_vault_channel(user) is not None
              and _vault_channel_plain(user))
    if not _plain and not _vault_kdf_available():
        try:
            await query.edit_message_text(
                "❌ Шифрование недоступно: на сервере нет библиотеки "
                "cryptography (pip install cryptography).",
                reply_markup=get_vault_menu_keyboard(),
            )
        except Exception:
            pass
        return MAIN_MENU
    context.user_data['vault_put_mode'] = True
    context.user_data.pop('vault_batch', None)
    context.user_data.pop('vault_migrate_ids', None)
    context.user_data.pop('vault_setup_pw', None)
    context.user_data.pop('vault_ack_mid', None)   # 22.19: новое уведомление
    context.user_data.pop('vault_ack_last', None)  # для новой сессии
    context.user_data.pop('vault_q_warned', None)  # 22.20: совет про качество — заново
    if _plain:
        # ВОЛНА 22.25: честные инструкции режима «без шифра».
        try:
            await query.edit_message_text(
                "📥 Сохраняем файлы в ВАШ КАНАЛ (БЕЗ шифра)\n\n"
                f"Режим «без шифрования» включён в 🔗 Моём облаке — файлы "
                f"лягут в «{_user_vault_channel(user)[1]}» КАК ЕСТЬ, с "
                "исходными именами, без пароля. Достать их можно в любой "
                "момент — пароль НЕ спрашивается.\n\n"
                "⚠️ ЧЕСТНО: содержимое таких файлов видно всем, у кого есть "
                "доступ к каналу. Уже зашифрованные файлы остаются под "
                "шифром — режим действует только на НОВЫЕ загрузки.\n\n"
                "Отправьте документ, фото, видео или аудио — можно СРАЗУ "
                "НЕСКОЛЬКО файлов ПАЧКОЙ; или НАПИШИТЕ текст — он станет "
                "заметкой. Фото/видео присылайте «КАК ФАЙЛ» (скрепка → "
                "«Файл»), чтобы Telegram не сжал их.\n\n"
                "✅ ЗАКОНЧИЛИ? Кнопка «✅ Готово» ПОД сообщением (дальше — "
                "название загрузки, пароль НЕ нужен).",
                reply_markup=InlineKeyboardMarkup([[
                    InlineKeyboardButton("⬅️ Назад", callback_data="vault_menu")]]),
            )
        except Exception:
            pass
        _ack = await query.message.reply_text(
            "Жду файл или текст 👇 (закончить — кнопка «✅ Готово» ниже)",
            reply_markup=_vault_put_kb(),
        )
        _vault_track_ack(context, _ack, user=user)
        return VAULT_PUT_WAIT
    try:
        await query.edit_message_text(
            "📥 Шифруем файлы в Сейфе\n\n"
            "Отправьте документ, фото, видео или аудио — можно СРАЗУ "
            "НЕСКОЛЬКО файлов ПАЧКОЙ; или НАПИШИТЕ текст — он станет "
            "зашифрованной заметкой.\n"
            "📸 КАЧЕСТВО (совет разработчика): фото и видео присылайте «КАК "
            "ФАЙЛ» (скрепка → «Файл», или «Отправить как файл» в меню "
            "вложения) — Telegram не сожмёт их при отправке, и из Сейфа "
            "вернётся ровно тот же файл: выдача всегда идёт документом, "
            "без пережатия.\n\n"
            f"📏 Размеры: до {_fmt_bytes(VAULT_MAX_FILE_BYTES)} — мгновенно; "
            "от 20 МБ до 2 ГБ — режим больших файлов (зашифрую ПОТОКОМ, "
            "это займёт несколько минут — прогресс будет виден).\n\n"
            "✅ ЗАКОНЧИЛИ? Нажмите кнопку «✅ Готово» ПОД сообщением — писать "
            "«готово» не нужно (можно и написать, кнопка просто быстрее).\n\n"
            "🏷 НАЗВАНИЕ: сразу после «Готово» бот попросит назвать то, что вы "
            "кладёте, — название будет ВИДНО в «📦 Мои файлы», чтобы не "
            "запутаться, где что. Каждый файл можно подписать и отдельно — "
            "reply-ответом на СВОЁ сообщение с ним.\n\n"
            "🔑 Дальше бот попросит ПАРОЛЬ СЕЙФА. Он один на весь Сейф и "
            "нигде не хранится; при первой настройке бот задаст 3 секретных "
            "вопроса для восстановления доступа.",
            # ВОЛНА 22.25: «⬅️ Назад» на инструкции — выход в меню Сейфа
            # (кнопки «✅ Готово»/«❌ Отмена» — на отдельном сообщении ниже).
            reply_markup=InlineKeyboardMarkup([[
                InlineKeyboardButton("⬅️ Назад", callback_data="vault_menu")]]),
        )
    except Exception:
        pass
    _ack = await query.message.reply_text(
        "Жду файл или текст 👇 (закончить — кнопка «✅ Готово» ниже)",
        reply_markup=_vault_put_kb(),
    )
    _vault_track_ack(context, _ack, user=user)
    return VAULT_PUT_WAIT


def _vault_track_ack(context, message, user=None):
    """ВОЛНА 11/12: запоминает id СООБЩЕНИЯ БОТА, чтобы стереть его вместе со
    следами пачки при отмене/выходе/после шифрования.
    ВОЛНА 12: дублируем id в ПЕРСИСТЕНТНЫЙ след (user.vault_trace) — он живёт
    в базе и переживает рестарт бота (после рестарта user_data пуст)."""
    try:
        mid = int(getattr(message, "message_id", 0) or 0)
    except (TypeError, ValueError):
        mid = 0
    if not mid or context is None:
        return
    lst = context.user_data.setdefault('vault_chat_acks', [])
    if isinstance(lst, list) and mid not in lst:
        lst.append(mid)
    _vault_trace_add(context, user, getattr(message, "chat_id", None), mid)


def _vault_trace_add(context, user, chat_id, msg_id):
    """ВОЛНА 12: добавляет id сообщения (файл/заметка/вопрос/ответ/подсказка
    бота) в ПЕРСИСТЕНТНЫЙ след user.vault_trace. Хранятся ТОЛЬКО номера
    сообщений — никакого содержимого. След живёт в users.json (и уходит в
    снапшот канала), поэтому «❌ Отмена» стирает файлы из чата даже ПОСЛЕ
    рестарта/деплоя бота — раньше следы были только в памяти и терялись."""
    try:
        mid = int(msg_id or 0)
    except (TypeError, ValueError):
        mid = 0
    if not mid:
        return
    # 1) Быстрая память текущей сессии (user_data).
    try:
        if context is not None:
            lst = context.user_data.setdefault('vault_chat_acks', [])
            if isinstance(lst, list) and mid not in lst:
                lst.append(mid)
    except Exception:
        pass
    # 2) Персистентный след в базе.
    if user is None:
        return
    try:
        tr = getattr(user, 'vault_trace', None)
        if not isinstance(tr, dict):
            tr = {"chat_id": 0, "msgs": []}
        msgs = tr.get("msgs")
        if not isinstance(msgs, list):
            msgs = []
        if mid not in msgs:
            msgs.append(mid)
        tr["msgs"] = msgs[-60:]  # потолок: не даём следу разрастаться
        try:
            tr["chat_id"] = int(chat_id or 0)
        except (TypeError, ValueError):
            pass
        user.vault_trace = tr
        save_user(user)
    except Exception as e:
        logger.warning(f"vault trace: не удалось сохранить след: {e}")


async def _vault_cleanup_chat(context, chat_id, batch, user=None, keep_ids=None):
    """ВОЛНА 11/12: стирает из чата ВСЕ следы загрузки в Сейф.

    Пользователь просил: нажал «Отмена»/вышел из Сейфа — загруженные файлы
    не должны оставаться в чате. Удаляем: сообщения пользователя с принятыми
    файлами/заметками (chat_msg_id в элементах пачки), подтверждения бота
    («Принято…», подсказки — vault_chat_acks) и — ВОЛНА 12 — ПЕРСИСТЕНТНЫЙ
    след user.vault_trace (переживает рестарт: файлы, заметки, набранные
    вопросы/ответы на секретные вопросы). Best-effort: что не удалилось
    (старше 48ч, нет прав) — честно остаётся. Возвращает число удалённых.

    keep_ids (ВОЛНА 12): id, которые НЕ удаляем и НЕ гасим из следа — так
    файлы, НЕЗАШИФРОВАВШИЕСЯ из-за сбоя, остаются в чате (политика волны 11:
    иначе пользователь их потеряет), пока не выйдут сами или не отменятся."""
    keep = set()
    for _k in (keep_ids or []):
        try:
            _ki = int(_k or 0)
            if _ki:
                keep.add(_ki)
        except (TypeError, ValueError):
            pass
    ids, seen = [], set()
    for _it in (batch or []):
        try:
            _mid = int((_it or {}).get("chat_msg_id") or 0)
        except (TypeError, ValueError, AttributeError):
            _mid = 0
        if _mid and _mid not in seen and _mid not in keep:
            seen.add(_mid)
            ids.append(_mid)
    for _mid in (context.user_data.get('vault_chat_acks') or []):
        try:
            _mid = int(_mid or 0)
        except (TypeError, ValueError):
            _mid = 0
        if _mid and _mid not in seen and _mid not in keep:
            seen.add(_mid)
            ids.append(_mid)
    context.user_data.pop('vault_chat_acks', None)
    # ВОЛНА 12: персистентный след — работает и после рестарта бота.
    if user is not None:
        try:
            tr = getattr(user, 'vault_trace', None)
            if isinstance(tr, dict):
                try:
                    _tch = int(tr.get("chat_id") or 0)
                except (TypeError, ValueError):
                    _tch = 0
                if _tch and int(chat_id) == _tch:
                    _survivors = []
                    for _mid in (tr.get("msgs") or []):
                        try:
                            _mid = int(_mid or 0)
                        except (TypeError, ValueError):
                            _mid = 0
                        if not _mid or _mid in seen or _mid in keep:
                            if _mid in keep:
                                _survivors.append(_mid)  # остаётся в следе
                            continue
                        seen.add(_mid)
                        ids.append(_mid)
                    tr["msgs"] = _survivors
                    user.vault_trace = tr
                    save_user(user)
                else:
                    # След из другого чата — просто гасим.
                    user.vault_trace = {"chat_id": 0, "msgs": []}
                    save_user(user)
        except Exception as e:
            logger.warning(f"vault cleanup: след не очищен: {e}")
    # ВОЛНА 14/17: сырых копий больших файлов в каналах-хранилищах больше НЕТ
    # (источник — сообщение в личном чате). На случай незавершённых старых
    # сессий поддерживаем ключ channel_id. Отмена/выход/срыв сессии —
    # источники стираем (best-effort): незашифрованного нигде не остаётся.
    for _it in (batch or []):
        if not isinstance(_it, dict):
            continue
        _mt = _it.get("mt_raw")
        if isinstance(_mt, dict):
            _ch17 = int(_mt.get("peer_id") or _mt.get("channel_id") or 0)
            _mi17 = int(_mt.get("msg_id") or 0)
            if _ch17 and _mi17:
                try:
                    await context.bot.delete_message(
                        chat_id=_ch17, message_id=_mi17)
                except Exception:
                    pass
            _it.pop("mt_raw", None)
    deleted = 0
    for _mid in ids:
        try:
            await context.bot.delete_message(chat_id=chat_id, message_id=_mid)
            deleted += 1
        except Exception:
            pass
    return deleted


async def vault_put_receive(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """ВОЛНА 9: принимает ФАЧКУ файлов/заметок для Сейфа.

    Файлы скачиваются в ПАМЯТЬ (Telegram разрешает ботам качать только
    ≤20 МБ — этим же лимитом и ограничены файлы Сейфа) и складываются в
    user_data['vault_batch']. По слову «готово» бот просит ПАРОЛЬ СЕЙФА
    (один на весь Сейф) и шифрует всё пачкой."""
    msg = update.message
    user_id = str(update.effective_user.id)
    user = get_user(user_id)
    if not user:
        context.user_data.pop('vault_put_mode', None)
        await msg.reply_text("Сначала зарегистрируйтесь — отправьте /start.")
        return ConversationHandler.END
    if not get_cloud_channel_ids() and not _user_vault_channel(user):
        context.user_data.pop('vault_put_mode', None)
        await msg.reply_text(
            "❌ Общего хранилища нет, и личный канал не подключён. "
            "Подключите СВОЙ канал: 🔗 Моё облако → «➕ Подключить мой "
            "канал» — тогда Сейф заработает без разработчика.",
            reply_markup=get_main_menu_keyboard(user),
        )
        return MAIN_MENU

    att = None
    kind = None
    if getattr(msg, "photo", None):
        att = msg.photo[-1]
        kind = "photo"
    elif getattr(msg, "document", None):
        att = msg.document
        kind = "document"
    elif getattr(msg, "video", None):
        att = msg.video
        kind = "video"
    elif getattr(msg, "audio", None):
        att = msg.audio
        kind = "audio"
    elif getattr(msg, "voice", None):
        att = msg.voice
        kind = "voice"

    batch = context.user_data.get('vault_batch')
    if not isinstance(batch, list):
        batch = []
        context.user_data['vault_batch'] = batch

    raw_text = (msg.text or "").strip()
    low_raw = raw_text.lower()
    # Отмена/выход в любой момент. ВОЛНА 11: раньше кнопка клавиатуры
    # «⬅️ Назад в меню» НЕ распознавалась — текст уходил в заметки пачки и бот
    # «не выходил» из Сейфа. Теперь «назад в меню» тоже значит выход, а следы
    # загруженных в чат файлов стираются (файл не должен оставаться в чате).
    if (low_raw in ("отмена", "cancel", "/cancel", "❌ отмена", "❌ отменить")
            or "отмена" in low_raw or "cancel" in low_raw
            or "назад в меню" in low_raw):
        _batch_clean = batch if isinstance(batch, list) else None
        context.user_data.pop('vault_put_mode', None)
        context.user_data.pop('vault_batch', None)
        context.user_data.pop('vault_migrate_ids', None)
        context.user_data.pop('vault_ack_mid', None)   # 22.19: сессия закрыта
        context.user_data.pop('vault_ack_last', None)
        context.user_data.pop('vault_q_warned', None)  # 22.20
        _cleaned = await _vault_cleanup_chat(context, msg.chat_id, _batch_clean, user=user)
        await msg.reply_text(
            "Отменено — ничего не зашифровано и не загружено."
            + (f"\n🧹 Из чата стёрто сообщений: {_cleaned}." if _cleaned else ""),
            reply_markup=get_main_menu_keyboard(user),
        )
        return MAIN_MENU

    ts_fn = datetime.now().strftime("%Y-%m-%d_%H-%M")

    # «готово» — закончить пачку. ВОЛНА 13: дальше шаг НАЗВАНИЯ («сразу
    # назвать, что кладу» — будет видно в «Мои файлы») и только потом пароль
    # Сейфа. Кнопка «✅ Готово» ПОД сообщением делает то же самое (vault_done_cb).
    if att is None and low_raw in ("готово", "готово!", "готово.", "всё", "все", "done"):
        if not batch:
            await msg.reply_text(
                "Пачка пуста: пришлите хотя бы один файл или напишите "
                "текст-заметку. Завершить пачку — кнопкой «✅ Готово» или "
                "словом «готово»."
            )
            return VAULT_PUT_WAIT
        return await _vault_ask_label(msg, context, user)

    # ВОЛНА 12: ✏️ ПОДПИСЬ ФАЙЛА через reply. Текст-ОТВЕТ на своё сообщение
    # с файлом/заметкой из пачки становится подписью этого файла: она видна
    # в списке Сейфа открытым текстом — «чтобы не запутаться, где что».
    if att is None and raw_text and isinstance(batch, list) and getattr(msg, "reply_to_message", None):
        try:
            _rt_mid = int(getattr(msg.reply_to_message, "message_id", 0) or 0)
        except (TypeError, ValueError):
            _rt_mid = 0
        _target = next(
            (it for it in reversed(batch)
             if isinstance(it, dict) and int(it.get("chat_msg_id") or 0) == _rt_mid),
            None,
        ) if _rt_mid else None
        if _target is not None:
            _target["label"] = raw_text.strip()[:80]
            # ВОЛНА 22.19 (C.1): то же ОДНО редактируемое уведомление.
            # ВОЛНА 22.25: в режиме «без шифра» честно говорим как есть.
            _lbl_note = ("сам файл ХРАНИТСЯ КАК ЕСТЬ — режим «без шифра»"
                         if (_user_vault_channel(user) is not None
                             and _vault_channel_plain(user))
                         else "сам файл по-прежнему под шифром")
            await _vault_put_ack(
                update, context, user,
                note=(f"✏️ Подпись сохранена: «{_target['label']}» — она будет "
                      f"видна в списке Сейфа ({_lbl_note})."),
                force=True)
            return VAULT_PUT_WAIT

    if att is None:
        # Текст → заметка (txt) в пачке (ВОЛНА 22.25: шифрованная — только
        # в обычном режиме; «без шифра» — честно без приставки).
        _plain_note = (_user_vault_channel(user) is not None
                       and _vault_channel_plain(user))
        text = raw_text
        if not text:
            await msg.reply_text(
                ("📝 Пришлите ФАЙЛ (документ/фото/видео/аудио) или НАПИШИТЕ "
                 "текст — он станет заметкой в вашем канале. Закончить пачку — "
                 "словом «готово», выйти — «отмена».")
                if _plain_note else
                ("🔐 Пришлите ФАЙЛ (документ/фото/видео/аудио) или НАПИШИТЕ "
                 "текст — он станет зашифрованной заметкой. Закончить пачку — "
                 "словом «готово», выйти — «отмена».")
            )
            return VAULT_PUT_WAIT
        if len(text) > VAULT_MAX_TEXT_CHARS:
            await msg.reply_text(
                f"Текст длиннее {VAULT_MAX_TEXT_CHARS} символов. Разбейте на "
                "части или пришлите его документом."
            )
            return VAULT_PUT_WAIT
        batch.append({
            "source": "text", "payload": text.encode("utf-8"),
            "name": f"Заметка_{ts_fn}.txt", "kind": "document",
            "mime": "text/plain", "size": len(text.encode("utf-8")),
            "chat_msg_id": int(getattr(msg, "message_id", 0) or 0),  # ВОЛНА 11
        })
        _vault_trace_add(context, user, msg.chat_id, msg.message_id)  # ВОЛНА 12
        # ВОЛНА 22.19 (C.1): ОДНО редактируемое уведомление вместо нового
        # сообщения на каждую заметку.
        await _vault_put_ack(update, context, user,
                             note=("Текст станет заметкой в вашем канале (без шифра)."
                                   if _plain_note else
                                   "Текст станет зашифрованной заметкой."))
        return VAULT_PUT_WAIT

    # Файл.
    fsize = int(getattr(att, "file_size", 0) or 0)
    if kind == "photo":
        name = getattr(att, "file_name", None) or f"Фото_{ts_fn}.jpg"
    elif kind == "document":
        name = getattr(att, "file_name", None) or f"Файл_{ts_fn}"
    elif kind == "video":
        name = getattr(att, "file_name", None) or f"Видео_{ts_fn}.mp4"
    elif kind == "audio":
        name = getattr(att, "file_name", None) or f"Аудио_{ts_fn}.mp3"
    else:
        name = f"Голосовое_{ts_fn}.ogg"
    # ВОЛНА 8: подпись (caption) становится именем заметки Сейфа —
    # «подписывать можно было» теперь работает и при шифровании.
    _vcap = str(getattr(msg, "caption", "") or "").strip()
    if _vcap:
        _vext = ""
        if name and "." in name:
            _vext = name[name.rfind("."):].lower()[:12]
        name = _vcap[:100] + (_vext if _vext and not _vcap.lower().endswith(_vext) else "")

    # ВОЛНА 22.20 (КАЧЕСТВО, честно): Telegram сжимает фото/видео, присланные
    # НЕ «как файл», ЕЩЁ НА ОТПРАВКЕ в чат — бот получает уже сжатые байты и
    # сохраняет/выдаёт их байт-в-байт (двойного сжатия в Сейфе больше нет с
    # 22.19). Чтобы пользователь понимал, ОТКУДА потери, и как их избежать —
    # предупреждение в ОДНОМ редактируемом уведомлении, один раз за сессию.
    _q_note = ""
    if kind in ("photo", "video") and not context.user_data.get('vault_q_warned'):
        context.user_data['vault_q_warned'] = True
        _q_note = (
            "⚠️ КАЧЕСТВО: этот файл Telegram сжал ЕЩЁ ПРИ ОТПРАВКЕ в чат (так "
            "работает Telegram с фото/видео, отправленными не «как файл»). Я "
            "сохраню и верну его байт-в-байт, но исходного качества в нём уже "
            "нет. Чтобы потерь НЕ БЫЛО ВООБЩЕ: присылайте «как файл» (скрепка "
            "→ «Файл») или грузите оригиналы через 🌐 Веб-облако (Mini App)."
        )

    # ВОЛНА 14: больше ~2 ГБ — жёсткий потолок Telegram даже для MTProto
    # (2000 МиБ для ботов; 4 ГБ — только Premium у людей, ботам недоступен).
    if fsize > VAULT_MTPROTO_MAX_BYTES:
        await msg.reply_text(
            f"🚫 Файл больше {_fmt_bytes(VAULT_MTPROTO_MAX_BYTES)} (~2 ГБ) — "
            "это жёсткий потолок Telegram для ботов, дальше физика не "
            "пускает (4 ГБ — только Premium у людей, ботам он недоступен).\n\n"
            "Что делать:\n"
            "• разделите файл на части по ~1,5 ГБ и пришлите пачкой — "
            "сложу всё в Сейф одной загрузкой;\n"
            "• или сожмите то, что сжимается (тексты, PDF — в разы; "
            "видео/фото уже сжаты своим форматом)."
        )
        return VAULT_PUT_WAIT
    # ВОЛНА 14/17: от 20 МБ до 2 ГБ — гибрид Bot API + MTProto (Telethon).
    # Оригинал НЕ скачивается (Bot API так не умеет) и НИКУДА не копируется:
    # ВОЛНА 17 — сырых копий в каналах больше НЕТ (пользователь видел в канале
    # незашифрованные большие файлы и потребовал это убрать). Источник для
    # шифрования — САМО сообщение пользователя в личном чате: после «✅ Готово»
    # бот скачает его потоком через MTProto и зашифрует в DVF2 (куски по 1 МБ).
    # В канал уйдёт ТОЛЬКО шифр.
    if fsize > VAULT_MAX_FILE_BYTES:
        if not _TELETHON_OK or not BOT_TOKEN:
            await msg.reply_text(
                f"🚫 Файл больше {_fmt_bytes(VAULT_MAX_FILE_BYTES)}: обычный "
                "режим бота такие файлы скачать не может, а режим больших "
                "файлов (до 2 ГБ) сейчас ВЫКЛЮЧЕН на сервере — "
                + ("нет токена бота (BOT_TOKEN)." if not BOT_TOKEN else
                   "библиотека Telethon не установлена. Пересоберите деплой "
                   "из нового zip (requirements.txt: telethon>=1.36) — в логе "
                   "старта должна появиться строка «mtproto: клиент поднялся».")
                + "\n\nПока можно: сжать файл в ZIP/7z или разбить на части "
                "по 15–19 МБ и прислать каждую отдельно — сложу в Сейф пачкой."
            )
            return VAULT_PUT_WAIT
        # ВОЛНА 16: каналы «только для базы» тоже годятся для шифров Сейфа —
        # раньше при пустом cloud-списке большие файлы отказывали, хотя
        # канал у пользователя был.
        # ВОЛНА 22.20: у пользователя свой канал — шифр пойдёт только в него.
        _uch = _user_vault_channel(user)
        _cloud_ids = ([_uch[0]] if _uch
                      else (get_cloud_channel_ids() or get_db_channel_ids()))
        if not _cloud_ids:
            await msg.reply_text(
                "❌ Некуда класть шифр: нет ни общего хранилища, ни вашего "
                "личного канала. Подключите СВОЙ канал: 🔐 Сейф → 🔗 Моё "
                "облако → «➕ Подключить мой канал» (создайте приватный "
                "канал, добавьте бота администратором с правом «Публикация "
                "сообщений» и перешлите сюда любое сообщение из него). "
                "Без канала большим файлам (до 2 ГБ) физически некуда лечь.")
            return VAULT_PUT_WAIT
        try:
            await context.bot.send_chat_action(
                chat_id=update.effective_chat.id, action="typing")
        except Exception:
            pass
        batch.append({
            "source": "mtproto", "name": name[:120], "kind": kind,
            "mime": str(getattr(att, "mime_type", "") or ""),
            "size": fsize,
            "chat_msg_id": int(getattr(msg, "message_id", 0) or 0),  # ВОЛНА 11
            # ВОЛНА 18: file_id — запасное скачивание ≤20 МБ через Bot API,
            # если MTProto не откроет источник (холодный кэш после рестарта).
            "file_id": str(getattr(att, "file_id", "") or ""),
            # ВОЛНА 17: источник — личный чат (peer_id > 0), НЕ канал.
            "mt_raw": {"peer_id": int(msg.chat_id),
                       "msg_id": int(getattr(msg, "message_id", 0) or 0)},
        })
        _vault_trace_add(context, user, msg.chat_id, msg.message_id)  # ВОЛНА 12
        # ВОЛНА 22.19 (C.1): то же ОДНО редактируемое уведомление; важная
        # информация о потоковом режиме — с force=True (не гасится тротлингом).
        # ВОЛНА 22.20: + предупреждение о качестве фото/видео (если это они).
        _big_note = (f"📦 Большой файл {_fmt_bytes(fsize)}: зашифрую ПОТОКОМ после "
                     "«✅ Готово» прямо из этого чата (несколько минут — это "
                     "нормально; в канал уйдёт ТОЛЬКО шифр, никаких "
                     "незашифрованных копий, оригинал из чата сотру после "
                     "шифрования).")
        if _q_note:
            _big_note += "\n\n" + _q_note
        _ack = await _vault_put_ack(update, context, user, note=_big_note,
                                    force=True)
        # ВОЛНА 18: ранний прогрев источника — фоном, ПОКА пользователь
        # называет файлы и вводит пароль; access_hash запомнится заранее,
        # и к моменту «✅ Готово» источник уже проверен.
        try:
            _ptask = asyncio.create_task(
                _vault_mt_precheck(context, batch[-1], _ack))
            _bd = getattr(getattr(context, "application", None),
                          "bot_data", None)
            if isinstance(_bd, dict):
                _bd.setdefault("_bg_tasks", []).append(_ptask)
        except Exception:
            pass
        return VAULT_PUT_WAIT

    # Скачиваем В ПАМЯТЬ (≤20 МБ — разрешено Bot API).
    try:
        await context.bot.send_chat_action(chat_id=update.effective_chat.id, action="typing")
    except Exception:
        pass
    try:
        tg_file = await context.bot.get_file(att.file_id)
        buf = io.BytesIO()
        await asyncio.wait_for(tg_file.download_to_memory(out=buf), timeout=120)
        payload = buf.getvalue()
    except Exception as e:
        logger.error(f"vault put: скачать файл не удалось: {e}")
        await msg.reply_text("❌ Не смог скачать файл для шифрования. Попробуйте ещё раз.")
        return VAULT_PUT_WAIT
    batch.append({
        "source": "file", "payload": payload, "name": name[:120],
        "kind": kind, "mime": str(getattr(att, "mime_type", "") or ""),
        "size": len(payload),
        "chat_msg_id": int(getattr(msg, "message_id", 0) or 0),  # ВОЛНА 11
    })
    _vault_trace_add(context, user, msg.chat_id, msg.message_id)  # ВОЛНА 12
    # ВОЛНА 22.19 (C.1): ОДНО редактируемое уведомление вместо нового
    # сообщения на каждый файл. ВОЛНА 22.20: + заметка про качество
    # (первое фото/видео сессии — с force=True, чтобы точно было видно).
    await _vault_put_ack(update, context, user, note=_q_note,
                         force=bool(_q_note))
    return VAULT_PUT_WAIT


# ============================================================
# === ВОЛНА 13: «✅ Готово» КНОПКОЙ + НАЗВАНИЕ СРАЗУ + 🔎 ИМЯ ===
# ============================================================

def _vault_put_kb():
    """ВОЛНА 13: кнопки ПОД сообщением загрузки в Сейф.
    «✅ Готово» — закончить пачку БЕЗ ввода текста «готово» (просьба
    пользователя: «кнопка готово должна быть снизу сообщения… а не писать
    готово — лучше сразу кнопку нажать»). «❌ Отмена» — выйти и стереть
    все следы из чата (то же, что текст «отмена»)."""
    return InlineKeyboardMarkup([
        [InlineKeyboardButton("✅ Готово", callback_data="vault_done"),
         InlineKeyboardButton("❌ Отмена", callback_data="vault_cancel")],
    ])


class _VaultAckRef:
    """ВОЛНА 22.19: лёгкая ссылка на сообщение-уведомление пачки (id уже
    известен) — для _vault_mt_precheck, который правит ТЕКСТ того же
    сообщения: нужны только chat_id / message_id / text."""
    __slots__ = ("chat_id", "message_id", "text")

    def __init__(self, chat_id, message_id, text=""):
        self.chat_id = chat_id
        self.message_id = message_id
        self.text = text


def _vault_put_ack_text(context, note="", user=None):
    """ВОЛНА 22.19 (C.1): текст ОДНОГО редактируемого уведомления о пачке.
    По просьбе пользователя: «не должно отправляться столько уведомлений,
    сколько файлов — одно сообщение просто должно редактироваться».
    ВОЛНА 22.25: в режиме «БЕЗ шифрования» текст честно говорит про заливку
    в личный канал без пароля (user передаётся из _vault_put_ack)."""
    batch = context.user_data.get('vault_batch')
    n = len(batch) if isinstance(batch, list) else 0
    _plain = user is not None and _user_vault_channel(user) is not None \
        and _vault_channel_plain(user)
    lines = [
        f"📥 Принято: {n} шт.",
        "Файлы держу в памяти — в чат они не попадут; все следы сотру после "
        + ("заливки" if _plain else "шифрования") + " или отмены.",
    ]
    if note:
        lines.append(note)
    lines.append(
        "Пришлите ещё файл/заметку или нажмите «✅ Готово» ниже — дальше "
        + ("попросим название (пароль НЕ нужен — режим «без шифра»)."
           if _plain else
           "попросят название и пароль Сейфа.")
        + " Подписать файл — ответьте (reply) "
        "на СВОЁ сообщение с ним названием."
    )
    return "\n\n".join(lines)


async def _vault_put_ack(update, context, user, note="", force=False):
    """ВОЛНА 22.19 (C.1): ОДНО сообщение-уведомление на всю загрузку в Сейф.

    Первый файл/заметка создаёт сообщение; каждый следующий — РЕДАКТИРУЕТ
    его (edit_message_text). Тротлинг правок 1,1 сек (лимит Telegram);
    важные заметки (потоковый режим, подпись файла) проходят с force=True.
    Кнопки «✅ Готово»/«❌ Отмена» передаются при КАЖДОЙ правке — иначе
    Telegram их снимет (это и есть «галочка ровно на месте»). Возвращает
    _VaultAckRef (для _vault_mt_precheck)."""
    msg = update.message
    mid = context.user_data.get('vault_ack_mid')
    text = _vault_put_ack_text(context, note, user=user)
    if mid:
        now = time.monotonic()
        last = float(context.user_data.get('vault_ack_last', 0) or 0)
        if now - last < 1.1 and not force:
            return _VaultAckRef(msg.chat_id, int(mid))  # тротлинг: счётчик
            # обновится следующей правкой/шагом — спама всё равно нет
        try:
            try:
                await context.bot.edit_message_text(
                    text, chat_id=msg.chat_id, message_id=int(mid),
                    reply_markup=_vault_put_kb())
            except TGRetryAfter as e:
                # Telegram сам сказал, сколько ждать — честно ждём и повторяем.
                await asyncio.sleep(float(getattr(e, "retry_after", 1) or 1))
                await context.bot.edit_message_text(
                    text, chat_id=msg.chat_id, message_id=int(mid),
                    reply_markup=_vault_put_kb())
            context.user_data['vault_ack_last'] = time.monotonic()
            return _VaultAckRef(msg.chat_id, int(mid), text)
        except TGBadRequest as e:
            if "not modified" in str(e).lower():
                context.user_data['vault_ack_last'] = time.monotonic()
                return _VaultAckRef(msg.chat_id, int(mid), text)
            # «Message to edit not found» и т.п. — сообщение пропало:
            # шлём новое ниже (оно снова будет единственным).
        except Exception:
            pass
    _ack = await msg.reply_text(text, reply_markup=_vault_put_kb())
    _vault_track_ack(context, _ack, user=user)
    try:
        context.user_data['vault_ack_mid'] = int(_ack.message_id)
    except Exception:
        pass
    context.user_data['vault_ack_last'] = time.monotonic()
    return _VaultAckRef(msg.chat_id, int(getattr(_ack, "message_id", 0) or 0), text)


def _vault_kind_label(kind):
    """Человекочитаемое имя типа файла Сейфа (для карточки 🔎)."""
    return {"photo": "фото", "video": "видео", "audio": "аудио",
            "voice": "голосовое"}.get(str(kind or ""), "документ")


def _vault_item_label(item, batch_label=""):
    """ВОЛНА 13: итоговая подпись элемента Сейфа.
    Приоритет: reply-подпись КОНКРЕТНОГО файла → название ВСЕЙ загрузки
    (шаг «сразу назвать, что кладу») → пусто («Файл #N» в списке).
    Обрезка 80 символов — как у reply-подписи волны 12."""
    return (str((item or {}).get("label") or "").strip()
            or str(batch_label or "").strip())[:80]


async def _vault_ask_label(msg, context, user):
    """ВОЛНА 13: шаг «НАЗОВИТЕ, что кладёте» — после «✅ Готово» (кнопкой или
    словом) и ДО пароля Сейфа. Одно название на всю загрузку; попадает в
    «📦 Мои файлы» (кнопка-строка, текст списка, карточка 🔎). Пропустить
    можно кнопкой «⏭ Пропустить» — останутся исходные имена/подписи файлов."""
    _ack = await msg.reply_text(
        "🏷 НАЗОВИТЕ, что вы кладёте в Сейф — одно название для всей загрузки "
        f"(файлов в пачке: {len(context.user_data.get('vault_batch') or [])}).\n\n"
        "Название будет ВИДНО в «📦 Мои файлы» — чтобы не запутаться, где что. "
        "Например: «Контрольная по алгебре», «Документы на кружок».\n\n"
        "Не нужно общее название — нажмите «⏭ Пропустить»: останутся исходные "
        "имена файлов (подписать каждый отдельно можно и позже — ✏️ в списке).",
        reply_markup=InlineKeyboardMarkup([
            [InlineKeyboardButton("⏭ Пропустить", callback_data="vault_labelskip"),
             InlineKeyboardButton("❌ Отмена", callback_data="vault_cancel")],
            # ВОЛНА 22.25: «⬅️ Назад» — вернуться к добавлению файлов в пачку.
            [InlineKeyboardButton("⬅️ Назад к файлам", callback_data="vault_put_back")],
        ]),
    )
    _vault_track_ack(context, _ack, user=user)
    return VAULT_LABEL_WAIT


async def vault_done_cb(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """ВОЛНА 13: кнопка «✅ Готово» ПОД сообщением — закончить пачку без
    набора текста. Дальше — шаг названия и пароль Сейфа."""
    query = update.callback_query
    await query.answer()
    user = get_user(str(query.from_user.id))
    if not user:
        await query.answer("Сначала зарегистрируйтесь — /start", show_alert=True)
        return MAIN_MENU
    batch = context.user_data.get('vault_batch')
    if not isinstance(batch, list) or not batch:
        await query.answer(
            "Пачка пуста — пришлите хотя бы один файл или текст-заметку.",
            show_alert=True)
        return VAULT_PUT_WAIT
    return await _vault_ask_label(query.message, context, user)


@timeout(CONVERSATION_TIMEOUT)
async def vault_label_receive(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """ВОЛНА 13: приём НАЗВАНИЯ загрузки Сейфа (одно на всю пачку)."""
    msg = update.message
    user = get_user(str(update.effective_user.id))
    batch = context.user_data.get('vault_batch')
    if not user or not isinstance(batch, list) or not batch:
        context.user_data.pop('vault_batch_label', None)
        await msg.reply_text(
            "Сессия загрузки потеряна. Начните заново: ☁️ Облако → 🔐 Сейф.",
            reply_markup=get_main_menu_keyboard(user) if user else None,
        )
        return MAIN_MENU
    text = (msg.text or "").strip()
    if not text:
        await msg.reply_text(
            "Напишите название ОДНИМ сообщением — например «Контрольная по "
            "алгебре», — или нажмите «⏭ Пропустить».")
        return VAULT_LABEL_WAIT
    context.user_data['vault_batch_label'] = text[:80]
    return await _vault_ask_category(msg, context, user)


async def vault_labelskip_cb(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """ВОЛНА 13: «⏭ Пропустить» — без общего названия (исходные имена +
    reply-подписи файлов остаются)."""
    query = update.callback_query
    await query.answer()
    user = get_user(str(query.from_user.id))
    if not user:
        await query.answer("Сначала зарегистрируйтесь — /start", show_alert=True)
        return MAIN_MENU
    batch = context.user_data.get('vault_batch')
    if not isinstance(batch, list) or not batch:
        await query.answer("Пачка пуста — пришлите файлы.", show_alert=True)
        return VAULT_PUT_WAIT
    return await _vault_ask_category(query.message, context, user)


# === ВОЛНА 22.12: КАТЕГОРИЯ И ТЕГИ при загрузке, ПОИСК по «Мои файлы» ===
VAULT_CATEGORIES = (
    ("music", "🎵 Музыка"),
    ("photo", "📷 Фото"),
    ("video", "🎬 Видео"),
    ("file",  "📄 Файл"),
    ("other", "📦 Другое"),
)
_VAULT_CAT_TITLES = dict(VAULT_CATEGORIES)


def _vault_cat_by_kind(kind, mime=""):
    """Автокатегория по типу содержимого (для старых загрузок без выбора)."""
    _k = str(kind or "").lower()
    _m = str(mime or "").lower()
    if "audio" in _k or "audio" in _m:
        return "music"
    if "video" in _k or "video" in _m:
        return "video"
    if "photo" in _k or "image" in _k or "image" in _m:
        return "photo"
    if _k in ("document", "file") or _m:
        return "file"
    return "other"


async def _vault_ask_category(msg, context, user):
    """ВОЛНА 22.12: шаг «ВЫБЕРИТЕ КАТЕГОРИЮ» — после названия и ДО пароля.
    Категория попадает в карточку файла и участвует в поиске."""
    _kb = [[InlineKeyboardButton(t, callback_data=f"vault_cat_{c}")]
           for c, t in VAULT_CATEGORIES]
    _kb.append([InlineKeyboardButton("❌ Отмена", callback_data="vault_cancel")])
    # ВОЛНА 22.25: «⬅️ Назад» — вернуться к шагу названия загрузки.
    _kb.append([InlineKeyboardButton("⬅️ Назад", callback_data="vault_cat_back")])
    _ack = await msg.reply_text(
        "🗂 КАТЕГОРИЯ ЗАГРУЗКИ — что это? (файлов в пачке: "
        f"{len(context.user_data.get('vault_batch') or [])})\n\n"
        "Категория поможет находить файлы через 🔍 Поиск «Мои файлов». "
        "Если не выбрать — подберём по типу файла.",
        reply_markup=InlineKeyboardMarkup(_kb),
    )
    _vault_track_ack(context, _ack, user=user)
    return VAULT_CAT_WAIT


async def vault_cat_cb(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """ВОЛНА 22.12: выбор категории — сохраняем и просим теги."""
    query = update.callback_query
    await query.answer()
    user = get_user(str(query.from_user.id))
    batch = context.user_data.get('vault_batch')
    if not user or not isinstance(batch, list) or not batch:
        await query.answer("Сессия загрузки потеряна. Начните заново.",
                           show_alert=True)
        return MAIN_MENU
    code = query.data[len("vault_cat_"):]
    if code not in _VAULT_CAT_TITLES:
        await query.answer("Неизвестная категория", show_alert=True)
        return VAULT_CAT_WAIT
    context.user_data['vault_batch_cat'] = code
    return await _vault_ask_tags(query.message, context, user)


async def _vault_ask_tags(msg, context, user):
    """ВОЛНА 22.12: шаг «ТЕГИ» — необязательные метки для поиска."""
    _ack = await msg.reply_text(
        "🏷 ТЕГИ ДЛЯ ПОИСКА — необязательно. Пришлите 1–8 меток через запятую "
        "(каждая до 24 символов): например «алгебра, контрольная, 8А».\n\n"
        "Теги видны только вам и работают в 🔍 Поиске «Мои файлов».",
        reply_markup=InlineKeyboardMarkup([
            [InlineKeyboardButton("⏭ Пропустить", callback_data="vault_tagskip"),
             InlineKeyboardButton("❌ Отмена", callback_data="vault_cancel")],
            # ВОЛНА 22.25: «⬅️ Назад» — вернуться к шагу категории.
            [InlineKeyboardButton("⬅️ Назад", callback_data="vault_tags_back")],
        ]),
    )
    _vault_track_ack(context, _ack, user=user)
    return VAULT_TAGS_WAIT


def _vault_parse_tags(text):
    """ВОЛНА 22.12: разбор тегов — запятые/переводы строк, до 8, по 24 симв."""
    raw = re.split(r"[,;\n]+", str(text or ""))
    tags, seen = [], set()
    for t in raw:
        t = t.strip()[:24]
        if not t:
            continue
        low = t.lower()
        if low in seen:
            continue
        seen.add(low)
        tags.append(t)
        if len(tags) >= 8:
            break
    return tags


@timeout(CONVERSATION_TIMEOUT)
async def vault_tags_receive(update: Update,
                             context: ContextTypes.DEFAULT_TYPE):
    """ВОЛНА 22.12: приём тегов загрузки Сейфа."""
    msg = update.message
    user = get_user(str(update.effective_user.id))
    batch = context.user_data.get('vault_batch')
    if not user or not isinstance(batch, list) or not batch:
        await msg.reply_text(
            "Сессия загрузки потеряна. Начните заново: ☁️ Облако → 🔐 Сейф.",
            reply_markup=get_main_menu_keyboard(user) if user else None,
        )
        return MAIN_MENU
    tags = _vault_parse_tags(msg.text)
    if not tags:
        await msg.reply_text(
            "Не увидел тегов. Пришлите их через запятую — например «алгебра, "
            "контрольная» — или нажмите «⏭ Пропустить».")
        return VAULT_TAGS_WAIT
    context.user_data['vault_batch_tags'] = tags
    # ВОЛНА 22.25: режим «БЕЗ шифрования» — пароль не нужен, заливаем сразу.
    if _user_vault_channel(user) is not None and _vault_channel_plain(user):
        return await _vault_plain_upload(msg, context, user)
    return await _vault_prompt_password(msg, user, context=context)


