@timeout(CONVERSATION_TIMEOUT)
async def vault_search_receive(update: Update,
                               context: ContextTypes.DEFAULT_TYPE):
    """ВОЛНА 22.12: 🔍 ПОИСК по «Мои файлы» — названия, теги, категория.
    Все слова запроса должны найтись в названии И/ИЛИ тегах И/ИЛИ категории."""
    msg = update.message
    user = get_user(str(update.effective_user.id))
    if not user:
        await msg.reply_text("Сначала зарегистрируйтесь — /start")
        return MAIN_MENU
    query_text = (msg.text or "").strip()
    if not query_text:
        await msg.reply_text("Пришлите запрос словами — например «контрольная "
                             "алгебра» или «музыка».")
        return VAULT_SEARCH_WAIT
    matches = _vault_search_matches(user, query_text)
    if not matches:
        await msg.reply_text(
            "🙈 По запросу «" + query_text[:60] + "» в Сейфе ничего не нашлось.\n\n"
            "Ищем по НАЗВАНИЮ (🏷 при загрузке или ✏️ в списке), ТЕГАМ и "
            "КАТЕГОРИИ (🎵/📷/🎬/📄/📦). Попробуйте другое слово.",
            reply_markup=InlineKeyboardMarkup([[
                InlineKeyboardButton("⬅️ К списку файлов",
                                     callback_data="vault_files")]]),
        )
        return MAIN_MENU
    kb = []
    for rec in matches:
        label = str(rec.get("label") or "").strip() or "Файл без подписи"
        cat = _VAULT_CAT_TITLES.get(rec.get("cat") or "", "")
        title = (label[:28] + (" • " + cat if cat else ""))
        kb.append([
            InlineKeyboardButton(f"📥 {title}",
                                 callback_data=f"vault_get_{rec.get('id')}"),
            InlineKeyboardButton("🔎", callback_data=f"vault_show_{rec.get('id')}"),
        ])
    kb.append([InlineKeyboardButton("⬅️ К списку файлов",
                                    callback_data="vault_files")])
    await msg.reply_text(
        f"🔍 НАЙДЕНО: {len(matches)} шт. по запросу «{query_text[:60]}»",
        reply_markup=InlineKeyboardMarkup(kb),
    )
    return MAIN_MENU


def _vault_search_matches(user, query_text):
    """ВОЛНА 22.12: поиск по Сейфу — все слова запроса должны найтись в
    названии И/ИЛИ тегах И/ИЛИ категории файла. Топ-10 по релевантности."""
    _q = (query_text or "").strip().lower()
    if not _q:
        return []
    toks = [t for t in re.split(r"[\s,;]+", _q) if t][:6]
    files = [f for f in (getattr(user, "vault_files", []) or [])
             if isinstance(f, dict)]
    res = []
    for rec in files:
        label = str(rec.get("label") or "")
        tags = " ".join(str(t) for t in (rec.get("tags") or []))
        cat_code = str(rec.get("cat") or "") or _vault_cat_by_kind(
            rec.get("kind"), rec.get("mime"))
        cat_title = _VAULT_CAT_TITLES.get(cat_code, "")
        hay = (label + " " + tags + " " + cat_title + " " + cat_code).lower()
        if not all(t in hay for t in toks):
            continue
        score = sum((t in label.lower()) * 2 + (t in tags.lower())
                    for t in toks)
        res.append((score, rec))
    res.sort(key=lambda p: -p[0])
    return [rec for _s, rec in res[:10]]


async def vault_cancel_cb(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """ВОЛНА 13: кнопка «❌ Отмена» ПОД сообщением — то же, что текст
    «отмена»: выйти из Сейфа и СТЕРЕТЬ все следы из чата (файлы, заметки,
    подсказки; персистентный след чистится даже после рестарта бота).
    ВОЛНА 22.5: если ПРЯМО СЕЙЧАС идёт шифрование/загрузка или выдача файла —
    кнопка только ставит флаг отмены и ничего не чистит: user_data и следы
    принадлежат работающему процессу (честную зачистку сделает сам цикл)."""
    query = update.callback_query
    _uid = str(query.from_user.id)
    if _vault_op_running(_uid):
        _VAULT_OPS[_uid]["event"].set()
        await query.answer()
        try:
            await query.edit_message_text(
                "⛔ Останавливаю операцию Сейфа — секунду, подчищу всё "
                "недогруженное…")
        except Exception:
            pass
        return None
    await query.answer()
    user = get_user(str(query.from_user.id))
    batch = context.user_data.get('vault_batch')
    _batch_clean = batch if isinstance(batch, list) else None
    for key in ('vault_put_mode', 'vault_batch', 'vault_migrate_ids',
                'vault_batch_label', 'vault_batch_cat', 'vault_batch_tags'):
        context.user_data.pop(key, None)
    _cleaned = 0
    try:
        _cleaned = await _vault_cleanup_chat(
            context, query.message.chat_id, _batch_clean, user=user)
    except Exception:
        _cleaned = 0
    try:
        await query.edit_message_text(
            "Отменено — ничего не зашифровано и не загружено."
            + (f"\n🧹 Из чата стёрто сообщений: {_cleaned}." if _cleaned else ""))
    except Exception:
        pass
    if user:
        await query.message.reply_text(
            "Главное меню:", reply_markup=get_main_menu_keyboard(user))
    return MAIN_MENU


async def vault_getstop_cb(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """ВОЛНА 22.5/22.8-легаси: кнопка «❌ Отмена» НА прогрессе выдачи
    большого файла (осталась только на сообщениях, отправленных ДО
    обновления — в 22.8 отмена живёт в клавиатуре). Только ставит
    флаг отмены — сам процесс заметит его на ближайшем куске и ЧЕСТНО
    подчищает временные файлы; шифр в канале не трогается."""
    query = update.callback_query
    _uid = str(query.from_user.id)
    op = _VAULT_OPS.get(_uid)
    if op is not None and op.get("active") and not op["event"].is_set():
        op["event"].set()
        await query.answer("⛔ Останавливаю — подчищаю временные файлы…")
    else:
        await query.answer("Нечего отменять: операция уже завершилась.")
    return None  # состояние не меняем — работающий процесс сам всё завершит


def _vault_dialog_kb():
    """ВОЛНА 22.10: клавиатура процесса Сейфа — РОВНО ОДНА кнопка «❌ Отмена»
    (просьба пользователя: «нужна одна кнопка отмены, которая за весь этот
    процесс будет отвечать, а не две»; «после распаковки и загрузки должна
    оставаться только одна кнопка отмены, и при загрузке тоже одна»).
    Эта единственная кнопка обслуживает ВЕСЬ процесс: закрывает диалоги
    (ввод пароля/подписи — глобальный перехват отмены), останавливает
    заливку В Сейф, даёт выдаче дойти до конца (потом сама сотрёт файл и
    вернёт главное меню) и стирает уже выданный файл. Нажатия ловятся
    инжектом глобальной отмены из ЛЮБОГО состояния (_GLOBAL_CANCEL_RE)."""
    return ReplyKeyboardMarkup([['❌ Отмена']], resize_keyboard=True)


def _vault_wipe_target(user_id, context):
    """ВОЛНА 22.10: цель отмены — {chat_id, msg_id} выданного файла Сейфа,
    который ещё висит в чате. Ищем в user_data (быстро) и в профиле
    (vault_kb_wipe — переживает рестарт бота). None — цели нет."""
    _t = None
    try:
        _t = context.user_data.get("vault_kb_wipe")
    except Exception:
        _t = None
    if not (isinstance(_t, dict) and _t.get("msg_id")):
        _u = get_user(str(user_id)) if user_id else None
        _t = getattr(_u, "vault_kb_wipe", None) if _u is not None else None
    if isinstance(_t, dict) and _t.get("msg_id"):
        return _t
    return None


async def vault_kb_cancel_msg(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """ВОЛНА 22.10: ЕДИНСТВЕННАЯ кнопка «❌ Отмена» — отвечает за ВЕСЬ процесс
    Сейфа (просьба пользователя: «одна кнопка отмены, которая за весь этот
    процесс будет отвечать, а не две»). Что она делает:
    1) ПРЯМО СЕЙЧАС идёт ЗАЛИВКА В СЕЙФ (kind="put") — ставим флаг отмены:
       процесс сам остановится на ближайшем куске и честно подчистит
       временные файлы (22.3);
    1а) ПРЯМО СЕЙЧАС идёт ВЫДАЧА файла (kind="get") — НЕ прерываем её
       («если еще загружается то загрузка должна закончиться»), но помечаем
       op["cancel_after"]: когда загрузка дойдёт до конца, бот САМ удалит
       файл из чата (по настройке 22.7) и вернёт главное меню — нажимать
       второй раз не нужно;
    2) файл недавно выдан из Сейфа и ещё висит в чате — удаляем сообщение
       с ним (если в ⚙️ Настройках включено удаление; цель хранится в
       профиле — vault_kb_wipe — и переживает рестарт бота) и ВЫВОДИМ
       ПОЛЬЗОВАТЕЛЯ НА ГЛАВНЫЙ ЭКРАН (главное меню в клавиатуре);
    3) нечего отменять — честно говорим и возвращаем главное меню."""
    chat = update.effective_chat
    if chat is None or chat.type != "private":
        return MAIN_MENU  # в группах кнопка Сейфа не работает
    user_id = str(update.effective_user.id)
    user = get_user(user_id)
    _kb_menu = get_main_menu_keyboard(user) if user is not None else None
    # 1) Активная операция Сейфа: род решает семантику (22.9/22.10).
    if _vault_op_running(user_id):
        _op = _VAULT_OPS.get(user_id) or {}
        if str(_op.get("kind") or "put") == "get":
            # 1а) ВЫДАЧА файла — НЕ прерываем (требование пользователя:
            # «если еще загружается то загрузка должна закончиться»),
            # но отмену запоминаем: после выдачи файл будет удалён
            # автоматически (по настройке) и юзер вернётся в меню.
            try:
                _op["cancel_after"] = True
            except Exception:
                pass
            await update.message.reply_text(
                "⏳ Отмена принята — выдачу не прерываю: загрузка спокойно "
                "дойдёт до конца. Как только файл будет выдан, я сам удалю "
                "его из чата (или оставлю — смотря что у вас в ⚙️ Настройках) "
                "и верну вас в главное меню.")
            return MAIN_MENU
        # 1) ЗАЛИВКА В СЕЙФ — останавливаем (22.3, как просил пользователь).
        _VAULT_OPS[user_id]["event"].set()
        await update.message.reply_text(
            "⛔ Останавливаю — процесс заметит отмену на ближайшем куске и "
            "честно подчистит временные файлы. Шифр в Сейфе цел.",
            reply_markup=_kb_menu)
        return MAIN_MENU
    # 2) Выданный файл — стереть из чата (настройка 22.7 уважается) и
    #    вывести пользователя на главный экран (22.10).
    target = _vault_wipe_target(user_id, context)
    if target is not None:
        _wipe_on = True if user is None else bool(
            getattr(user, "vault_wipe_on_cancel", True))
        if not _wipe_on:
            await update.message.reply_text(
                "ℹ️ Файл ОСТАВЛЕН в чате: в ⚙️ Настройках выключено удаление "
                "расшифрованного файла при «Отмене». Включить обратно можно "
                "там же.",
                reply_markup=_kb_menu)
            return MAIN_MENU
        _gone = False
        try:
            await context.bot.delete_message(
                chat_id=int(target.get("chat_id") or chat.id),
                message_id=int(target.get("msg_id")))
            _gone = True
        except Exception:
            pass
        # Цель отработана — гасим, чтобы повторное нажатие не удаляло заново.
        context.user_data.pop("vault_kb_wipe", None)
        if user is not None:
            try:
                user.vault_kb_wipe = None
                save_user(user)
            except Exception:
                pass
        await update.message.reply_text(
            "❌ Готово — файл исчез из чата (отмена после распаковки). "
            "Шифр в Сейфе цел: расшифровать снова можно в любой момент."
            if _gone else
            "Файл уже исчез из чата (или не найден). Шифр в Сейфе цел — "
            "расшифруйте заново, когда понадобится.",
            reply_markup=_kb_menu)
        return MAIN_MENU
    # 3) Нечего отменять — честно и сразу в главное меню (22.10).
    await update.message.reply_text(
        "Сейчас нечего отменять: «❌ Отмена» остановит заливку файла В Сейф, "
        "даст спокойно дойти до конца выдаче (потом сама сотрёт файл) и "
        "сотрёт из чата уже выданный файл.",
        reply_markup=_kb_menu)
    return MAIN_MENU


async def _vault_offer_wipe(context, chat_id, file_msg_id, wipe_enabled=True,
                            user=None, cancel_after=False):
    """ВОЛНА 22.6→22.10: честная подсказка после выдачи (распаковки) файла.
    ВОЛНА 22.10: на сообщении кнопки НЕТ и в главном меню её тоже НЕТ —
    после выдачи в клавиатуре остаётся РОВНО ОДНА кнопка «❌ Отмена»
    (просьба пользователя: «после распаковки и загрузки должна оставаться
    только одна кнопка отмены»). Здесь:
    • регистрируем цель отмены — user.vault_kb_wipe (переживает рестарт,
      дубль в user_data): её сотрёт кнопка «❌ Отмена» из клавиатуры;
    • шлём подсказку ВМЕСТЕ с однокнопочной клавиатурой «❌ Отмена»;
    • 22.7: если автоудаление выключено (wipe_enabled=False) — честно
      сообщаем, что файл останется в чате.
    cancel_after=True (22.10): «Отмена» была нажата ЕЩЁ ВО ВРЕМЯ выдачи —
    загрузке дали дойти до конца (требование пользователя), теперь
    выполняем обещание: сами стираем файл (по настройке 22.7) и возвращаем
    пользователю главное меню — второй раз нажимать не нужно.
    Работает и для Bot API-выдачи, и для MTProto: сообщение отправлено
    самим ботом, значит бот может его удалить."""
    try:
        if user is None:
            try:
                user = get_user(str(int(chat_id)))
            except (TypeError, ValueError):
                user = None
        _kb_menu = get_main_menu_keyboard(user) if user is not None else None
        if cancel_after:
            # 22.10: отмена была ВО ВРЕМЯ загрузки — загрузка закончилась,
            # теперь стираем файл (по настройке) и возвращаем главное меню.
            _deleted = False
            if wipe_enabled:
                try:
                    await context.bot.delete_message(
                        chat_id=int(chat_id), message_id=int(file_msg_id))
                    _deleted = True
                except Exception:
                    pass
            if not wipe_enabled:
                _text = ("✅ Загрузка закончилась — файл выдан.\n"
                         "ℹ️ Файл ОСТАВЛЕН в чате: в ⚙️ Настройках выключено "
                         "удаление при «Отмене».")
            elif _deleted:
                _text = ("✅ Загрузка закончилась — и отмена сработала: файл "
                         "исчез из чата. Шифр в Сейфе цел: файл можно "
                         "получить снова.")
            else:
                _text = ("✅ Загрузка закончилась — файл выдан (стереть его "
                         "из чата не удалось: возможно, он уже удалён).")
            await context.bot.send_message(
                chat_id=chat_id, text=_text, reply_markup=_kb_menu)
            return
        _target = {"chat_id": int(chat_id), "msg_id": int(file_msg_id)}
        try:
            context.user_data["vault_kb_wipe"] = _target
        except Exception:
            pass
        if user is not None:
            try:
                user.vault_kb_wipe = _target
                save_user(user)
            except Exception:
                pass
        _kb_cancel = _vault_dialog_kb()
        if not wipe_enabled:
            await context.bot.send_message(
                chat_id=chat_id,
                text=("✅ Готово — файл распакован и выдан только вам.\n"
                      "ℹ️ Автоудаление при «Отмене» выключено в ⚙️ Настройках "
                      "— файл остаётся в чате. Шифр в Сейфе цел: файл можно "
                      "получить снова. «❌ Отмена» в клавиатуре вернёт вас "
                      "в главное меню."),
                reply_markup=_kb_cancel)
            return
        await context.bot.send_message(
            chat_id=chat_id,
            text=("✅ Готово — файл распакован и выдан только вам.\n"
                  "❌ «Отмена» — единственная кнопка в КЛАВИАТУРЕ снизу: "
                  "нажмите, и файл исчезнет из чата, а вы вернётесь в "
                  "главное меню. Нужен ещё — сохраните/перешлите его "
                  "заранее; шифр в Сейфе останется целым, файл можно "
                  "получить снова."),
            reply_markup=_kb_cancel)
    except Exception as e:
        logger.warning(f"vault wipe: не удалось показать подсказку отмены: {e}")


async def vault_wipe_cb(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """ВОЛНА 22.6/22.8-легаси: inline-кнопка «❌ Отменить» ПОД выданным
    файлом (осталась только на сообщениях до обновления — в 22.8 отмена
    живёт В КЛАВИАТУРЕ через vault_kb_cancel_msg). Файл (расшифрованная
    копия) ИСЧЕЗАЕТ из чата. Сам шифр в
    канале остаётся: файл всегда можно расшифровать заново."""
    query = update.callback_query
    await query.answer()
    # Стирать может только владелец личного чата (защита от чужих групп).
    if query.message.chat.id != query.from_user.id:
        await query.answer("Это можно сделать только в своём чате с ботом.",
                           show_alert=True)
        return None
    try:
        _mid = int(query.data.replace("vault_wipe_", "", 1))
    except (TypeError, ValueError):
        return None
    # ВОЛНА 22.7: настройка «🗑 Удалять файл при «Отмене»» (⚙️ Настройки).
    _user = get_user(str(query.from_user.id))
    _wipe_on = True if _user is None else bool(
        getattr(_user, "vault_wipe_on_cancel", True))
    if not _wipe_on:
        # Удаление выключено в настройках: файл ОСТАЁТСЯ в чате — честно сообщаем.
        try:
            await query.edit_message_text(
                "ℹ️ Файл ОСТАВЛЕН в чате: в ⚙️ Настройках выключено удаление "
                "расшифрованного файла при «Отменить». Включить обратно "
                "можно там же.")
        except Exception:
            pass
        if _user:
            try:
                await context.bot.send_message(
                    chat_id=query.message.chat.id, text="Главное меню:",
                    reply_markup=get_main_menu_keyboard(_user))
            except Exception:
                pass
        return MAIN_MENU
    _gone = False
    try:
        await context.bot.delete_message(
            chat_id=query.message.chat.id, message_id=_mid)
        _gone = True
    except Exception:
        pass
    try:
        await query.edit_message_text(
            "❌ Готово — файл исчез из чата (отмена после распаковки). "
            "Шифр в Сейфе цел: расшифровать снова можно в любой момент."
            if _gone else
            "Файл уже исчез из чата (или не найден). Шифр в Сейфе цел — "
            "расшифруйте заново, когда понадобится.")
    except Exception:
        pass
    if _user:
        try:
            await context.bot.send_message(
                chat_id=query.message.chat.id, text="Главное меню:",
                reply_markup=get_main_menu_keyboard(_user))
        except Exception:
            pass
    return MAIN_MENU


async def vault_wipe_toggle_cb(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """ВОЛНА 22.7: тоггл в ⚙️ Настройках — «🗑 Удалять файл при «Отмене»».
    ДА (по умолчанию) — «❌ Отменить» после распаковки удаляет файл из чата;
    НЕТ — файл остаётся в чате, подсказка об удалении не предлагается."""
    query = update.callback_query
    await query.answer()
    user_id = str(query.from_user.id)
    user = get_user(user_id)
    if not user:
        user = User(user_id)
    user.vault_wipe_on_cancel = not bool(
        getattr(user, "vault_wipe_on_cancel", True))
    save_user(user)
    return await user_settings(update, context)


async def vault_show_cb(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """ВОЛНА 13: кнопка «🔎» у файла — РАСКРЫТЬ полное название.

    В кнопках списка длинные названия обрезает сам Telegram (около 25–30
    символов). Карточка показывает название ЦЕЛИКОМ; «⬅️ Свернуть (к
    списку)» закрывает карточку — можно раскрыть ДРУГОЙ файл (просьба:
    «раскрыть его, а потом закрыть и посмотреть другой файл»)."""
    query = update.callback_query
    await query.answer()
    user = get_user(str(query.from_user.id))
    if not user:
        await query.answer("Сначала зарегистрируйтесь — /start", show_alert=True)
        return MAIN_MENU
    vid = query.data.replace("vault_show_", "", 1)
    rec = _vault_find_record(user, vid)
    if not rec:
        await query.answer("Файл не найден.", show_alert=True)
        return MAIN_MENU
    files = [f for f in (getattr(user, "vault_files", []) or []) if isinstance(f, dict)]
    try:
        idx = files.index(rec) + 1
    except ValueError:
        idx = 0
    label = str(rec.get("label") or "").strip()
    lines = ["🔎 ПОЛНОЕ НАЗВАНИЕ ФАЙЛА", ""]
    if label:
        lines.append(f"🏷 «{label}»")
    else:
        lines.append(f"Без подписи — «Файл #{idx}». Подписать можно кнопкой ✏️ ниже.")
    if rec.get("plain"):
        # ВОЛНА 22.25: у файла «без шифра» имя не секрет — показываем сразу.
        _pname = str(rec.get("name") or "").strip()
        if _pname and _pname != label:
            lines.append(f"📄 Имя файла: {_pname}")
    lines.append("")
    lines.append(
        f"📦 Размер: {_fmt_bytes(rec.get('size_orig', 0))} "
        + (f"• 🔓 хранится БЕЗ шифра (режим «без шифра»)"
           if rec.get("plain") else
           f"(в шифре {_fmt_bytes(rec.get('size_enc', 0))})"))
    lines.append(
        f"📅 Добавлено: {_rec_ts_display(rec)} • 🧩 тип: {_vault_kind_label(rec.get('kind'))}")
    lines.append("")
    # ВОЛНА 22.25: честный блок про хранение — зависит от режима файла.
    if rec.get("plain"):
        lines.append("🔓 Файл хранится в вашем канале КАК ЕСТЬ (режим «без "
                     "шифра»): выдача — сразу, без пароля. Виден всем, у кого "
                     "есть доступ к каналу.")
    else:
        lines.append("🔒 Настоящее имя файла и его содержимое под шифром — "
                     "увидите после ввода пароля (📥 Достать).")
    kb = [
        [InlineKeyboardButton("⬅️ Свернуть (к списку)", callback_data="vault_files")],
        [InlineKeyboardButton("📥 Достать", callback_data=f"vault_get_{vid}"),
         InlineKeyboardButton("✏️ Подписать", callback_data=f"vault_ren_{vid}"),
         InlineKeyboardButton("🗑 Удалить", callback_data=f"vault_del_{vid}")],
        # ВОЛНА 22.12: 🔗 — собрать share-ссылку с этим файлом внутри.
        [InlineKeyboardButton("🔗 Поделиться этим файлом",
                              callback_data=f"share_open_{vid}")],
    ]
    try:
        await query.edit_message_text("\n".join(lines), reply_markup=InlineKeyboardMarkup(kb))
    except Exception:
        await query.message.reply_text("\n".join(lines), reply_markup=InlineKeyboardMarkup(kb))
    return MAIN_MENU


async def _vault_prompt_password(msg, user, note: str = "", context=None):
    """ВОЛНА 9: единый запрос пароля Сейфа (после пачки/переноса).
    ВОЛНА 11: при ПЕРВОЙ настройке показываем таблицу стойкости пароля
    (за сколько его разгадала бы супер-машина — дословные значения)."""
    if _vault_auth_valid(user):
        _sent = await msg.reply_text(
            f"{note}🔑 Введите ПАРОЛЬ СЕЙФА (попыток: {VAULT_ATTEMPTS_MAX}) — "
            "он один для всех файлов Сейфа. Сообщение с паролем сразу сотрётся.\n\n"
            "Забыли? Отправьте слово «восстановить» или нажмите «🔑 Забыл "
            "пароль» в меню Сейфа.",
            reply_markup=_vault_dialog_kb(),
        )
    else:
        _sent = await msg.reply_text(
            f"{note}🔑 Придумайте ПАРОЛЬ СЕЙФА (минимум {VAULT_MIN_PASSWORD} символов). "
            "Он будет открывать ВСЕ файлы Сейфа, храниться нигде не будет и "
            "сотрётся из чата.\n\n"
            + _vault_strength_table_text() + "\n\n"
            "Сразу после этого бот задаст 3 СЕКРЕТНЫХ ВОПРОСА — они вернут "
            "доступ, если пароль забудется.\n\n"
            "Отправьте пароль одним сообщением.",
            reply_markup=_vault_dialog_kb(),
        )
    if context is not None:
        _vault_track_ack(context, _sent, user=user)
    return VAULT_PUT_PASSWORD


@timeout(CONVERSATION_TIMEOUT)
async def vault_put_password(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """ВОЛНА 9: шифрует пачку ПАРОЛЕМ СЕЙФА.

    • Пароль Сейфа уже настроен → проверяем его (3 попытки) и шифруем.
    • Первый раз → этот пароль становится паролем Сейфа; сначала бот задаст
      3 секретных вопроса (VAULT_QS_WAIT), потом зашифрует пачку."""
    msg = update.message
    user_id = str(update.effective_user.id)
    user = get_user(user_id)
    # ВОЛНА 22.3: прямо сейчас идёт шифрование/загрузка Сейфа? Тогда «Отмена»
    # ТОЛЬКО ставит флаг отмены и не трогает user_data — им владеет работающий
    # процесс; зачистку и честный отчёт сделает сам цикл шифрования.
    if _vault_op_running(user_id):
        _VAULT_OPS[user_id]["event"].set()
        await msg.reply_text(
            "⛔ Останавливаю шифрование/загрузку — секунду, подчищу всё "
            "недогруженное…")
        return VAULT_PUT_PASSWORD
    batch = context.user_data.get('vault_batch')
    if not user or not isinstance(batch, list) or not batch:
        context.user_data.pop('vault_put_mode', None)
        context.user_data.pop('vault_batch', None)
        context.user_data.pop('vault_migrate_ids', None)
        await msg.reply_text(
            "Сессия шифрования потеряна. Начните заново: 🔐 Сейф → 📥 Положить.",
            reply_markup=get_main_menu_keyboard(user) if user else None,
        )
        return MAIN_MENU
    password = (msg.text or "").strip()
    # Стираем сообщение с паролем (в личке бот умеет удалять сообщения).
    try:
        await context.bot.delete_message(chat_id=msg.chat_id, message_id=msg.message_id)
    except Exception:
        pass
    # Кнопка клавиатуры шлёт «❌ Отмена» — принимаем любой разумный вариант.
    # ВОЛНА 11: «назад в меню» тоже выход; при отмене стираем и следы файлов
    # из чата (пользователь просил: файл не должен оставаться в чате).
    _pw_low = password.lower().strip()
    if (_pw_low in ("отмена", "cancel", "/cancel", "❌ отмена", "❌ отменить")
            or "отмена" in _pw_low or "cancel" in _pw_low
            or "назад в меню" in _pw_low):
        await _vault_cleanup_chat(context, msg.chat_id, batch, user=user)
        context.user_data.pop('vault_put_mode', None)
        context.user_data.pop('vault_batch', None)
        context.user_data.pop('vault_migrate_ids', None)
        await msg.reply_text(
            "Отменено — файлы НЕ зашифрованы и НЕ загружены, следы в чате стёрты.",
            reply_markup=get_main_menu_keyboard(user),
        )
        return MAIN_MENU
    # ВОЛНА 9: забыли пароль прямо на этом шаге — не мучаем пользователя.
    # Файлы пачки жили только в памяти, честно предупреждаем об их потере.
    if _pw_low in ("восстановить", "восстановление", "забыл", "забыла"):
        # ВОЛНА 11: пачка уходит из памяти — следы файлов из чата тоже.
        await _vault_cleanup_chat(context, msg.chat_id, batch, user=user)
        context.user_data.pop('vault_batch', None)
        context.user_data.pop('vault_migrate_ids', None)
        context.user_data.pop('vault_put_mode', None)
        context.user_data.pop('vault_attempts', None)
        await msg.reply_text(
            "Файлы текущей пачки забыты (они были только в памяти) — после "
            "восстановления доступа пришлите их заново: это займёт секунды.")
        return await _vault_rec_begin(msg, context, user)
    if _vault_auth_valid(user):
        # Пароль Сейфа уже существует — введённый ДОЛЖЕН совпасть с ним.
        if not _vault_check_safe_password(user, password):
            attempts = int(context.user_data.get('vault_attempts', 0) or 0) + 1
            context.user_data['vault_attempts'] = attempts
            if attempts >= VAULT_ATTEMPTS_MAX:
                # ВОЛНА 11: файлы не зашифрованы — их следы из чата тоже стираем.
                await _vault_cleanup_chat(context, msg.chat_id, batch, user=user)
                for key in ('vault_put_mode', 'vault_batch', 'vault_migrate_ids', 'vault_attempts'):
                    context.user_data.pop(key, None)
                await msg.reply_text(
                    f"🚫 Неверный пароль Сейфа {VAULT_ATTEMPTS_MAX} раза — файлы "
                    "НЕ зашифрованы и НЕ загружены. Начните заново позже.",
                    reply_markup=get_main_menu_keyboard(user),
                )
                return MAIN_MENU
            await msg.reply_text(
                f"❌ Неверный пароль Сейфа (попытка {attempts} из "
                f"{VAULT_ATTEMPTS_MAX}). Попробуйте ещё раз, отправьте «отмена» "
                "или «восстановить» — верну доступ по секретным вопросам."
            )
            return VAULT_PUT_PASSWORD
        context.user_data.pop('vault_attempts', None)
        return await _vault_encrypt_batch(msg, context, user, password)
    # Первый запуск Сейфа: этот пароль станет паролем Сейфа.
    if len(password) < VAULT_MIN_PASSWORD:
        await msg.reply_text(
            f"Пароль короче {VAULT_MIN_PASSWORD} символов — такой легко подобрать. "
            "Придумайте подлиннее (отменить: «отмена»)."
        )
        return VAULT_PUT_PASSWORD
    context.user_data['vault_setup_pw'] = password
    context.user_data['vault_qs_data'] = {"mode": "setup", "q": [], "a": [], "stage": 0}
    await msg.reply_text(
        "🛡️ Пароль Сейфа принят (он скрыт и нигде не сохранён в открытом виде)."
        f"\n{_vault_strength_note(password)}\n\n"
        "Теперь 3 СЕКРЕТНЫХ ВОПРОСА — ваша страховка: ответив на них, вы "
        "вернёте доступ, если забудете пароль. Придумайте вопросы, ответы "
        "на которые знаете ТОЛЬКО вы.\n\n"
        "Вопрос 1 из 3:"
    )
    return VAULT_QS_WAIT


# === ВОЛНА 22.3: живая анимация заливки Сейфа + честная ОТМЕНА ===
# Пользователь просил: (1) при заливании шифра в канал — анимация, чтобы было
# видно, что всё грузится; (2) «❌ Отмена» во время шифрования/загрузки должна
# ОСТАНОВИТЬ процесс и удалить то, что успело зашифроваться/загрузиться.

class _VaultCancelled(Exception):
    """Кооперативная отмена операции Сейфа по команде пользователя."""


# Реестр активных операций Сейфа: uid → состояние (одно на пользователя).
_VAULT_OPS = {}
_VAULT_OP_FRAMES = "🌑🌒🌓🌔🌕🌖🌗🌘"


def _vault_op_begin(user_id, total, kind="put"):
    """Открывает операцию Сейфа для пользователя.
    ВОЛНА 22.9: у операции есть РОД — kind="put" (заливка В Сейф) или
    kind="get" (выдача файла ИЗ Сейфа в чат). Род определяет семантику
    отмены: заливку можно остановить (22.3), а выдача по прямому требованию
    пользователя («если еще загружается то загрузка должна закончиться»)
    НЕ прерывается — она спокойно дойдёт до конца."""
    op = {
        "event": asyncio.Event(),          # установка = «пользователь нажал Отмена»
        "sent": [],                        # (channel_id, msg_id) залитых шифров ЭТОЙ пачки
        "temp": [],                        # временные каталоги/файлы на диске
        "phase": "Шифрую и заливаю",       # человекочитаемая фаза
        "kind": str(kind or "put"),        # 22.9: "put" (заливка) / "get" (выдача)
        "done": 0, "total": int(total or 0),
        "sub": "",                         # подстрока прогресса («качаю и шифрую 43%»)
        "active": True,
    }
    _VAULT_OPS[str(user_id)] = op
    return op


def _vault_op_end(user_id):
    """Закрывает операцию (флаг снят, реестр почищен)."""
    op = _VAULT_OPS.pop(str(user_id), None)
    if op is not None:
        op["active"] = False
    return op


def _vault_op_running(user_id):
    """True, пока идёт шифрование/загрузка пачки Сейфа."""
    op = _VAULT_OPS.get(str(user_id))
    return bool(op and op.get("active") and not op["event"].is_set())


async def _vault_animate_progress(context, progress_msg, op):
    """ВОЛНА 22.3: анимация на сообщении-прогрессе. Правит текст РАЗ В 2.5 с
    (лимиты editMessageText соблюдаются), кадры-луны крутятся, фаза/счётчик/
    подстрока берутся из op — их обновляет рабочий цикл и потоковое шифро­вание."""
    j = 0
    while True:
        await asyncio.sleep(2.5)
        j += 1
        frame = _VAULT_OP_FRAMES[j % len(_VAULT_OP_FRAMES)]
        txt = f"🔐 {op.get('phase') or 'Шифрую и заливаю'}: " \
              f"{op.get('done', 0)}/{op.get('total', 0)} {frame}"
        if op.get("sub"):
            txt += f"\n{op['sub']}"
        try:
            await context.bot.edit_message_text(
                txt, chat_id=progress_msg.chat_id,
                message_id=progress_msg.message_id)
        except Exception:
            pass  # один сбой правки не должен убивать анимацию


def _vault_bar(done, total, width=10):
    """ВОЛНА 22.12: полоса прогресса [▓▓▓░░░░░░░] для заливки/выдачи Сейфа."""
    try:
        done = max(0, int(done or 0))
        total = max(0, int(total or 0))
    except (TypeError, ValueError):
        return "░" * width
    if total <= 0 or done <= 0:
        return "░" * width
    filled = max(0, min(width, int(width * done / total + 0.5)))
    return "▓" * filled + "░" * (width - filled)


def _fmt_eta(seconds):
    """ВОЛНА 22.12: остаток времени в человекочитаемом виде (3с / 1м 20с / 2ч 5м)."""
    try:
        s = max(0, int(seconds))
    except (TypeError, ValueError):
        return "—"
    if s < 60:
        return f"{s}с"
    if s < 3600:
        return f"{s // 60}м {s % 60}с"
    if s < 86400:
        return f"{s // 3600}ч {(s % 3600) // 60}м"
    return f"{s // 86400}д {(s % 86400) // 3600}ч"


class _VaultSubProg:
    """Интерфейс как у _ProgressEdit, но текст пишется в op['sub'] — его
    показывает аниматор. Так потоковое шифрование и спиннер не дерутся за
    одно сообщение (правки не дублируются, лимиты не нарушаются).
    ВОЛНА 22.12: done/total рисуют полосу [▓▓▓░░░░░░░] со скоростью и ETA;
    sync_bar() — синхронная точка для колбэка Telethon (заливка шифра)."""

    def __init__(self, op, prefix=""):
        self.op = op
        self.prefix = prefix or ""
        self._last = 0.0
        self._sp_t = None
        self._sp_done = 0
        self._sp_ema = 0.0
        self._sync_last = 0.0

    def _bar_line(self, text, done, total):
        now = time.monotonic()
        try:
            done = max(0, int(done or 0))
            total = max(0, int(total or 0))
        except (TypeError, ValueError):
            return text
        if total > 0 and done >= 0:
            if self._sp_t is not None and now > self._sp_t:
                inst = (done - self._sp_done) / (now - self._sp_t)
                self._sp_ema = (0.65 * self._sp_ema + 0.35 * inst
                                if self._sp_ema else inst)
            self._sp_t, self._sp_done = now, done
            line = (f"[{_vault_bar(done, total)}] {_fmt_bytes(done)} / "
                    f"{_fmt_bytes(total)} ({done * 100 // total}%)")
            if self._sp_ema > 1:
                line += f"\n⚡ {_fmt_bytes(int(self._sp_ema))}/с"
                _eta = (total - done) / self._sp_ema
                if 0 <= _eta < 86400 * 7:
                    line += f" | ⏱ осталось {_fmt_eta(int(_eta))}"
            return (text + "\n" + line) if text else line
        return text

    async def edit(self, text=None, force=False, done=None, total=None):
        if self.op is None:
            return None
        now = time.monotonic()
        if not force and (now - self._last) < 3.5:
            return None
        self._last = now
        if done is not None or total is not None:
            text = self._bar_line(text, done, total)
        t = (text or "").strip()
        self.op["sub"] = f"{self.prefix} {t}".strip() if t else self.prefix
        return None

    def sync_bar(self, current, total, stage="📥 Скачивание"):
        """ВОЛНА 22.12: СИНХРОННАЯ точка прогресса для Telethon
        (progress_callback(current, total)) — обновляет op['sub'] не чаще
        раза в секунду, без await и без правок сообщения."""
        if self.op is None:
            return
        now = time.monotonic()
        if now - self._sync_last < 1.0:
            return
        self._sync_last = now
        try:
            self.op["sub"] = self._bar_line(
                f"{self.prefix} {stage}", current, total).strip()
        except Exception:
            pass


async def _vault_cancel_cleanup(context, op):
    """Отмена: стираем из каналов шифры ЭТОЙ пачки и временные файлы с диска.
    Возвращает число удалённых шифр-сообщений (для честного отчёта)."""
    deleted = 0
    for cid, mid in (op.get("sent") or []):
        if not cid or not mid:
            continue
        try:
            await context.bot.delete_message(chat_id=int(cid), message_id=int(mid))
            deleted += 1
        except Exception:
            pass
    op["sent"] = []
    for p in (op.get("temp") or []):
        try:
            if os.path.isdir(p):
                _shutil.rmtree(p, ignore_errors=True)
            elif os.path.isfile(p):
                os.remove(p)
        except Exception:
            pass
    op["temp"] = []
    return deleted


async def _vault_encrypt_batch(msg, context, user, password):
    """ВОЛНА 9: шифрует пачку паролем Сейфа, грузит шифры в канал по кругу,
    удаляет миграционные оригиналы. Возвращает состояние для ConversationHandler.
    ВОЛНА 13: файлы без СВОЕЙ reply-подписи получают название ВСЕЙ загрузки
    (шаг «сразу назвать, что кладу») — видно в «📦 Мои файлы»."""
    batch = context.user_data.get('vault_batch') or []
    # ВОЛНА 13: читаем название ДО чистки user_data ниже.
    _batch_label = str(context.user_data.get('vault_batch_label') or "").strip()[:80]
    # ВОЛНА 22.3: операция (для честной отмены) + ЖИВАЯ анимация прогресса
    # вместо статичного текста — пользователь видит, что всё грузится.
    op = _vault_op_begin(getattr(user, "user_id", "") or "", len(batch))
    progress = None
    anim = None
    try:
        progress = await msg.reply_text(
            f"🔐 Шифрую и заливаю 0/{len(batch)} {_VAULT_OP_FRAMES[0]}")
    except Exception:
        progress = None
    if progress is not None:
        anim = asyncio.create_task(_vault_animate_progress(context, progress, op))
    files = [f for f in (getattr(user, "vault_files", []) or []) if isinstance(f, dict)]
    ok_n, fail_n = 0, 0
    fail_reasons = []  # ВОЛНА 18: честные причины сбоев — в сообщение юзеру
    cancelled = False  # ВОЛНА 22.3: пачка прервана пользователем
    try:
        for i, item in enumerate(batch, 1):
            # ВОЛНА 22.3: «❌ Отмена» — прекращаем ВЕСЬ цикл немедленно.
            if op["event"].is_set():
                raise _VaultCancelled()
            op["done"] = i - 1
            op["sub"] = f"«{(item.get('name') or 'файл')}»: шифрую…"
        # ВОЛНА 14: большой файл (>20 МБ) — потоковый путь DVF2 через
        # MTProto. ВОЛНА 17: источник — сообщение пользователя в ЛИЧНОМ чате
        # (никаких сырых копий в каналах); здесь бот качает
        # его потоком, шифрует кусками по 1 МБ и заливает контейнер.
            if item.get("source") == "mtproto":
                try:
                    rec_mt = await _vault_seal_item_mtproto(
                        msg, context, user, item, password,
                        progress, i, len(batch))
                except _VaultCancelled:
                    raise  # ВОЛНА 22.3: отмену НЕ глотаем как сбой файла
                except Exception as e:
                    # ПОЛИТИКА ПДн 1.2: имя файла пользователя в лог не попадает.
                    logger.error(
                        f"vault put: большой файл, user_id={getattr(user, 'user_id', '?')}: {e}")
                    rec_mt = None
                    fail_reasons.append(
                        f"«{(item.get('name') or 'файл')}»: "
                        f"{_vault_fail_reason(e)}")
                if rec_mt is None:
                    fail_n += 1
                    continue
                # ВОЛНА 13: без своей reply-подписи — название всей загрузки.
                rec_mt["label"] = _vault_item_label(item, _batch_label)
                # ВОЛНА 22.12: категория и теги — для поиска по «Мои файлы».
                rec_mt["cat"] = (context.user_data.get('vault_batch_cat')
                                 or _vault_cat_by_kind(item.get("kind"),
                                                       item.get("mime")))
                rec_mt["tags"] = list(context.user_data.get('vault_batch_tags') or [])
                files.append(rec_mt)
                ok_n += 1
                op["done"] = i
                op["sub"] = ""
                item["done"] = True  # ВОЛНА 11: шифр в канале — оригинал из чата сотрём
                continue
            try:
                container = await asyncio.to_thread(
                    _vault_pack, password, item.get("payload") or b"", {
                        "n": item.get("name", "файл"), "k": item.get("kind", "document"),
                        "m": item.get("mime", ""), "t": datetime.now().strftime("%Y-%m-%d %H:%M"),
                    },
                )
            except Exception as e:
                # ПОЛИТИКА ПДн 1.2: имя файла пользователя в лог не попадает.
                logger.error(f"vault put: шифрование не удалось, "
                             f"user_id={getattr(user, 'user_id', '?')}: {e}")
                fail_n += 1
                fail_reasons.append(
                    f"«{(item.get('name') or 'файл')}»: {_vault_fail_reason(e)}")
                item["payload"] = b""
                continue
            item["payload"] = b""  # исходник больше не нужен — только шифр
            salt_hex = container[9:25].hex()
            nonce_hex = container[25:37].hex()
            iters = int.from_bytes(container[5:9], "big")
            key = _vault_derive_key(password, bytes.fromhex(salt_hex), iters)
            verifier_hex = _vault_verifier(key).hex()
            # Грузим ШИФР в канал по кругу (cloud-каналы).
            _vfn = f"vault_{datetime.now().strftime('%Y%m%d_%H%M%S')}_{i}.bin"
            _vcap = "🔐 Сейф: зашифрованный файл (открыть без пароля невозможно)."
            # ВОЛНА 22.3: отмена между шагами загрузки.
            if op["event"].is_set():
                raise _VaultCancelled()
            op["sub"] = f"«{(item.get('name') or 'файл')}»: заливаю шифр…"
            up = await _storage_upload_document(context, container,
                                                filename=_vfn, caption=_vcap,
                                                user=user)
            if up is None:
                # ВОЛНА 18: вторая попытка Bot API (одноразовые сбои бывают),
                # затем заливка шифра через MTProto — ≤48 МБ ботам разрешено.
                if op["event"].is_set():
                    raise _VaultCancelled()
                up = await _storage_upload_document(context, container,
                                                    filename=_vfn, caption=_vcap,
                                                    user=user)
                if up is None and _TELETHON_OK and BOT_TOKEN:
                    if op["event"].is_set():
                        raise _VaultCancelled()
                    _mtc = await _mt_client()
                    if _mtc is not None:
                        _updir = _tempfile.mkdtemp(prefix="dvf1_up_")
                        op["temp"].append(_updir)  # ВОЛНА 22.3: для отмены
                        try:
                            _uppath = os.path.join(_updir, "c.bin")
                            with open(_uppath, "wb") as _ufh:
                                _ufh.write(container)
                            up = await _mt_upload_container(
                                _mtc, _uppath, len(container),
                                caption=_vcap, filename=_vfn, user=user)
                        finally:
                            _shutil.rmtree(_updir, ignore_errors=True)
            container = b""
            if up is None:
                fail_n += 1
                fail_reasons.append(
                    f"«{(item.get('name') or 'файл')}»: шифр не приняли каналы — "
                    "проверьте, что бот администратор канала")
                continue
            # ВОЛНА 22.3: запоминаем залитый шифр ЭТОЙ пачки — при отмене
            # пользователь попросил «удалить что шифровал и загружал».
            try:
                op["sent"].append((int(up.get("channel_id")
                                       or get_storage_channel_id() or 0),
                                   int(up.get("message_id") or 0)))
            except (TypeError, ValueError):
                pass
            files.append({
                "id": _vault_gen_id(user),
                "kind": item.get("kind", "document"),
                "mime": item.get("mime", ""),
                "ts": _file_ts_now(), "tss": datetime.now().strftime("%Y-%m-%d %H:%M"),
                "size_orig": int(item.get("size", 0) or 0),
                "size_enc": int(up.get("size", 0) or 0),
                "salt": salt_hex,
                "verifier": verifier_hex,
                "iters": iters,
                "nonce": nonce_hex,
                "msg_id": int(up.get("message_id", 0)),
                "file_id": up.get("file_id"),
                "channel_id": up.get("channel_id"),
                # ВОЛНА 12: видная подпись («чтобы не запутаться, где что»).
                # ВОЛНА 13: без своей подписи — название всей загрузки.
                # Содержимое и настоящее имя — по-прежнему под шифром.
                "label": _vault_item_label(item, _batch_label),
                # ВОЛНА 22.12: категория и теги — для поиска по «Мои файлы».
                "cat": (context.user_data.get('vault_batch_cat')
                        or _vault_cat_by_kind(item.get("kind"),
                                              item.get("mime"))),
                "tags": list(context.user_data.get('vault_batch_tags') or []),
            })
            ok_n += 1
            op["done"] = i
            op["sub"] = ""
            item["done"] = True  # ВОЛНА 11: шифр в канале — оригинал из чата сотрём
    except _VaultCancelled:
        cancelled = True
    finally:
        # ВОЛНА 22.3: анимацию останавливаем в любом исходе, операцию закрываем.
        if anim is not None:
            anim.cancel()
            try:
                await anim
            except (asyncio.CancelledError, Exception):
                pass
        _vault_op_end(getattr(user, "user_id", "") or "")
    if cancelled:
        # ВОЛНА 22.3: пользователь нажал «❌ Отмена» — честная зачистка:
        # шифры ЭТОЙ пачки стираются из канала, временные файлы — с диска.
        deleted = await _vault_cancel_cleanup(context, op)
        if progress is not None:
            try:
                await context.bot.edit_message_text(
                    "⛔ Остановлено",
                    chat_id=progress.chat_id, message_id=progress.message_id)
            except Exception:
                pass
        for key in ('vault_put_mode', 'vault_batch', 'vault_migrate_ids',
                    'vault_attempts', 'vault_setup_pw', 'vault_qs_data',
                    'vault_batch_label',
                    'vault_ack_mid', 'vault_ack_last', 'vault_q_warned'):
            context.user_data.pop(key, None)
        await msg.reply_text(
            "⛔ Остановлено по вашему «❌ Отмена».\n\n"
            f"• Загрузка прервана: обработано {op.get('done', 0)}/{op.get('total', 0)}.\n"
            f"• Из канала стёрто шифров этой загрузки: {deleted}.\n"
            "• Временные файлы стёрты с сервера.\n"
            "• Исходные файлы ОСТАЛИСЬ в чате — ничего не потеряно.\n"
            "• В Сейфе — только то, что лежало до этой загрузки.\n\n"
            "Положить заново: 🔐 Сейф → 📥 Положить.",
            reply_markup=get_main_menu_keyboard(user))
        return MAIN_MENU
    user.vault_files = files
    # Миграция: незашифрованные оригиналы («старые файлы») больше не нужны —
    # правило «файлы всегда в сейфе облака».
    migrated = 0
    migrate_ids = context.user_data.get('vault_migrate_ids') or []
    if migrate_ids:
        cloud_recs = [f for f in (getattr(user, "cloud_files", []) or []) if isinstance(f, dict)]
        for mid in migrate_ids:
            rec = next((r for r in cloud_recs if r.get("id") == mid), None)
            if not rec:
                continue
            ch = rec.get("channel_id") or get_storage_channel_id()
            if ch and rec.get("msg_id"):
                try:
                    await context.bot.delete_message(chat_id=ch, message_id=int(rec["msg_id"]))
                except Exception:
                    pass
            cloud_recs = [r for r in cloud_recs if r.get("id") != mid]
            migrated += 1
        if migrated:
            user.cloud_files = cloud_recs
    save_user(user)
    # ВОЛНА 17: пароль+вопросы+новые шифры должны доехать до канала сразу —
    # не ждём 30-сек тикер (при рестарте в этом окне Сейф «забывал»).
    _vault_flush_soon(context, reason="шифрование пачки Сейфа")
    # was_setup: флоу первичной настройки — пароль Сейфа только что создан.
    was_setup = bool(context.user_data.get('vault_setup_pw'))
    for key in ('vault_put_mode', 'vault_batch', 'vault_migrate_ids',
                'vault_attempts', 'vault_setup_pw', 'vault_qs_data',
                'vault_batch_label',
                'vault_ack_mid', 'vault_ack_last', 'vault_q_warned'):
        context.user_data.pop(key, None)
    lines = []
    if ok_n:
        lines.append(f"✅ ЗАШИФРОВАНО И ЗАГРУЖЕНО: {ok_n} файл(ов).")
    else:
        lines.append("❌ Не удалось зашифровать/загрузить ни одного файла.")
    if _batch_label and ok_n:
        lines.append(f"🏷 Название загрузки: «{_batch_label}» — видно в «📦 Мои файлы».")
    if fail_n:
        lines.append(f"⚠️ Не удалось обработать: {fail_n} — попробуйте ещё раз позже.")
        # ВОЛНА 18: честные причины прямо в сообщении — раньше причина жила
        # только в логах Render, которые пользователь не читает.
        if fail_reasons:
            lines.append("")
            lines.append("Причины:")
            for _fr in fail_reasons[:3]:
                lines.append(f"• {_fr}")
            if len(fail_reasons) > 3:
                lines.append(f"• …и ещё {len(fail_reasons) - 3}")
            lines.append("")
            lines.append("Файлы, которые не зашифровались, ОСТАЛИСЬ в чате — "
                         "ничего не потеряно. Попробуйте ещё раз: 🔐 Сейф → "
                         "📥 Положить (файлы пришлите заново).")
    if migrated:
        lines.append(f"🗂 Старые незашифрованные копии удалены: {migrated} — теперь файлы только в Сейфе.")
    # ВОЛНА 19: «В канале только шифр / пароль стёрт / имена в шифрах» —
    # ТОЛЬКО когда реально зашифровался хоть один файл. Раньше блок печатался
    # и при полном провале: чат пустел, а текст обещал «данные только в
    # Сейфе», которого не было, — это выглядело как потеря данных.
    if ok_n:
        lines.append("")
        lines.append("• В канале теперь только шифр — без пароля его не откроет никто.")
        lines.append("• Пароль стёрт из чата и нигде не хранится.")
        lines.append("• Даже имена файлов спрятаны в шифрах.")
    if was_setup:
        if ok_n:
            lines.append("• Сейф настроен: пароль + 3 секретных вопроса сохранены.")
        else:
            lines.append("• Сейф настроен (пароль + 3 секретных вопроса сохранены), "
                         "но ни один файл не сохранился — положите их позже: "
                         "🔐 Сейф → 📥 Положить.")
    if ok_n:
        lines.append("")
        lines.append("🔑 Забыли пароль? 🔐 Сейф → «🔑 Забыл пароль» — восстановление по вашим вопросам.")
    # ВОЛНА 11: оригиналы успешно зашифрованных файлов стираем из чата —
    # «файл в памяти, в чат не попадёт» теперь буквально правда. Файлы, не
    # зашившиеся из-за сбоя, в чате ОСТАЮТСЯ (иначе пользователь их потеряет).
    # ВОЛНА 19: при НУЛЕВОМ успехе не стираем НИЧЕГО (ни файлы, ни подсказки,
    # ни след) — раньше зачистка запускалась всегда, и при полном провале
    # чат пустел, хотя в Сейфе не оказалось ни одного файла.
    if ok_n:
        _done_items = [it for it in batch if isinstance(it, dict) and it.get("done")]
        # ВОЛНА 12: оригиналы НЕзашифровавшихся файлов (сбой сети/канала) остают
        # в чате — политика волны 11 — и остаются в персистентном следе, чтобы
        # отменить/зачистить их позже можно было кнопкой отмены.
        _failed_ids = [it.get("chat_msg_id") for it in batch
                       if isinstance(it, dict) and not it.get("done") and it.get("chat_msg_id")]
        try:
            _cleaned = await _vault_cleanup_chat(context, msg.chat_id, _done_items,
                                                 user=user, keep_ids=_failed_ids)
        except Exception:
            _cleaned = 0
        if _cleaned:
            lines.append(f"🧹 Следов из чата стёрто: {_cleaned} (оригиналы зашифрованных файлов и подсказки) — данные только в Сейфе.")
    else:
        lines.append("")
        lines.append("🧹 Из чата ничего не стёрто — все ваши файлы и подсказки на месте.")
    await msg.reply_text("\n".join(lines), reply_markup=get_main_menu_keyboard(user))
    return MAIN_MENU


# ============================================================
# === ВОЛНА 22.25: РЕЖИМ «ФАЙЛЫ БЕЗ ШИФРОВАНИЯ» (личный канал) ===
# Пользователь просил: «Если пользователь захочет он может для своего канала
# сделать чтобы файлы не шифровались». Режим включается ТОЛЬКО пользователем
# и ТОЛЬКО для ЕГО личного канала («🔗 Моё облако» → 🔓 или мини-апп →
# Хранилище): новые загрузки Сейфа ложатся в канал КАК ЕСТЬ, с исходными
# именами, пароль не спрашивается ни при заливке, ни при выдаче. Файлы в
# записи помечены "plain": True — выдача для них идёт БЕЗ пароля. Уже
# зашифрованные файлы остаются под шифром. В ОБЩЕЕ хранилище бота
# незашифрованные файлы Сейфа не попадают НИКОГДА (нет личного канала —
# нет и режима).
# ============================================================

_PLAIN_CAP = "☁️ Файл Сейфа (режим «без шифра» — лежит в вашем канале как есть)."


async def _vault_plain_item_mtproto(msg, context, user, item,
                                    progress_msg, idx, total):
    """ВОЛНА 22.25: ОДИН большой файл (источник — сообщение в личном чате)
    в режиме «БЕЗ шифра»: оригинал перекачивается в личный канал КАК ЕСТЬ
    (без DVF2-контейнера). ≤48 МБ — Bot API, больше — MTProto.
    Возвращает запись user.vault_files; при сбое бросает исключение —
    оригинал остаётся в чате, чтобы пользователь его не потерял."""
    last_err = None
    for _attempt in (1, 2):
        try:
            return await _vault_plain_item_mtproto_once(
                msg, context, user, item, progress_msg, idx, total)
        except _VaultCancelled:
            raise  # отмену пользователя НЕ ретраим — это не сбой
        except Exception as e:
            last_err = e
            # ПОЛИТИКА ПДн 1.2: имя файла пользователя в лог не попадает.
            logger.error(f"vault plain: попытка {_attempt}/2 не удалась, "
                         f"user_id={getattr(user, 'user_id', '?')}: {e}")
            if _attempt == 1:
                await asyncio.sleep(5)
    raise last_err


async def _vault_plain_item_mtproto_once(msg, context, user, item,
                                         progress_msg, idx, total):
    """ВОЛНА 22.25: одна попытка перекачки большого файла без шифрования."""
    name = str(item.get("name") or "файл")
    kind = str(item.get("kind") or "document")
    mime = str(item.get("mime") or "")
    size = int(item.get("size", 0) or 0)
    mt = dict(item.get("mt_raw") or {})
    raw_ch = int(mt.get("peer_id") or mt.get("channel_id") or 0)
    raw_mid = int(mt.get("msg_id") or 0)
    if not raw_ch or not raw_mid:
        raise RuntimeError("источник файла потерян — пришлите файл ещё раз")
    small = 0 < size <= VAULT_MAX_FILE_BYTES
    client = await _mt_client()  # None — не приговор: ≤20 МБ пойдёт через Bot API
    doc = None
    mt_err = None
    if client is not None:
        try:
            _m, doc = await _mt_fetch_document(
                client, raw_ch, raw_mid, int(mt.get("ah") or 0))
        except Exception as e:
            mt_err = e
            logger.warning(f"vault plain: MTProto-источник не открылся ({e}); "
                           "пробую запасной путь Bot API/file_id")
    botapi_payload = None
    if doc is None:
        fid = str(item.get("file_id") or "")
        if fid and 0 < size <= VAULT_MAX_FILE_BYTES:
            try:
                botapi_payload = await _vault_botapi_download(context, fid)
            except Exception as e:
                logger.warning(f"vault plain: Bot API-скачивание не удалось: {e}")
        if botapi_payload is None:
            if client is None:
                raise RuntimeError(
                    "перекачка больших файлов сейчас недоступна на сервере: "
                    f"{_mt_unavailable_reason()}"
                    + ("" if small else
                       " — файл больше 20 МБ, без потока его не взять; "
                       "повторите позже или пришлите файл заново"))
            if mt_err is not None:
                raise mt_err
            raise RuntimeError(
                "файл исчез из чата (сообщение удалено?) — пришлите файл ещё раз")
    _op_here = _VAULT_OPS.get(str(getattr(user, "user_id", "") or ""))
    if _op_here is not None:
        _op_here["phase"] = f"Файл {idx}/{total}: «{name}»"
        if _op_here["event"].is_set():
            raise _VaultCancelled()
    prog = _VaultSubProg(_op_here, f"📦 [{idx}/{total}] «{name}»")
    up = None
    if botapi_payload is not None:
        # Оригинал уже в памяти (Bot API) — заливаем как есть.
        if _op_here is not None and _op_here["event"].is_set():
            raise _VaultCancelled()
        up = await _storage_upload_document(
            context, botapi_payload, filename=name, caption=_PLAIN_CAP,
            user=user)
        botapi_payload = b""
    else:
        doc_size = int(getattr(doc, "size", 0) or size or 0)
        if not _dvf2_disk_ok(doc_size):
            raise RuntimeError("мало свободного места на диске сервера")
        job = _dvf2_make_job_dir()
        if _op_here is not None:
            _op_here["temp"].append(job)  # при отмене сотрём
        try:
            tmp_raw = os.path.join(job, "original.bin")
            if _op_here is not None:
                _op_here["sub"] = f"📦 [{idx}/{total}] «{name}»: качаю…"
            with open(tmp_raw, "wb") as fh:
                def _sink(chunk):
                    if _op_here is not None and _op_here["event"].is_set():
                        raise _VaultCancelled()
                    fh.write(chunk)
                await _mt_download_stream(client, doc, doc_size, _sink, prog,
                                          f"📦 [{idx}/{total}] «{name}»: качаю",
                                          cancel_check=lambda: bool(
                                              _op_here and _op_here["event"].is_set()))
            raw_size = doc_size or os.path.getsize(tmp_raw)
            if _op_here is not None:
                _op_here["sub"] = f"📦 [{idx}/{total}] «{name}»: заливаю в канал…"
            if raw_size <= (49 * 1024 * 1024 - 1024 * 1024):
                with open(tmp_raw, "rb") as fh:
                    raw_bytes = fh.read()
                try:
                    up = await _storage_upload_document(
                        context, raw_bytes, filename=name, caption=_PLAIN_CAP,
                        user=user)
                finally:
                    raw_bytes = b""
                # Bot API отказал — ≤48 МБ можно залить и MTProto.
                if up is None and _TELETHON_OK and BOT_TOKEN:
                    if _op_here is not None and _op_here["event"].is_set():
                        raise _VaultCancelled()
                    up = await _mt_upload_container(
                        client, tmp_raw, raw_size,
                        caption=_PLAIN_CAP, filename=name,
                        progress_cb=(lambda cur, tot: prog.sync_bar(cur, tot, "📤 Заливаю"))
                        if _op_here is not None else None, user=user)
            else:
                up = await _mt_upload_container(
                    client, tmp_raw, raw_size,
                    caption=_PLAIN_CAP, filename=name,
                    progress_cb=(lambda cur, tot: prog.sync_bar(cur, tot, "📤 Заливаю"))
                    if _op_here is not None else None, user=user)
        finally:
            try:
                _shutil.rmtree(job, ignore_errors=True)
            except Exception:
                pass
    if up is None:
        raise RuntimeError(
            "файл не принят каналом — проверьте, что бот администратор "
            "вашего канала-хранилища")
    if _op_here is not None:
        try:
            _op_here["sent"].append(
                (int(up.get("channel_id") or get_storage_channel_id() or 0),
                 int(up.get("message_id") or 0)))
        except (TypeError, ValueError):
            pass
    rec = {
        "id": _vault_gen_id(user),
        "kind": kind, "mime": mime,
        "ts": _file_ts_now(), "tss": datetime.now().strftime("%Y-%m-%d %H:%M"),
        "size_orig": size or int(up.get("size", 0) or 0),
        "size_enc": int(up.get("size", 0) or 0),
        "msg_id": int(up.get("message_id", 0)),
        "file_id": up.get("file_id"),
        "channel_id": up.get("channel_id"),
        # ВОЛНА 22.25: исходное имя хранится В ЗАПИСИ (оно не секрет —
        # режим «без шифра»), пометка plain — выдача без пароля.
        "name": name[:120],
        "plain": True,
    }
    _stat_bump("vault_upload")
    # Источник (сообщение в личном чате) стираем ТОЛЬКО при успехе.
    item.pop("mt_raw", None)
    if raw_ch and raw_mid:
        try:
            await context.bot.delete_message(chat_id=raw_ch, message_id=raw_mid)
        except Exception:
            pass
    return rec


async def _vault_plain_upload(msg, context, user, note=""):
    """ВОЛНА 22.25: заливка пачки Сейфа в ЛИЧНЫЙ канал БЕЗ шифрования.
    Зеркало _vault_encrypt_batch (та же живая анимация, честная отмена 22.3,
    миграция старых файлов, чистка чата), но: без пароля, без _vault_pack —
    файлы уходят КАК ЕСТЬ с исходными именами, записи помечаются "plain".
    Возвращает состояние для ConversationHandler."""
    batch = context.user_data.get('vault_batch') or []
    _batch_label = str(context.user_data.get('vault_batch_label') or "").strip()[:80]
    _uch = _user_vault_channel(user)
    if not _uch:
        # Честный предохранитель: режим без личного канала невозможен.
        context.user_data.pop('vault_put_mode', None)
        context.user_data.pop('vault_batch', None)
        await msg.reply_text(
            "❌ Режим «без шифра» работает только с ВАШИМ каналом, а он не "
            "подключён — незашифрованные файлы в общее хранилище бота я не "
            "принимаю. Подключите канал: 🔐 Сейф → 🔗 Моё облако.",
            reply_markup=get_main_menu_keyboard(user))
        return MAIN_MENU
    op = _vault_op_begin(getattr(user, "user_id", "") or "", len(batch))
    op["phase"] = "Заливаю БЕЗ ШИФРА"
    progress = None
    anim = None
    try:
        progress = await msg.reply_text(
            f"{note}☁️ Заливаю в ваш канал (БЕЗ шифра) 0/{len(batch)} "
            f"{_VAULT_OP_FRAMES[0]}")
    except Exception:
        progress = None
    if progress is not None:
        anim = asyncio.create_task(_vault_animate_progress(context, progress, op))
    files = [f for f in (getattr(user, "vault_files", []) or []) if isinstance(f, dict)]
    ok_n, fail_n = 0, 0
    fail_reasons = []
    cancelled = False
    try:
        for i, item in enumerate(batch, 1):
            if op["event"].is_set():
                raise _VaultCancelled()
            op["done"] = i - 1
            op["sub"] = f"«{(item.get('name') or 'файл')}»: готовлю…"
            if item.get("source") == "mtproto":
                try:
                    rec_mt = await _vault_plain_item_mtproto(
                        msg, context, user, item, progress, i, len(batch))
                except _VaultCancelled:
                    raise
                except Exception as e:
                    logger.error(
                        f"vault plain: большой файл, "
                        f"user_id={getattr(user, 'user_id', '?')}: {e}")
                    rec_mt = None
                    fail_reasons.append(
                        f"«{(item.get('name') or 'файл')}»: {_vault_fail_reason(e)}")
                if rec_mt is None:
                    fail_n += 1
                    continue
                rec_mt["label"] = _vault_item_label(item, _batch_label)
                rec_mt["cat"] = (context.user_data.get('vault_batch_cat')
                                 or _vault_cat_by_kind(item.get("kind"),
                                                       item.get("mime")))
                rec_mt["tags"] = list(context.user_data.get('vault_batch_tags') or [])
                files.append(rec_mt)
                ok_n += 1
                op["done"] = i
                op["sub"] = ""
                item["done"] = True
                continue
            # Обычный файл/заметка: payload уже в памяти — заливаем как есть.
            payload = item.get("payload") or b""
            name = str(item.get("name") or f"file_{i}.bin")
            if op["event"].is_set():
                raise _VaultCancelled()
            op["sub"] = f"«{(item.get('name') or 'файл')}»: заливаю…"
            up = await _storage_upload_document(
                context, payload, filename=name, caption=_PLAIN_CAP, user=user)
            if up is None:
                # Одна повторная попытка Bot API (одноразовые сбои бывают),
                # затем MTProto-заливка, если поднят.
                if op["event"].is_set():
                    raise _VaultCancelled()
                up = await _storage_upload_document(
                    context, payload, filename=name, caption=_PLAIN_CAP, user=user)
                if up is None and _TELETHON_OK and BOT_TOKEN:
                    _mtc = await _mt_client()
                    if _mtc is not None:
                        _updir = _tempfile.mkdtemp(prefix="dvf1_up_")
                        op["temp"].append(_updir)
                        try:
                            _uppath = os.path.join(_updir, name)
                            with open(_uppath, "wb") as _ufh:
                                _ufh.write(payload)
                            up = await _mt_upload_container(
                                _mtc, _uppath, len(payload),
                                caption=_PLAIN_CAP, filename=name, user=user)
                        finally:
                            _shutil.rmtree(_updir, ignore_errors=True)
            item["payload"] = b""  # исходник больше не нужен
            if up is None:
                fail_n += 1
                fail_reasons.append(
                    f"«{(item.get('name') or 'файл')}»: канал не принял файл — "
                    "проверьте, что бот администратор вашего канала")
                continue
            try:
                op["sent"].append((int(up.get("channel_id") or _uch[0] or 0),
                                   int(up.get("message_id") or 0)))
            except (TypeError, ValueError):
                pass
            files.append({
                "id": _vault_gen_id(user),
                "kind": item.get("kind", "document"),
                "mime": item.get("mime", ""),
                "ts": _file_ts_now(), "tss": datetime.now().strftime("%Y-%m-%d %H:%M"),
                "size_orig": int(item.get("size", 0) or 0),
                "size_enc": int(up.get("size", 0) or 0),
                "msg_id": int(up.get("message_id", 0)),
                "file_id": up.get("file_id"),
                "channel_id": up.get("channel_id"),
                "name": name[:120],
                "plain": True,
                "label": _vault_item_label(item, _batch_label),
                "cat": (context.user_data.get('vault_batch_cat')
                        or _vault_cat_by_kind(item.get("kind"),
                                              item.get("mime"))),
                "tags": list(context.user_data.get('vault_batch_tags') or []),
            })
            _stat_bump("vault_upload")
            ok_n += 1
            op["done"] = i
            op["sub"] = ""
            item["done"] = True
    except _VaultCancelled:
        cancelled = True
    finally:
        if anim is not None:
            anim.cancel()
            try:
                await anim
            except (asyncio.CancelledError, Exception):
                pass
        _vault_op_end(getattr(user, "user_id", "") or "")
    if cancelled:
        deleted = await _vault_cancel_cleanup(context, op)
        if progress is not None:
            try:
                await context.bot.edit_message_text(
                    "⛔ Остановлено",
                    chat_id=progress.chat_id, message_id=progress.message_id)
            except Exception:
                pass
        for key in ('vault_put_mode', 'vault_batch', 'vault_migrate_ids',
                    'vault_attempts', 'vault_setup_pw', 'vault_qs_data',
                    'vault_batch_label',
                    'vault_ack_mid', 'vault_ack_last', 'vault_q_warned'):
            context.user_data.pop(key, None)
        await msg.reply_text(
            "⛔ Остановлено по вашему «❌ Отмена».\n\n"
            f"• Заливка прервана: обработано {op.get('done', 0)}/{op.get('total', 0)}.\n"
            f"• Из канала стёрто файлов этой загрузки: {deleted}.\n"
            "• Временные файлы стёрты с сервера.\n"
            "• Исходные файлы ОСТАЛИСЬ в чате — ничего не потеряно.\n\n"
            "Положить заново: 🔐 Сейф → 📥 Положить.",
            reply_markup=get_main_menu_keyboard(user))
        return MAIN_MENU
    user.vault_files = files
    migrated = 0
    migrate_ids = context.user_data.get('vault_migrate_ids') or []
    if migrate_ids:
        cloud_recs = [f for f in (getattr(user, "cloud_files", []) or []) if isinstance(f, dict)]
        for mid in migrate_ids:
            rec = next((r for r in cloud_recs if r.get("id") == mid), None)
            if not rec:
                continue
            ch = rec.get("channel_id") or get_storage_channel_id()
            if ch and rec.get("msg_id"):
                try:
                    await context.bot.delete_message(chat_id=ch, message_id=int(rec["msg_id"]))
                except Exception:
                    pass
            cloud_recs = [r for r in cloud_recs if r.get("id") != mid]
            migrated += 1
        if migrated:
            user.cloud_files = cloud_recs
    save_user(user)
    _vault_flush_soon(context, reason="заливка пачки Сейфа (без шифра)")
    for key in ('vault_put_mode', 'vault_batch', 'vault_migrate_ids',
                'vault_attempts', 'vault_setup_pw', 'vault_qs_data',
                'vault_batch_label',
                'vault_ack_mid', 'vault_ack_last', 'vault_q_warned'):
        context.user_data.pop(key, None)
    lines = []
    if ok_n:
        lines.append(f"✅ СОХРАНЕНО В ВАШ КАНАЛ (БЕЗ ШИФРА): {ok_n} файл(ов).")
    else:
        lines.append("❌ Не удалось загрузить ни одного файла.")
    if _batch_label and ok_n:
        lines.append(f"🏷 Название загрузки: «{_batch_label}» — видно в «📦 Мои файлы».")
    if fail_n:
        lines.append(f"⚠️ Не удалось обработать: {fail_n} — попробуйте ещё раз позже.")
        if fail_reasons:
            lines.append("")
            lines.append("Причины:")
            for _fr in fail_reasons[:3]:
                lines.append(f"• {_fr}")
            if len(fail_reasons) > 3:
                lines.append(f"• …и ещё {len(fail_reasons) - 3}")
            lines.append("")
            lines.append("Файлы, которые не ушли, ОСТАЛИСЬ в чате — ничего "
                         "не потеряно. Попробуйте ещё раз: 🔐 Сейф → 📥 Положить.")
    if ok_n:
        lines.append("")
        lines.append("• Файлы лежат в вашем канале КАК ЕСТЬ, с исходными именами — "
                     "их видно всем, у кого есть доступ к каналу.")
        lines.append("• Достаю их по кнопке файла в «📦 Мои файлы» — БЕЗ пароля.")
        lines.append("• Уже зашифрованные ранее файлы остались под шифром.")
        lines.append("")
        lines.append("🔒 Передумали? 🔐 Сейф → 🔗 Моё облако → «🔒 Включить "
                     "шифрование файлов» — вернёт шифрование для новых загрузок.")
    if migrated:
        lines.append(f"🗂 Старая незашифрованная копия в общем хранилище удалена: {migrated}.")
    if ok_n:
        _done_items = [it for it in batch if isinstance(it, dict) and it.get("done")]
        _failed_ids = [it.get("chat_msg_id") for it in batch
                       if isinstance(it, dict) and not it.get("done") and it.get("chat_msg_id")]
        try:
            _cleaned = await _vault_cleanup_chat(context, msg.chat_id, _done_items,
                                                 user=user, keep_ids=_failed_ids)
        except Exception:
            _cleaned = 0
        if _cleaned:
            lines.append(f"🧹 Следов из чата стёрто: {_cleaned}.")
    else:
        lines.append("")
        lines.append("🧹 Из чата ничего не стёрто — все ваши файлы и подсказки на месте.")
    await msg.reply_text("\n".join(lines), reply_markup=get_main_menu_keyboard(user))
    return MAIN_MENU


async def _vault_get_plain(msg, context, user, rec):
    """ВОЛНА 22.25: выдача файла, хранящегося БЕЗ шифра, — пароль НЕ нужен.
    ≤20 МБ с file_id — Bot API; иначе MTProto (качаем во временник и отдаём:
    ≤49 МБ — Bot API документом, больше — MTProto прямо в чат, как DVF2)."""
    channel_id = rec.get("channel_id") or get_storage_channel_id()
    mid = int(rec.get("msg_id") or 0)
    name = str(rec.get("name") or rec.get("label") or f"vault_{rec.get('id', 'file')}.bin")
    _lbl = str(rec.get("label") or "").strip()
    cap = (f"🔓 {_lbl} — {name}" if _lbl
           else f"🔓 Файл из Сейфа (хранится без шифра): {name}")
    size = int(rec.get("size_orig") or rec.get("size_enc") or 0)
    fid = rec.get("file_id")
    app_bot = context.bot
    # Путь 1: Bot API (быстрый).
    if fid and 0 < size <= VAULT_MAX_FILE_BYTES:
        try:
            await app_bot.send_chat_action(chat_id=msg.chat_id, action="upload_document")
            tg_file = await app_bot.get_file(fid)
            buf = io.BytesIO()
            await asyncio.wait_for(tg_file.download_to_memory(out=buf), timeout=120)
            payload = buf.getvalue()
            _sent_msg = await app_bot.send_document(
                chat_id=msg.chat_id, document=InputFile(payload, filename=name),
                caption=cap,
            )
            try:
                sent_mid = int(getattr(_sent_msg, "message_id", 0) or 0)
            except (TypeError, ValueError):
                sent_mid = 0
            if sent_mid:
                await _vault_offer_wipe(
                    context, msg.chat_id, sent_mid,
                    wipe_enabled=bool(getattr(user, "vault_wipe_on_cancel", True)),
                    user=user)
            else:
                await msg.reply_text("✅ Готово.")
            return MAIN_MENU
        except Exception as e:
            logger.warning(f"vault get plain: Bot API не отдал файл ({e}); пробую MTProto")
    # Путь 2: MTProto.
    client = await _mt_client()
    if client is None:
        await msg.reply_text(
            "❌ Файл сейчас недоступен: " + (_MT_LAST_ERR or "MTProto не подключён")
            + ". Попробуйте позже.",
            reply_markup=get_main_menu_keyboard(user))
        return MAIN_MENU
    if not channel_id or not mid:
        await msg.reply_text(
            "❌ Файл недоступен: он лежал в канале, который больше не "
            "подключён, либо указатель потерян.",
            reply_markup=get_main_menu_keyboard(user))
        return MAIN_MENU
    try:
        _m, doc = await _mt_fetch_document(client, int(channel_id), mid)
    except Exception as e:
        logger.error(f"vault get plain: не удалось открыть файл: {e}")
        doc = None
    if doc is None:
        await msg.reply_text(
            "❌ Не смог скачать файл из канала. Возможно, сообщение в канале "
            "удалено вручную.",
            reply_markup=get_main_menu_keyboard(user))
        return MAIN_MENU
    doc_size = int(getattr(doc, "size", 0) or size or 0)
    if not _dvf2_disk_ok(doc_size):
        await msg.reply_text(
            f"❌ На диске сервера сейчас меньше свободного места, чем нужно "
            f"для файла ({_fmt_bytes(doc_size)}). Место освобождается после "
            "перезапуска бота — попробуйте позже.",
            reply_markup=get_main_menu_keyboard(user))
        return MAIN_MENU
    op = _vault_op_begin(getattr(user, "user_id", "") or "", 1, kind="get")
    op["phase"] = "Качаю файл"
    progress_msg = None
    try:
        progress_msg = await msg.reply_text(
            "📤 Качаю файл из вашего канала… 0%\n⏳ Не прерываю — загрузка "
            "спокойно дойдёт до конца.")
    except Exception:
        progress_msg = None
    prog = _ProgressEdit(context, progress_msg, "📤 Качаю файл из вашего канала")
    job = _dvf2_make_job_dir()
    op["temp"].append(job)
    err_text = None
    cancelled = False
    sent_mid = 0
    try:
        out_path = os.path.join(job, name)
        with open(out_path, "wb") as fh:
            def _sink(chunk):
                if op["event"].is_set():
                    raise _VaultCancelled()
                fh.write(chunk)
            await _mt_download_stream(
                client, doc, doc_size, _sink, prog,
                "📤 Качаю файл из вашего канала",
                cancel_check=lambda: op["event"].is_set())
        real_size = os.path.getsize(out_path)
        if op["event"].is_set():
            raise _VaultCancelled()
        try:
            await context.bot.send_chat_action(
                chat_id=msg.chat_id, action="upload_document")
        except Exception:
            pass
        op["phase"] = "Отправляю файл"
        await _ProgressEdit(context, progress_msg, "").edit(
            "📤 Отправляю файл… 0%", force=True)
        if real_size <= (49 * 1024 * 1024 - 1024 * 1024):
            with open(out_path, "rb") as fh:
                _sent_msg = await context.bot.send_document(
                    chat_id=msg.chat_id,
                    document=InputFile(fh, filename=name),
                    caption=cap,
                )
            sent_mid = int(getattr(_sent_msg, "message_id", 0) or 0)
        else:
            _sent = await _mt_send_file_to_user(
                client, msg.chat_id, out_path, real_size, cap,
                context, progress_msg or msg,
                cancel_check=lambda: op["event"].is_set())
            sent_mid = int(getattr(_sent, "id", 0) or 0)
    except _VaultCancelled:
        cancelled = True
    except Exception as e:
        logger.error(f"vault get plain: выдача не удалась: {e}")
        err_text = "сбой при перекачке файла"
    finally:
        try:
            _shutil.rmtree(job, ignore_errors=True)
        except Exception:
            pass
        _vault_op_end(getattr(user, "user_id", "") or "")
    if cancelled:
        if progress_msg is not None:
            try:
                await context.bot.edit_message_text(
                    "⛔ Отменено — перекачка остановлена, временные файлы "
                    "стёрты. Файл в вашем канале цел.",
                    chat_id=progress_msg.chat_id,
                    message_id=progress_msg.message_id)
            except Exception:
                pass
        await msg.reply_text(
            "Отменено.", reply_markup=get_main_menu_keyboard(user))
        return MAIN_MENU
    if err_text is not None:
        await msg.reply_text(
            f"❌ Передать файл не удалось: {err_text}. Попробуйте ещё раз.",
            reply_markup=get_main_menu_keyboard(user))
        return MAIN_MENU
    if progress_msg is not None:
        try:
            await context.bot.edit_message_text(
                "✅ Файл отправлен ниже.",
                chat_id=progress_msg.chat_id,
                message_id=progress_msg.message_id)
        except Exception:
            pass
    if sent_mid:
        await _vault_offer_wipe(
            context, msg.chat_id, sent_mid,
            wipe_enabled=bool(getattr(user, "vault_wipe_on_cancel", True)),
            user=user)
    else:
        await msg.reply_text("✅ Готово.")
    return MAIN_MENU


async def vault_get_start(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Выбор файла для скачивания: список без имён (zero-knowledge)."""
    query = update.callback_query
    await query.answer()
    user = get_user(str(query.from_user.id))
    if not user:
        await query.answer("Сначала зарегистрируйтесь — /start", show_alert=True)
        return MAIN_MENU
    text = _vault_files_text(user)
    try:
        await query.edit_message_text(text, reply_markup=get_vault_files_keyboard(user))
    except Exception:
        await query.message.reply_text(text, reply_markup=get_vault_files_keyboard(user))
    return MAIN_MENU


async def vault_get_password_start(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await query.answer()
    user = get_user(str(query.from_user.id))
    if not user:
        await query.answer("Сначала зарегистрируйтесь — /start", show_alert=True)
        return MAIN_MENU
    vid = query.data.replace("vault_get_", "", 1)
    rec = _vault_find_record(user, vid)
    if not rec:
        await query.answer("Файл не найден.", show_alert=True)
        return MAIN_MENU
    # ВОЛНА 22.25: файл режима «БЕЗ шифра» — пароль не нужен и не существует:
    # честно выдаём сразу (то же окно прогресса, что у больших файлов).
    if rec.get("plain"):
        return await _vault_get_plain(query.message, context, user, rec)
    context.user_data['vault_get_id'] = vid
    context.user_data['vault_attempts'] = 0
    await query.message.reply_text(
        "🔑 Введите пароль этого файла. Попыток: "
        f"{VAULT_ATTEMPTS_MAX} (пароль сотрётся из чата).",
        reply_markup=_vault_dialog_kb(),
    )
    return VAULT_GET_PASSWORD


@timeout(CONVERSATION_TIMEOUT)
async def vault_get_password(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Скачивает шифр из канала, расшифровывает В ПАМЯТИ и отдаёт файл.

    Ничего не пишется на диск; пароль сразу стирается из чата и user_data.
    Также обслуживает:
    • ШАГ 1 смены пароля файла (vault_chp_stage == "old");
    • ШАГ 1 смены секретных вопросов (vault_qs_stage == "auth", волна 9);
    • команду «восстановить» — переход к восстановлению по вопросам (волна 9)."""
    msg = update.message
    # ВОЛНА 22.5/22.9: прямо сейчас идёт операция Сейфа. ЗАЛИВКА (kind="put")
    # останавливается флагом — как в 22.3. ВЫДАЧА (kind="get") НЕ прерывается
    # никогда — требование пользователя: «если еще загружается то загрузка
    # должна закончиться»; зачистку сделает сам процесс по завершении.
    _uid_now = str(update.effective_user.id)
    if _vault_op_running(_uid_now):
        if str((_VAULT_OPS.get(_uid_now) or {}).get("kind") or "put") == "put":
            _VAULT_OPS[_uid_now]["event"].set()
            await msg.reply_text(
                "⛔ Останавливаю шифрование/загрузку — секунду, подчищу всё "
                "недогруженное…")
            return VAULT_GET_PASSWORD
        await msg.reply_text(
            "⏳ Отмена принята — выдачу не прерываю: загрузка спокойно "
            "дойдёт до конца. Как только файл будет выдан, я сам удалю "
            "его из чата (или оставлю — смотря что у вас в ⚙️ Настройках) "
            "и верну вас в главное меню.")
        try:
            _VAULT_OPS[_uid_now]["cancel_after"] = True  # 22.10
        except Exception:
            pass
        return VAULT_GET_PASSWORD
    user = get_user(str(update.effective_user.id))
    if not user:
        await msg.reply_text("Сначала зарегистрируйтесь — отправьте /start.")
        return MAIN_MENU
    # ВОЛНА 9: смена секретных вопросов, шаг 1 — проверка пароля Сейфа.
    qs_stage = context.user_data.get('vault_qs_stage')
    if qs_stage == "auth":
        return await _vault_qs_auth_password(update, context, user)
    vid = context.user_data.get('vault_get_id')
    chp_stage = context.user_data.get('vault_chp_stage')
    chp_id = context.user_data.get('vault_chp_id')
    # ВОЛНА 9: пользователь забыл пароль прямо на вводе — не мучаем его.
    _typed = (msg.text or "").strip().lower()
    if _typed in ("восстановить", "восстановление", "забыл", "забыла", "забыл пароль"):
        for key in ('vault_get_id', 'vault_attempts'):
            context.user_data.pop(key, None)
        return await _vault_rec_begin(msg, context, user)
    if not vid and chp_stage != "old":
        await msg.reply_text(
            "Сессия потеряна. Начните заново: 🔐 Сейф → 📦 Мои файлы.",
        )
        return MAIN_MENU
    if chp_stage == "old" and chp_id:
        rec = _vault_find_record(user, chp_id)
    else:
        rec = _vault_find_record(user, vid) if vid else None
    if rec is None:
        for key in ('vault_get_id', 'vault_attempts', 'vault_chp_id', 'vault_chp_stage'):
            context.user_data.pop(key, None)
        await msg.reply_text("Файл не найден (уже удалён?).")
        return MAIN_MENU
    # ВОЛНА 22.25: страховка — если файл стал «без шифра», пока пользователь
    # сидел в ожидании пароля, пароль не нужен: выдаём сразу.
    if chp_stage != "old" and rec.get("plain"):
        context.user_data.pop('vault_get_id', None)
        context.user_data.pop('vault_attempts', None)
        return await _vault_get_plain(msg, context, user, rec)
    password = (msg.text or "").strip()
    try:
        await context.bot.delete_message(chat_id=msg.chat_id, message_id=msg.message_id)
    except Exception:
        pass
    _pw_low = password.lower().strip()
    if _pw_low in ("отмена", "cancel", "/cancel", "❌ отмена", "❌ отменить") or "отмена" in _pw_low or "cancel" in _pw_low:
        for key in ('vault_get_id', 'vault_attempts', 'vault_chp_id', 'vault_chp_stage', 'vault_chp_old'):
            context.user_data.pop(key, None)
        # ВОЛНА 12: заодно гасим персистентный след (если был).
        try:
            await _vault_cleanup_chat(context, msg.chat_id, None, user=user)
        except Exception:
            pass
        await msg.reply_text("Отменено.", reply_markup=get_main_menu_keyboard(user))
        return MAIN_MENU
    attempts = int(context.user_data.get('vault_attempts', 0) or 0)
    if not _vault_check_password(user, rec, password):
        attempts += 1
        context.user_data['vault_attempts'] = attempts
        if attempts >= VAULT_ATTEMPTS_MAX:
            for key in ('vault_get_id', 'vault_attempts', 'vault_chp_id', 'vault_chp_stage'):
                context.user_data.pop(key, None)
            await msg.reply_text(
                f"🚫 Пароль не подошёл {VAULT_ATTEMPTS_MAX} раза. Операция прервана "
                "— файл остался в шифре. Проверьте пароль и попробуйте позже.",
                reply_markup=get_main_menu_keyboard(user),
            )
            return MAIN_MENU
        _hint = ""
        auth = getattr(user, "vault_auth", None)
        if _vault_auth_valid(user) and (auth or {}).get("rec"):
            _hint = (" Забыли? Отправьте «восстановить» — верну доступ по "
                     "вашим секретным вопросам.")
        await msg.reply_text(
            f"❌ Неверный пароль (попытка {attempts} из {VAULT_ATTEMPTS_MAX}). "
            "Попробуйте ещё раз или отправьте «отмена»." + _hint
        )
        return VAULT_GET_PASSWORD
    # ШАГ 1 смены пароля пройден: запоминаем старый пароль и просим новый.
    if chp_stage == "old" and chp_id:
        context.user_data['vault_chp_old'] = password
        context.user_data['vault_chp_stage'] = "new"
        context.user_data.pop('vault_attempts', None)
        await msg.reply_text(
            "✅ Старый пароль верный — шаг 2: введите НОВЫЙ пароль (минимум "
            f"{VAULT_MIN_PASSWORD} символов). Файл будет перешифрован, а старый "
            "шифр стёрт из канала.",
        )
        return VAULT_CHPASS_NEW
    # ВОЛНА 14: большой файл (>20 МБ, DVF2) — потоковый путь через MTProto.
    # Обязателен ДО Bot API-пути: тот ограничен 20 МБ и не умеет контейнеры
    # без file_id (большие шифры заливаются только MTProto).
    # Пароль подтверждён — выдача началась (счётчик статистики).
    _stat_bump("vault_get")
    if rec.get("dvf2"):
        return await _vault_get_dvf2(msg, context, user, rec, password)
    # Пароль верный: скачиваем шифр из канала (в память).
    channel_id = rec.get("channel_id") or get_storage_channel_id()
    file_id = rec.get("file_id")
    if not channel_id or not file_id:
        await msg.reply_text(
            "❌ Шифр недоступен: файл лежал в канале, который больше не "
            "подключён, либо указатель потерян.",
            reply_markup=get_main_menu_keyboard(user),
        )
        return MAIN_MENU
    try:
        await context.bot.send_chat_action(chat_id=msg.chat_id, action="upload_document")
        tg_file = await context.bot.get_file(file_id)
        buf = io.BytesIO()
        await asyncio.wait_for(tg_file.download_to_memory(out=buf), timeout=120)
        container = buf.getvalue()
    except Exception as e:
        logger.error(f"vault get: не удалось скачать шифр: {e}")
        await msg.reply_text(
            "❌ Не смог скачать шифр из канала. Возможно, сообщение в канале "
            "удалено вручную.",
            reply_markup=get_main_menu_keyboard(user),
        )
        return MAIN_MENU
    try:
        meta, payload = await asyncio.to_thread(_vault_unpack, password, container)
    except ValueError as e:
        context.user_data.pop('vault_get_id', None)
        context.user_data.pop('vault_attempts', None)
        await msg.reply_text(
            f"❌ Расшифровать не удалось: {e}. Если забыли пароль — файл "
            "открыть нельзя (запасного ключа не существует).",
            reply_markup=get_main_menu_keyboard(user),
        )
        return MAIN_MENU
    finally:
        container = b""
    context.user_data.pop('vault_get_id', None)
    context.user_data.pop('vault_attempts', None)
    name = str(meta.get("n") or f"vault_{vid}.bin")
    kind = str(meta.get("k") or "document")
    _lbl = str(rec.get("label") or "").strip()
    caption = (f"🔓 {_lbl} — {name}" if _lbl else f"🔓 Расшифровано: {name}")
    _sent_msg = None
    try:
        # ВОЛНА 22.19 (C.2): выдача ВСЕГДА ДОКУМЕНТОМ. Telegram пережимает
        # ТОЛЬКО фото/видео, отправленные как медиа; документ уходит
        # байт-в-байт — ровно тот файл, что был зашифрован. Раньше фото и
        # видео загружались обратно как медиа, Telegram сжимал их на сервере
        # ПОВТОРНО — отсюда «после облака качество чуть хуже». Большие файлы
        # (DVF2, >20 МБ) и так уходят документом (force_document=True).
        _sent_msg = await context.bot.send_document(
            chat_id=msg.chat_id, document=InputFile(payload, filename=name),
            caption=caption,
        )
    except Exception as e:
        logger.error(f"vault get: выдача файла не удалась: {e}")
        await msg.reply_text("❌ Не удалось отправить файл. Попробуйте ещё раз.")
        return MAIN_MENU
    finally:
        payload = b""
    # ВОЛНА 22.6: после выдачи — кнопка «❌ Отменить» с подсказкой:
    # отмена после распаковки = файл исчезает из чата (прописано в боте).
    if _sent_msg is not None and getattr(_sent_msg, "message_id", None):
        await _vault_offer_wipe(
            context, msg.chat_id, _sent_msg.message_id,
            wipe_enabled=bool(getattr(user, "vault_wipe_on_cancel", True)),
            user=user)
    else:
        await msg.reply_text("✅ Готово. Файл расшифрован только что и только для вас.")
    return MAIN_MENU


# ============================================================
# === ВОЛНА 12: ПОДПИСЬ ФАЙЛА СЕЙФА (✏️ в списке «Мои файлы») ===
# ============================================================

async def vault_ren_cb(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """ВОЛНА 12: кнопка «✏️» у файла в списке Сейфа — задать/изменить подпись.
    Подпись видна в списке открытым текстом — чтобы не запутаться, где что."""
    query = update.callback_query
    await query.answer()
    user = get_user(str(query.from_user.id))
    if not user:
        await query.answer("Сначала зарегистрируйтесь — /start", show_alert=True)
        return MAIN_MENU
    vid = query.data.replace("vault_ren_", "", 1)
    rec = _vault_find_record(user, vid)
    if not rec:
        await query.answer("Файл не найден.", show_alert=True)
        return MAIN_MENU
    context.user_data['vault_ren_id'] = vid
    await query.message.reply_text(
        "✏️ Пришлите КОРОТКУЮ ПОДПИСЬ для файла — она будет видна в списке "
        "Сейфа (например «Фото контрольной», «Документы на кружок»). "
        "Сам файл и его настоящее имя останутся под шифром.\n\n"
        "Выйти — «❌ Отмена».",
        reply_markup=_vault_dialog_kb(),
    )
    return VAULT_REN_WAIT


@timeout(CONVERSATION_TIMEOUT)
async def vault_ren_save(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """ВОЛНА 12: сохранение подписи файла Сейфа."""
    msg = update.message
    user = get_user(str(update.effective_user.id))
    vid = context.user_data.get('vault_ren_id')
    if not user or not vid:
        await msg.reply_text("Сессия потеряна. Начните заново: 🔐 Сейф → 📦 Мои файлы.")
        return MAIN_MENU
    rec = _vault_find_record(user, vid)
    text = (msg.text or "").strip()
    low = text.lower()
    if low in ("отмена", "cancel", "/cancel", "❌ отмена", "❌ отменить") or "отмена" in low or "cancel" in low:
        context.user_data.pop('vault_ren_id', None)
        await msg.reply_text("Отменено — подпись не менялась.",
                             reply_markup=get_main_menu_keyboard(user))
        return MAIN_MENU
    if not text:
        await msg.reply_text("Пришлите текст подписи одним сообщением (или «отмена»).")
        return VAULT_REN_WAIT
    if rec is None:
        context.user_data.pop('vault_ren_id', None)
        await msg.reply_text("Файл не найден (уже удалён?).")
        return MAIN_MENU
    rec["label"] = text[:80]
    user.vault_files = [
        f for f in (getattr(user, "vault_files", []) or []) if isinstance(f, dict)
    ]
    save_user(user)
    context.user_data.pop('vault_ren_id', None)
    await msg.reply_text(
        f"✏️ Подпись сохранена: «{rec['label']}». Теперь в списке Сейфа видно, "
        "где что лежит.",
        reply_markup=get_main_menu_keyboard(user),
    )
    return MAIN_MENU


# ============================================================
# === ВОЛНА 9: ВОССТАНОВЛЕНИЕ ПО СЕКРЕТНЫМ ВОПРОСАМ + СМЕНА ВОПРОСОВ ===
# ============================================================

async def vault_rec_cb(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """ВОЛНА 9: кнопка «🔑 Забыл пароль (восстановить)» в меню Сейфа."""
    query = update.callback_query
    await query.answer()
    user = get_user(str(query.from_user.id))
    if not user:
        await query.answer("Сначала зарегистрируйтесь — /start", show_alert=True)
        return MAIN_MENU
    return await _vault_rec_begin(query.message, context, user)


async def _vault_rec_begin(msg, context, user):
    """ВОЛНА 9: запуск восстановления — проверка настроенности/блока, вопрос 1."""
    for key in ('vault_get_id', 'vault_attempts', 'vault_chp_id', 'vault_chp_stage',
                'vault_chp_old', 'vault_qs_stage'):
        context.user_data.pop(key, None)
    if not _vault_kdf_available():
        await msg.reply_text(
            "❌ Шифрование недоступно: на сервере нет библиотеки cryptography.\n"
            "Разработчику нужно выполнить: pip install cryptography")
        return MAIN_MENU
    auth = getattr(user, "vault_auth", None)
    if not _vault_auth_valid(user) or not auth.get("rec"):
        await msg.reply_text(
            "❌ Восстановление не настроено: секретные вопросы задаются при "
            "создании пароля Сейфа. У вашего Сейфа их пока нет (старая версия), "
            "а задать их без действующего пароля честно невозможно.\n\n"
            "Если пароль помните — задайте вопросы через «❓ Сменить секретные "
            "вопросы», чтобы страховка заработала на будущее.",
            reply_markup=get_main_menu_keyboard(user),
        )
        return MAIN_MENU
    # Блокировка после исчерпания попыток (честная защита от перебора).
    until_raw = getattr(user, "vault_rec_until", "") or ""
    if until_raw:
        try:
            until = datetime.fromisoformat(until_raw)
            if until.tzinfo is None:
                until = until.replace(tzinfo=timezone.utc)
            # _utcnow() наивный UTC — приводим к aware для честного сравнения.
            now = _utcnow().replace(tzinfo=timezone.utc)
            if now < until:
                left = int((until - now).total_seconds() // 60) + 1
                await msg.reply_text(
                    f"🚫 Восстановление заблокировано после {VAULT_REC_MAX_ATTEMPTS} "
                    f"неудачных попыток. Попробуйте примерно через {left} мин.",
                    reply_markup=get_main_menu_keyboard(user),
                )
                return MAIN_MENU
        except Exception:
            pass
        # Время блока вышло — честно обнуляем счётчик.
        user.vault_rec_until = ""
        user.vault_rec_fails = 0
        save_user(user)
    # ВОЛНА 17: вопросы могут быть зашифрованы в базе (enc) — открываем.
    questions = _vault_auth_open(auth).get("questions") or []
    if len(questions) < VAULT_QUESTIONS_N:
        await msg.reply_text(
            "❌ Не смог расшифровать секретные вопросы (например, сменился "
            "BOT_TOKEN). Если помните текущий пароль — задайте новые вопросы: "
            "🔐 Сейф → «❓ Сменить секретные вопросы».",
            reply_markup=get_main_menu_keyboard(user),
        )
        return MAIN_MENU
    context.user_data['vault_rec_answers'] = []
    tries_left = max(0, VAULT_REC_MAX_ATTEMPTS - int(getattr(user, "vault_rec_fails", 0) or 0))
    _ack = await msg.reply_text(
        "🔑 ВОССТАНОВЛЕНИЕ ДОСТУПА К СЕЙФУ\n\n"
        f"Вопрос 1 из {VAULT_QUESTIONS_N}:\n{questions[0]}\n\n"
        f"(попыток: {tries_left} из {VAULT_REC_MAX_ATTEMPTS}; отмена — «отмена»)",
        reply_markup=_vault_dialog_kb(),
    )
    _vault_track_ack(context, _ack, user=user)  # ВОЛНА 12
    return VAULT_REC_ANSWER


@timeout(CONVERSATION_TIMEOUT)
async def vault_rec_answer(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """ВОЛНА 9: приём ответов (3 вопроса подряд = 1 попытка). После трёх
    верных ответов бот распечатывает запечатанный пароль и сразу предлагает
    сменить его на новый. Неверный ответ съедает попытку."""
    msg = update.message
    user = get_user(str(update.effective_user.id))
    answers = context.user_data.get('vault_rec_answers')
    if not user or not isinstance(answers, list):
        context.user_data.pop('vault_rec_answers', None)
        await msg.reply_text(
            "Сессия восстановления потеряна. Начните заново: 🔐 Сейф → "
            "«🔑 Забыл пароль».")
        return MAIN_MENU
    text = (msg.text or "").strip()
    low = text.lower()
    if low in ("отмена", "cancel", "/cancel", "❌ отмена", "❌ отменить") or "отмена" in low or "cancel" in low:
        context.user_data.pop('vault_rec_answers', None)
        # ВОЛНА 12: набранные ответы на секретные вопросы стиряем из чата.
        await _vault_cleanup_chat(context, msg.chat_id, None, user=user)
        await msg.reply_text(
            "Отменено. Набранные ответы стёрты из чата. Пароль Сейфа не менялся.",
            reply_markup=get_main_menu_keyboard(user),
        )
        return MAIN_MENU
    answers.append(text)
    _vault_trace_add(context, user, msg.chat_id, msg.message_id)  # ВОЛНА 12
    auth = getattr(user, "vault_auth", None) or {}
    # ВОЛНА 17: вопросы могут быть зашифрованы в базе (enc) — открываем.
    questions = _vault_auth_open(auth).get("questions") or []
    if len(questions) < VAULT_QUESTIONS_N:
        await msg.reply_text(
            "❌ Не смог расшифровать секретные вопросы (например, сменился "
            "BOT_TOKEN). Набранные ответы стёрты. Если помните текущий "
            "пароль — задайте новые вопросы: 🔐 Сейф → «❓ Сменить секретные "
            "вопросы».",
            reply_markup=get_main_menu_keyboard(user),
        )
        context.user_data.pop('vault_rec_answers', None)
        return MAIN_MENU
    if len(answers) < VAULT_QUESTIONS_N:
        await msg.reply_text(f"Вопрос {len(answers) + 1} из {VAULT_QUESTIONS_N}:\n{questions[len(answers)]}")
        return VAULT_REC_ANSWER
    # Все три ответа собраны — пробуем распечатать запечатанный пароль.
    password = _vault_unseal_password(auth.get("rec"), answers)
    if password:
        # Ответы НЕ стираем: они нужны, чтобы запечатать НОВЫЙ пароль теми же
        # вопросами в vault_rec_newpass (очистятся там по завершении).
        user.vault_rec_fails = 0
        user.vault_rec_until = ""
        save_user(user)
        context.user_data['vault_rec_oldpw'] = password
        await msg.reply_text(
            "✅ Ответы верные — доступ возвращаю.\n\n"
            f"Придумайте НОВЫЙ ПАРОЛЬ СЕЙФА (минимум {VAULT_MIN_PASSWORD} символов): "
            "старый заменится, все файлы, зашифрованные паролем Сейфа, будут "
            "перешифрованы, и вы сразу сможете посмотреть или забрать свои данные.\n\n"
            + _vault_strength_table_text() + "\n\n"
            "(Сам забытый пароль я вам не покажу — он сразу заменяется новым.)",
            reply_markup=_vault_dialog_kb(),
        )
        return VAULT_REC_NEWPASS
    # Неверные ответы — попытка потрачена; начинаем новый цикл с вопроса 1.
    fails = int(getattr(user, "vault_rec_fails", 0) or 0) + 1
    if fails >= VAULT_REC_MAX_ATTEMPTS:
        user.vault_rec_fails = 0
        user.vault_rec_until = (_utcnow() + timedelta(minutes=VAULT_REC_COOLDOWN_MIN)).isoformat()
        save_user(user)
        context.user_data.pop('vault_rec_answers', None)
        # ВОЛНА 12: неверные ответы не должны висеть в чате.
        await _vault_cleanup_chat(context, msg.chat_id, None, user=user)
        await msg.reply_text(
            f"🚫 Ответы неверные {VAULT_REC_MAX_ATTEMPTS} раза — восстановление "
            f"заблокировано на {VAULT_REC_COOLDOWN_MIN} минут. Вспомните ответы "
            "и попробуйте позже.",
            reply_markup=get_main_menu_keyboard(user),
        )
        return MAIN_MENU
    user.vault_rec_fails = fails
    save_user(user)
    context.user_data['vault_rec_answers'] = []
    await msg.reply_text(
        f"❌ Ответы неверные (попытка {fails} из {VAULT_REC_MAX_ATTEMPTS}). "
        "Неверно хотя бы одно — придётся ответить на все заново.\n\n"
        f"Вопрос 1 из {VAULT_QUESTIONS_N}:\n{questions[0]}"
    )
    return VAULT_REC_ANSWER


@timeout(CONVERSATION_TIMEOUT)
async def vault_rec_newpass(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """ВОЛНА 9: новый пароль Сейфа после восстановления + перешифровка всех
    файлов, зашифрованных СТАРЫМ паролем Сейфа. После этого данные доступны."""
    msg = update.message
    user = get_user(str(update.effective_user.id))
    old_pw = context.user_data.get('vault_rec_oldpw')
    answers = context.user_data.get('vault_rec_answers')
    if not user or not old_pw or not isinstance(answers, list) or len(answers) < VAULT_QUESTIONS_N:
        context.user_data.pop('vault_rec_oldpw', None)
        context.user_data.pop('vault_rec_answers', None)
        await msg.reply_text(
            "Сессия потеряна. Начните заново: 🔐 Сейф → «🔑 Забыл пароль».")
        return MAIN_MENU
    password = (msg.text or "").strip()
    try:
        await context.bot.delete_message(chat_id=msg.chat_id, message_id=msg.message_id)
    except Exception:
        pass
    low = password.lower()
    if low in ("отмена", "cancel", "/cancel", "❌ отмена", "❌ отменить") or "отмена" in low or "cancel" in low:
        context.user_data.pop('vault_rec_oldpw', None)
        context.user_data.pop('vault_rec_answers', None)
        # ВОЛНА 12: ответы на вопросы стеряем из чата и здесь.
        await _vault_cleanup_chat(context, msg.chat_id, None, user=user)
        await msg.reply_text(
            "Отменено. ВНИМАНИЕ: доступ вы подтвердили вопросами, но пароль "
            "не сменили — при доступе к файлам продолжайте вводить СТАРЫЙ "
            "(восстановление можно пройти снова).",
            reply_markup=get_main_menu_keyboard(user),
        )
        return MAIN_MENU
    if len(password) < VAULT_MIN_PASSWORD:
        await msg.reply_text(
            f"Пароль короче {VAULT_MIN_PASSWORD} символов. Придумайте подлиннее.")
        return VAULT_REC_NEWPASS
    auth = getattr(user, "vault_auth", None) or {}
    files = [f for f in (getattr(user, "vault_files", []) or []) if isinstance(f, dict)]
    # Перешифровываем только файлы, зашифрованные СТАРЫМ паролем Сейфа;
    # файлы с отдельными (легаси) паролями честно пропускаем.
    targets = [f for f in files if _vault_check_password(user, f, old_pw)]
    skipped = len(files) - len(targets)
    progress = None
    try:
        progress = await msg.reply_text(
            f"🔁 Перешифровываю {len(targets)} файл(ов) новым паролем…")
    except Exception:
        progress = None
    done, fail = 0, 0
    for i, rec in enumerate(targets, 1):
        if progress is not None:
            try:
                await context.bot.edit_message_text(
                    f"🔁 Перешифровываю {i}/{len(targets)}…",
                    chat_id=progress.chat_id, message_id=progress.message_id,
                )
            except Exception:
                pass
        # ВОЛНА 14: большие файлы (DVF2) перешифровываем ПОТОКОМ через
        # MTProto — их нельзя скачать Bot API и нельзя держать в ОЗУ.
        if rec.get("dvf2"):
            if await _vault_reencrypt_dvf2(msg, context, user, rec, old_pw, password):
                done += 1
            else:
                fail += 1
            continue
        channel_id = rec.get("channel_id") or get_storage_channel_id()
        file_id = rec.get("file_id")
        if not channel_id or not file_id:
            fail += 1
            continue
        try:
            await context.bot.send_chat_action(chat_id=msg.chat_id, action="typing")
            tg_file = await context.bot.get_file(file_id)
            buf = io.BytesIO()
            await asyncio.wait_for(tg_file.download_to_memory(out=buf), timeout=120)
            container = buf.getvalue()
            meta, payload = await asyncio.to_thread(_vault_unpack, old_pw, container)
            new_container = await asyncio.to_thread(_vault_pack, password, payload, meta)
            container = b""
            payload = b""
        except Exception as e:
            logger.error(f"vault rec reencrypt ({rec.get('id')}): {e}")
            fail += 1
            continue
        up = await _storage_upload_document(
            context, new_container,
            filename=f"vault_{datetime.now().strftime('%Y%m%d_%H%M%S')}_{rec.get('id', 'f')}.bin",
            caption="🔐 Сейф: зашифрованный файл (открыть без пароля невозможно).",
            user=user)
        salt_hex = new_container[9:25].hex()
        nonce_hex = new_container[25:37].hex()
        new_container = b""
        if up is None:
            fail += 1
            continue
        new_key = _vault_derive_key(password, bytes.fromhex(salt_hex), VAULT_KDF_ITERS)
        old_msg_id = int(rec.get("msg_id") or 0)
        old_channel = channel_id
        rec.update({
            "salt": salt_hex,
            "nonce": nonce_hex,
            "verifier": _vault_verifier(new_key).hex(),
            "iters": VAULT_KDF_ITERS,
            "msg_id": int(up.get("message_id", 0)),
            "file_id": up.get("file_id"),
            "channel_id": up.get("channel_id"),
            "size_enc": int(up.get("size", 0) or 0),
        })
        # Старый шифр стираем (best-effort) — только после обновления записи.
        if old_msg_id:
            try:
                await context.bot.delete_message(chat_id=old_channel, message_id=old_msg_id)
            except Exception:
                pass
        done += 1
    user.vault_files = files
    # Обновляем «удостоверение» Сейфа: новый пароль + запечатываем его ТЕМИ ЖЕ
    # ответами (вопросы не менялись — менять их вправе сам пользователь отдельно).
    auth["salt"] = os.urandom(16).hex()
    auth["iters"] = VAULT_KDF_ITERS
    key = _vault_derive_key(password, bytes.fromhex(auth["salt"]), auth["iters"])
    auth["verifier"] = _vault_verifier(key).hex()
    auth["rec"] = _vault_seal_password(password, answers)
    # ВОЛНА 17: свежая метка времени (для merge при восстановлении) + шифруем
    # открытые вопросы, чтобы в файле базы лежал только шифр.
    auth["ts"] = _utcnow().strftime("%Y-%m-%d %H:%M:%S")
    user.vault_auth = _vault_auth_seal(auth)
    save_user(user)
    _vault_flush_soon(context, reason="новый пароль Сейфа (восстановление)")
    for key_name in ('vault_rec_oldpw', 'vault_rec_answers'):
        context.user_data.pop(key_name, None)
    # ВОЛНА 12: ответы, которыми распечатывали пароль, из чата стиряем —
    # они больше не нужны, а секрет в чате оставаться не должен.
    try:
        await _vault_cleanup_chat(context, msg.chat_id, None, user=user)
    except Exception:
        pass
    lines = ["✅ ГОТОВО — пароль Сейфа изменён."]
    lines.append(_vault_strength_note(password))  # ВОЛНА 11: стойкость нового пароля
    lines.append(f"• Перешифровано файлов: {done}.")
    if fail:
        lines.append(f"• Не удалось перешифровать: {fail} (файл мог пропасть из канала — попробуйте позже).")
    if skipped:
        lines.append(f"• Пропущено: {skipped} — эти файлы зашифрованы ОТДЕЛЬНЫМ паролем (старый режим), их пароль так не восстановить.")
    lines.append("")
    lines.append("Теперь можно посмотреть или взять данные: 🔐 Сейф → 📦 Мои файлы (новый пароль).")
    await msg.reply_text("\n".join(lines), reply_markup=get_main_menu_keyboard(user))
    return MAIN_MENU


async def vault_qs_cb(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """ВОЛНА 9: «❓ Сменить секретные вопросы» — шаг 1: текущий пароль Сейфа."""
    query = update.callback_query
    await query.answer()
    user = get_user(str(query.from_user.id))
    if not user:
        await query.answer("Сначала зарегистрируйтесь — /start", show_alert=True)
        return MAIN_MENU
    if not _vault_kdf_available():
        await query.answer(
            "Шифрование недоступно: на сервере нет библиотеки cryptography.",
            show_alert=True,
        )
        return MAIN_MENU
    if not _vault_auth_valid(user):
        await query.answer(
            "Вопросы ещё не настроены: положите первый файл в Сейф — бот задаст "
            "пароль и вопросы. Без действующего пароля задать их нельзя.",
            show_alert=True,
        )
        return MAIN_MENU
    context.user_data['vault_qs_stage'] = "auth"
    context.user_data['vault_attempts'] = 0
    _ack = await query.message.reply_text(
        "❓ СМЕНА СЕКРЕТНЫХ ВОПРОСОВ — шаг 1: введите текущий ПАРОЛЬ СЕЙФА "
        "(попыток: 3).",
        reply_markup=_vault_dialog_kb(),
    )
    _vault_track_ack(context, _ack, user=user)  # ВОЛНА 12
    return VAULT_GET_PASSWORD


async def _vault_qs_auth_password(update, context, user):
    """ВОЛНА 9: проверка пароля Сейфа перед сменой секретных вопросов."""
    msg = update.message
    password = (msg.text or "").strip()
    try:
        await context.bot.delete_message(chat_id=msg.chat_id, message_id=msg.message_id)
    except Exception:
        pass
    low = password.lower()
    if low in ("отмена", "cancel", "/cancel", "❌ отмена", "❌ отменить") or "отмена" in low or "cancel" in low:
        context.user_data.pop('vault_qs_stage', None)
        context.user_data.pop('vault_attempts', None)
        # ВОЛНА 12: гасим персистентный след (если был).
        try:
            await _vault_cleanup_chat(context, msg.chat_id, None, user=user)
        except Exception:
            pass
        await msg.reply_text("Отменено — вопросы остались прежними.",
                             reply_markup=get_main_menu_keyboard(user))
        return MAIN_MENU
    if _vault_check_safe_password(user, password):
        context.user_data['vault_qs_pw'] = password
        context.user_data.pop('vault_qs_stage', None)
        context.user_data.pop('vault_attempts', None)
        context.user_data['vault_qs_data'] = {"mode": "change", "q": [], "a": [], "stage": 0}
        await msg.reply_text(
            "✅ Пароль верный — шаг 2: придумайте НОВЫЙ секретный вопрос 1 из 3:")
        return VAULT_QS_WAIT
    attempts = int(context.user_data.get('vault_attempts', 0) or 0) + 1
    context.user_data['vault_attempts'] = attempts
    if attempts >= VAULT_ATTEMPTS_MAX:
        context.user_data.pop('vault_qs_stage', None)
        context.user_data.pop('vault_attempts', None)
        await msg.reply_text(
            f"🚫 Неверный пароль {VAULT_ATTEMPTS_MAX} раза — смена вопросов прервана.",
            reply_markup=get_main_menu_keyboard(user),
        )
        return MAIN_MENU
    await msg.reply_text(
        f"❌ Неверный пароль Сейфа (попытка {attempts} из {VAULT_ATTEMPTS_MAX}). "
        "Попробуйте ещё раз или отправьте «отмена».")
    return VAULT_GET_PASSWORD


@timeout(CONVERSATION_TIMEOUT)
async def vault_qs_receive(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """ВОЛНА 9: цикл «вопрос → ответ» ×3 для первичной настройки (после
    первого пароля) и для смены вопросов (после проверки пароля)."""
    msg = update.message
    user = get_user(str(update.effective_user.id))
    # ВОЛНА 22.3: идёт шифрование/загрузка (первая настройка)? «Отмена»
    # только ставит флаг — зачистку делает рабочий цикл, чтобы не порвать
    # наполовину зашифрованную пачку.
    if _vault_op_running(str(update.effective_user.id)):
        _VAULT_OPS[str(update.effective_user.id)]["event"].set()
        await msg.reply_text(
            "⛔ Останавливаю шифрование/загрузку — секунду, подчищу всё "
            "недогруженное…")
        return VAULT_QS_WAIT
    qs = context.user_data.get('vault_qs_data')
    if not user or not isinstance(qs, dict):
        context.user_data.pop('vault_qs_data', None)
        context.user_data.pop('vault_setup_pw', None)
        context.user_data.pop('vault_qs_pw', None)
        await msg.reply_text("Сессия потеряна. Начните заново: 🔐 Сейф.")
        return MAIN_MENU
    text = (msg.text or "").strip()
    low = text.lower()
    if low in ("отмена", "cancel", "/cancel", "❌ отмена", "❌ отменить") or "отмена" in low or "cancel" in low:
        was_setup = qs.get("mode") == "setup"
        context.user_data.pop('vault_qs_data', None)
        context.user_data.pop('vault_setup_pw', None)
        context.user_data.pop('vault_qs_pw', None)
        # ВОЛНА 12: стереть из чата и НАБРАННЫЕ вопросы/ответы (персистентный
        # след) — при отмене они не должны оставаться ни в памяти, ни в чате.
        await _vault_cleanup_chat(
            context, msg.chat_id,
            context.user_data.get('vault_batch') if was_setup else None,
            user=user,
        )
        if was_setup:
            context.user_data.pop('vault_batch', None)
            context.user_data.pop('vault_put_mode', None)
            await msg.reply_text(
                "Отменено — вопросы и ответы не сохранены, следы из чата "
                "стёрты, файлы НЕ зашифрованы.",
                reply_markup=get_main_menu_keyboard(user),
            )
        else:
            await msg.reply_text(
                "Отменено — вопросы остались прежними (набранные новые "
                "стёрты из чата).",
                reply_markup=get_main_menu_keyboard(user),
            )
        return MAIN_MENU
    stage = int(qs.get("stage", 0) or 0)
    if stage % 2 == 0:
        # Ждём ВОПРОС (stage 0/2/4).
        if len(text) < 3:
            await msg.reply_text(
                "Вопрос слишком короткий (минимум 3 символа). Придумайте вопрос:")
            return VAULT_QS_WAIT
        qs.setdefault("q", []).append(text[:200])
        qs["stage"] = stage + 1
        _vault_trace_add(context, user, msg.chat_id, msg.message_id)  # ВОЛНА 12
        _ack = await msg.reply_text(
            "✅ Вопрос принят. Теперь напишите на него ОТВЕТ — коротко, "
            "так, как запомните (регистр не важен):")
        _vault_track_ack(context, _ack, user=user)  # ВОЛНА 12
        return VAULT_QS_WAIT
    # Ждём ОТВЕТ (stage 1/3/5).
    if len(text) < 2:
        await msg.reply_text(
            "Ответ слишком короткий (минимум 2 символа). Напишите ответ:")
        return VAULT_QS_WAIT
    qs.setdefault("a", []).append(text[:300])
    qs["stage"] = stage + 1
    _vault_trace_add(context, user, msg.chat_id, msg.message_id)  # ВОЛНА 12
    if qs["stage"] < VAULT_QUESTIONS_N * 2:
        _ack = await msg.reply_text(
            f"✅ Ответ принят. Вопрос {qs['stage'] // 2 + 1} из {VAULT_QUESTIONS_N}:")
        _vault_track_ack(context, _ack, user=user)  # ВОЛНА 12
        return VAULT_QS_WAIT
    # Все 3 пары собраны — финализируем.
    if qs.get("mode") == "setup":
        password = context.user_data.get('vault_setup_pw')
        if not password:
            context.user_data.pop('vault_qs_data', None)
            context.user_data.pop('vault_batch', None)
            await msg.reply_text(
                "❌ Сессия настройки потеряна. Начните заново: 🔐 Сейф → 📥 Положить.")
            return MAIN_MENU
        auth = {
            "salt": os.urandom(16).hex(),
            "iters": VAULT_KDF_ITERS,
            "questions": qs.get("q", [])[:VAULT_QUESTIONS_N],
        }
        key = _vault_derive_key(password, bytes.fromhex(auth["salt"]), auth["iters"])
        auth["verifier"] = _vault_verifier(key).hex()
        auth["rec"] = _vault_seal_password(password, qs.get("a", [])[:VAULT_QUESTIONS_N])
        # ВОЛНА 17: вопросы уходят в базу ТОЛЬКО зашифрованными (ключ бота).
        auth["ts"] = _utcnow().strftime("%Y-%m-%d %H:%M:%S")
        user.vault_auth = _vault_auth_seal(auth)
        save_user(user)
        _vault_flush_soon(context, reason="первая настройка Сейфа")
        context.user_data.pop('vault_qs_data', None)
        context.user_data.pop('vault_setup_pw', None)
        await msg.reply_text("🛡️ Вопросы сохранены. Шифрую файлы паролем Сейфа…")
        _st = await _vault_encrypt_batch(msg, context, user, password)
        # ВОЛНА 12: набранные вопросы/ответы стёрты из чата (след уже погашен
        # внутри _vault_encrypt_batch через персистентный след).
        return _st
    # mode == "change": перепечатываем ТЕКУЩИЙ пароль новыми ответами.
    auth = getattr(user, "vault_auth", None)
    pw = context.user_data.get('vault_qs_pw')
    if not isinstance(auth, dict) or not pw:
        context.user_data.pop('vault_qs_data', None)
        context.user_data.pop('vault_qs_pw', None)
        await msg.reply_text("❌ Сессия потеряна. Начните заново: 🔐 Сейф.")
        return MAIN_MENU
    auth["questions"] = qs.get("q", [])[:VAULT_QUESTIONS_N]
    auth["rec"] = _vault_seal_password(pw, qs.get("a", [])[:VAULT_QUESTIONS_N])
    # ВОЛНА 17: свежая метка времени + вопросы — только шифром в базе.
    auth["ts"] = _utcnow().strftime("%Y-%m-%d %H:%M:%S")
    user.vault_auth = _vault_auth_seal(auth)
    save_user(user)
    _vault_flush_soon(context, reason="смена секретных вопросов")
    for key in ('vault_qs_data', 'vault_qs_pw', 'vault_attempts'):
        context.user_data.pop(key, None)
    # ВОЛНА 12: набранные вопросы/ответы больше не нужны в чате — стираем.
    await _vault_cleanup_chat(context, msg.chat_id, None, user=user)
    await msg.reply_text(
        "✅ Секретные вопросы обновлены (следы набора стёрты из чата). "
        "Восстановление теперь работает по новым вопросам; пароль Сейфа "
        "не менялся.",
        reply_markup=get_main_menu_keyboard(user),
    )
    return MAIN_MENU


async def vault_chpass_start(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Смена пароля файла: сначала старый пароль (VAULT_GET_PASSWORD), затем
    новый (VAULT_CHPASS_NEW). Внутри — расшифровка и перешифровка в памяти."""
    query = update.callback_query
    await query.answer()
    user = get_user(str(query.from_user.id))
    if not user:
        await query.answer("Сначала зарегистрируйтесь — /start", show_alert=True)
        return MAIN_MENU
    vid = query.data.replace("vault_chp_", "", 1)
    rec = _vault_find_record(user, vid)
    if not rec:
        await query.answer("Файл не найден.", show_alert=True)
        return MAIN_MENU
    context.user_data['vault_chp_id'] = vid
    context.user_data['vault_chp_stage'] = "old"
    context.user_data['vault_attempts'] = 0
    await query.message.reply_text(
        "🔑 СМЕНА ПАРОЛЯ — шаг 1: введите ТЕКУЩИЙ пароль файла.",
        reply_markup=_vault_dialog_kb(),
    )
    return VAULT_GET_PASSWORD


@timeout(CONVERSATION_TIMEOUT)
async def vault_chpass_new_password(update: Update, context: ContextTypes.DEFAULT_TYPE):
    msg = update.message
    user = get_user(str(update.effective_user.id))
    vid = context.user_data.get('vault_chp_id')
    if not user or not vid:
        await msg.reply_text("Сессия потеряна. Начните заново: 🔐 Сейф → 📦 Мои файлы.")
        return MAIN_MENU
    rec = _vault_find_record(user, vid)
    password = (msg.text or "").strip()
    try:
        await context.bot.delete_message(chat_id=msg.chat_id, message_id=msg.message_id)
    except Exception:
        pass
    _pw_low = password.lower().strip()
    if _pw_low in ("отмена", "cancel", "/cancel", "❌ отмена", "❌ отменить") or "отмена" in _pw_low or "cancel" in _pw_low:
        for key in ('vault_chp_id', 'vault_chp_stage', 'vault_chp_old', 'vault_get_id'):
            context.user_data.pop(key, None)
        # ВОЛНА 12: гасим персистентный след (если был).
        try:
            await _vault_cleanup_chat(context, msg.chat_id, None, user=user)
        except Exception:
            pass
        await msg.reply_text("Отменено — пароль не менялся.", reply_markup=get_main_menu_keyboard(user))
        return MAIN_MENU
    if len(password) < VAULT_MIN_PASSWORD:
        await msg.reply_text(
            f"Пароль короче {VAULT_MIN_PASSWORD} символов. Придумайте подлиннее."
        )
        return VAULT_CHPASS_NEW
    old_password = context.user_data.get('vault_chp_old')
    # ВОЛНА 14: большой файл (DVF2) — потоковая перешифровка через MTProto.
    # ВАЖНО: раньше эта ветка должна стоять ДО проверки file_id — у записей
    # DVF2 Bot API file_id нет (шифр заливался через MTProto).
    if rec.get("dvf2"):
        if not old_password:
            for key in ('vault_chp_id', 'vault_chp_stage', 'vault_chp_old'):
                context.user_data.pop(key, None)
            await msg.reply_text("❌ Смена пароля сорвалась. Попробуйте заново позже.")
            return MAIN_MENU
        _ok_dvf2 = await _vault_reencrypt_dvf2(
            msg, context, user, rec, old_password, password)
        for key in ('vault_chp_id', 'vault_chp_stage', 'vault_chp_old'):
            context.user_data.pop(key, None)
        if not _ok_dvf2:
            await msg.reply_text(
                "❌ Не удалось перешифровать файл (скорее всего, сообщение "
                "удалено из канала, или на сервере мало места). Пароль НЕ "
                "изменён. Попробуйте позже.",
                reply_markup=get_main_menu_keyboard(user),
            )
            return MAIN_MENU
        save_user(user)
        await msg.reply_text(
            "✅ Пароль изменён. Большой файл перешифрован новым паролем, "
            "старый шифр стёрт из канала (насколько это позволяет Telegram).")
        return MAIN_MENU
    channel_id = rec.get("channel_id") or get_storage_channel_id()
    file_id = rec.get("file_id")
    if not old_password or not channel_id or not file_id:
        for key in ('vault_chp_id', 'vault_chp_stage', 'vault_chp_old'):
            context.user_data.pop(key, None)
        await msg.reply_text("❌ Смена пароля сорвалась. Попробуйте заново позже.")
        return MAIN_MENU
    try:
        await context.bot.send_chat_action(chat_id=msg.chat_id, action="typing")
        tg_file = await context.bot.get_file(file_id)
        buf = io.BytesIO()
        await asyncio.wait_for(tg_file.download_to_memory(out=buf), timeout=120)
        container = buf.getvalue()
        meta, payload = await asyncio.to_thread(_vault_unpack, old_password, container)
        new_container = await asyncio.to_thread(_vault_pack, password, payload, meta)
    except Exception as e:
        logger.error(f"vault chpass: {e}")
        for key in ('vault_chp_id', 'vault_chp_stage', 'vault_chp_old'):
            context.user_data.pop(key, None)
        await msg.reply_text(
            "❌ Не удалось перешифровать файл (скорее всего, сообщение удалено "
            "из канала). Попробуйте позже.",
            reply_markup=get_main_menu_keyboard(user),
        )
        return MAIN_MENU
    finally:
        container = b""
        payload = b""
    # Грузим новый шифр и обновляем запись.
    up = await _storage_upload_document(
        context, new_container, filename=f"vault_{vid}.bin",
        caption="🔐 Сейф: зашифрованный файл (открыть без пароля невозможно).",
        user=user)
    new_container = b""
    if up is None:
        for key in ('vault_chp_id', 'vault_chp_stage', 'vault_chp_old'):
            context.user_data.pop(key, None)
        await msg.reply_text("❌ Не удалось загрузить новый шифр. Пароль НЕ изменён.")
        return MAIN_MENU
    salt_hex = new_container[9:25].hex()
    nonce_hex = new_container[25:37].hex()  # ВОЛНА 9: честный nonce новой записи
    new_container = b""
    new_key = _vault_derive_key(password, bytes.fromhex(salt_hex), VAULT_KDF_ITERS)
    old_msg_id = int(rec.get("msg_id") or 0)
    old_channel_id = channel_id
    rec.update({
        "salt": salt_hex,
        "nonce": nonce_hex,
        "verifier": _vault_verifier(new_key).hex(),
        "iters": VAULT_KDF_ITERS,
        "msg_id": int(up.get("message_id", 0)),
        "file_id": up.get("file_id"),
        "channel_id": up.get("channel_id"),
        "size_enc": int(up.get("size", 0) or 0),
    })
    save_user(user)
    # Старый шифр в канале стираем (best-effort) — ТОЛЬКО ПОСЛЕ обновления записи.
    if old_msg_id:
        try:
            await context.bot.delete_message(chat_id=old_channel_id, message_id=old_msg_id)
        except Exception:
            pass
    for key in ('vault_chp_id', 'vault_chp_stage', 'vault_chp_old'):
        context.user_data.pop(key, None)
    await msg.reply_text(
        "✅ Пароль изменён. Файл перешифрован новым паролем, старый шифр "
        "стёрт из канала (насколько это возможно)."
        f"\n{_vault_strength_note(password)}",
        reply_markup=get_main_menu_keyboard(user),
    )
    return MAIN_MENU


async def vault_del_cb(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    user = get_user(str(query.from_user.id))
    if not user:
        await query.answer("Сначала зарегистрируйтесь — /start", show_alert=True)
        return MAIN_MENU
    vid = query.data.replace("vault_del_", "", 1)
    rec = _vault_find_record(user, vid)
    if not rec:
        await query.answer("Файл не найден.", show_alert=True)
        return MAIN_MENU
    await query.answer()
    try:
        await query.edit_message_reply_markup(reply_markup=InlineKeyboardMarkup([
            [InlineKeyboardButton("✅ Да, удалить НАВСЕГДА", callback_data=f"vault_delyes_{vid}")],
            [InlineKeyboardButton("❌ Оставить", callback_data="vault_files")],
        ]))
    except Exception:
        await query.message.reply_text(
            "Удалить файл из Сейфа? Без пароля его всё равно никто не откроет, "
            "но и вы его больше не достанете.",
            reply_markup=InlineKeyboardMarkup([
                [InlineKeyboardButton("✅ Да, удалить НАВСЕГДА", callback_data=f"vault_delyes_{vid}")],
                [InlineKeyboardButton("❌ Оставить", callback_data="vault_files")],
            ]),
        )
    return MAIN_MENU


async def vault_del_yes_cb(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    user = get_user(str(query.from_user.id))
    if not user:
        await query.answer("Сначала зарегистрируйтесь — /start", show_alert=True)
        return MAIN_MENU
    vid = query.data.replace("vault_delyes_", "", 1)
    rec = _vault_find_record(user, vid)
    if not rec:
        await query.answer("Файл не найден.", show_alert=True)
        return MAIN_MENU
    await query.answer()
    channel_id = rec.get("channel_id") or get_storage_channel_id()
    if channel_id:
        try:
            await context.bot.delete_message(
                chat_id=channel_id, message_id=int(rec.get("msg_id") or 0),
            )
        except Exception:
            pass
    user.vault_files = [
        f for f in (getattr(user, "vault_files", []) or [])
        if not (isinstance(f, dict) and f.get("id") == vid)
    ]
    save_user(user)
    try:
        await query.edit_message_text(
            "🗑 Файл удалён из Сейфа: запись стёрта, шифр в канале уничтожен "
            "(насколько это позволяет Telegram)."
        )
    except Exception:
        await query.message.reply_text("🗑 Файл удалён из Сейфа.")
    return MAIN_MENU


async def vault_exit_cb(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await query.answer()
    user = get_user(str(query.from_user.id))
    # ВОЛНА 11/12: выход из Сейфа — следы загруженных файлов из чата стираем
    # ВСЕГДА (персистентный след работает и после рестарта бота).
    _stale_batch = context.user_data.get('vault_batch')
    try:
        await _vault_cleanup_chat(
            context, query.message.chat_id,
            _stale_batch if isinstance(_stale_batch, list) else None, user=user)
    except Exception:
        pass
    for key in ('vault_put_mode', 'vault_get_id', 'vault_chp_id', 'vault_attempts',
                'vault_pending', 'vault_chp_stage', 'vault_chp_old', 'vault_ren_id',
                'vault_batch', 'vault_migrate_ids', 'vault_setup_pw', 'vault_qs_data',
                'vault_qs_pw', 'vault_qs_stage', 'vault_rec_answers', 'vault_rec_oldpw',
                'vault_batch_label',
                'vault_ack_mid', 'vault_ack_last', 'vault_q_warned'):
        context.user_data.pop(key, None)
    try:
        await query.edit_message_text("🔐 Сейф закрыт.")
    except Exception:
        pass
    if user:
        await query.message.reply_text("Главное меню:", reply_markup=get_main_menu_keyboard(user))
    return MAIN_MENU


