def get_storage_dev_keyboard(cfg=None):
    cfg = cfg or load_storage_config()
    auto = "🔄 Авто-бэкап: ВКЛ" if cfg.get("auto_backup", True) else "🔄 Авто-бэкап: ВЫКЛ"
    cdb = "🗄️ База в канале: ВКЛ" if cfg.get("channel_db_enabled") else "🗄️ База в канале: ВЫКЛ"
    channels_n = len(cfg.get("channels") or [])
    return InlineKeyboardMarkup([
        [InlineKeyboardButton(f"🔗 Каналы ({channels_n})", callback_data="dev_storage_set")],
        [InlineKeyboardButton("➕ Подключить новый канал", callback_data="dev_storage_set")],
        [InlineKeyboardButton(cdb, callback_data="dev_cdb_toggle")],
        [InlineKeyboardButton("💾 Слить базу в канал сейчас", callback_data="dev_cdb_sync")],
        # ВОЛНА 10: «вспомнить всё» — вытянуть самую свежую базу из канала.
        [InlineKeyboardButton("📦 Вспомнить всё из канала", callback_data="dev_cdb_recall")],
        # ВОЛНА 15: файл базы — в личку разработчика: хранить где угодно,
        # потом просто отправить файл боту в чат — всё восстановится.
        [InlineKeyboardButton("💾 Снапшот базы мне в личку", callback_data="dev_cdb_export")],
        [InlineKeyboardButton(auto, callback_data="dev_storage_toggle")],
        [InlineKeyboardButton("📦 Бэкап сейчас", callback_data="dev_storage_backup")],
        [InlineKeyboardButton("♻️ Восстановить из бэкапа", callback_data="dev_storage_restore")],
        [InlineKeyboardButton("⬅️ Назад", callback_data="dev_back_panel")],
    ])


def _storage_dev_status_text(cfg):
    channels = _storage_channels_of(cfg)
    lines = ["☁️ Хранилище (приватные каналы)", ""]
    if channels:
        lines.append(f"🔗 Подключено каналов: {len(channels)}")
        for ch in channels:
            badge = STORAGE_KIND_LABELS.get(ch.get("kind"), "🔀 Оба")
            lines.append(f"   • {badge} — «{ch.get('title')}» (id {ch.get('id')})")
        db_n = len(get_db_channel_ids())
        cloud_n = len(get_cloud_channel_ids())
        lines.append("")
        lines.append(f"🗄️ Для бэкапов базы: {db_n} • ☁️ для файлов: {cloud_n} "
                     "(файлы грузятся по кругу, бэкап — зеркалится во все)")
    else:
        lines.append("❌ Каналы не заданы.")
        if STORAGE_ENV_CHANNEL:
            lines.append("(env STORAGE_CHANNEL_ID задан, но не числовой -100… — используйте панель)")
        else:
            lines.append("(подсказка: задайте env STORAGE_CHANNELS=\"-100…,-100…\" — "
                         "после обновления/смены сервера каналы подключатся сами)")
    lines.append("")
    lines.append(f"🔄 Авто-бэкап: {'ВКЛ' if cfg.get('auto_backup', True) else 'ВЫКЛ'} "
                 f"(около {cfg.get('backup_hour_utc', 4)}:00 UTC)")
    lines.append(f"🕒 Последний бэкап: {cfg.get('last_backup_date') or 'не было'}")
    lines.append(f"🗃 Бэкапов в реестре: {len(cfg.get('backups') or [])}")
    # ВОЛНА 16: статус режима больших файлов Сейфа (до 2 ГБ) — сразу видно,
    # работает ли он и что именно чинить, если нет.
    if _TELETHON_OK and BOT_TOKEN:
        lines.append("🟢 Сейф до 2 ГБ (MTProto): ВКЛ — telethon установлен.")
    else:
        lines.append("🔴 Сейф до 2 ГБ (MTProto): ВЫКЛ — telethon не установлен "
                     "(requirements.txt: telethon>=1.36; пересоберите деплой).")
    # ВОЛНА 8: статус режима «Канал = база данных».
    if cfg.get("channel_db_enabled"):
        dirty = len(_CDB_DIRTY)
        reg = cfg.get("cdb_registry") or {}
        lines.append("")
        lines.append("🗄️ БАЗА В КАНАЛЕ: ВКЛ — канал = первичная база, сервер = кэш.")
        lines.append(f"   Неслитых изменений: {dirty} • последний слив: {cfg.get('cdb_last_flush') or 'не было'}")
        if reg:
            snap = list(reg.values())[0]
            lines.append(f"   Закреплённый снапшот: {_fmt_bytes(int(snap.get('size', 0) or 0))} от {snap.get('ts', '?')} (юзеров {snap.get('users', '?')})")
        lines.append("   📦 При обновлении/смене сервера: подключите ЛЮБОЙ 🗄️-канал —")
        lines.append("   бот сам вспомнит ВСЁ (данные + остальные каналы). Кнопка:")
        lines.append("   «📦 Вспомнить всё из канала».")
        # ВОЛНА 13: путь «я сам вставляю снапшот в канал».
        lines.append("   💡 Можно и просто перекинуть файл снапшота (devorks_db_snapshot_…)")
        lines.append("   ПРЯМО В КАНАЛ — бот возьмёт ПОСЛЕДНИЙ актуальный, применит базу,")
        lines.append("   сам его ЗАКРЕПИТ и сотрёт старые снапшоты (дубли не плодятся).")
        # ВОЛНА 15: путь «файл базы у меня в телефоне — отправлю боту в чат».
        lines.append("   💡 ВОЛНА 15/16: кнопка «💾 Снапшот базы мне в личку» отдаст файл ТЕБЕ:")
        lines.append("   отправь его боту В ЧАТ в любой момент — применит базу (БЕЗ отказов")
        lines.append("   «не новее»), ответит «Готово!», ЗАКРЕПИТ в канале и сотрёт старые.")
    else:
        lines.append("")
        lines.append("🗄️ База в канале: ВЫКЛ (данные только на сервере).")
        lines.append("   При включении бот начнёт непрерывно зеркалить базу в канал.")
    try:
        users = load_users()
        total_files = 0
        total_size = 0
        vault_files = 0
        vault_size = 0
        for u in users.values():
            for f in (getattr(u, 'cloud_files', []) or []):
                if isinstance(f, dict):
                    total_files += 1
                    total_size += int(f.get("size", 0) or 0)
            for f in (getattr(u, 'vault_files', []) or []):
                if isinstance(f, dict):
                    vault_files += 1
                    vault_size += int(f.get("size_enc", 0) or 0)
        lines.append(f"☁️ Файлов в облаке: {total_files} • {_fmt_bytes(total_size)}")
        lines.append(f"🔐 Зашифровано в Сейфах: {vault_files} • {_fmt_bytes(vault_size)} (без пароля не открыть)")
    except Exception:
        pass
    lines.append("")
    lines.append(
        "Как подключить: создайте ПРИВАТНЫЙ канал → добавьте бота АДМИНОМ → "
        "нажмите «➕ Подключить канал» и перешлите сюда любое сообщение из "
        "канала (или отправьте -100…ID). Затем выберите режим: 🗄️ База данных "
        "(бэкапы), ☁️ Облако (файлы) или 🔀 Оба. Каналов может быть сколько "
        "угодно. Бот не читает историю канала: закреплённый снапшот — «память» "
        "базы, остальное — реестр в storage_config.json (список каналов сам "
        "возится внутри снапшота — при переезде вспомнится автоматически)."
    )
    return "\n".join(lines)


