async def dev_storage_channel_delete(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Отключение одного из каналов (callback dev_ch_del_<id>)."""
    query = update.callback_query
    await query.answer()
    if str(query.from_user.id) != DEVELOPER_ID:
        await query.edit_message_text("Доступ запрещён.")
        return DEV_PANEL
    try:
        chat_id = int(query.data.replace("dev_ch_del_", "", 1))
    except (TypeError, ValueError):
        await query.answer("Некорректный канал.", show_alert=True)
        return DEV_PANEL
    cfg, removed = _storage_remove_channel(chat_id)
    channels = _storage_channels_of(cfg)
    note = (f"✅ Канал {chat_id} отключён." if removed
            else "Канал и так не был подключён.")
    if not channels:
        note += "\n⚠️ Не осталось ни одного канала: облако и бэкапы недоступны."
    text = f"{note}\n\n" + _storage_dev_status_text(cfg)
    try:
        await query.edit_message_text(text, reply_markup=get_storage_dev_keyboard(cfg))
    except Exception:
        await query.message.reply_text(text, reply_markup=get_storage_dev_keyboard(cfg))
    return DEV_PANEL


@timeout(CONVERSATION_TIMEOUT)
async def dev_storage_channel_input(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if str(update.effective_user.id) != DEVELOPER_ID:
        await update.message.reply_text("Доступ запрещён.")
        return DEV_PANEL
    msg = update.message
    text = (msg.text or "").strip()
    chat_id = None
    title = ""
    # 1) Пересланное сообщение из канала — самый надёжный путь для приватного.
    fwd = getattr(msg, "forward_origin", None)
    fwd_chat = getattr(fwd, "chat", None) if fwd is not None else None
    if fwd_chat is None:
        fwd_chat = getattr(msg, "forward_from_chat", None)
    if fwd_chat is not None and getattr(fwd_chat, "id", None):
        chat_id = int(fwd_chat.id)
        title = str(getattr(fwd_chat, "title", "") or "")
    elif text.startswith("@"):
        try:
            chat = await context.bot.get_chat(text)
            chat_id = int(chat.id)
            title = str(getattr(chat, "title", "") or text)
        except Exception as e:
            await msg.reply_text(f"❌ Не удалось найти канал {text}: {e}")
            return DEV_STORAGE_CHANNEL
    else:
        t = text.replace(" ", "")
        if t.lstrip("-").isdigit() and t.startswith("-100"):
            try:
                chat_id = int(t)
            except ValueError:
                chat_id = None
        if chat_id is None:
            await msg.reply_text(
                "Не понял канал. Перешлите сообщение из канала, либо отправьте "
                "-100…ID, либо @username публичного канала."
            )
            return DEV_STORAGE_CHANNEL
    # Проверка видимости канала ботом.
    ok, err, chat_title = await _storage_check_channel(context, chat_id)
    title = chat_title or title
    if not ok:
        await msg.reply_text(
            f"❌ Канал не подключён: {err}.\n"
            "Добавьте бота АДМИНОМ в канал (Права: публикация сообщений, удаление, "
            "редактирование) и пришлите канал ещё раз."
        )
        return DEV_STORAGE_CHANNEL
    # Тестовая загрузка — единственная честная проверка, что Telegram даст
    # боту публиковать файлы в этот канал.
    try:
        test = await context.bot.send_document(
            chat_id=chat_id,
            document=InputFile(b"DEVORKS+ storage test", filename="devorks_test.txt"),
            caption="✅ Тестовая загрузка хранилища — можно удалить.",
        )
        try:
            await context.bot.delete_message(chat_id=chat_id, message_id=test.message_id)
        except Exception:
            pass
    except Exception as e:
        await msg.reply_text(
            f"❌ Тестовая загрузка не удалась: {e}.\n"
            "Бот должен быть именно АДМИНОМ канала, а не просто подписчиком."
        )
        return DEV_STORAGE_CHANNEL
    # ВОЛНА 7: канал проверен — спрашиваем РЕЖИМ через кнопки.
    context.user_data['pending_channel'] = {"id": chat_id, "title": title or str(chat_id)}
    await msg.reply_text(
        f"✅ Канал «{title or chat_id}» (id {chat_id}) проверен: бот — админ, "
        "загрузка работает.\n\n"
        "Теперь выберите, ЗАЧЕМ его использовать:",
        reply_markup=InlineKeyboardMarkup([
            [InlineKeyboardButton("🗄️ Только база данных (бэкапы)", callback_data=f"dev_ch_kind_db_{chat_id}")],
            [InlineKeyboardButton("☁️ Только облако (файлы)", callback_data=f"dev_ch_kind_cloud_{chat_id}")],
            [InlineKeyboardButton("🔀 И база, и облако", callback_data=f"dev_ch_kind_both_{chat_id}")],
            [InlineKeyboardButton("❌ Не подключать", callback_data="dev_storage")],
        ]),
    )
    return DEV_PANEL


async def dev_storage_channel_kind(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Сохранение канала с выбранным режимом (callback dev_ch_kind_<kind>_<id>)."""
    query = update.callback_query
    await query.answer()
    if str(query.from_user.id) != DEVELOPER_ID:
        await query.edit_message_text("Доступ запрещён.")
        return DEV_PANEL
    payload = query.data.replace("dev_ch_kind_", "", 1)
    kind, _, id_part = payload.rpartition("_")
    if kind not in STORAGE_CHANNEL_KINDS:
        await query.answer("Некорректный режим.", show_alert=True)
        return DEV_PANEL
    try:
        chat_id = int(id_part)
    except (TypeError, ValueError):
        await query.answer("Некорректный канал.", show_alert=True)
        return DEV_PANEL
    pending = context.user_data.get('pending_channel') or {}
    title = str(pending.get("title") or "")
    if pending.get("id") not in (None, chat_id):
        title = title or ""
    cfg, added = _storage_add_channel(chat_id, title, kind)
    context.user_data.pop('pending_channel', None)
    badge = STORAGE_KIND_LABELS.get(kind, kind)
    n_ch = len(cfg.get("channels") or [])
    # ВОЛНА 10: «когда я задам все каналы — бот должен вспомнить всё».
    # Подключение 🗄️-канала = момент истины: если локальная база пуста
    # (свежий сервер после обновления/переезда) — немедленно вытягиваем
    # закреплённый снапшот из канала и оживляем ВСЁ: юзеров, классы, ДЗ,
    # Сейфы, таймеры, настройки и остальные каналы из конфига в снапшоте.
    recall_note = ""
    if kind in ("db", "both"):
        # Режим «канал = база» включаем сразу (это и есть его смысл).
        if not cfg.get("channel_db_enabled"):
            cfg["channel_db_enabled"] = True
            save_storage_config(cfg)
            recall_note += "🗄️ Режим «База в канале» ВКЛЮЧЁН — канал теперь первичная база.\n"
        # На пустом сервере восстанавливаем МОЛЧА и СРАЗУ (нет риска
        # затереть свежие данные — их просто нет). На живом сервере
        # принудительную перезапись не делаем: есть кнопка «📦 Вспомнить всё
        # из канала» с подтверждением.
        if not os.path.exists(str(USERS_FILE)):
            try:
                ok, rep = await _cdb_recall(context, suppress_dirty=True)
                if ok:
                    recall_note += "\n✅ ВСПОМНИЛ ВСЁ ИЗ КАНАЛА:\n" + rep
                else:
                    recall_note += ("\nℹ️ В канале пока нет закреплённого снапшота — "
                                    "база начнёт копиться с текущего момента (первый "
                                    "слив — при первом изменении данных).")
            except Exception as e:
                logger.error(f"dev_storage_channel_kind: recall failed: {e}")
                recall_note += "\n⚠️ Автовосстановление из канала не удалось (см. лог)."
        else:
            recall_note += ("\nℹ️ Локальная база на месте — автоматически НЕ перезаписываю. "
                            "Если нужно вспомнить данные из канала: «📦 Вспомнить всё из канала».")
    await query.edit_message_text(
        f"✅ Канал «{title or chat_id}» подключён в режиме: {badge}.\n\n"
        f"Всего каналов: {n_ch}. Файлы пользователей распределяются по кругу "
        f"между ☁️-каналами, бэкап базы зеркалится во все 🗄️-каналы.\n\n"
        f"{recall_note}\n"
        "Подключить ещё канал: 🔗 Каналы → пришлите следующий канал."
    )
    try:
        await query.message.reply_text(
            "☁️ Хранилище — текущий статус:",
            reply_markup=InlineKeyboardMarkup([[
                InlineKeyboardButton("⬅️ К панели хранилища", callback_data="dev_storage"),
            ]]),
        )
    except Exception:
        pass
    return DEV_PANEL


