async def dev_cdb_toggle(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """ВОЛНА 8: включение/выключение «Канал = база данных».

    При ВКЛЮЧЕНИИ сразу сливаем текущую базу в канал — канал становится
    актуальным с этого момента (иначе первый рестарт откатил бы данные
    к старому снапшоту). При ВЫКЛЮЧЕНИИ — канал перестаёт быть первичным,
    бот работает как раньше (локально/Supabase)."""
    query = update.callback_query
    await query.answer()
    if str(query.from_user.id) != DEVELOPER_ID:
        await query.edit_message_text("Доступ запрещён.")
        return DEV_PANEL
    cfg = load_storage_config()
    if not cfg.get("channel_db_enabled"):
        if not get_db_channel_ids():
            await query.answer(
                "Сначала подключите канал в режиме 🗄️ База данных (или 🔀 Оба).",
                show_alert=True,
            )
            return DEV_PANEL
        cfg["channel_db_enabled"] = True
        save_storage_config(cfg)
        ok, report = await _cdb_flush(context, force=True, reason="режим включён")
        if not ok:
            cfg["channel_db_enabled"] = False
            save_storage_config(cfg)
            await query.edit_message_text(
                f"❌ Не удалось включить: первый слив базы в канал не удался.\n{report}\n\n"
                "Режим остался ВЫКЛЮЧЕННЫМ — данные не тронуты.",
                reply_markup=get_storage_dev_keyboard(cfg),
            )
            return DEV_PANEL
    else:
        cfg["channel_db_enabled"] = False
        save_storage_config(cfg)
    cfg = load_storage_config()
    text = ("🗄️ База в канале: " + ("ВКЛ" if cfg.get("channel_db_enabled") else "ВЫКЛ") + "\n\n"
            + _storage_dev_status_text(cfg))
    try:
        await query.edit_message_text(text, reply_markup=get_storage_dev_keyboard(cfg))
    except Exception:
        pass
    return DEV_PANEL


