async def dev_cdb_recall(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """ВОЛНА 10: кнопка «📦 Вспомнить всё из канала» — шаг 1 (подтверждение)."""
    query = update.callback_query
    await query.answer()
    if str(query.from_user.id) != DEVELOPER_ID:
        await query.edit_message_text("Доступ запрещён.")
        return DEV_PANEL
    cfg = load_storage_config()
    db_ids = get_db_channel_ids()
    if not db_ids:
        await query.answer(
            "Сначала подключите канал в режиме 🗄️ База данных (или 🔀 Оба).",
            show_alert=True,
        )
        return DEV_PANEL
    reg = cfg.get("cdb_registry") or {}
    reg_line = ""
    if reg:
        try:
            snap = list(reg.values())[0]
            reg_line = (f"Последний известный снапшот: {_fmt_bytes(int(snap.get('size', 0) or 0))} "
                        f"от {snap.get('ts', '?')}.\n\n")
        except Exception:
            reg_line = ""
    await query.edit_message_text(
        "📦 ВСПОМНИТЬ ВСЁ ИЗ КАНАЛА\n\n"
        f"Бот проверит {len(db_ids)} 🗄️-канал(ов), возьмёт САМЫЙ СВЕЖИЙ "
        "закреплённый снапшот и восстановит из него ВСЁ: пользователей, "
        "классы, ДЗ, Сейфы (файлы вернутся — пароль тот же), таймеры, "
        "настройки и остальные каналы.\n\n"
        f"{reg_line}"
        "⚠️ Текущие ЛОКАЛЬНЫЕ данные будут перезаписаны данными из канала.\n\n"
        "Продолжить?",
        reply_markup=InlineKeyboardMarkup([
            [InlineKeyboardButton("✅ Да, вспомнить всё", callback_data="dev_cdb_recall_go")],
            [InlineKeyboardButton("❌ Отмена", callback_data="dev_storage")],
        ]),
    )
    return DEV_PANEL


async def dev_cdb_recall_go(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """ВОЛНА 10: кнопка «📦 Вспомнить всё из канала» — шаг 2 (исполнение)."""
    query = update.callback_query
    await query.answer("Достаю базу из канала…", show_alert=False)
    if str(query.from_user.id) != DEVELOPER_ID:
        await query.edit_message_text("Доступ запрещён.")
        return DEV_PANEL
    ok, report = await _cdb_recall(context, suppress_dirty=True)
    if ok:
        text = ("✅ Готово — бот вспомнил всё.\n\n" + report)
    else:
        text = ("⚠️ Вспомнить не удалось: " + report +
                "\n\nЕсли снапшота нет — данные ещё не слились в канал: "
                "нажмите «💾 Слить базу в канал сейчас» и повторите позже.")
    cfg = load_storage_config()
    try:
        await query.edit_message_text(
            text + "\n\n" + _storage_dev_status_text(cfg),
            reply_markup=get_storage_dev_keyboard(cfg),
        )
    except Exception:
        await query.message.reply_text(
            text + "\n\n" + _storage_dev_status_text(cfg),
            reply_markup=get_storage_dev_keyboard(cfg),
        )
    return DEV_PANEL


