async def dev_storage_backup_confirm(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await query.answer("Скачиваю бэкап…", show_alert=False)
    if str(query.from_user.id) != DEVELOPER_ID:
        await query.edit_message_text("Доступ запрещён.")
        return DEV_PANEL
    try:
        idx = int(query.data.rsplit("_", 1)[1])
    except (ValueError, IndexError):
        await query.answer("Некорректный выбор.", show_alert=True)
        return DEV_PANEL
    cfg = load_storage_config()
    backups = [b for b in (cfg.get("backups") or []) if isinstance(b, dict)]
    if idx < 0 or idx >= len(backups):
        await query.answer("Такого бэкапа уже нет в реестре.", show_alert=True)
        return DEV_PANEL
    b = backups[idx]
    file_id = b.get("file_id")
    has_parts = bool(b.get("parts"))
    if not file_id and not has_parts:
        await query.edit_message_text(
            "❗ У записи нет file_id — восстановление невозможно. Отправьте файл "
            "бэкапа вручную.",
            reply_markup=InlineKeyboardMarkup([[
                InlineKeyboardButton("⬅️ Назад", callback_data="dev_storage_restore"),
            ]]),
        )
        return DEV_PANEL
    try:
        # ВОЛНА 7: бэкап может быть одним документом или ЧАСТЯМИ (>19 МБ).
        payload = await _storage_download_big(context, b)
    except Exception as e:
        await query.edit_message_text(
            f"❌ Не удалось скачать бэкап: {e}",
            reply_markup=InlineKeyboardMarkup([[
                InlineKeyboardButton("⬅️ Назад", callback_data="dev_storage_restore"),
            ]]),
        )
        return DEV_PANEL
    restored, problems = _storage_restore_apply(payload)
    lines = [f"♻️ Восстановление из бэкапа {b.get('date', '')}: завершено.", ""]
    if restored:
        lines.append(f"✅ Восстановлено файлов: {len(restored)}\n" + ", ".join(restored))
    if problems:
        lines.append("\n⚠️ Проблемы: " + "; ".join(problems[:10]))
    if not restored:
        lines.append("\n❗ Ни один файл не восстановлен — данные НЕ менялись.")
    try:
        await query.edit_message_text("\n".join(lines))
    except Exception:
        await query.message.reply_text("\n".join(lines))
    return DEV_PANEL


