@timeout(CONVERSATION_TIMEOUT)
async def dev_storage_restore_file_receive(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if str(update.effective_user.id) != DEVELOPER_ID:
        await update.message.reply_text("Доступ запрещён.")
        return DEV_PANEL
    msg = update.message
    doc = getattr(msg, "document", None)
    if doc is None:
        await msg.reply_text("Отправьте именно ФАЙЛ (документом): zip или json.")
        return DEV_STORAGE_RESTORE
    if int(getattr(doc, "file_size", 0) or 0) > STORAGE_MAX_FILE_BYTES:
        await msg.reply_text("❌ Файл больше 49 МБ — Telegram не даст его скачать.")
        return DEV_STORAGE_RESTORE
    try:
        tg_file = await context.bot.get_file(doc.file_id)
        buf = io.BytesIO()
        await asyncio.wait_for(tg_file.download_to_memory(out=buf), timeout=120)
        buf.seek(0)
        payload = buf.read()
    except Exception as e:
        await msg.reply_text(f"❌ Не удалось скачать файл: {e}")
        return DEV_STORAGE_RESTORE
    # Превью содержимого.
    inside = []
    try:
        with zipfile.ZipFile(io.BytesIO(payload)) as zf:
            known_bases = {os.path.basename(str(p)) for p in set(STORAGE_BACKUP_FILES)}
            inside = [n for n in zf.namelist()
                      if os.path.basename(n) in known_bases and not n.endswith("/")][:25]
    except Exception:
        base = os.path.basename(str(getattr(doc, "file_name", "") or ""))
        if base in {os.path.basename(str(p)) for p in set(STORAGE_BACKUP_FILES)}:
            inside = [base]
    context.user_data['dev_restore_payload'] = payload
    context.user_data['dev_restore_name'] = str(getattr(doc, "file_name", "") or "backup")
    preview = ", ".join(inside) if inside else "известных файлов данных не найдено!"
    await msg.reply_text(
        f"Файл «{context.user_data['dev_restore_name']}» получен ({_fmt_bytes(len(payload))}).\n\n"
        f"Внутри: {preview}\n\n⚠️ Восстановить сейчас? Текущие данные будут перезаписаны.",
        reply_markup=InlineKeyboardMarkup([
            [InlineKeyboardButton("✅ Да, восстановить", callback_data="dev_restore_do")],
            [InlineKeyboardButton("❌ Отмена", callback_data="dev_storage")],
        ]),
    )
    return DEV_PANEL


