async def delete_my_data_yes(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """ВОЛНА 22.18: полное удаление личных данных пользователя.
    Право на удаление/отзыв согласия — 152-ФЗ (ст. 9, 14, 21)."""
    query = update.callback_query
    await query.answer()
    uid = str(query.from_user.id)

    users = load_users()
    user = users.pop(uid, None)
    removed = {"timers": 0, "anon": 0, "buttons": 0, "share": 0}

    # 1) Таймеры и напоминания.
    try:
        timers = load_data(TIMERS_FILE, {}) or {}
        for k in list(timers):
            rec = timers[k] if isinstance(timers[k], dict) else {}
            if str(rec.get("user_id") or rec.get("owner") or "") == uid:
                timers.pop(k)
                removed["timers"] += 1
        save_data(TIMERS_FILE, timers)
    except Exception as e:
        logger.error(f"delete_my_data: таймеры: {e}")

    # 2) Анонимные сообщения (входящие И исходящие).
    try:
        anon = load_data(ANONYMOUS_MESSAGES_FILE, {}) or {}
        for k in list(anon):
            rec = anon[k] if isinstance(anon[k], dict) else {}
            if (str(rec.get("to_user_id") or "") == uid
                    or str(rec.get("from_user_id") or rec.get("owner") or "") == uid):
                anon.pop(k)
                removed["anon"] += 1
        save_data(ANONYMOUS_MESSAGES_FILE, anon)
    except Exception as e:
        logger.error(f"delete_my_data: анонимки: {e}")

    # 3) Личные кнопки.
    try:
        pbs = load_data(PERSONAL_BUTTONS_FILE, {}) or {}
        for k in list(pbs):
            rec = pbs[k] if isinstance(pbs[k], dict) else {}
            if str(rec.get("user_id") or rec.get("owner") or "") == uid:
                pbs.pop(k)
                removed["buttons"] += 1
        save_data(PERSONAL_BUTTONS_FILE, pbs)
    except Exception as e:
        logger.error(f"delete_my_data: личные кнопки: {e}")

    # 4) Share-ссылки владельца.
    try:
        shares = load_data(SHARE_FILE, {}) or {}
        for k in list(shares):
            rec = shares[k] if isinstance(shares[k], dict) else {}
            if str(rec.get("owner") or rec.get("user_id") or "") == uid:
                shares.pop(k)
                removed["share"] += 1
        save_data(SHARE_FILE, shares)
    except Exception as e:
        logger.error(f"delete_my_data: share-ссылки: {e}")

    # 5) Запись в классах (создателя класса не вычёркиваем — иначе
    #    класс «умрёт»; это честно указано в политике удаления).
    try:
        classes = load_classes()
        for code, cls in list(classes.items()):
            changed = False
            for attr in ("students", "members", "users"):
                lst = getattr(cls, attr, None)
                if isinstance(lst, list) and uid in [str(x) for x in lst]:
                    setattr(cls, attr, [x for x in lst if str(x) != uid])
                    changed = True
            if hasattr(cls, "blocked_users") and isinstance(cls.blocked_users, list) \
                    and uid in [str(x) for x in cls.blocked_users]:
                cls.blocked_users = [x for x in cls.blocked_users if str(x) != uid]
                changed = True
            if changed:
                classes[code] = cls
        save_classes(classes)
    except Exception as e:
        logger.error(f"delete_my_data: классы: {e}")

    # 6) Зашифрованные файлы Сейфа: попытка удалить сами сообщения из
    #    канала (не более 20 за раз, чтобы не зависнуть).
    try:
        if user is not None:
            ch_ids = get_cloud_channel_ids()[:1]
            vf = list(getattr(user, "vault_files", []) or [])[:20]
            for f in vf:
                if not isinstance(f, dict):
                    continue
                mid = f.get("mid") or f.get("message_id")
                if mid and ch_ids:
                    try:
                        await context.bot.delete_message(
                            chat_id=ch_ids[0], message_id=int(mid))
                    except Exception:
                        pass
    except Exception as e:
        logger.error(f"delete_my_data: файлы Сейфа: {e}")

    # 7) Сохраняем пользователей без удаляемого.
    try:
        save_users(users)
    except Exception as e:
        logger.error(f"delete_my_data: save_users: {e}")

    # 8) Сброс кэша PTB-данных пользователя.
    try:
        await context.application.drop_user_data(int(uid))
    except Exception:
        pass

    stat = (f"🗑 Готово. Удалено: аккаунт, таймеров — {removed['timers']}, "
            f"анонимных сообщений — {removed['anon']}, личных кнопок — "
            f"{removed['buttons']}, share-ссылок — {removed['share']}, "
            f"запись в классах. Согласие на обработку ПДн отозвано.\n\n"
            "Копии хранилища обновятся при ближайшей ротации резервных "
            "копий.\n\n/start — если захотите вернуться (с чистого листа).")
    try:
        await query.edit_message_text(stat)
    except Exception:
        await context.bot.send_message(chat_id=int(uid), text=stat)
    return ConversationHandler.END


async def instructions_read_handler(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """ПУНКТ 1: После прочтения инструкции пользователь идёт по обычному пути регистрации."""
    query = update.callback_query
    await query.answer()

    user_id = str(query.from_user.id)
    user = get_user(user_id)

    if not user:
        user = User(user_id, query.from_user.username, query.from_user.first_name)
        user.user_code = generate_user_code()
        save_user_code(user.user_code, user_id)

    user.instructions_read = True
    save_user(user)

    # Дальше — регистрация как раньше.
    # ВОЛНА 22.28: ДР обязателен — просим у всех без даты рождения.
    if not user.birthday:
        await query.edit_message_text(
            "👋 Добро пожаловать в DEVORKS+! Давайте настроим ваш профиль.\n\n"
            "🎂 Введите вашу реальную дату рождения в формате ГГГГ-ММ-ДД (например, 2005-04-15):\n\n"
            "Дата рождения обязательна: по ней проверяется возраст 13+.\n"
            "Бот будет напоминать вам о дне рождения и может поздравить вас в классе!",
            reply_markup=get_skip_birthday_keyboard()
        )
        return ENTER_BIRTHDAY
    elif not user.disclaimer_accepted:
        await show_disclaimer(update, context)
        return SHOW_INSTRUCTIONS
    elif not user.pdn_accepted:
        # ВОЛНА 22.18 (152-ФЗ): без согласия на обработку ПДн дальше — никак.
        await show_pdn_consent(update, context)
        return PDN_CONSENT_WAIT
    elif not user.setup_completed:
        # ПУНКТ 10: ручной ввод времени убран — спрашиваем только город,
        # часовой пояс определяется автоматически.
        # ПОЛИТИКА ПДн 1.2: город необязателен — есть «⏭ Пропустить».
        await query.edit_message_text(
            "🏙 Введите ваш город (например: Москва, Санкт-Петербург, Казань).\n"
            "По нему я сам определю часовой пояс и настрою уведомления.\n\n"
            "Указывать необязательно: нажмите «⏭ Пропустить», если не хотите.",
            reply_markup=get_skip_city_keyboard()
        )
        return ENTER_CITY
    else:
        await show_main_menu(update, context, user)
        return MAIN_MENU

@timeout(CONVERSATION_TIMEOUT)
async def set_time_handler(update: Update, context: ContextTypes.DEFAULT_TYPE):
    user_id = str(update.effective_user.id)
    user = get_user(user_id)
    time_str = update.message.text.strip()

    try:
        user_time_dt = datetime.strptime(time_str, "%H:%M")
        timezone = calculate_timezone(time_str)
        user.timezone = timezone
        user.local_time_set = True
        user.setup_completed = True
        save_user(user)

        # ПУНКТ 6: запланировать утренние/вечерние уведомления для нового пользователя
        try:
            schedule_user_daily_jobs(context.application, user)
        except Exception as e:
            logger.error(f"Не удалось запланировать daily jobs: {e}")
        # ПУНКТ (ДР): сразу ставим ежедневную проверку дня рождения — чтобы бот
        # поздравил пользователя, даже если он зарегистрировался незадолго до ДР.
        try:
            schedule_user_birthday_job(context.application, user)
        except Exception as e:
            logger.error(f"Не удалось запланировать birthday job: {e}")

        success_text = (
            f"✅ **Настройка завершена!**\n\n"
            f"⏰ Ваше время: {user_time_dt.strftime('%H:%M')}\n"
            f"🌍 Часовой пояс: UTC{timezone:+d}\n"
            f"🎂 День рождения: {user.birthday}\n\n"

            f"Теперь я буду присылать вам утренние и вечерние уведомления!\n"
        )
        await update.message.reply_text(success_text, parse_mode="Markdown")
        # === НОВОЕ: после общей настройки спрашиваем город (для погоды) ===
        if not getattr(user, 'city', None):
            await update.message.reply_text(
                "🏙 Укажите ваш город (для прогноза погоды и утренних уведомлений).\n\n"
                "Введите название города (например: Москва, Санкт-Петербург, Казань):",
                reply_markup=get_cancel_keyboard()
            )
            return ENTER_CITY
        await class_management(update, context)
        return CLASS_MANAGEMENT

    except ValueError:
        await update.message.reply_text("Введите время в формате ЧЧ:ММ (например, 08:30):")
        return SET_TIME

async def restore_session(update: Update, context: ContextTypes.DEFAULT_TYPE):
    user_id = str(update.effective_user.id)
    # Обязательная подписка на канал — до восстановления сессии тоже нужно
    # проверить, чтобы отписавшийся пользователь не получил клавиатуру меню.
    if not await ensure_subscribed(update, context):
        return ConversationHandler.END
    if is_user_blocked(user_id):
        await send_blocked_message(update, context, user_id)
        return ConversationHandler.END
    user = get_user(user_id)
    if user and user.setup_completed:
        await update.message.reply_text("🔄 Сессия восстановлена!", reply_markup=get_main_menu_keyboard(user))
        return MAIN_MENU
    else:
        await update.message.reply_text("Нажмите /start для начала работы.")
        return ConversationHandler.END

async def show_main_menu(update: Update, context: ContextTypes.DEFAULT_TYPE, user=None):
    if not user:
        user_id = str(update.effective_user.id)
        user = get_user(user_id)

    # === Реферальный бонус (отложенное начисление) ===
    # Если пользователь пришёл по ссылке /start ref_<id> и завершил регистрацию,
    # начисляем приглашающему ровно REFERRAL_REWARD_STARS звёзд один раз.
    try:
        ref_id = getattr(user, 'referrer_id', None)
        already_paid = getattr(user, 'referral_bonus_paid', False)
        setup_done = bool(getattr(user, 'setup_completed', False))
        if ref_id and (not already_paid) and setup_done:
            granted = credit_referrer_for(user.user_id, ref_id)
            if granted:
                # Пытаемся уведомить приглашающего о бонусе.
                try:
                    await context.bot.send_message(
                        chat_id=int(ref_id),
                        text=(
                            f"🎉 Ваш приглашённый пользователь зарегистрировался!\n"
                            f"+{REFERRAL_REWARD_STARS} ⭐ зачислены на ваш виртуальный баланс.\n"
                            f"Откройте «⭐ Звёзды» в главном меню, чтобы потратить их на функции."
                        )
                    )
                except Exception as e:
                    logger.warning(f"Не удалось уведомить приглашающего {ref_id}: {e}")
    except Exception as e:
        logger.error(f"show_main_menu: ошибка обработки реферального бонуса: {e}")

    # ВОЛНА 22.5: версии/сборки в приветствии БОЛЬШЕ НЕТ (просьба
    # пользователя) — обычный приветственный текст без технических деталей.
    greeting_text = f"👋 Добро пожаловать в DEVORKS+, {user.first_name}!"
    keyboard = get_main_menu_keyboard(user)

    if hasattr(update, 'message') and update.message:
        await update.message.reply_text(greeting_text, reply_markup=keyboard)
    elif hasattr(update, 'callback_query') and update.callback_query:
        try:
            await update.callback_query.edit_message_text("✅ Возвращаюсь в главное меню...")
        except Exception:
            pass
        await context.bot.send_message(
            chat_id=update.callback_query.from_user.id,
            text=greeting_text,
            reply_markup=keyboard
        )
    else:
        await context.bot.send_message(
            chat_id=user.user_id,
            text=greeting_text,
            reply_markup=keyboard
        )
    return MAIN_MENU

