def _resolve_button_name(cb_fragment, user):
    """Сопоставляет обрезанный callback_data фрагмент с полным именем кнопки."""
    all_names = get_all_user_button_names(user)
    for name in all_names:
        if _safe_cb("toggle_visibility_", name).replace("toggle_visibility_", "") == cb_fragment:
            return name
    for name in all_names:
        if name.startswith(cb_fragment):
            return name
    return cb_fragment


async def toggle_button_visibility_handler(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await query.answer()

    user_id = str(query.from_user.id)
    user = get_user(user_id)
    if not user:
        user = User(user_id)

    cb_fragment = query.data.replace("toggle_visibility_", "")
    button_name = _resolve_button_name(cb_fragment, user)

    if not hasattr(user, 'hidden_buttons'):
        user.hidden_buttons = []

    if button_name in user.hidden_buttons:
        user.hidden_buttons.remove(button_name)
        action = "показана"
    else:
        user.hidden_buttons.append(button_name)
        action = "скрыта"

    save_user(user)

    hidden_count = len(user.hidden_buttons)
    text = (
        f"👁 Управление видимостью кнопок\n\n"
        f"📊 Скрытых кнопок: {hidden_count}\n\n"
        f"✅ Кнопка '{button_name}' {action}!\n\n"
        f"Нажмите на кнопку, чтобы скрыть или показать её."
    )

    try:
        await query.edit_message_text(text, reply_markup=get_button_visibility_keyboard(user))
    except Exception as e:
        logger.error(f"Ошибка toggle_visibility: {e}")
    return MANAGE_BUTTON_VISIBILITY

async def finish_button_visibility(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await query.answer()

    user_id = str(query.from_user.id)
    user = get_user(user_id)

    hidden_count = len(getattr(user, 'hidden_buttons', []))

    text = f"⚙️ Настройки\n\n👤 Имя: {user.first_name}\n🌍 Часовой пояс: UTC{_fmt_tz_offset(user.timezone)}\n🔔 Уведомления: {'Включены' if user.notifications else 'Выключены'}\n🎂 День рождения: {user.birthday or 'Не установлен'}\n\n✅ Видимость сохранена! Скрыто: {hidden_count}\n\nВыберите действие:"
    try:
        await query.edit_message_text(text, reply_markup=get_settings_keyboard(user))
    except Exception:
        await context.bot.send_message(chat_id=user_id, text=text, reply_markup=get_settings_keyboard(user))

    await context.bot.send_message(
        chat_id=user_id,
        text="⚙️ Меню обновлено!",
        reply_markup=get_main_menu_keyboard(user)
    )
    return USER_SETTINGS

async def back_to_settings_handler(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await query.answer()
    return await user_settings(update, context)

# ==================================
# === ОСНОВНОЕ МЕНЮ ===
# ==================================

async def auto_reenter_main_menu(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Автоматический повторный вход в главное меню, если ConversationHandler
    завершился (по таймауту или ошибке). Не требует /start."""
    # Не пытаемся обрабатывать callback-и здесь — они идут через handle_callback
    if not getattr(update, "message", None):
        return MAIN_MENU
    user_id = str(update.effective_user.id)
    user = get_user(user_id)
    if not user or not user.setup_completed:
        return await start(update, context)
    return await handle_main_menu(update, context)


# ==================================
# === БЫСТРЫЕ КОМАНДЫ ИЗ ЛЮБОГО СОСТОЯНИЯ ===
# ==================================
# Пользователь должен иметь возможность нажать «👨‍🏫 Учителя», «⏰ Таймер»,
# «📝 Домашнее задание» и другие кнопки главного меню из ЛЮБОГО режима —
# даже когда бот ждёт от него ввода (текст ДЗ, имя учителя, время и т. п.).
# Раньше такие нажатия «съедались» текущим состоянием и трактовались как
# вводимые данные. Теперь первым хендлером в каждом текстовом состоянии
# стоит перехватчик точных названий команд (QUICK_COMMANDS), который
# аккуратно перенаправляет их в штатный handle_main_menu.

async def handle_quick_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Перехватчик быстрых команд из любого состояния.

    Текст гарантированно совпадает с одной из QUICK_COMMANDS (фильтр),
    поэтому просто делегируем в handle_main_menu — он знает, что делать,
    и вернёт корректное новое состояние разговора.
    """
    return await handle_main_menu(update, context)


def build_quick_commands_pattern():
    """Строит анкеренный regex из QUICK_COMMANDS (эмодзи + точные названия)."""
    import re as _re
    parts = [_re.escape(cmd) for cmd in QUICK_COMMANDS]
    return "^(" + "|".join(parts) + ")$"


async def cancel_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Обработчик /cancel: отвечает пользователю и возвращает в главное меню,
    не роняя ConversationHandler."""
    try:
        if getattr(update, "message", None):
            await update.message.reply_text("Отменено.")
    except Exception:
        pass
    user_id = str(update.effective_user.id) if update.effective_user else None
    user = get_user(user_id) if user_id else None
    if user and user.setup_completed:
        try:
            await show_main_menu(update, context, user)
        except Exception as e:
            logger.error(f"cancel_command show_main_menu error: {e}")
        return MAIN_MENU
    return ConversationHandler.END


# ==================================
# === ВОЛНА 12: ГЛОБАЛЬНАЯ КНОПКА ОТМЕНЫ ===
# ==================================

async def _global_cancel_cleanup(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """ВОЛНА 12 (выделено в 22.10): общая чистка при выходе из диалога:
    • стирает из чата ВСЕ следы загрузки в Сейф: файлы, заметки, подсказки
      бота, набранные вопросы/ответы на секретные вопросы (персистентный
      след user.vault_trace — работает даже после перезапуска бота);
    • стирает НЕСОХРАНЁННЫЕ секретные вопросы/ответы и любые недоделанные
      сессии Сейфа/облака (vault_*/cloud_*/poll_flow ключи user_data);
    • выключает режим AI-чата, если он был включён («отмена» = «стоп, в меню»);
    • возвращает в главное меню."""
    msg = getattr(update, "message", None)
    if msg is None:
        return MAIN_MENU
    user_id = str(update.effective_user.id) if update.effective_user else None
    user = get_user(user_id) if user_id else None
    # 1) Чистка следов в чате: пачка + персистентный след (пережил рестарт).
    batch = context.user_data.get('vault_batch')
    _deleted = 0
    try:
        _deleted = await _vault_cleanup_chat(
            context, msg.chat_id,
            batch if isinstance(batch, list) else None, user=user)
    except Exception:
        _deleted = 0
    # 2) Полная чистка сессий Сейфа/облака (включая недописанные
    #    секретные вопросы/ответы — vault_qs_data/vault_setup_pw).
    for _key in _VAULT_SESSION_KEYS:
        context.user_data.pop(_key, None)
    context.user_data.pop('vault_chat_acks', None)
    # 3) «Отмена» в чате с ИИ — тоже выход в меню (текст больше не уйдёт в ИИ).
    _was_ai = bool(context.user_data.get('ai_mode'))
    if _was_ai:
        context.user_data['ai_mode'] = False
        try:
            user_conversations.pop(user_id, None)
        except Exception:
            pass
    # 4) Ответ + главное меню.
    _lines = ["✅ Готово: вышли в главное меню."]
    if _deleted:
        _lines.append(f"🧹 Из чата стёрто сообщений: {_deleted} (файлы, заметки, вопросы/ответы).")
    if _was_ai:
        _lines.append("🤖 Режим AI выключен.")
    try:
        await msg.reply_text(
            "\n".join(_lines),
            reply_markup=get_main_menu_keyboard(user) if user else None,
        )
    except Exception as e:
        logger.warning(f"global_cancel: ответ не отправлен: {e}")
    return MAIN_MENU


async def _global_cancel_dialog(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """ВОЛНА 22.10: версия перехватчика отмены для ДИАЛОГОВ (инжектится в
    состояния ConversationHandler). Нажатие «❌ Отмена» в диалоге = ВЫХОД
    из диалога (общая чистка). НО если прямо сейчас идёт операция Сейфа
    (заливка/выдача) — работает семантика Сейфа (vault_kb_cancel_msg):
    заливку остановим, выдаче дадим дойти до конца. Цель «стереть выданный
    файл» здесь НАМЕРЕННО не трогается: пользователь отменяет ДИАЛОГ,
    а не удаляет файл — файл не должен исчезнуть от отмены ввода пароля."""
    msg = getattr(update, "message", None)
    if msg is None:
        return MAIN_MENU
    _uid = str(update.effective_user.id) if update.effective_user else ""
    try:
        if _uid and (msg.text or "").strip() in ("❌ Отмена", "❌ Отменить") \
                and _vault_op_running(_uid):
            return await vault_kb_cancel_msg(update, context)
    except Exception:
        pass
    return await _global_cancel_cleanup(update, context)


async def global_cancel_handler(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """ВОЛНА 12/22.10: «❌ Отмена» работает ИЗ ЛЮБОГО СОСТОЯНИЯ — даже когда
    FSM потерян после рестарта/деплоя (раньше текст отмены улетал в чат с ИИ:
    «нажимаю кнопку отмены в сейфе — отвечает ИИ и не выйти с сейфа, и файл
    не пропадает»).

    Умная (standalone) версия — регистрируется ПОСЛЕ ConversationHandler
    (state=None) и вызывается из главного меню (22.10: MAIN_MENU исключён
    из инжекта). Семантика:
    • идёт операция Сейфа (заливка/выдача) ИЛИ файл недавно выдан и ещё
      висит в чате → семантика Сейфа (vault_kb_cancel_msg): остановим
      заливку / пометим выдачу / сотрём файл и вернём главное меню;
    • иначе — общая чистка и выход в главное меню."""
    msg = getattr(update, "message", None)
    if msg is None:
        return MAIN_MENU
    _uid = str(update.effective_user.id) if update.effective_user else ""
    try:
        if (msg.text or "").strip() in ("❌ Отмена", "❌ Отменить"):
            if _uid and (_vault_op_running(_uid)
                         or _vault_wipe_target(_uid, context) is not None):
                return await vault_kb_cancel_msg(update, context)
    except Exception:
        pass
    return await _global_cancel_cleanup(update, context)


def _inject_global_cancel(states_dict):
    """ВОЛНА 12/22.10: инжектит перехватчик отмены (_global_cancel_dialog)
    ПЕРВЫМ хендлером в каждое состояние с текстовым вводом.
    ГЛАВНОЕ МЕНЮ (MAIN_MENU) с 22.10 НЕ инжектится: оно обрабатывает
    «❌ Отмена»/«❌ Отменить» само (handle_main_menu) — с семантикой Сейфа
    (стереть выданный файл), которую диалоговая чистка знать не должна.
    Возвращает число инжектированных состояний."""
    cancel_filter = filters.Regex(_GLOBAL_CANCEL_RE)
    injected = 0
    for _state, _handlers in states_dict.items():
        if _state == MAIN_MENU:
            # 22.10: главное меню обрабатывает отмену сам (handle_main_menu).
            continue
        if _state == AGE_BLOCKED:
            # ВОЛНА 22.27: «❌ Отмена» не должна выкидывать пользователя
            # с возрастным гейтом 13+ обратно в меню — гейт держим намертво.
            continue
        has_text_input = any(isinstance(h, MessageHandler) for h in _handlers)
        if has_text_input:
            _handlers.insert(0, MessageHandler(
                cancel_filter, _global_cancel_dialog))
            injected += 1
    return injected

@timeout(CONVERSATION_TIMEOUT)
async def ai_photo_reject_handler(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """ВОЛНА 22.4: AI больше НЕ принимает фото — требование пользователя
    («ai не должен принимать фото»). Раньше фото из главного меню (в режиме
    AI) и из чата «🤖 DEVORKS+ai» уходили в OCR/Groq Vision; теперь оба входа
    закрыты одним честным отказом.

    Фото/файлы остались легальными ровно в двух местах:
      • вложения к ДЗ — админ, «➕ Добавить ДЗ» (после выбора даты);
      • картинка расписания — «📅 Редактировать расписание» → выбрать день.

    Возвращаем None — в PTB это означает «остаться в текущем состоянии», то
    есть пользователь не вылетает из AI-чата и не теряет историю диалога."""
    user_id = str(update.effective_user.id)
    if not await ensure_subscribed(update, context):
        return None
    if is_user_blocked(user_id):
        await send_blocked_message(update, context, user_id)
        return ConversationHandler.END

    await update.message.reply_text(
        "🖼 AI не принимает фото.\n\n"
        "Фото и файлы у нас живут в двух местах:\n"
        "• 📝 ДЗ — админ может прикрепить фото/файлы к заданию "
        "(«➕ Добавить ДЗ» → выберите предмет и дату → присылайте);\n"
        "• 📅 Расписание — картинку расписания можно прислать при "
        "редактировании дня («📅 Редактировать расписание»).\n\n"
        "А если хотели что-то спросить — напишите текстом, я отвечу."
    )
    # None = остаться в текущем состоянии (не выкидываем из AI-чата).
    return None


@timeout(CONVERSATION_TIMEOUT)
async def handle_main_menu(update: Update, context: ContextTypes.DEFAULT_TYPE):
    user_id = str(update.effective_user.id)

    # Обязательная подписка на канал — если пользователь отписался, просим
    # подписаться обратно на любом нажатии кнопки.
    if not await ensure_subscribed(update, context):
        return MAIN_MENU

    if is_user_blocked(user_id):
        # ПУНКТ 8: показываем кнопку разблокировки со звёздами
        await send_blocked_message(update, context, user_id)
        return ConversationHandler.END

    user = get_user(user_id)
    if not user:
        user = User(user_id)
    # ВОЛНА 22.27: возрастной порог 13+ — проверка и в главном меню
    # (не только на /start: у пользователя мог поменяться/исправиться ДР).
    if _age_gate_violation(user):
        await _send_age_block(update, context)
        return AGE_BLOCKED
    # ВОЛНА 22.28: «дату рождения нельзя пропустить» — у пользователей
    # без ДР (в т.ч. нажимавших «⏭ Пропустить» раньше) меню не открывается,
    # пока дата не введена. Ровно та же проверка, что и на /start.
    if not getattr(user, "birthday", None):
        await update.message.reply_text(
            "🎂 Введите вашу реальную дату рождения в формате ГГГГ-ММ-ДД "
            "(например, 2005-04-15):\n\n"
            "Дата рождения обязательна: по ней проверяется возраст 13+.",
            reply_markup=get_skip_birthday_keyboard())
        return ENTER_BIRTHDAY
    # ВОЛНА 22.13: отметка дневной активности (для DAU/WAU/MAU статистики).
    _touch_activity(user_id)
    message_text = update.message.text

    # ПУНКТ 4: если пользователь переименовал кнопку, отображаемое имя нужно
    # сопоставить с оригинальным, чтобы внутренняя логика осталась рабочей.
    reverse_map = get_user_button_reverse_map(user)
    if message_text in reverse_map:
        message_text = reverse_map[message_text]

    # ВОЛНА 22.10: единая кнопка «❌ Отмена» (и легаси «❌ Отменить»):
    # в ГЛАВНОМ МЕНЮ её больше нет, но если она нажата (хвост процесса Сейфа:
    # идёт операция или файл недавно выдан) — семантика Сейфа: остановить
    # заливку / пометить выдачу / стереть выданный файл и вернуться в меню.
    # Нечего отменять — общая чистка (выход в меню). Ловим ДО ai_mode и
    # остальных режимов, чтобы кнопка не утекала в AI.
    if message_text in ("❌ Отмена", "❌ Отменить"):
        if _vault_op_running(user_id) or _vault_wipe_target(user_id, context):
            return await vault_kb_cancel_msg(update, context)
        return await global_cancel_handler(update, context)
    # Легаси-фразы отмены («отмена», «cancel», «назад в меню»): раньше их
    # ловил инжектированный хендлер — теперь главное меню обрабатывает их
    # сам (22.10: состояние MAIN_MENU исключено из инжекта отмены).
    if _GLOBAL_CANCEL_RE.match((message_text or "").strip()):
        return await global_cancel_handler(update, context)

    # ВОЛНА 22.11/22.12: анти-гонка опросов. concurrent_updates(True): текст
    # вопроса, отправленный сразу после нажатия «📊 Опрос», может обогнать
    # колбэк и прийти, пока состояние ещё MAIN_MENU — тогда он молча уходил
    # в AI/автоматизацию (бот «молчал»). Теперь если недоделанный опрос ждёт
    # — текст принимается: без вопроса это ВОПРОС, с вопросом это ВАРИАНТЫ
    # (или новый вопрос одной строкой). Отправленный опрос (sent) не ловим.
    _pflow = context.user_data.get("poll_flow") or {}
    if (_pflow.get("scope") in ("all", "class")
            and not _pflow.get("sent")
            and message_text and not message_text.startswith("/")
            and message_text not in QUICK_COMMANDS
            and (message_text or "").strip().lower() not in _MENU_TEXT_ALIASES):
        if not _pflow.get("q"):
            return await _poll_accept_question(update, context, _pflow,
                                               message_text)
        return await _poll_accept_options(update, context, _pflow,
                                          message_text)

    if context.user_data.get('replying_to_anon'):
        return await send_anonymous_reply(update, context)

    # ВОЛНА 22.12: «📚 Решения» — общая база решений класса.
    if message_text == "📚 Решения":
        return await solutions_menu(update, context)

    if context.user_data.get('ai_mode'):
        # Любой вариант «выход» — гарантированно выходим из режима AI
        lowered = (message_text or "").strip().lower()
        exit_triggers = {
            "❌ выход из ai", "выход из ai", "выйти из ai",
            "выйти", "выход", "exit", "/exit", "stop", "/stop",
        }
        if lowered in exit_triggers:
            context.user_data['ai_mode'] = False
            # Чистим историю диалога с AI, чтобы следующий вход начинался «с чистого листа»
            user_conversations.pop(user_id, None)
            await update.message.reply_text(
                "👋 Вы вышли из режима ai.",
                reply_markup=get_main_menu_keyboard(user),
            )
            return MAIN_MENU
        # Любой другой текст — передаём в AI. handle_ai_message сам ловит все ошибки.
        await handle_ai_message(update, context)
        return MAIN_MENU

    personal_buttons = get_personal_buttons(user_id)
    for button in personal_buttons:
        if button.name == message_text:
            if button.button_type == "url":
                await update.message.reply_text(
                    f"🔗 **{button.name}**",
                    reply_markup=InlineKeyboardMarkup([
                        [InlineKeyboardButton("🔗 Перейти по ссылке", url=button.content)]
                    ]),
                    parse_mode=ParseMode.MARKDOWN
                )
            else:
                await update.message.reply_text(f"📝 **{button.name}:**\n\n{button.content}", parse_mode=ParseMode.MARKDOWN)
            return MAIN_MENU

    global_buttons = get_global_buttons()
    for button in global_buttons:
        if button.name == message_text:
            if button.button_type == "url":
                await update.message.reply_text(
                    f"🔗 {button.name}",
                    reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("Перейти по ссылке", url=button.content)]])
                )
            else:
                await update.message.reply_text(f"📝 {button.content}")
            return MAIN_MENU

    class_obj = get_class_by_user(user_id)
    if class_obj and not is_user_class_blocked(user_id, class_obj.class_code):
        custom_buttons = get_class_custom_buttons(class_obj.class_code)
        for custom_button in custom_buttons:
            button_text = custom_button.name
            if custom_button.name.startswith("CLASS_"):
                button_text = custom_button.name.replace("CLASS_", "")

            if button_text == message_text:
                if custom_button.button_type == "url":
                    await update.message.reply_text(
                        f"🔗 {button_text}",
                        reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("Перейти по ссылке", url=custom_button.content)]])
                    )
                else:
                    await update.message.reply_text(f"📝 {custom_button.content}")
                return MAIN_MENU

    if message_text == "➕ Добавить ДЗ":
        if class_obj and str(user_id) in class_obj.admins:
            context.user_data['current_admin_class'] = class_obj.class_code
            keyboard = []
            subjects = class_obj.subjects or []
            if subjects:
                for subject in subjects:
                    cb_subj = subject[:50]
                    keyboard.append([InlineKeyboardButton(f"📚 {subject}", callback_data=f"hw_subject_{cb_subj}")])
            keyboard.append([InlineKeyboardButton("➕ Свой предмет", callback_data="hw_new_subject")])
            if subjects:
                keyboard.append([InlineKeyboardButton("🗑️ Удалить предмет", callback_data="hw_delete_subject_list")])
            keyboard.append([InlineKeyboardButton("❌ Отмена", callback_data="cancel_action")])
