    user = get_user(user_id)
    if not user:
        user = User(user_id)

    # callback_data: anon_pay_virt_<msg_id>; msg_id может содержать «_» и «-»,
    # поэтому склеиваем хвост.
    parts = query.data.split("_", 3)
    if len(parts) < 4:
        try:
            await query.edit_message_text("Неверный формат данных.")
        except Exception:
            pass
