    user = get_user(user_id)
    if not user:
        user = User(user_id)
    message_text = update.message.text
    class_code = context.user_data.get('current_admin_class')

    if not class_code:
        error_text = "Класс не выбран."
        await update.message.reply_text(error_text)
        return await admin_panel(update, context)

    class_obj = get_class_by_code(class_code)
    if not class_obj:
        error_text = "Класс не найден."
        await update.message.reply_text(error_text)
        return await admin_panel(update, context)

    rejected = await reject_if_forbidden_chars(update, message_text, SEND_CLASS_MESSAGE)
    if rejected is not None:
        return rejected

    members = [m for m in (class_obj.students + class_obj.admins) if m not in class_obj.blocked_users]
    sent_count = 0

    for member_id in members:
        if member_id != user_id:
            try:
                await context.bot.send_message(
                    chat_id=member_id,
                    text=f"📢 **Сообщение от администратора класса {class_obj.class_name}:**\n\n{message_text}",
                    parse_mode="Markdown"
                )
                sent_count += 1
            except Exception as e:
                logger.error(f"Ошибка при отправке сообщения {member_id}: {e}")

    success_text = f"✅ Сообщение отправлено {sent_count} участникам класса!"

    # ВОЛНА 22.27: журнал действий админов — доказуемая авторство рассылки.
    _log_admin_action(user_id, class_code, "Рассылка классу",
                      message_text[:200])

    # ВОЛНА 22.29: журнал ОБЪЯВЛЕНИЙ класса — по нему «🤒 Я болел(а)»
    # показывает «что писал админ за время болезни». Хранится В КЛАССЕ
    # (classes.json → канал-БД), капа 300 записей.
    try:
        log_ann = getattr(class_obj, 'announcements', None)
        if not isinstance(log_ann, list):
            log_ann = []
        log_ann.append({
            "ts": datetime.now().strftime("%Y-%m-%d %H:%M"),
            "by": str(user_id),
            "name": str(getattr(user, 'first_name', '') or ''),
            "text": str(message_text)[:1000],
        })
        class_obj.announcements = log_ann[-300:]
        save_class(class_obj)
    except Exception as e:
        logger.error(f"send_class_message: не удалось записать объявление в журнал: {e}")

    await update.message.reply_text(success_text)
    return await admin_panel(update, context)

