@timeout(CONVERSATION_TIMEOUT)
async def timer_edit_time_save(update: Update, context: ContextTypes.DEFAULT_TYPE):
    tid = context.user_data.get('tmr_edit_id')
    time_str = (update.message.text or "").strip()
    if not tid:
        await update.message.reply_text("Напоминание не выбрано.")
        return TIMER_SET_DATE
    try:
        datetime.strptime(time_str, "%H:%M")
    except ValueError:
        await update.message.reply_text("Не понял время. Формат ЧЧ:ММ (например 07:30):")
        return TIMER_EDIT_TIME
    timers = load_data(TIMERS_FILE, {})
    td = timers.get(tid)
    if not isinstance(td, dict) or str(td.get('user_id')) != str(update.effective_user.id):
        await update.message.reply_text("Напоминание не найдено.")
        context.user_data.pop('tmr_edit_id', None)
        return TIMER_SET_DATE
    td['target_time'] = time_str
    td.pop('fired_at', None)
    # Пересчитать дату ближайшего запуска.
    _reps = td.get('repeat_days') or []
    tz_offset = 3
    try:
        _u = get_user(str(update.effective_user.id))
        if _u is not None:
            tz_offset = getattr(_u, 'timezone', 3)
    except Exception:
        pass
    now_local = _now_utc() + timedelta(hours=tz_offset)
    if _reps:
        try:
            days = {int(d) for d in _reps if 0 <= int(d) <= 6}
        except (TypeError, ValueError):
            days = set()
        _nd = now_local if (now_local.weekday() in days
                            and datetime.strptime(
                                f"{now_local.strftime('%Y-%m-%d')} {time_str}",
                                "%Y-%m-%d %H:%M") > now_local) \
            else _timer_next_days_date(list(days), now_local)
        if _nd is not None:
            td['target_date'] = _nd.strftime("%Y-%m-%d")
    elif td.get('repeat_weekly') is not None and not td.get('repeat_daily'):
        try:
            _wd = int(td['repeat_weekly'])
            _nd = now_local if (now_local.weekday() == _wd
                                and datetime.strptime(
                                    f"{now_local.strftime('%Y-%m-%d')} {time_str}",
                                    "%Y-%m-%d %H:%M") > now_local) \
                else _timer_next_weekday_date(_wd, now_local)
            if _nd is not None:
                td['target_date'] = _nd.strftime("%Y-%m-%d")
        except (TypeError, ValueError):
            pass
    else:
        # Разовый: та же дата, а если она уже прошла — завтра.
        try:
            _cand = datetime.strptime(f"{td.get('target_date')} {time_str}",
                                      "%Y-%m-%d %H:%M")
            if _cand <= now_local:
                td['target_date'] = (now_local + timedelta(days=1)).strftime("%Y-%m-%d")
        except ValueError:
            pass
    td['is_active'] = True
    timers[tid] = td
    save_data(TIMERS_FILE, timers)
    try:
        schedule_timer_job(context.application, tid, td)
    except Exception as e:
        logger.error(f"timer edit: не удалось перепланировать {tid}: {e}")
    context.user_data.pop('tmr_edit_id', None)
    await update.message.reply_text(
        f"✅ Время обновлено: {td.get('target_date')} в {time_str}")
    return TIMER_SET_DATE


# ==================================
# === ВОЛНА 22.28: ПОМОДОРО-ТАЙМЕР («в таймере добавь помодоро таймер») ===
# ==================================
# Сессия = цепочка фаз «работа → короткий перерыв → … → длинный перерыв →
# 🎉 конец сессии». Хранится в POMODORO_FILE (в канале-БД — переживает
# рестарт: тикер сам продолжает прерванные фазы). Управление — колбэки
# pomo_* БЕЗ ConversationHandler: кнопки помодоро не ломают текущий FSM,
# из handle_callback возвращается None (остаться в текущем состоянии).

_POMO_DEFAULTS = {"work": 25, "brk": 5, "long": 15, "cycles": 4}
_POMO_CHOICES = {
    "work":   [15, 20, 25, 30, 45, 50, 60],
    "brk":    [3, 5, 10, 15],
    "long":   [10, 15, 20, 30],
    "cycles": [1, 2, 3, 4, 6, 8],
}


def _pomo_cfg_from_user_data(context):
    """Настройки помодоро из user_data (или дефолт 25/5/15/4)."""
    cfg = context.user_data.get('pomo_cfg')
    if not isinstance(cfg, dict):
        cfg = {}
    out = dict(_POMO_DEFAULTS)
    for k in out:
        try:
            v = int(cfg.get(k, out[k]))
            if v > 0:
                out[k] = v
        except (TypeError, ValueError):
            pass
    return out


def _pomo_load_sessions():
    return load_data(POMODORO_FILE, {})


def _pomo_get_session(uid, sessions=None):
    sessions = sessions if sessions is not None else _pomo_load_sessions()
    s = sessions.get(str(uid))
    return s if isinstance(s, dict) and s.get('is_active') else None


def _pomo_phase_kb():
    """Кнопки под КАЖДЫМ помодоро-уведомлением и в меню активной сессии."""
    return InlineKeyboardMarkup([
        [InlineKeyboardButton("⏭ Пропустить этап", callback_data="pomo_skip"),
         InlineKeyboardButton("⏹ Остановить", callback_data="pomo_stop")],
    ])


def _pomo_menu_text(sess, cfg, tz=3):
    if sess:
        try:
            _ends = datetime.strptime(str(sess.get('ends')), "%Y-%m-%d %H:%M")
            # ВАЖНО: ends — в ЛОКАЛЬНОМ времени пользователя, datetime.now() —
            # в локальном времени СЕРВЕРА (на Render это UTC). Сравниваем
            # через _utcnow() + сдвиг часового пояса, иначе «осталось» врёт.
            _now_local = _utcnow() + timedelta(hours=(tz or 3))
            _left = max(0, int((_ends - _now_local).total_seconds() // 60))
        except (TypeError, ValueError):
            _left = None
        _ph = {'work': '▶️ учёба', 'break': '☕️ отдых',
               'long': '🛌 большой отдых'}.get(sess.get('phase'), sess.get('phase'))
        _left_line = f" · осталось ≈{_left} мин" if _left is not None else ""
        return (f"🍅 Таймер учёбы\n\n"
                f"Сейчас: {_ph}{_left_line}\n"
                f"🔁 Пройдено кругов: {sess.get('cycle_done', 0)} из {sess.get('cycles', 4)}\n\n"
                "Ничего нажимать не нужно — бот САМ пришлёт сообщение, когда "
                "пора отдыхать или возвращаться к учёбе.")
    return (f"🍅 Таймер учёбы — учёба с перерывами\n\n"
            "Как это работает: бот чередует учёбу и отдых. "
            f"Сейчас: {cfg['work']} мин занимаетесь → {cfg['brk']} мин отдыхаете. "
            f"После {cfg['cycles']} таких кругов — большой отдых {cfg['long']} мин.\n\n"
            "Короткие перерывы помогают не устать. Таймер сам следит за "
            "временем и позовёт вас.")


def _pomo_menu_kb(sess, cfg):
    rows = []
    if sess:
        rows.append([InlineKeyboardButton("⏭ Пропустить этап", callback_data="pomo_skip"),
                     InlineKeyboardButton("⏹ Остановить", callback_data="pomo_stop")])
    else:
        rows.append([InlineKeyboardButton(
            f"▶️ Начать ({cfg['work']} учёба / {cfg['brk']} отдых)",
            callback_data="pomo_start_def")])
        rows.append([InlineKeyboardButton("⚙️ Изменить время", callback_data="pomo_setup")])
    rows.append([InlineKeyboardButton("⬅️ Назад к таймерам", callback_data="pomo_back")])
    return InlineKeyboardMarkup(rows)


async def pomo_menu_cb(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """«🍅 Таймер учёбы» в меню таймеров (бывший «Помодоро»): статус сессии
    или настройка+старт — объяснение простыми словами без терминов."""
    query = update.callback_query
    try:
        await query.answer()
    except Exception:
        pass
    uid = str(query.from_user.id)
    cfg = _pomo_cfg_from_user_data(context)
    sess = _pomo_get_session(uid)
    _u = get_user(uid)
    _tz = getattr(_u, 'timezone', 3) if _u else 3
    _txt = _pomo_menu_text(sess, cfg, tz=_tz)
    _kb = _pomo_menu_kb(sess, cfg)
    try:
        await query.edit_message_text(_txt, reply_markup=_kb)
    except Exception:
        await context.bot.send_message(chat_id=int(uid), text=_txt, reply_markup=_kb)
    return None  # не трогаем текущее состояние FSM


def _pomo_setup_kb(cfg):
    _names = {"work": "▶️ Учёба", "brk": "☕️ Отдых",
              "long": "🛌 Большой отдых", "cycles": "🔁 Кругов"}
    rows = []
    for key in ("work", "brk", "long", "cycles"):
        rows.append([InlineKeyboardButton(
            f"{_names[key]}: {v}{'✅' if int(cfg[key]) == v else ''}",
            callback_data=f"pomo_{key[0] if key != 'cycles' else 'c'}_{v}")
            for v in _POMO_CHOICES[key]])
    rows.append([InlineKeyboardButton("▶️ Начать с этими настройками",
                                      callback_data="pomo_start_cfg")])
    rows.append([InlineKeyboardButton("⬅️ Назад", callback_data="pomo_menu")])
    return InlineKeyboardMarkup(rows)


async def pomo_setup_cb(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    try:
        await query.answer()
    except Exception:
        pass
    cfg = _pomo_cfg_from_user_data(context)
    _txt = ("⚙️ Изменить время\n\nВыберите, сколько длится учёба и отдых, "
            "и сколько кругов сделать (✅ — текущий выбор):")
    try:
        await query.edit_message_text(_txt, reply_markup=_pomo_setup_kb(cfg))
    except Exception:
        await context.bot.send_message(chat_id=int(query.from_user.id),
                                       text=_txt, reply_markup=_pomo_setup_kb(cfg))
    return None


async def pomo_pick_cb(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Выбор длительности: pomo_w_25 / pomo_b_5 / pomo_l_15 / pomo_c_4."""
    query = update.callback_query
    await query.answer()
    try:
        _kind, _val = query.data.split("_")[1], int(query.data.split("_")[2])
    except (IndexError, ValueError):
        return None
    _kmap = {"w": "work", "b": "brk", "l": "long", "c": "cycles"}
    key = _kmap.get(_kind)
    if key is None or _val not in _POMO_CHOICES.get(key, []):
        return None
    cfg = _pomo_cfg_from_user_data(context)
    cfg[key] = _val
    context.user_data['pomo_cfg'] = cfg
    _txt = ("⚙️ Изменить время\n\nВыберите, сколько длится учёба и отдых, "
            "и сколько кругов сделать (✅ — текущий выбор):")
    try:
        await query.edit_message_text(_txt, reply_markup=_pomo_setup_kb(cfg))
    except Exception:
        pass
    return None


async def pomo_start_cb(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Старт помодоро-сессии: одна активная сессия на пользователя."""
    query = update.callback_query
    uid = str(query.from_user.id)
    user = get_user(uid)
    if not user:
        user = User(uid)
    sessions = _pomo_load_sessions()
    if _pomo_get_session(uid, sessions):
        # СЕССИЯ УЖЕ ИДЁТ: именно этот answer показит алерт (двойного нет).
        try:
            await query.answer("Сессия уже идёт — остановите её кнопкой «⏹».",
                               show_alert=True)
        except Exception:
            pass
        return None
    await query.answer()
    cfg = (_pomo_cfg_from_user_data(context)
           if query.data == "pomo_start_cfg" else dict(_POMO_DEFAULTS))
    tz_offset = getattr(user, 'timezone', 3) or 3
    now_local = _utcnow() + timedelta(hours=tz_offset)
    sess = {
        'user_id': uid,
        'work': int(cfg['work']), 'brk': int(cfg['brk']),
        'long': int(cfg['long']), 'cycles': int(cfg['cycles']),
        'cycle_done': 0, 'phase': 'work',
        'ends': (now_local + timedelta(minutes=int(cfg['work']))
                 ).strftime("%Y-%m-%d %H:%M"),
        'is_active': True,
        'created': now_local.strftime("%Y-%m-%d %H:%M"),
    }
    sessions[uid] = sess
    save_data(POMODORO_FILE, sessions)
    _txt = (f"🍅 Таймер учёбы запущен!\n\n"
            f"▶️ Учёба: {sess['work']} мин → ☕️ отдых: {sess['brk']} мин\n"
            f"🔁 Кругов: {sess['cycles']} · потом 🛌 большой отдых {sess['long']} мин\n"
            f"⏰ Этап закончится в {sess['ends'][11:]}\n\n"
            f"Удачи! Ничего нажимать не нужно — бот позовёт сам.")
    try:
        await query.edit_message_text(_txt, reply_markup=_pomo_phase_kb())
    except Exception:
        await context.bot.send_message(chat_id=int(uid), text=_txt,
                                       reply_markup=_pomo_phase_kb())
    return None


async def pomo_stop_cb(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """⏹ Полностью остановить помодоро-сессию (из меню или уведомления)."""
    query = update.callback_query
    await query.answer()
    uid = str(query.from_user.id)
    sessions = _pomo_load_sessions()
    sess = sessions.get(uid)
    _kb = None
    if isinstance(sess, dict) and sess.get('is_active'):
        sess['is_active'] = False
        sess['stopped_at'] = datetime.now().strftime("%Y-%m-%d %H:%M")
        sessions[uid] = sess
        save_data(POMODORO_FILE, sessions)
        _n_done = int(sess.get('cycle_done', 0) or 0)
        _txt = (f"⏹ Таймер учёбы остановлен.\nСделано кругов: {_n_done} из "
                f"{sess.get('cycles', 4)}.")
        _kb = InlineKeyboardMarkup([[InlineKeyboardButton(
            "▶️ Запустить заново", callback_data="pomo_menu")]])
    else:
        _txt = "Активного таймера учёбы нет."
    try:
        await query.edit_message_text(_txt, reply_markup=_kb)
    except Exception:
        await context.bot.send_message(chat_id=int(uid), text=_txt,
                                       reply_markup=_kb)
    return None


async def pomo_skip_cb(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """⏭ Досрочно завершить текущую фазу — тикер переключит её в течение 30 с."""
    query = update.callback_query
    uid = str(query.from_user.id)
    sessions = _pomo_load_sessions()
    sess = _pomo_get_session(uid, sessions)
    if not sess:
        try:
            await query.answer("Активной сессии нет.", show_alert=True)
        except Exception:
            pass
        return None
    sess['ends'] = datetime.now().strftime("%Y-%m-%d %H:%M")
    sessions[uid] = sess
    save_data(POMODORO_FILE, sessions)
    try:
        await query.answer("Этап будет закрыт в течение полминуты.")
    except Exception:
        pass
    return None


async def _tick_send_pomodoro(bot):
    """Часть тикера (22.28): закрывает созревшие фазы помодоро и запускает
    следующие. Переживает рестарт — сессии лежат в POMODORO_FILE."""
    try:
        sessions = _pomo_load_sessions()
    except Exception as e:
        logger.error(f"tick/pomodoro: load error: {e}")
        return
    if not sessions:
        return
    now_utc = _utcnow()
    changed = False
    for uid, s in list(sessions.items()):
        try:
            if not isinstance(s, dict) or not s.get('is_active'):
                continue
            try:
                ends_local = datetime.strptime(str(s.get('ends')), "%Y-%m-%d %H:%M")
            except (TypeError, ValueError):
                sessions.pop(uid, None)
                changed = True
                continue
            user = get_user(uid)
            tz = getattr(user, 'timezone', 3) if user else 3
            if (now_utc - (ends_local - timedelta(hours=tz))).total_seconds() < 0:
                continue  # фаза ещё не закончилась
            phase = s.get('phase')
            if phase == 'work':
                s['cycle_done'] = int(s.get('cycle_done', 0) or 0) + 1
                if s['cycle_done'] >= int(s.get('cycles', 4) or 4):
                    nxt, dur = 'long', int(s.get('long', 15) or 15)
                else:
                    nxt, dur = 'break', int(s.get('brk', 5) or 5)
            elif phase == 'break':
                nxt, dur = 'work', int(s.get('work', 25) or 25)
            elif phase == 'long':
                # длинный перерыв закончился — сессия завершена
                sessions.pop(uid, None)
                changed = True
                try:
                    await bot.send_message(
                        chat_id=int(uid),
                        text=(f"🎉 Таймер учёбы завершён! Отличная работа: "
                              f"{s.get('cycle_done', 0)} кругов учёбы сделано.\n\n"
                              f"Запустить новую — «⏰ Таймер» → «🍅 Таймер учёбы»."),
                        reply_markup=InlineKeyboardMarkup([[
                            InlineKeyboardButton("🍅 Таймер учёбы",
                                                 callback_data="pomo_menu")]]))
                except Exception as e:
                    logger.error(f"tick/pomodoro: завершение {uid}: {e}")
                continue
            else:
                sessions.pop(uid, None)
                changed = True
                continue
            now_local = now_utc + timedelta(hours=tz)
            s['phase'] = nxt
            s['ends'] = (now_local + timedelta(minutes=dur)).strftime("%Y-%m-%d %H:%M")
            sessions[uid] = s
            changed = True
            if nxt == 'break':
                _msg = (f"🍅 Готово {s['cycle_done']} из {s.get('cycles', 4)}!\n\n"
                        f"☕️ Отдыхайте {dur} мин — отходите от учёбы, "
                        "бот напомнит, когда продолжить.")
            elif nxt == 'long':
                _msg = (f"🛌 Все круги сделаны ({s['cycle_done']})! "
                        f"Большой отдых — {dur} мин. Вы отлично поработали!")
            else:
                _msg = (f"☕️ Отдых окончен — пора за учёбу!\n\n"
                        f"▶️ Учёба {dur} мин (круг {s['cycle_done'] + 1} "
                        f"из {s.get('cycles', 4)}).")
            _msg += f"\n⏰ до {s['ends'][11:]}"
            try:
                await bot.send_message(chat_id=int(uid), text=_msg,
                                       reply_markup=_pomo_phase_kb())
                logger.info(f"tick/pomodoro: {uid} -> {nxt} ({dur} мин)")
            except Exception as e:
                logger.error(f"tick/pomodoro: send failed {uid}: {e}")
        except Exception as e:
            logger.error(f"tick/pomodoro: error on {uid}: {e}")
    if changed:
        try:
            save_data(POMODORO_FILE, sessions)
        except Exception as e:
            logger.error(f"tick/pomodoro: final save failed: {e}")


# ==================================
# === ВОЛНА 22.30: ДЕЖУРНЫЕ ===
# Каждое утро (время выбирает админ класса, дни — обычно Пн-Пт) бот случайно
# назначает дежурного(ых) из класса: дежурному приходит «Вы сегодня дежурный»,
# всему классу — «Сегодня дежурный: имя». Под утренним сообщением кнопка
# «🤒 Заболел(а)»: заболевшего заменяет следующий из очереди, заболевший
# уходит в её конец. Когда очередь кончается — перемешивается заново.
# Полный список грядущих дежурных — «📋 Ещё» → «🕐 Дежурные».
# Состояние — ПОЛЯ КЛАССА (duty_*), переживает рестарт; план задач в тикере.
# ==================================

_DUTY_DAYS_RU = ["Пн", "Вт", "Ср", "Чт", "Пт", "Сб", "Вс"]
_DUTY_DAYS_RU_FULL = ["Понедельник", "Вторник", "Среда", "Четверг",
                      "Пятница", "Суббота", "Воскресенье"]
_DUTY_MAX_LATE_MIN = 600  # догоняем утро, если хостинг проспал (до 10 ч)


def _duty_pool(class_obj):
    """Кто вообще может дежурить: ученики+админы класса минус заблокированные
    минус исключённые админом, и только зарегистрированные (есть в базе)."""
    members = list(dict.fromkeys(
        [str(m) for m in (getattr(class_obj, "students", []) or [])] +
        [str(m) for m in (getattr(class_obj, "admins", []) or [])]
    ))
    blocked = set(str(b) for b in (getattr(class_obj, "blocked_users", []) or []))
    excluded = set(str(e) for e in (getattr(class_obj, "duty_excluded", []) or []))
    return [m for m in members if m not in blocked and m not in excluded
            and get_user(m) is not None]


def _duty_clean_queue(class_obj):
    """Чистит очередь от тех, кто больше не может дежурить (вышел/заблокирован/
    исключён). Возвращает (очередь, менялось_ли)."""
    pool = set(_duty_pool(class_obj))
    q = [str(u) for u in (getattr(class_obj, "duty_queue", []) or [])]
    nq = [u for u in q if u in pool]
    class_obj.duty_queue = nq
    return nq, nq != q


def _duty_member_name(uid, with_id=False):
    """Имя участника для объявлений (как в «ДР одноклассников» — first_name).
    ВОЛНА 22.30: имя экранируется — сообщения дежурных идут с parse_mode=HTML,
    а в first_name может быть «<», «&» и т.п., что сломало бы разметку."""
    u = get_user(str(uid))
    if u:
        base = (getattr(u, "first_name", "") or "").strip() or \
               (("@ " + u.username) if getattr(u, "username", "") else None) or \
               f"Ученик {str(uid)[-4:]}"
    else:
        base = f"Ученик {str(uid)[-4:]}"
    try:
        from html import escape as _html_escape
        base = _html_escape(base)
    except Exception:
        pass
    return f"{base} ({str(uid)[-4:]})" if with_id else base


def _duty_tz(class_obj):
    """Часовой пояс класса: по автору класса (админ задаёт время в СВОЁМ
    часовом поясе), с запасным вариантом — UTC+3."""
    try:
        creator = get_user(str(getattr(class_obj, "creator_id", "")) or "")
        if creator is not None:
            tz = float(getattr(creator, "timezone", 3) or 3)
            return tz
    except (TypeError, ValueError):
        pass
    return 3.0



def _duty_is_admin(uid, class_obj):
    """ВОЛНА 22.30: админ ИМЕННО этого класса (список admins класса)."""
    return str(uid) in [str(a) for a in (getattr(class_obj, "admins", []) or [])]


def _duty_is_day_on(class_obj, weekday):
    return int(weekday) in [int(d) for d in (getattr(class_obj, "duty_days", []) or [])]


def _duty_custom_names(class_obj):
    """ВОЛНА 22.35: список имён СВОЕГО графика (без ТГ-аккаунтов) или []."""
    dc = getattr(class_obj, "duty_custom", None)
    if not isinstance(dc, dict):
        return []
    names = [str(n).strip()[:60] for n in (dc.get("names") or []) if str(n).strip()]
    return names


def _duty_custom_plan_for(class_obj, occ):
    """ВОЛНА 22.35: имена из плана своего графика на дату occ или None."""
    dc = getattr(class_obj, "duty_custom", None)
    if not isinstance(dc, dict):
        return None
    plan = dc.get("plan") if isinstance(dc.get("plan"), dict) else {}
    names = plan.get(occ)
    if isinstance(names, list) and names:
        return [str(n).strip()[:60] for n in names if str(n).strip()]
    return None


def _duty_pick_today(class_obj, occ):
    """Выбирает дежурных на дату occ. Если на сегодня уже есть ручное
    назначение (duty_today) — используем его. Иначе берём голову очереди;
    если в очереди меньше нужного — перемешиваем ВСЁ заново (рандом под
    каждый день, как просил пользователь).
    ВОЛНА 22.35: режим СВОЕГО графика — имена берутся из плана на дату
    (duty_custom.plan), а если даты в плане нет — случайные имена из списка.
    Возвращает список uid (может быть пустым — дежурить некому)."""
    need = max(1, min(3, int(getattr(class_obj, "duty_count", 1) or 1)))
    today = getattr(class_obj, "duty_today", None)
    if isinstance(today, dict) and today.get("date") == occ:
        names = today.get("names")
        if isinstance(names, list) and names:
            class_obj.duty_today = {"date": occ, "ids": [], "names": names}
            return []
        ids = [str(i) for i in (today.get("ids") or [])]
        pool = set(_duty_pool(class_obj))
        ids = [i for i in ids if i in pool]
        if ids:
            class_obj.duty_today = {"date": occ, "ids": ids}
            return ids
    # --- ВОЛНА 22.35: свой график (имена без аккаунтов) ---
    if _duty_custom_names(class_obj):
        plan_names = _duty_custom_plan_for(class_obj, occ)
        if plan_names:
            selected_names = plan_names[:3]
        else:
            pool_names = _duty_custom_names(class_obj)
            random.shuffle(pool_names)
            selected_names = pool_names[:need]
        class_obj.duty_today = {"date": occ, "ids": [], "names": selected_names}
        return []
    queue, _ch = _duty_clean_queue(class_obj)
    if len(queue) < need:
        pool = _duty_pool(class_obj)
        if not pool:
            class_obj.duty_today = {"date": occ, "ids": []}
            return []
        random.shuffle(pool)
        queue = pool
    selected = queue[:need]
    class_obj.duty_queue = queue[need:]
    class_obj.duty_today = {"date": occ, "ids": selected}
    return selected


def _duty_upcoming_schedule(class_obj, local_today, days_ahead=14):
    """Готовит план «дата → [имена]» на ближайшие дни дежурств по очереди
    (для списка «🕐 Дежурные»). Очередь НЕ меняет — просто визуализация."""
    queue, _ch = _duty_clean_queue(class_obj)
    days = sorted({int(d) for d in (getattr(class_obj, "duty_days", []) or [])})
    if not days:
        return []
    need = max(1, min(3, int(getattr(class_obj, "duty_count", 1) or 1)))
    plan = []
    d = local_today
    qi = 0
    for _ in range(days_ahead):
        d = d + timedelta(days=1)
        if d.weekday() not in days:
            continue
        chunk = queue[qi:qi + need]
        qi += need
        if not chunk:
            plan.append((d, [None]))  # к этому дню очередь кончится — новый рандом
            continue
        plan.append((d, chunk))
        if qi >= len(queue):
            break
    return plan


def _duty_overview_text(class_obj, local_today, for_admin=False):
    """Текст «🕐 Дежурные»: кто сегодня + план на ближайшие дни."""
    tz = _duty_tz(class_obj)
    occ = local_today.strftime("%Y-%m-%d")
    lines = [f"🕐 <b>Дежурные</b> — {getattr(class_obj, 'class_name', '')}", ""]
    if not getattr(class_obj, "duty_enabled", False):
        lines.append("Функция ВЫКЛЮЧЕНА. Попросите админа включить её: "
                     "админ-панель → «🕐 Дежурные».")
        return "\n".join(lines)
    days = sorted({int(d) for d in class_obj.duty_days})
    days_str = " ".join(_DUTY_DAYS_RU[d] for d in days) if days else "—"
    lines.append(f"⏰ Время: <b>{getattr(class_obj, 'duty_time', '07:30')}</b> · "
                 f"дни: <b>{days_str}</b> · "
                 f"дежурных в день: <b>{getattr(class_obj, 'duty_count', 1)}</b>")
    lines.append("")
    today = getattr(class_obj, "duty_today", None)
    if isinstance(today, dict) and today.get("date") == occ and today.get("names"):
        # ВОЛНА 22.35: свой график — сегодня дежурят ПО ИМЕНАМ из списка
        names = ", ".join(str(n) for n in today["names"])
        lines.append(f"📌 Сегодня ({occ}) дежурят: <b>{names}</b>")
    elif isinstance(today, dict) and today.get("date") == occ and today.get("ids"):
        names = ", ".join(_duty_member_name(i) for i in today["ids"])
        lines.append(f"📌 Сегодня ({occ}) дежурят: <b>{names}</b>")
    elif _duty_is_day_on(class_obj, local_today.weekday()):
        lines.append("📌 Сегодня дежурных ещё не объявляли.")
    else:
        lines.append("📌 Сегодня не день дежурств.")
    lines.append("")
    # ВОЛНА 22.35: свой график — план из заданных дат (ближайшие 14 дней)
    dc = getattr(class_obj, "duty_custom", None)
    if isinstance(dc, dict):
        cnames = [str(n) for n in (dc.get("names") or []) if str(n).strip()]
        cplan = dc.get("plan") if isinstance(dc.get("plan"), dict) else {}
        if cnames:
            lines.append(f"📥 <b>Свой график</b> — {len(cnames)} чел. "
                         "(имена из списка, без привязки к аккаунтам)")
            future = sorted(k for k in cplan.keys()
                            if isinstance(k, str) and k >= occ)[:14]
            if future:
                lines.append("📅 <b>План по датам:</b>")
                for k in future:
                    try:
                        d = datetime.strptime(k, "%Y-%m-%d").date()
                        ds = f"{_DUTY_DAYS_RU_FULL[d.weekday()]} {d.strftime('%d.%m')}"
                    except Exception:
                        ds = k
                    names = ", ".join(str(n) for n in (cplan[k] or [])[:3])
                    lines.append(f"  • {ds} — {names}")
            else:
                lines.append("Даты не заданы — в дни дежурств бот выбирает "
                             "случайные имена из списка.")
            return "\n".join(lines)
    plan = _duty_upcoming_schedule(class_obj, local_today)
    if plan:
        lines.append("📅 <b>Дальше по очереди:</b>")
        for d, ids in plan:
            ds = d.strftime("%d.%m")
            dn = _DUTY_DAYS_RU_FULL[d.weekday()]
            if ids == [None]:
                lines.append(f"  • {dn} {ds} — 🔀 (новый случайный подбор)")
            else:
                names = ", ".join(_duty_member_name(i) for i in ids)
                lines.append(f"  • {dn} {ds} — {names}")
    else:
        lines.append("Очередь пуста — в день дежурства состав перемешается заново.")
    return "\n".join(lines)


async def _duty_announce(bot, class_obj, selected, sick_note=None):
    """Утреннее объявление: дежурному — «вы сегодня дежурный» с кнопкой
    «🤒 Я заболел(а)», всем — «Сегодня дежурный: …» (у админов — кнопки
    «заболел» на каждого дежурного). sick_note — если это замена болевшего.
    ВОЛНА 22.35: если selected — СТРОКИ-имена (свой график), рассылаем
    текст «Сегодня дежурят: …» без личных сообщений.
    ВОЛНА 22.36: в режиме имён админы получают копию с кнопками
    «🤒 заболел(а)» / «🚫 не будет» на каждого дежурного — нажатие передаёт
    дежурство следующему по списку, а заболевший уходит в конец списка."""
    if selected and all(isinstance(i, str) and not i.isdigit() for i in selected):
        names = ", ".join(str(i) for i in selected) if selected else "—"
        members = [str(m) for m in dict.fromkeys(
            [str(m) for m in (class_obj.students or [])] +
            [str(m) for m in (class_obj.admins or [])])]
        blocked = set(str(b) for b in (class_obj.blocked_users or []))
        members = [m for m in members if m not in blocked and get_user(m)]
        # ВОЛНА 22.36: админам — кнопки замены по индексу в списке дежурных
        admin_rows = []
        for i, nm in enumerate(selected):
            admin_rows.append([
                InlineKeyboardButton(f"🤒 {str(nm)[:20]} — заболел(а)",
                                     callback_data=f"duty_cns_{i}"),
                InlineKeyboardButton(f"🚫 не будет", callback_data=f"duty_cnn_{i}"),
            ])
        admin_kb = InlineKeyboardMarkup(admin_rows) if admin_rows else None
        for uid in members:
            is_admin = str(uid) in [str(a) for a in (class_obj.admins or [])]
            try:
                await bot.send_message(
                    chat_id=int(uid),
                    text=("🕐 <b>Сегодня дежурят: " + names + "</b>\n"
                          + (sick_note if sick_note else "")).rstrip(),
                    parse_mode=ParseMode.HTML,
                    reply_markup=admin_kb if is_admin else None)
            except Exception as e:
                logger.error(f"duty announce(names): send failed {uid}: {e}")
        return
    members = [str(m) for m in dict.fromkeys(
        [str(m) for m in (class_obj.students or [])] +
        [str(m) for m in (class_obj.admins or [])])]
    blocked = set(str(b) for b in (class_obj.blocked_users or []))
    members = [m for m in members if m not in blocked and get_user(m)]
    names = ", ".join(_duty_member_name(i) for i in selected) if selected else "—"
    officer_kb = InlineKeyboardMarkup([[
        InlineKeyboardButton("🤒 Я заболел(а)", callback_data="duty_sick")]])
    for uid in members:
        try:
            if uid in selected:
                await bot.send_message(
                    chat_id=int(uid),
                    text=("📅 <b>Вы сегодня дежурный!</b>\n\n"
                          "Не забудьте про свои обязанности. Хорошего дня!\n\n"
                          "Если приболели — нажмите кнопку ниже, и дежурство "
                          "перейдёт следующему, а вы вернётесь в конец очереди.")
                          + (f"\n\n{sick_note}" if sick_note else ""),
                    parse_mode=ParseMode.HTML,
                    reply_markup=officer_kb)
                continue
            is_admin = str(uid) in [str(a) for a in (class_obj.admins or [])]
            kb = None
            if is_admin and selected:
                # ВОЛНА 22.36: у админа на каждого дежурного ДВЕ кнопки —
                # «заболел(а)» и «не будет» (обе передают дежурство дальше)
                rows = []
                for i in selected:
                    if str(i) == str(uid):
                        continue
                    _nm = _duty_member_name(i)
                    rows.append([InlineKeyboardButton(
                        f"🤒 {_nm} — заболел(а)",
                        callback_data=f"duty_sick_uid_{i}"),
                        InlineKeyboardButton("🚫 не будет",
                                             callback_data=f"duty_skip_uid_{i}")])
                if rows:
                    kb = InlineKeyboardMarkup(rows)
            await bot.send_message(
                chat_id=int(uid),
                text=("🕐 <b>Сегодня дежурный(е): " + names + "</b>\n"
                      + (sick_note if sick_note else "")).rstrip(),
                parse_mode=ParseMode.HTML,
                reply_markup=kb)
        except Exception as e:
            logger.error(f"duty announce: send failed {uid}: {e}")


async def _tick_send_duty(bot):
    """ВОЛНА 22.30: часть тикера — утренний подбор дежурных по классам."""
    try:
        classes = load_classes()
    except Exception as e:
        logger.error(f"tick/duty: load classes failed: {e}")
        return
    if not classes:
        return
    now_utc = _now_utc()
    for class_code, class_obj in classes.items():
        try:
            if not getattr(class_obj, "duty_enabled", False):
                continue
            tz = _duty_tz(class_obj)
            local_now = now_utc + timedelta(hours=tz)
            if not _duty_is_day_on(class_obj, local_now.weekday()):
                continue
            occ = local_now.strftime("%Y-%m-%d")
            if getattr(class_obj, "duty_last_date", None) == occ:
                continue  # сегодня уже объявляли
            due, too_late, slot_occ = _is_daily_time_due(
                local_now, getattr(class_obj, "duty_time", "07:30"),
                max_late_minutes=_DUTY_MAX_LATE_MIN)
            if not due or too_late or slot_occ != occ:
                continue  # время не подошло / проснулись слишком поздно / вчерашний слот
            # Атомарная пометка ДО отправки — рестарт не задублирует объявления.
            class_obj.duty_last_date = occ
            save_class(class_obj)
            selected = _duty_pick_today(class_obj, occ)
            save_class(class_obj)
            await _duty_announce(bot, class_obj, selected)
            logger.info(f"tick/duty: {class_code} -> {selected} ({occ})")
        except Exception as e:
            logger.error(f"tick/duty: error on {class_code}: {e}")


def _duty_reassign_sick(class_obj, sick_uid, occ):
    """Заболел дежурный: на смену идёт СЛЕДУЮЩИЙ из очереди, заболевший
    уходит В КОНЕЦ очереди. Возвращает (новый_дежурный|None, был_ли_в_очереди)."""
    pool = set(_duty_pool(class_obj))
    today = getattr(class_obj, "duty_today", None)
    ids = [str(i) for i in (today.get("ids") or [])] \
        if isinstance(today, dict) and today.get("date") == occ else []
    sick_uid = str(sick_uid)
    ids = [i for i in ids if i != sick_uid]
    queue, _ch = _duty_clean_queue(class_obj)
    queue = [q for q in queue if q not in ids and q != sick_uid]
    candidate = None
    if queue:
        candidate = queue.pop(0)
    else:
        rest = [p for p in _duty_pool(class_obj) if p not in ids]
        if rest:
            random.shuffle(rest)
            candidate = rest.pop(0)
            queue = rest
    if candidate:
        ids.append(candidate)
    # заболевший — в КОНЕЦ очереди (если вообще в ротации)
    if sick_uid in pool:
        queue = [q for q in queue if q != sick_uid]
        queue.append(sick_uid)
    class_obj.duty_queue = queue
    class_obj.duty_today = {"date": occ, "ids": ids}
    return candidate


def _duty_ensure_admin_class(context, uid_str):
    """Класс для дежурных-колбэков: рабочий класс админ-панели или свой."""
    cls = None
    cur = context.user_data.get('current_admin_class')
    if cur:
        cls = get_class_by_code(cur) if isinstance(cur, str) else cur
    if cls is None:
        cls = get_class_by_user(uid_str)
    return cls


