@timeout(CONVERSATION_TIMEOUT)
async def dev_instant_broadcast_handler(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Отправка анонимной (без подписи) рассылки всем."""
    user_id = str(update.effective_user.id)
    if user_id != DEVELOPER_ID:
        await update.message.reply_text("Доступ запрещён.")
        return MAIN_MENU
    message_text = update.message.text
    users = load_users()
    sent = 0
    for uid, user in users.items():
        if getattr(user, 'is_blocked', False):
            continue
        try:
            await context.bot.send_message(chat_id=int(uid), text=message_text)
            sent += 1
        except Exception as e:
            logger.error(f"Ошибка анонимной рассылки {uid}: {e}")
        # ЗАЩИТА (22.13): пауза между отправками (анти-флуд).
        await asyncio.sleep(0.05)
    await update.message.reply_text(
        f"✅ Сообщение отправлено {sent} пользователям (без подписи разработчика)."
    )
    return await developer_panel(update, context)


# ==================================
# === ВОЛНА 22.10: ОПРОСЫ ===
# ==================================
# Просьба пользователя: «добавь ещё чтобы админ и разработчик мог делать
# опросы в боте». Админ класса — «📊 Опрос классу» (админ-панель), разработчик
# — «📊 Опрос всем» (панель разработчика). Поток: вопрос → варианты (2–10,
# по одному в строке) → превью → «✅ Отправить» → бот рассылает НАСТОЯЩИЙ
# ============================================================
# === ВОЛНА 22.12: ОБЩАЯ БАЗА РЕШЕНИЙ КЛАССА ===
# Участники класса отправляют готовые решения (фото/файл); публикует их
# староста (админ класса) — МОДЕРАЦИЯ; автор может отправить АНОНИМНО.
# Одобренные решения лежат в базе, любой участник класса может открыть и
# списать. О новом решении бот присылает участникам сообщение — эти
# уведомления отключаются в ⚙️ Настройках или в меню базы.
# Хранение: SOLUTIONS_FILE (переживает рестарт бота). Файл решения копируется
# ботом в cloud-канал (как шифры Сейфа) — оригинал в личке не нужен.
# ============================================================

SOL_WAIT_FILE = 133  # (константа объявлена в блоке состояний выше)

_SOL_MAX_PER_CLASS = 50  # храним последние 50 решений на класс (FIFO)
_SOL_SUBJECT_MAX = 100

# ВОЛНА 22.13: автоудаление решений. Отправитель выбирает срок при отправке,
# староста может поменять его при модерации, а староста класса может включить
# АВТОМАТИЧЕСКУЮ модерацию и задать общий срок удаления публикаций.
SOL_TTLS = (
    ("1 час", 1),
    ("1 день", 24),
    ("3 дня", 72),
    ("1 неделя", 168),
    ("1 месяц", 720),
    ("не удалять", 0),
)
_SOL_EXPIRE_CHECK_EVERY = 300  # чистка просроченных — раз в 5 минут

_SOL_CACHE = None


def _solutions_all():
    """Весь реестр решений: {class_code: [entry…]} (ленивая загрузка)."""
    global _SOL_CACHE
    if _SOL_CACHE is None:
        data = load_data(SOLUTIONS_FILE, {})
        _SOL_CACHE = data if isinstance(data, dict) else {}
    return _SOL_CACHE


def _solutions_save():
    save_data(SOLUTIONS_FILE, _solutions_all())


def _sol_class_entries(class_code):
    return _solutions_all().setdefault(str(class_code or ""), [])


def _sol_gen_id():
    return "sol_" + "".join(random.choices(
        string.ascii_lowercase + string.digits, k=8))


def _sol_find_entry(sol_id):
    for _code, entries in _solutions_all().items():
        for e in entries:
            if isinstance(e, dict) and e.get("id") == sol_id:
                return e
    return None


# === ВОЛНА 22.13: автоудаление решений ===

def _sol_ttl_label(ttl_h):
    """Читаемое имя срока хранения по часам (0 = не удалять)."""
    for _lbl, _h in SOL_TTLS:
        if int(_h or 0) == int(ttl_h or 0):
            return _lbl
    return f"{ttl_h} ч" if ttl_h else "не удалять"


def _sol_apply_ttl(entry, ttl_h):
    """Записать в решение срок хранения (expire_ts). ttl_h=0 — не удалять."""
    ttl_h = int(ttl_h or 0)
    entry["ttl_h"] = ttl_h
    entry["expire_ts"] = (time.time() + ttl_h * 3600) if ttl_h > 0 else None


def _sol_alive_entries(class_code):
    """Только не просроченные одобренные... (все живые) решения класса."""
    now = time.time()
    out = []
    for e in _sol_class_entries(class_code):
        if not isinstance(e, dict):
            continue
        exp = e.get("expire_ts")
        if exp and float(exp) < now:
            continue
        out.append(e)
    return out


async def _sol_delete_channel_file(context, entry):
    """Лучшие усилия: удалить шифр файла решения из канала-хранилища."""
    _f = entry.get("file") or {}
    _ch, _mid = int(_f.get("ch") or 0), int(_f.get("mid") or 0)
    if not _ch or not _mid:
        return
    try:
        await context.bot.delete_message(chat_id=_ch, message_id=_mid)
    except Exception:
        pass


async def _sol_purge_expired(context):
    """ВОЛНА 22.13: удаляет просроченные решения (любой статус) из реестра
    и их шифры из канала. Вызывается из единого тикера раз в 5 минут."""
    now = time.time()
    removed = []
    for code, entries in _solutions_all().items():
        keep = []
        for e in entries:
            if not isinstance(e, dict):
                continue
            exp = e.get("expire_ts")
            if exp and float(exp) < now:
                removed.append(e)
                continue
            keep.append(e)
        _solutions_all()[code] = keep
    if removed:
        _solutions_save()
        for e in removed[:20]:  # не больше 20 удалений из канала за цикл
            await _sol_delete_channel_file(context, e)
        logger.info(f"solutions: автоудалено просроченных решений: {len(removed)}")


