async def share_list_cb(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """ВОЛНА 22.12: «🗂 Мои активные ссылки» — список с остатком времени
    и лимитом, у каждой — кнопка «Отозвать»."""
    query = update.callback_query
    try:
        await query.answer()
    except Exception:
        pass
    _uid = str(query.from_user.id)
    now = time.time()
    mine = []
    for tok, r in _share_all().items():
        if (isinstance(r, dict) and str(r.get("owner")) == _uid
                and (r.get("expires_ts") or 0) > now and not r.get("revoked")):
            mine.append((tok, r))
    if not mine:
        try:
            await query.edit_message_text(
                "🗂 Активных ссылок нет.\n\nСоздайте: 🔐 Сейф → 📦 Мои файлы → "
                "🔗 Поделиться.",
                reply_markup=InlineKeyboardMarkup([[
                    InlineKeyboardButton("⬅️ К настройкам ссылки",
                                         callback_data="share_back")]]))
        except Exception:
            pass
        return MAIN_MENU
    kb = []
    lines = [f"🗂 ВАШИ АКТИВНЫЕ ССЫЛКИ: {len(mine)}\n"]
    for tok, r in mine[:10]:
        left = int((r["expires_ts"] - now) // 60)
        _lim = r.get("limit") or 0
        _lim_s = f"{r.get('used', 0)}/{_lim}" if _lim else f"{r.get('used', 0)}/∞"
        lines.append(f"• {tok} · {_lim_s} · осталось {_fmt_eta(left * 60)}")
        kb.append([InlineKeyboardButton(
            f"🚫 Отозвать {tok}", callback_data=f"share_revoke_{tok}")])
    kb.append([InlineKeyboardButton("⬅️ К настройкам ссылки",
                                    callback_data="share_back")])
    try:
        await query.edit_message_text("\n".join(lines),
                                      reply_markup=InlineKeyboardMarkup(kb))
    except Exception:
        pass
    return MAIN_MENU


async def share_revoke_cb(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """ВОЛНА 22.12: досрочный отзыв ссылки в 1 клик."""
    query = update.callback_query
    try:
        await query.answer()
    except Exception:
        pass
    tok = query.data[len("share_revoke_"):]
    rec = _share_all().get(tok)
    if not rec or str(rec.get("owner")) != str(query.from_user.id):
        await query.answer("Ссылка не найдена.", show_alert=True)
        return MAIN_MENU
    rec["revoked"] = True
    _share_save()
    _share_all().pop(tok, None)
    _share_save()
    try:
        await query.edit_message_text(f"🚫 Ссылка {tok} отозвана — больше не работает.")
    except Exception:
        pass
    return MAIN_MENU


# === ПОЛУЧЕНИЕ ПО ССЫЛКЕ (deep-link /start dl_xxx или код) ===

async def share_redeem_start(update, context, tok):
    """Проверяет токен и либо выдаёт файлы, либо просит PIN (state).
    Вызывается из start() (пользователь уже настроен).
    ВОЛНА 22.13: rate-limit на подбор токенов и проверка формата."""
    user_id = str(update.effective_user.id)
    # ЗАЩИТА: перебор токенов (dl_xxx) — не чаще 8 попыток в минуту на
    # пару (пользователь+токен): разные токены не мешают друг другу.
    if is_user_spamming(user_id + ":" + str(tok or ""), "share_redeem",
                        0.4, 8, 60):
        await update.effective_message.reply_text(
            "⏳ Слишком много попыток открыть ссылки. Подождите минуту.")
        return MAIN_MENU
    if not re.fullmatch(r"dl_[A-Za-z0-9]{3,24}", str(tok or "")):
        await update.effective_message.reply_text(
            "🙈 Ссылка повреждена или подделана.")
        return MAIN_MENU
    rec = _share_all().get(tok)
    if rec is None:
        await update.effective_message.reply_text(
            "🙈 Ссылка не найдена — она сгорела, отозвана, истекла или по ней "
            "уже исчерпан лимит скачиваний.")
        return MAIN_MENU
    now = time.time()
    if rec.get("expires_ts", 0) < now:
        _share_all().pop(tok, None)
        _share_save()
        await update.effective_message.reply_text(
            "⏳ Срок действия ссылки истёк — файлы больше не выдаются.")
        return MAIN_MENU
    if rec.get("limit", 0) and rec.get("used", 0) >= rec["limit"]:
        _share_all().pop(tok, None)
        _share_save()
        await update.effective_message.reply_text(
            "🔥 Лимит скачиваний по ссылке исчерпан — ссылка сгорела.")
        return MAIN_MENU
    if rec.get("pw"):
        # ЗАЩИТА от брутфорса PIN: после 5 неверных вводов ссылка
        # «запирается» на 10 минут, владелец получает уведомление.
        lock_until = float(rec.get("pin_lock_until") or 0)
        if lock_until > now:
            await update.effective_message.reply_text(
                "🔒 Ссылка временно заблокирована: слишком много неверных "
                "попыток PIN. Попробуйте через "
                + _fmt_eta(int(lock_until - now)) + ".")
            return MAIN_MENU
        context.user_data["share_pin_tok"] = tok
        await update.effective_message.reply_text(
            "🔒 Эта ссылка защищена паролем. Пришлите PIN одним сообщением:")
        return SHARE_PIN_WAIT
    return await _share_redeem_deliver(update, context, tok)


@timeout(CONVERSATION_TIMEOUT)
async def share_pin_receive(update: Update,
                            context: ContextTypes.DEFAULT_TYPE):
    """ВОЛНА 22.12: PIN получателя ссылки. ВОЛНА 22.13: анти-брутфорс —
    5 неверных попыток запирают ссылку на 10 минут + весть владельцу."""
    msg = update.message
    tok = context.user_data.pop("share_pin_tok", None)
    if not tok:
        await msg.reply_text("Сессия потеряна — откройте ссылку заново.")
        return MAIN_MENU
    rec = _share_all().get(tok)
    pin = (msg.text or "").strip()[:64]
    if rec is None:
        await msg.reply_text("🙈 Ссылка уже не работает.")
        return MAIN_MENU
    now = time.time()
    if float(rec.get("pin_lock_until") or 0) > now:
        await msg.reply_text(
            "🔒 Слишком много неверных попыток — ссылка заперта на 10 минут.")
        return MAIN_MENU
    if pin != str(rec.get("pw") or ""):
        fails = int(rec.get("pin_fails", 0) or 0) + 1
        rec["pin_fails"] = fails
        _share_save()
        if fails >= 5:
            rec["pin_lock_until"] = now + 600
            _share_save()
            try:
                await context.bot.send_message(
                    chat_id=int(rec.get("owner")),
                    text=f"🛡 Кто-то 5 раз неверно ввёл PIN вашей ссылки "
                         f"{tok} — она заперта на 10 минут. Если это не вы, "
                         "ссылку можно отозвать: Сейф → 🗂 Мои активные ссылки.")
            except Exception:
                pass
            context.user_data.pop("share_pin_tok", None)
            await msg.reply_text(
                "🔒 Ссылка заперта на 10 минут: слишком много неверных PIN.")
            return MAIN_MENU
        context.user_data["share_pin_tok"] = tok
        await msg.reply_text(
            f"❌ Неверный PIN. Попыток до блокировки: {5 - fails}.")
        return SHARE_PIN_WAIT
    rec["pin_fails"] = 0
    _share_save()
    return await _share_redeem_deliver(update, context, tok)


async def _share_redeem_deliver(update, context, tok):
    """Выдача файлов по ссылке + счётчик + уведомление владельца.
    ВОЛНА 22.13: элементы ftype="seal" скачиваются из канала ШИФОМ и
    расшифровываются ключом бота в момент выдачи; легаси-"document"
    (до 22.13) по-прежнему копируются напрямую."""
    rec = _share_all().get(tok)
    if rec is None:
        await update.effective_message.reply_text(
            "🙈 Ссылка уже сгорела — файлы больше не выдаются.")
        return MAIN_MENU
    chat_id = update.effective_chat.id
    protect = bool(rec.get("protect"))
    ok = 0
    for item in rec.get("items") or []:
        try:
            if item.get("ftype") == "url":
                await context.bot.send_message(
                    chat_id=chat_id,
                    text=f"🔗 {item.get('title') or 'Ссылка'}\n{item.get('url')}",
                    protect_content=protect,
                    disable_web_page_preview=False)
                ok += 1
            elif item.get("ftype") == "seal":
                payload = None
                if item.get("fid"):
                    try:
                        payload = await _vault_botapi_download(context, item["fid"])
                    except Exception:
                        payload = None
                if payload is None:
                    _ch, _mid = int(item.get("ch") or 0), int(item.get("mid") or 0)
                    client = await _mt_client() if _ch and _mid else None
                    if client is not None:
                        _m, doc = await _mt_fetch_document(client, _ch, _mid, 0)
                        if doc is not None:
                            buf = io.BytesIO()
                            await _mt_download_stream(
                                client, doc, int(getattr(doc, "size", 0) or 0),
                                buf.write, None, "")
                            payload = buf.getvalue()
                if not payload:
                    raise RuntimeError("шифр файла не найден")
                _meta, plain = await asyncio.to_thread(_seal_unpack, payload)
                payload = b""
                _name = _dvf2_safe_name(str(_meta.get("n") or "file.bin"))
                await context.bot.send_document(
                    chat_id=chat_id,
                    document=InputFile(plain, filename=_name),
                    caption=None, protect_content=protect)
                plain = b""
                ok += 1
            else:
                await context.bot.copy_message(
                    chat_id=chat_id, from_chat_id=int(item.get("ch") or 0),
                    message_id=int(item.get("mid") or 0),
                    protect_content=protect)
                ok += 1
            await asyncio.sleep(0.06)  # анти-флуд между файлами
        except Exception as e:
            logger.error(f"share deliver: {e}")
    if not ok:
        await update.effective_message.reply_text(
            "❌ Не удалось выдать файлы — сообщите отправителю ссылки.")
        return MAIN_MENU
    rec["used"] = int(rec.get("used", 0)) + 1
    _stat_bump("share_redeemed")
    _exhausted = bool(rec.get("limit") and rec["used"] >= rec["limit"])
    if _exhausted:
        _share_all().pop(tok, None)
    _share_save()
    try:
        await context.bot.send_message(
            chat_id=int(rec.get("owner") or 0),
            text=(f"📥 Вашу ссылку ({rec.get('ts', '')}) использовали: "
                  f"выдано {ok} файл(ов)."
                  + ("\n🔥 Лимит исчерпан — ссылка деактивирована." if _exhausted
                     else f"\nСкачиваний: {rec['used']}"
                          + (f" из {rec['limit']}" if rec.get("limit") else ""))))
    except Exception:
        pass
    return MAIN_MENU
# ответы, и итоги не собрать). Голос каждого пользователя виден только боту
# (опрос живёт в личке), в итогах — ОБЩИЕ числа без имён.
# Хранение итогов: память процесса (_POLL_LOG/_POLL_INDEX) — честно
# предупреждаем в панели, что после рестарта бота итоги начинаются с нуля.

_POLL_LOG = []      # список опросов (последний — в конце), максимум _POLL_KEEP
_POLL_INDEX = {}    # poll_id Telegram -> запись опроса (у каждого получателя свой poll_id)
_POLL_KEEP = 20     # сколько последних опросов помним


def _poll_register(question, options, scope, creator_id, class_code=None):
    """Регистрирует новый опрос (запись общая для всех его копий).
    ВОЛНА 22.13: храним и класс (cls) — для приватности итогов: разработчик
    видит только СВОИ опросы, админ — только опросы СВОЕГО класса."""
    entry = {
        "q": str(question),
        "opts": [str(o) for o in options],
        "tally": [0] * len(options),
        "votes": 0,
        "scope": str(scope or "all"),
        "by": str(creator_id or ""),
        "cls": str(class_code or ""),
        "when": datetime.now().strftime("%d.%m.%Y %H:%M"),
    }
    _POLL_LOG.append(entry)
    while len(_POLL_LOG) > _POLL_KEEP:
        _old = _POLL_LOG.pop(0)
        for _pid, _e in list(_POLL_INDEX.items()):
            if _e is _old:
                _POLL_INDEX.pop(_pid, None)
    return entry


def _poll_panel_kb(scope):
    """Клавиатура панели, в которую вернётся создатель после отправки."""
    return (get_developer_keyboard() if scope == "all"
            else get_admin_panel_keyboard())


async def poll_start(update: Update, context: ContextTypes.DEFAULT_TYPE,
                     scope, class_code=None):
    """ВОЛНА 22.10: начало создания опроса — запоминаем адресата (all/class)
    и спрашиваем ВОПРОС."""
    query = update.callback_query
    try:
        await query.answer()
    except Exception:
        pass
    # ВОЛНА 22.12: poll_flow уже мог быть создан анти-гонкой в
    # handle_callback (до query.answer()) — НЕ затираем его, иначе вопрос,
    # принятый между нажатием кнопки и этим кодом, потеряется. Вопрос уже
    # есть? Сразу показываем шаг 2, не мигая устаревшим «шагом 1».
    flow = context.user_data.get("poll_flow")
    if not (isinstance(flow, dict) and flow.get("scope") in ("all", "class")):
        flow = {}
    flow["scope"] = scope
    if class_code:
        flow["class_code"] = class_code
    context.user_data["poll_flow"] = flow
    where = ("ВСЕМ пользователям бота" if scope == "all"
             else "всем участникам вашего класса")
    if flow.get("q"):
        _step2 = ("✅ Вопрос уже принят: «" + flow["q"] + "»\n\n"
                  "📊 СОЗДАНИЕ ОПРОСА — шаг 2 из 3\n\n"
                  "2️⃣ Пришлите ВАРИАНТЫ ОТВЕТА — по одному в строке, "
                  "от 2 до 10 вариантов (каждый до 100 символов).\n\n"
                  "Например:\nДа\nНет\nНе знаю")
        try:
            await query.edit_message_text(_step2)
        except Exception:
            pass
        return POLL_WAIT_OPTS
    # ВОЛНА 22.11: шаг 1 не может уронить диалог молча. Двойное нажатие
    # («Message is not modified»), медиа-сообщение панели и прочие сбои edit
    # раньше убивали poll_start ДО return — состояние не переключалось, и
    # вопрос пользователя уходил «в никуда» (бот молчал). Теперь при сбое
    # edit текст шага 1 уходит НОВЫМ сообщением, POLL_WAIT_Q ставится всегда.
    _step1 = (f"📊 СОЗДАНИЕ ОПРОСА — шаг 1 из 3\n\n"
              f"1️⃣ Пришлите ВОПРОС опроса одним сообщением (до 300 символов).\n\n"
              f"Опрос будет отправлен {where}.")
    try:
        await query.edit_message_text(_step1)
    except Exception as e:
        logger.error(f"poll_start: edit шага 1 не удался ({e}) — шлю новым сообщением")
        try:
            await context.bot.send_message(chat_id=query.message.chat_id,
                                           text=_step1)
        except Exception as e2:
            logger.error(f"poll_start: шаг 1 не доставлен вовсе: {e2}")
    return POLL_WAIT_Q


async def poll_admin_start(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """ВОЛНА 22.10: «📊 Опрос классу» — только админ класса; класс берём из
    current_admin_class (ставится при входе в админ-панель)."""
    query = update.callback_query
    _uid = str(query.from_user.id)
    if not is_user_class_admin(_uid):
        await query.answer("Опросы может создавать только админ класса.",
                           show_alert=True)
        return MAIN_MENU
    code = context.user_data.get('current_admin_class')
    if not code:
        classes = load_classes()
        for class_obj in classes.values():
            if class_obj.is_active and _uid in class_obj.admins:
                code = class_obj.class_code
                break
        if not code:
            await query.answer("Нет активного класса, где вы админ.",
                               show_alert=True)
            return MAIN_MENU
        context.user_data['current_admin_class'] = code
    return await poll_start(update, context, "class", class_code=code)


async def _poll_accept_question(update, context, flow, text, is_update=False):
    """ВОЛНА 22.11: ЕДИНАЯ точка приёма ВОПРОСА опроса. Сразу после приёма
    бот ОБЯЗАН попросить варианты — молчание на этом шаге запрещено:
    подсказка «шаг 2 из 3» отправляется с двойной доставкой (reply → при
    сбое send_message), и пользователь всегда видит, что вопрос принят.

    Используется:
    • обычный шаг 1→2 (poll_question_handler);
    • самолечение: одна строка в шаге вариантов = пользователь прислал
      (пере)вопрос — принимаем и снова просим варианты;
    • анти-гонка: текст вопроса прилетел в главное меню раньше, чем
      завершилось нажатие «📊 Опрос» (concurrent_updates) — там его тоже
      принимает этот хелпер.
    """
    msg = update.message
    text = (text or "").strip()
    if not text:
        try:
            await msg.reply_text(
                "📊 СОЗДАНИЕ ОПРОСА — шаг 1 из 3\n\n"
                "1️⃣ Пришлите ВОПРОС опроса одним сообщением (до 300 символов).")
        except Exception:
            pass
        return POLL_WAIT_Q
    if len(text) > 300:
        try:
            await msg.reply_text(
                "❌ Вопрос длиннее 300 символов — Telegram не примет. Сократите "
                "и пришлите заново.")
        except Exception:
            pass
        return POLL_WAIT_Q
    rejected = await reject_if_forbidden_chars(update, text, POLL_WAIT_Q)
    if rejected is not None:
        return rejected
    flow["q"] = text
    context.user_data["poll_flow"] = flow
    head = (("♻️ Вопрос обновлён: «" + text + "»") if is_update
            else ("✅ Вопрос принят: «" + text + "»"))
    # ВОЛНА 22.12: редактирование вопроса из превью — варианты УЖЕ есть,
    # заново их не спрашиваем, сразу показываем обновлённое превью.
    if flow.get("opts"):
        return await _poll_send_preview(update, context, flow,
                                        head + "\n\n📊 ПРЕВЬЮ ОПРОСА обновлено.")
    _prompt = (head + "\n\n"
               "📊 СОЗДАНИЕ ОПРОСА — шаг 2 из 3\n\n"
               "2️⃣ Теперь пришлите ВАРИАНТЫ ОТВЕТА — по одному в строке, "
               "от 2 до 10 вариантов (каждый до 100 символов).\n\n"
               "Например:\nДа\nНет\nНе знаю")
    try:
        await msg.reply_text(_prompt)
    except Exception as e:
        logger.error(f"poll: подсказка вариантов не доставлена reply-ем: {e}")
        try:
            await context.bot.send_message(chat_id=msg.chat_id, text=_prompt)
        except Exception as e2:
            logger.error(f"poll: подсказка вариантов не доставлена совсем: {e2}")
    return POLL_WAIT_OPTS


@timeout(CONVERSATION_TIMEOUT)
async def poll_question_handler(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """ВОЛНА 22.10/22.11: шаг 2 — принимаем ВОПРОС опроса и СРАЗУ просим
    варианты (единый хелпер _poll_accept_question)."""
    msg = update.message
    flow = context.user_data.get("poll_flow") or {}
    if not flow.get("scope"):
        await msg.reply_text("Сессия создания опроса потеряна. Начните заново.")
        return MAIN_MENU
    return await _poll_accept_question(update, context, flow, msg.text)


@timeout(CONVERSATION_TIMEOUT)
async def poll_options_handler(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """ВОЛНА 22.10: шаг 3 — принимаем варианты, показываем превью.
    ВОЛНА 22.12: вся логика живёт в общем хелпере _poll_accept_options —
    его же вызывают анти-гонка главного меню (текст обогнал переключение
    состояния) и приём вариантов после редактирования."""
    msg = update.message
    flow = context.user_data.get("poll_flow") or {}
    if not flow.get("scope"):
        await msg.reply_text("Сессия создания опроса потеряна. Начните заново.")
        return MAIN_MENU
    return await _poll_accept_options(update, context, flow, msg.text)


async def _poll_accept_options(update, context, flow, text, is_update=False):
    """ВОЛНА 22.12: ЕДИНАЯ точка приёма ВАРИАНТОВ опроса (2–10 строк).
    Самолечение из 22.11 сохранено:
    • пришёл шаг вариантов БЕЗ вопроса (гонка/рестарт) → текст становится
      вопросом, бот сразу просит варианты;
    • ОДНА строка в шаге вариантов вариантами быть не может (опросу нужно
      ≥2) → считаем её (новым) вопросом и сразу просим варианты."""
    msg = update.message
    text = (text or "").strip()
    if not flow.get("q"):
        # Состояние перескочило к вариантам без вопроса — принимаем текст
        # как ВОПРОС и сразу просим варианты (самолечение, без тупика).
        return await _poll_accept_question(update, context, flow, text)
    if len([ln for ln in text.splitlines() if ln.strip()]) <= 1:
        # Одна строка ≠ варианты — это (новый) вопрос. Принимаем, не молчим.
        return await _poll_accept_question(update, context, flow, text,
                                           is_update=True)
    raw = [ln.strip() for ln in text.splitlines()]
    opts = [o for o in raw if o]
    # Дубликаты убираем, сохраняя порядок.
    _seen = set()
    opts = [o for o in opts if not (o in _seen or _seen.add(o))]
    if len(opts) < 2 or len(opts) > 10:
        await msg.reply_text(
            "❌ Нужно от 2 до 10 вариантов — по одному в строке. "
            "Пришлите заново (или пришлите новый вопрос одним сообщением).")
        return POLL_WAIT_OPTS
    if any(len(o) > 100 for o in opts):
        await msg.reply_text(
            "❌ Каждый вариант — до 100 символов. Сократите и пришлите заново.")
        return POLL_WAIT_OPTS
    rejected = await reject_if_forbidden_chars(update, "\n".join(opts),
                                               POLL_WAIT_OPTS)
    if rejected is not None:
        return rejected
    flow["opts"] = opts
    context.user_data["poll_flow"] = flow
    return await _poll_send_preview(update, context, flow)


def _poll_preview_kb():
    """ВОЛНА 22.12: клавиатура превью — отправить, ОТРЕДАКТИРОВАТЬ вопрос и
    варианты прямо из превью, запланировать отправку или отменить."""
    return InlineKeyboardMarkup([
        [InlineKeyboardButton("✅ Отправить", callback_data="poll_go")],
        [InlineKeyboardButton("✏️ Вопрос", callback_data="poll_edit_q"),
         InlineKeyboardButton("✏️ Варианты", callback_data="poll_edit_opts")],
        [InlineKeyboardButton("⏰ Запланировать", callback_data="poll_sched")],
        [InlineKeyboardButton("❌ Отмена", callback_data="poll_cancel")],
    ])


async def _poll_send_preview(update, context, flow, head=None):
    """Единая отправка превью опроса (создание И редактирование)."""
    msg = update.message
    opts = flow.get("opts") or []
    where = ("ВСЕМ пользователям бота" if flow.get("scope") == "all"
             else "всем участникам вашего класса")
    text = ((head + "\n\n") if head else "📋 ПРЕВЬЮ ОПРОСА\n\n") \
        + "❓ " + flow.get("q", "") + "\n" \
        + "\n".join(f"  • {o}" for o in opts) \
        + f"\n\nОтправить опрос {where}? Или исправьте его кнопками ниже."
    try:
        await msg.reply_text(text, reply_markup=_poll_preview_kb())
    except Exception as e:
        logger.error(f"poll: превью не доставлено reply-ем: {e}")
        try:
            await context.bot.send_message(chat_id=msg.chat_id, text=text,
                                           reply_markup=_poll_preview_kb())
        except Exception as e2:
            logger.error(f"poll: превью не доставлено совсем: {e2}")
    return POLL_WAIT_CONFIRM


def _poll_targets(scope, class_code=None, context=None):
    """ВОЛНА 22.12: ЕДИНЫЙ список адресатов опроса с дедупликацией.
    Раньше (класс) студент, который одновременно числился и старостой,
    получал ДВЕ одинаковые копии опроса (students + admins без чистки)."""
    targets = []
    class_obj = None
    _class_name = ""
    if scope == "all":
        users = load_users()
        targets = [uid for uid, u in users.items()
                   if not getattr(u, "is_blocked", False)]
    else:
        code = class_code
        if not code and context is not None:
            code = context.user_data.get('current_admin_class')
        class_obj = get_class_by_code(code) if code else None
        if class_obj is None:
            return [], None, ""
        members = [m for m in (class_obj.students + class_obj.admins)
                   if m not in (class_obj.blocked_users or [])]
        targets = [str(m) for m in members]
        _class_name = class_obj.class_name
    # Дедупликация с сохранением порядка — никаких двойных копий.
    return list(dict.fromkeys(targets)), class_obj, _class_name


async def _poll_dispatch(bot, q, opts, scope, class_code, creator_id,
                         context=None):
    """ВОЛНА 22.12: общая рассылка опроса (send_poll, не анонимный).
    Используется и «✅ Отправить», и запланированной отправкой.
    ЗАЩИТА (22.13): не больше 15 рассылок в минуту от одного создателя
    (burst-лимит) — чтобы опросы нельзя было использовать для спама."""
    if is_user_spamming(str(creator_id or "0"), "poll_dispatch", 0, 15, 60):
        logger.warning(f"poll: rate-limit рассылки для {creator_id}")
        try:
            await bot.send_message(
                chat_id=int(creator_id),
                text="⏳ Слишком много опросов за минуту — рассылка не "
                     "выполнена. Подождите немного и повторите.")
        except Exception:
            pass
        return 0
    entry = _poll_register(q, opts, scope, creator_id, class_code)
    targets, _cls, _class_name = _poll_targets(scope, class_code, context)
    sent = 0
    for uid in targets:
        try:
            _m = await bot.send_poll(
                chat_id=int(uid), question=q, options=opts,
                is_anonymous=False, allows_multiple_answers=False)
            sent += 1
            try:
                _pid = str(_m.poll.id)
                _POLL_INDEX[_pid] = entry
            except Exception:
                pass  # без poll_id итоги этой копии не соберутся — не критично
        except Exception as e:
            logger.error(f"poll: не доставлено {uid}: {e}")
    if sent:
        _stat_bump("poll_sent")
    return sent


async def poll_go_cb(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """ВОЛНА 22.10: «✅ Отправить» — рассылаем настоящий Telegram-опрос
    (send_poll, не анонимный) всем адресатам и регистрируем сбор итогов."""
    query = update.callback_query
    try:
        await query.answer()
    except Exception:
        pass
    flow = context.user_data.get("poll_flow") or {}
    q, opts, scope = flow.get("q"), flow.get("opts"), flow.get("scope")
    if not q or not opts or scope not in ("all", "class"):
        context.user_data.pop("poll_flow", None)
        await query.edit_message_text(
            "Сессия создания опроса потеряна — опрос не отправлен.")
        return MAIN_MENU
    if scope == "all":
        _class_name = ""
    else:
        code = flow.get("class_code") or context.user_data.get(
            'current_admin_class')
        if not code or get_class_by_code(code) is None:
            context.user_data.pop("poll_flow", None)
            await query.edit_message_text(
                "Класс не найден — опрос не отправлен.")
            return MAIN_MENU
        _class_name = get_class_by_code(code).class_name
    # ВОЛНА 22.12: флаг sent ставится ещё в handle_callback ДО await —
    # двойное нажатие «✅ Отправить» больше не может запустить вторую
    # рассылку (каждому приходило по два одинаковых опроса).
    sent = await _poll_dispatch(context.bot, q, opts, scope,
                                flow.get("class_code"),
                                query.from_user.id, context)
    context.user_data.pop("poll_flow", None)
    who = (f"участникам класса «{_class_name}»" if scope == "class"
           else "пользователям бота")
    try:
        await query.edit_message_text(
            f"✅ Опрос отправлен {sent} {who}.\n"
            "📈 Итоги соберутся автоматически: панель → «📈 Итоги опросов» "
            "(итоги хранятся, пока бот запущен).",
            reply_markup=_poll_panel_kb(scope),
        )
    except Exception as e:
        logger.error(f"poll_go: edit не удался ({e}) — шлю новым сообщением")
        try:
            await context.bot.send_message(
                chat_id=query.message.chat_id,
                text=f"✅ Опрос отправлен {sent} {who}.",
                reply_markup=_poll_panel_kb(scope))
        except Exception:
            pass
    return DEV_PANEL if scope == "all" else ADMIN_PANEL


async def poll_results_cb(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """ВОЛНА 22.10: «📈 Итоги опросов» — общие числа голосов (без имён).
    ВОЛНА 22.13 — ПРИВАТНОСТЬ: разработчик видит итоги ТОЛЬКО опросов,
    которые отправил сам («статистика опросов у разработчика — только
    которые он отправлял»); админ — только опросы СВОЕГО класса. Чужие
    классы не видны никому."""
    query = update.callback_query
    try:
        await query.answer()
    except Exception:
        pass
    _uid = str(query.from_user.id)
    _is_dev = _uid == DEVELOPER_ID
    if not _is_dev and not is_user_class_admin(_uid):
        await query.answer("Итоги доступны админам и разработчику.",
                           show_alert=True)
        return MAIN_MENU
    if _is_dev:
        # Только опросы, отправленные самим разработчиком (scope all ИЛИ его личные классовые).
        visible = [e for e in _POLL_LOG
                   if str(e.get("by")) == _uid]
    else:
        _my_cls = get_class_by_user(_uid)
        _my_code = _my_cls.class_code if _my_cls else ""
        visible = [e for e in _POLL_LOG
                   if e.get("scope") == "class" and str(e.get("cls")) == str(_my_code)]
    if not _POLL_LOG or not visible:
        if _is_dev:
            _why = "Вы ещё не отправляли своих опросов."
        else:
            _why = "В вашем классе опросов пока не было."
        await query.edit_message_text(
            "📊 Итогов пока нет.\n\n" + _why + "\n\n"
            "Создайте опрос кнопкой выше — итоги соберутся автоматически. "
            "Итоги хранятся, пока бот запущен.",
            reply_markup=_poll_panel_kb("all" if _is_dev else "class"),
        )
        return DEV_PANEL if _is_dev else ADMIN_PANEL
    lines = ["📈 ИТОГИ ОПРОСОВ (последние 5)\n"]
    for entry in reversed(visible[-5:]):
        total = entry["votes"]
        _scope_tag = "класс" if entry["scope"] == "class" else "все"
        lines.append(f"❓ {entry['q']}  ·  {entry['when']}  ·  {_scope_tag}")
        for opt, cnt in zip(entry["opts"], entry["tally"]):
            _pct = f"{(cnt * 100 // total)}%" if total else "—"
            lines.append(f"  • {opt} — {cnt} ({_pct})")
        lines.append(f"  👥 Всего голосов: {total}\n")
    lines.append("Итоги анонимные (только числа, без имён) и хранятся, "
                 "пока бот запущен.")
    await query.edit_message_text(
        "\n".join(lines),
        reply_markup=_poll_panel_kb("all" if _is_dev else "class"),
    )
    return DEV_PANEL if _is_dev else ADMIN_PANEL


# === ВОЛНА 22.12: редактирование опроса из превью + запланированная
# отправка. ВОЛНА 22.14: реестр _POLL_SCHEDULES больше НЕ «память процесса» —
# каждый план сразу пишется в БД (POLL_SCHEDULES_FILE: Supabase → Mongo →
# файл + снапшот канал-БД), а на старте _poll_schedules_restore() восстанавливает
# воркеры: будущие планы уйдут вовремя, опоздание ≤ 6 ч — сразу после старта,
# более позднее — честная отмена с уведомлением автора. ===
_POLL_SCHEDULES = []


def _poll_sched_save():
    """ВОЛНА 22.14: слить реестр запланированных опросов в БД. save_data
    пишет в Supabase/Mongo/файл и помечает снапшот канал-БД «грязным»."""
    try:
        save_data(POLL_SCHEDULES_FILE, _POLL_SCHEDULES)
    except Exception as e:
        logger.error(f"poll_sched save: {e}")


def _poll_sched_discard(job):
    """Вычеркнуть исполненный/отменённый план из реестра и сохранить БД.
    Сравнение по identity — воркеры держат ссылку на СВОЙ словарь-план."""
    for _i, _j in enumerate(_POLL_SCHEDULES):
        if _j is job:
            _POLL_SCHEDULES.pop(_i)
            break
    _poll_sched_save()


# Опоздание, при котором запланированный опрос ещё отправляем сразу после
# рестарта («лучше поздно, чем никогда»). Больше — честно отменяем.
_POLL_SCHED_LATE_GRACE = 6 * 3600


async def _poll_schedules_restore(application):
    """ВОЛНА 22.14: восстановить запланированные опросы из БД после старта.
    Вызывается из _post_init (ШАГ 12). Правила:
      • срок в будущем → воркер спит и отправит вовремя;
      • опоздание ≤ _POLL_SCHED_LATE_GRACE → отправляем сразу после старта,
        автору — честная пометка об отправке с задержкой;
      • опоздание больше → план отменяется, автору — честное уведомление.
    Битые строки (нечитаемое время) выбрасываются молча, реестр пересохраняется."""
    try:
        data = load_data(POLL_SCHEDULES_FILE, [])
        if not isinstance(data, list):
            return
        now = datetime.now()
        kept = []
        for job in data:
            if not isinstance(job, dict):
                continue
            try:
                when = datetime.strptime(str(job.get("when")),
                                         "%d.%m.%Y %H:%M")
            except (TypeError, ValueError):
                continue
            late = (now - when).total_seconds()
            if late <= 0:
                kept.append(job)
                try:
                    application.create_task(
                        _poll_scheduled_worker(application, when, job))
                except Exception as e:
                    logger.error(f"poll_sched restore worker: {e}")
            elif late <= _POLL_SCHED_LATE_GRACE:
                try:
                    await _poll_dispatch(
                        application.bot, job.get("q"), job.get("opts") or [],
                        job.get("scope"), job.get("class_code"), job.get("by"))
                    try:
                        await application.bot.send_message(
                            chat_id=int(job["by"]),
                            text="⏰ Запланированный опрос отправлен С "
                                 "ЗАДЕРЖКОЙ (бот был выключен в срок "
                                 "отправки):\n\n❓ " + str(job.get("q")))
                    except Exception:
                        pass
                except Exception as e:
                    logger.error(f"poll_sched restore late send: {e}")
            else:
                try:
                    await application.bot.send_message(
                        chat_id=int(job["by"]),
                        text="❌ Запланированный опрос не отправлен: срок "
                             "вышел, пока бот был выключен.\n\n❓ "
                             + str(job.get("q")))
                except Exception:
                    pass
        _POLL_SCHEDULES.clear()
        _POLL_SCHEDULES.extend(kept)
        _poll_sched_save()
        logger.info(f"poll_sched restore: активных планов {len(kept)} "
                    f"из {len(data)} в БД.")
    except Exception as e:
        logger.error(f"poll_sched restore crashed: {e}")

_POLL_SCHED_PROMPT = (
    "⏰ ЗАПЛАНИРОВАННАЯ ОТПРАВКА ОПРОСА\n\n"
    "Когда отправить опрос? Пришлите время одним сообщением:\n"
    "• 18:30 — сегодня (или завтра, если это время уже прошло)\n"
    "• 05.10 18:30 — дата и время\n"
    "• через 30м / через 2ч — через сколько отправить\n\n"
    "Отменить — «❌ Отмена». Опрос уйдёт с теми вопросом и вариантами, "
    "что вы видели в превью.")


def _parse_sched_time(text, now=None):
    """Разбор времени запланированной отправки: ЧЧ:ММ | ДД.ММ ЧЧ:ММ |
    ДД.ММ.ГГГГ ЧЧ:ММ | через Nм/мин/ч/час. Возвращает datetime или None."""
    now = now or datetime.now()
    t = (text or "").strip().lower().replace(",", " ").strip()
    m = re.match(r"^через\s+(\d{1,4})\s*(мин|м|час(?:ов|а)?|ч|h)\.?$", t)
    if m:
        n = int(m.group(1))
        if n <= 0 or n > 43200:  # максимум 30 суток
            return None
        return now + timedelta(minutes=n)
    m = re.match(r"^(\d{1,2}):(\d{2})$", t)
    if m:
        hh, mm = int(m.group(1)), int(m.group(2))
        if not (0 <= hh <= 23 and 0 <= mm <= 59):
            return None
        when = now.replace(hour=hh, minute=mm, second=0, microsecond=0)
        if when <= now:
            when += timedelta(days=1)
        return when
    m = re.match(r"^(\d{1,2})\.(\d{1,2})(?:\.(\d{2,4}))?\s+(\d{1,2}):(\d{2})$", t)
    if m:
        dd, mo, yy, hh, mm = (int(m.group(1)), int(m.group(2)),
                              m.group(3), int(m.group(4)), int(m.group(5)))
        if not (1 <= dd <= 31 and 1 <= mo <= 12 and 0 <= hh <= 23
                and 0 <= mm <= 59):
            return None
        year = now.year
        if yy is not None:
            _y = int(yy)
            year = (2000 + _y) if len(str(yy)) <= 2 else _y
        try:
            when = datetime(year, mo, dd, hh, mm)
        except ValueError:
            return None
        return when
    return None


async def poll_sched_cb(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """ВОЛНА 22.12: «⏰ Запланировать» из превью — спрашиваем время."""
    query = update.callback_query
    try:
        await query.answer()
    except Exception:
        pass
    flow = context.user_data.get("poll_flow") or {}
    if not (flow.get("q") and flow.get("opts")):
        await query.edit_message_text(
            "Сессия создания опроса потеряна — опрос не запланирован.")
        return MAIN_MENU
    await query.edit_message_text(_POLL_SCHED_PROMPT)
    return POLL_WAIT_SCHED


async def poll_sched_receive(update: Update,
                             context: ContextTypes.DEFAULT_TYPE):
    """ВОЛНА 22.12: приём времени запланированного опроса."""
    msg = update.message
    flow = context.user_data.get("poll_flow") or {}
    if not (flow.get("q") and flow.get("opts")):
        await msg.reply_text("Сессия создания опроса потеряна. Начните заново.")
        return MAIN_MENU
    when = _parse_sched_time(msg.text)
    if when is None:
        await msg.reply_text(
            "❌ Не понял время. Пришлите его в одном из форматов:\n"
            "• 18:30\n• 05.10 18:30\n• через 30м\n\n"
            "Или нажмите «❌ Отмена».")
        return POLL_WAIT_SCHED
    job = {
        "when": when.strftime("%d.%m.%Y %H:%M"),
        "q": flow["q"],
        "opts": list(flow["opts"]),
        "scope": flow.get("scope"),
        "class_code": flow.get("class_code"),
        "by": str(update.effective_user.id),
    }
    _POLL_SCHEDULES.append(job)
    _poll_sched_save()  # ВОЛНА 22.14: план сразу в БД (переживает рестарт)
    flow.pop("sched_wait", None)
    context.user_data.pop("poll_flow", None)
    application = context.application
    application.create_task(_poll_scheduled_worker(application, when, job))
    await msg.reply_text(
        "✅ Опрос запланирован на " + when.strftime("%d.%m %H:%M") + ":\n\n"
        "❓ " + job["q"] + "\n"
        + "\n".join(f"  • {o}" for o in job["opts"])
        + "\n\n💾 План сохранён в базе и переживёт рестарт бота: если бот "
        "перезапустится, опрос уйдёт вовремя, а при опоздании — сразу "
        "после включения (опоздание больше 6 часов — честная отмена с "
        "уведомлением). В момент отправки вам придёт уведомление.")
    return DEV_PANEL if job["scope"] == "all" else ADMIN_PANEL


async def _poll_scheduled_worker(application, when, job):
    """Спит до назначенного времени и рассылает опрос.

    ВОЛНА 22.14: после исполнения (или сбоя) план вычёркивается из реестра
    и БД пересохраняется. Единственное исключение — asyncio.CancelledError
    (бот выключается): план ОСТАЁТСЯ в реестре, чтобы после рестарта
    _poll_schedules_restore() снова поставил его в очередь."""
    try:
        delay = (when - datetime.now()).total_seconds()
        if delay > 0:
            await asyncio.sleep(delay)
        sent = await _poll_dispatch(application.bot, job["q"], job["opts"],
                                    job["scope"], job.get("class_code"),
                                    job.get("by"))
        try:
            await application.bot.send_message(
                chat_id=int(job["by"]),
                text=f"⏰ Запланированный опрос отправлен ({sent} получ.):\n\n"
                     f"❓ {job['q']}")
        except Exception:
            pass
        _poll_sched_discard(job)  # исполнен → из реестра и из БД
    except asyncio.CancelledError:
        raise  # выключение бота: план сохраняем для восстановления
    except Exception as e:
        logger.error(f"poll_sched worker: {e}")
        try:
            _poll_sched_discard(job)  # сбой рассылки: не дублируем при рестартах
        except Exception:
            pass


async def poll_edit_cb(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """ВОЛНА 22.12: «✏️ Вопрос» / «✏️ Варианты» прямо из превью."""
    query = update.callback_query
    try:
        await query.answer()
    except Exception:
        pass
    data = query.data
    flow = context.user_data.get("poll_flow") or {}
    if not flow.get("scope") or flow.get("sent"):
        await query.edit_message_text("Сессия создания опроса потеряна.")
        return MAIN_MENU
    if data == "poll_edit_q":
        # Варианты СОХРАНЯЕМ: после нового вопроса сразу покажем превью.
        flow.pop("q", None)
        context.user_data["poll_flow"] = flow
        await query.edit_message_text(
            "✏️ ПРИШЛИТЕ НОВЫЙ ВОПРОС одним сообщением (до 300 символов).\n\n"
            "Варианты останутся прежними — превью обновится сразу.")
        return POLL_WAIT_Q
    if data == "poll_edit_opts":
        flow.pop("opts", None)
        context.user_data["poll_flow"] = flow
        await query.edit_message_text(
            "✏️ ПРИШЛИТЕ ВАРИАНТЫ ЗАНОВО — по одному в строке, "
            "от 2 до 10 (каждый до 100 символов).")
        return POLL_WAIT_OPTS
    return POLL_WAIT_CONFIRM


async def poll_cancel_cb(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """ВОЛНА 22.12: «❌ Отмена» из превью — честная отмена создания опроса."""
    query = update.callback_query
    try:
        await query.answer("Опрос отменён.")
    except Exception:
        pass
    context.user_data.pop("poll_flow", None)
    try:
        await query.edit_message_text("❌ Создание опроса отменено.")
    except Exception:
        pass
    return MAIN_MENU


async def poll_answer_handler(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """ВОЛНА 22.10: сбор голосов. Telegram присылает PollAnswer по каждому
    голосу в НЕанонимном опросе — складываем в общую копилку опроса."""
    try:
        pa = update.poll_answer
        entry = _POLL_INDEX.get(str(getattr(pa, "poll_id", "")))
        if entry is None:
            return
        for oi in (getattr(pa, "option_ids", None) or []):
            _oi = int(oi)
            if 0 <= _oi < len(entry["tally"]):
                entry["tally"][_oi] += 1
                entry["votes"] += 1
    except Exception as e:
        logger.warning(f"poll_answer: {e}")


